window.STORY_BANK = [{"level": "A1", "genre": "neutral", "title": "A Quiet Morning", "paragraphs": ["Ana wakes up early. She opens the window. The sun is bright.", "She drinks tea and eats bread. The kitchen is small and clean. She likes her quiet morning.", "Ana walks to work. The street is calm. She feels happy today."], "paragraphs_pt": ["Ana acorda cedo. Ela abre a janela. O sol está forte.", "Ela toma chá e come pão. A cozinha é pequena e limpa. Ela gosta da manhã tranquila.", "Ana caminha para o trabalho. A rua está calma. Ela se sente feliz hoje."], "hard_words": ["bright", "calm", "quiet"], "vocab": [{"word": "wake up", "meaning": "acordar", "note": ""}, {"word": "window", "meaning": "janela", "note": ""}, {"word": "sun", "meaning": "sol", "note": ""}, {"word": "tea", "meaning": "chá", "note": ""}, {"word": "bread", "meaning": "pão", "note": ""}, {"word": "kitchen", "meaning": "cozinha", "note": ""}, {"word": "street", "meaning": "rua", "note": ""}, {"word": "happy", "meaning": "feliz", "note": ""}], "word_meanings": [{"word": "bright", "meaning": "forte/brilhante", "note": "usado aqui para a luz do sol"}, {"word": "calm", "meaning": "calma", "note": ""}, {"word": "quiet", "meaning": "tranquila", "note": ""}], "grammar_words": {"cognates": [], "tobe": ["is"], "irregular": [], "phrasal": [], "wh": [], "connectors": ["and"], "comparative": []}, "exercises": {"grammar": [{"point": "Simple present - to be", "explanation_pt": "Usamos 'is' com he/she/it, como em 'The sun is bright'."}], "multiple_choice": [{"question": "When does Ana wake up?", "options": ["Late at night", "Early", "At noon", "In the afternoon"], "correct_index": 1, "explanation": "O texto diz 'Ana wakes up early'."}, {"question": "What does Ana drink?", "options": ["Coffee", "Juice", "Tea", "Milk"], "correct_index": 2, "explanation": "Ela toma chá (tea)."}, {"question": "How is the kitchen?", "options": ["Big and dirty", "Small and clean", "Cold and dark", "Old and ugly"], "correct_index": 1, "explanation": "A cozinha é pequena e limpa."}, {"question": "How is the street?", "options": ["Noisy", "Busy", "Calm", "Dangerous"], "correct_index": 2, "explanation": "A rua está calma."}, {"question": "How does Ana feel today?", "options": ["Sad", "Tired", "Angry", "Happy"], "correct_index": 3, "explanation": "Ela se sente feliz hoje."}], "open_questions": [{"question": "What do you usually do in the morning?", "key_points_pt": ["descrever a rotina", "usar verbos no presente"]}, {"question": "Do you like quiet mornings? Why?", "key_points_pt": ["dar uma opinião simples", "usar 'because' se possível"]}]}}, {"level": "A1", "genre": "humor", "title": "The Funny Dog", "paragraphs": ["Max is a big dog. He always makes funny faces. He jumps on the sofa every day.", "Today Max steals a sock. He runs around the house. The family laughs a lot.", "Max hides the sock under the bed. Everyone looks for it. In the end, they laugh together."], "paragraphs_pt": ["Max é um cachorro grande. Ele sempre faz caras engraçadas. Ele pula no sofá todos os dias.", "Hoje Max rouba uma meia. Ele corre pela casa. A família ri muito.", "Max esconde a meia embaixo da cama. Todos procuram por ela. No final, eles riem juntos."], "hard_words": ["steals", "hides", "sofa"], "vocab": [{"word": "dog", "meaning": "cachorro", "note": ""}, {"word": "funny", "meaning": "engraçado", "note": ""}, {"word": "jump", "meaning": "pular", "note": ""}, {"word": "sofa", "meaning": "sofá", "note": ""}, {"word": "steal", "meaning": "roubar", "note": ""}, {"word": "sock", "meaning": "meia", "note": ""}, {"word": "laugh", "meaning": "rir", "note": ""}, {"word": "hide", "meaning": "esconder", "note": ""}], "word_meanings": [{"word": "steals", "meaning": "rouba", "note": "verbo 'steal' na 3ª pessoa"}, {"word": "hides", "meaning": "esconde", "note": "verbo 'hide' na 3ª pessoa"}, {"word": "sofa", "meaning": "sofá", "note": ""}, {"word": "look for", "meaning": "procurar", "note": "phrasal verb"}], "grammar_words": {"cognates": [], "tobe": ["is"], "irregular": [], "phrasal": [], "wh": [], "connectors": [], "comparative": []}, "exercises": {"grammar": [{"point": "Simple present (3rd person)", "explanation_pt": "Com he/she/it, o verbo recebe -s, como em 'Max steals a sock'."}], "multiple_choice": [{"question": "What kind of dog is Max?", "options": ["Small", "Big", "Old", "Sick"], "correct_index": 1, "explanation": "O texto diz 'Max is a big dog'."}, {"question": "Where does Max jump?", "options": ["On the bed", "On the table", "On the sofa", "On the chair"], "correct_index": 2, "explanation": "Ele pula no sofá."}, {"question": "What does Max steal?", "options": ["A shoe", "A sock", "A ball", "A hat"], "correct_index": 1, "explanation": "Max rouba uma meia."}, {"question": "Where does Max hide the sock?", "options": ["Under the bed", "In the kitchen", "In the garden", "Under the sofa"], "correct_index": 0, "explanation": "Ele esconde a meia embaixo da cama."}, {"question": "How does the family feel at the end?", "options": ["Angry", "Sad", "They laugh", "Worried"], "correct_index": 2, "explanation": "No final, eles riem juntos."}], "open_questions": [{"question": "Do you have a funny pet? Describe it.", "key_points_pt": ["descrever um animal", "usar adjetivos simples"]}, {"question": "What do you do when you lose something?", "key_points_pt": ["falar sobre procurar objetos", "usar 'look for'"]}]}}, {"level": "A1", "genre": "fairytale", "title": "The Little Star", "paragraphs": ["Once upon a time, a little star lives in the sky. She is small and shy. She wants to shine bright.", "One night, she meets the moon. The moon says, \"You are special.\" The little star smiles.", "Now the little star shines every night. Children look up and smile. She is happy in the sky."], "paragraphs_pt": ["Era uma vez uma estrelinha que vive no céu. Ela é pequena e tímida. Ela quer brilhar forte.", "Uma noite, ela encontra a lua. A lua diz: \"Você é especial.\" A estrelinha sorri.", "Agora a estrelinha brilha todas as noites. As crianças olham para cima e sorriem. Ela é feliz no céu."], "hard_words": ["shy", "shine", "special"], "vocab": [{"word": "star", "meaning": "estrela", "note": ""}, {"word": "sky", "meaning": "céu", "note": ""}, {"word": "moon", "meaning": "lua", "note": ""}, {"word": "night", "meaning": "noite", "note": ""}, {"word": "smile", "meaning": "sorrir", "note": ""}, {"word": "shine", "meaning": "brilhar", "note": ""}, {"word": "special", "meaning": "especial", "note": ""}, {"word": "children", "meaning": "crianças", "note": ""}], "word_meanings": [{"word": "shy", "meaning": "tímida", "note": ""}, {"word": "shine", "meaning": "brilhar", "note": ""}, {"word": "special", "meaning": "especial", "note": ""}, {"word": "look up", "meaning": "olhar para cima", "note": "phrasal verb"}], "grammar_words": {"cognates": [], "tobe": ["is", "are"], "irregular": [], "phrasal": ["look up"], "wh": [], "connectors": [], "comparative": []}, "exercises": {"grammar": [{"point": "Adjectives with to be", "explanation_pt": "Usamos 'is/are' + adjetivo, como em 'She is small and shy'."}], "multiple_choice": [{"question": "Where does the little star live?", "options": ["In the sea", "In the sky", "In a cave", "In a forest"], "correct_index": 1, "explanation": "A estrelinha vive no céu."}, {"question": "How is the little star at first?", "options": ["Big and loud", "Small and shy", "Angry", "Sad"], "correct_index": 1, "explanation": "Ela é pequena e tímida."}, {"question": "Who does the star meet at night?", "options": ["The sun", "A bird", "The moon", "A cloud"], "correct_index": 2, "explanation": "Ela encontra a lua."}, {"question": "What does the moon say?", "options": ["\"Go away\"", "\"You are special\"", "\"You are sad\"", "\"Be quiet\""], "correct_index": 1, "explanation": "A lua diz que ela é especial."}, {"question": "Who looks up and smiles?", "options": ["Children", "Birds", "Dogs", "Fish"], "correct_index": 0, "explanation": "As crianças olham para cima e sorriem."}], "open_questions": [{"question": "Do you like to look at the sky at night? Why?", "key_points_pt": ["dar opinião", "falar sobre o céu"]}, {"question": "What makes you feel special?", "key_points_pt": ["falar de sentimentos simples", "usar 'because'"]}]}}, {"level": "A1", "genre": "fable", "title": "The Ant and the Leaf", "paragraphs": ["A small ant walks near a river. The water is fast. The ant falls into the water.", "A bird sees the ant. The bird drops a leaf into the water. The ant climbs onto the leaf and swims to land.", "Later, a hunter tries to catch the bird. The ant bites the hunter's foot. The bird flies away safely."], "paragraphs_pt": ["Uma formiguinha caminha perto de um rio. A água está rápida. A formiga cai na água.", "Um pássaro vê a formiga. O pássaro deixa cair uma folha na água. A formiga sobe na folha e nada até a terra.", "Mais tarde, um caçador tenta pegar o pássaro. A formiga morde o pé do caçador. O pássaro voa para longe em segurança."], "hard_words": ["hunter", "bites", "safely"], "vocab": [{"word": "ant", "meaning": "formiga", "note": ""}, {"word": "river", "meaning": "rio", "note": ""}, {"word": "bird", "meaning": "pássaro", "note": ""}, {"word": "leaf", "meaning": "folha", "note": ""}, {"word": "swim", "meaning": "nadar", "note": ""}, {"word": "hunter", "meaning": "caçador", "note": ""}, {"word": "land", "meaning": "terra", "note": ""}, {"word": "friend", "meaning": "amigo", "note": ""}], "word_meanings": [{"word": "hunter", "meaning": "caçador", "note": ""}, {"word": "bites", "meaning": "morde", "note": "verbo 'bite' na 3ª pessoa"}, {"word": "safely", "meaning": "em segurança", "note": ""}], "grammar_words": {"cognates": [], "tobe": ["is"], "irregular": [], "phrasal": [], "wh": [], "connectors": ["and"], "comparative": []}, "exercises": {"grammar": [{"point": "Simple present for stories", "explanation_pt": "A fábula usa o presente simples para narrar, como em 'The ant falls into the water'."}], "multiple_choice": [{"question": "Where does the ant walk?", "options": ["Near a river", "Near a house", "Near a road", "Near a school"], "correct_index": 0, "explanation": "A formiga caminha perto de um rio."}, {"question": "What does the bird drop into the water?", "options": ["A stick", "A leaf", "A stone", "A flower"], "correct_index": 1, "explanation": "O pássaro deixa cair uma folha."}, {"question": "Who tries to catch the bird?", "options": ["A cat", "A hunter", "A fox", "A snake"], "correct_index": 1, "explanation": "Um caçador tenta pegar o pássaro."}, {"question": "What does the ant do to help the bird?", "options": ["It sings", "It hides", "It bites the hunter", "It flies away"], "correct_index": 2, "explanation": "A formiga morde o pé do caçador."}, {"question": "What is the lesson of the fable?", "options": ["Sleep a lot", "Friends help each other", "Never swim", "Birds are dangerous"], "correct_index": 1, "explanation": "Bons amigos se ajudam."}], "open_questions": [{"question": "How did the ant help the bird?", "key_points_pt": ["a formiga morde o caçador", "o pássaro escapa"]}, {"question": "Why is it good to help friends?", "key_points_pt": ["dar uma razão simples", "relacionar com a história"]}]}}, {"level": "A1", "genre": "adventure", "title": "The Small Boat", "paragraphs": ["Tom has a small boat. He sails to a new island. The sea is calm and blue.", "On the island, he finds a cave. Inside, there are old coins. Tom is very excited.", "He takes one coin home. He tells his friends about the island. They want to go too."], "paragraphs_pt": ["Tom tem um barquinho. Ele navega até uma ilha nova. O mar está calmo e azul.", "Na ilha, ele encontra uma caverna. Dentro, há moedas antigas. Tom está muito animado.", "Ele leva uma moeda para casa. Ele conta aos amigos sobre a ilha. Eles também querem ir."], "hard_words": ["sails", "cave", "coins"], "vocab": [{"word": "boat", "meaning": "barco", "note": ""}, {"word": "sail", "meaning": "navegar", "note": ""}, {"word": "island", "meaning": "ilha", "note": ""}, {"word": "sea", "meaning": "mar", "note": ""}, {"word": "cave", "meaning": "caverna", "note": ""}, {"word": "coin", "meaning": "moeda", "note": ""}, {"word": "excited", "meaning": "animado", "note": ""}, {"word": "friend", "meaning": "amigo", "note": ""}], "word_meanings": [{"word": "sails", "meaning": "navega", "note": "verbo 'sail' na 3ª pessoa"}, {"word": "cave", "meaning": "caverna", "note": ""}, {"word": "coins", "meaning": "moedas", "note": ""}], "grammar_words": {"cognates": [], "tobe": ["is", "are"], "irregular": [], "phrasal": [], "wh": [], "connectors": ["and"], "comparative": []}, "exercises": {"grammar": [{"point": "There is / There are", "explanation_pt": "Usamos 'there are' para falar de coisas no plural, como em 'there are old coins'."}], "multiple_choice": [{"question": "What does Tom have?", "options": ["A car", "A small boat", "A bike", "A map"], "correct_index": 1, "explanation": "Tom tem um barquinho."}, {"question": "How is the sea?", "options": ["Calm and blue", "Rough and grey", "Cold and dark", "Dirty"], "correct_index": 0, "explanation": "O mar está calmo e azul."}, {"question": "What does Tom find on the island?", "options": ["A house", "A cave", "A shop", "A garden"], "correct_index": 1, "explanation": "Ele encontra uma caverna."}, {"question": "What is inside the cave?", "options": ["Books", "Old coins", "Toys", "Clothes"], "correct_index": 1, "explanation": "Há moedas antigas dentro."}, {"question": "How does Tom feel about the island?", "options": ["Bored", "Excited", "Scared", "Angry"], "correct_index": 1, "explanation": "Tom está muito animado."}], "open_questions": [{"question": "Would you like to explore an island? Why?", "key_points_pt": ["dar uma opinião", "usar 'because'"]}, {"question": "What would you like to find in a cave?", "key_points_pt": ["imaginar um objeto", "descrever de forma simples"]}]}}, {"level": "A1", "genre": "travel", "title": "A Trip to the Beach", "paragraphs": ["Maria and her family go to the beach. They travel by car. The trip takes two hours.", "At the beach, the children swim in the sea. Maria reads a book under an umbrella. The sand is warm.", "In the evening, they eat fruit and watch the sunset. Everyone is tired but happy."], "paragraphs_pt": ["Maria e sua família vão à praia. Eles viajam de carro. A viagem dura duas horas.", "Na praia, as crianças nadam no mar. Maria lê um livro debaixo de um guarda-sol. A areia está quente.", "À noite, eles comem frutas e assistem ao pôr do sol. Todos estão cansados, mas felizes."], "hard_words": ["umbrella", "sunset", "tired"], "vocab": [{"word": "beach", "meaning": "praia", "note": ""}, {"word": "travel", "meaning": "viajar", "note": ""}, {"word": "swim", "meaning": "nadar", "note": ""}, {"word": "sand", "meaning": "areia", "note": ""}, {"word": "umbrella", "meaning": "guarda-sol", "note": ""}, {"word": "sunset", "meaning": "pôr do sol", "note": ""}, {"word": "tired", "meaning": "cansado", "note": ""}, {"word": "family", "meaning": "família", "note": ""}], "word_meanings": [{"word": "umbrella", "meaning": "guarda-sol", "note": ""}, {"word": "sunset", "meaning": "pôr do sol", "note": ""}, {"word": "tired", "meaning": "cansado", "note": ""}], "grammar_words": {"cognates": [], "tobe": ["is"], "irregular": [], "phrasal": [], "wh": [], "connectors": ["but"], "comparative": []}, "exercises": {"grammar": [{"point": "Simple present for routines", "explanation_pt": "Usamos o presente simples para ações do dia a dia, como em 'They travel by car'."}], "multiple_choice": [{"question": "How does the family travel?", "options": ["By bus", "By car", "By plane", "By boat"], "correct_index": 1, "explanation": "Eles viajam de carro."}, {"question": "How long does the trip take?", "options": ["One hour", "Two hours", "Five hours", "Ten hours"], "correct_index": 1, "explanation": "A viagem dura duas horas."}, {"question": "What do the children do at the beach?", "options": ["They read", "They sleep", "They swim", "They cook"], "correct_index": 2, "explanation": "As crianças nadam no mar."}, {"question": "What does Maria do under the umbrella?", "options": ["She sleeps", "She reads a book", "She swims", "She eats"], "correct_index": 1, "explanation": "Maria lê um livro."}, {"question": "How do they feel in the evening?", "options": ["Tired but happy", "Angry", "Bored", "Cold"], "correct_index": 0, "explanation": "Todos estão cansados, mas felizes."}], "open_questions": [{"question": "Do you like the beach? Why?", "key_points_pt": ["dar opinião pessoal", "usar 'because'"]}, {"question": "What do you do on a family trip?", "key_points_pt": ["descrever atividades simples", "usar presente simples"]}]}}, {"level": "A1", "genre": "cooking", "title": "Making Soup", "paragraphs": ["Grandma makes soup every Sunday. She cuts carrots and potatoes. The kitchen smells wonderful.", "She puts the vegetables in a big pot. She adds water and salt. The soup cooks slowly.", "The family sits at the table. Everyone eats a warm bowl of soup. Grandma smiles because they love her food."], "paragraphs_pt": ["A vovó faz sopa todo domingo. Ela corta cenouras e batatas. A cozinha cheira maravilhosamente.", "Ela coloca os legumes em uma panela grande. Ela adiciona água e sal. A sopa cozinha devagar.", "A família se senta à mesa. Todos comem uma tigela de sopa quente. A vovó sorri porque eles amam a comida dela."], "hard_words": ["wonderful", "pot", "slowly"], "vocab": [{"word": "soup", "meaning": "sopa", "note": ""}, {"word": "carrot", "meaning": "cenoura", "note": ""}, {"word": "potato", "meaning": "batata", "note": ""}, {"word": "pot", "meaning": "panela", "note": ""}, {"word": "salt", "meaning": "sal", "note": ""}, {"word": "cook", "meaning": "cozinhar", "note": ""}, {"word": "bowl", "meaning": "tigela", "note": ""}, {"word": "table", "meaning": "mesa", "note": ""}], "word_meanings": [{"word": "wonderful", "meaning": "maravilhoso", "note": ""}, {"word": "pot", "meaning": "panela", "note": ""}, {"word": "slowly", "meaning": "devagar", "note": ""}], "grammar_words": {"cognates": [], "tobe": [], "irregular": [], "phrasal": [], "wh": [], "connectors": ["and", "because"], "comparative": []}, "exercises": {"grammar": [{"point": "Simple present (3rd person -s)", "explanation_pt": "Verbos com he/she recebem -s, como em 'Grandma makes soup'."}], "multiple_choice": [{"question": "When does Grandma make soup?", "options": ["Every Monday", "Every Sunday", "Every Friday", "Every day"], "correct_index": 1, "explanation": "Ela faz sopa todo domingo."}, {"question": "What does she cut?", "options": ["Apples and bread", "Carrots and potatoes", "Meat and rice", "Onions and eggs"], "correct_index": 1, "explanation": "Ela corta cenouras e batatas."}, {"question": "Where does she put the vegetables?", "options": ["In a bag", "In a big pot", "On the table", "In the oven"], "correct_index": 1, "explanation": "Ela coloca os legumes em uma panela grande."}, {"question": "How does the soup cook?", "options": ["Quickly", "Slowly", "Badly", "Loudly"], "correct_index": 1, "explanation": "A sopa cozinha devagar."}, {"question": "Why does Grandma smile?", "options": ["Because it is hot", "Because they love her food", "Because she is tired", "Because it is Sunday"], "correct_index": 1, "explanation": "Ela sorri porque eles amam a comida dela."}], "open_questions": [{"question": "What food do you like to cook?", "key_points_pt": ["nomear um prato simples", "usar 'I like to cook'"]}, {"question": "Who cooks in your family?", "key_points_pt": ["falar sobre a família", "usar presente simples"]}]}}, {"level": "A1", "genre": "sports", "title": "The Big Race", "paragraphs": ["Leo loves to run. Every morning, he trains in the park. He wants to win the big race.", "On race day, many runners stand at the start line. Leo is nervous but ready. The whistle blows and everyone runs fast.", "Leo runs hard and reaches the finish line first. His friends cheer and give him a medal."], "paragraphs_pt": ["Leo adora correr. Toda manhã, ele treina no parque. Ele quer ganhar a corrida grande.", "No dia da corrida, muitos corredores ficam na linha de partida. Leo está nervoso, mas pronto. O apito toca e todos correm rápido.", "Leo corre com força e chega à linha de chegada primeiro. Seus amigos torcem e dão a ele uma medalha."], "hard_words": ["nervous", "whistle", "medal"], "vocab": [{"word": "run", "meaning": "correr", "note": ""}, {"word": "train", "meaning": "treinar", "note": ""}, {"word": "race", "meaning": "corrida", "note": ""}, {"word": "start", "meaning": "início", "note": ""}, {"word": "finish", "meaning": "fim", "note": ""}, {"word": "medal", "meaning": "medalha", "note": ""}, {"word": "cheer", "meaning": "torcer", "note": ""}, {"word": "nervous", "meaning": "nervoso", "note": ""}], "word_meanings": [{"word": "nervous", "meaning": "nervoso", "note": ""}, {"word": "whistle", "meaning": "apito", "note": ""}, {"word": "medal", "meaning": "medalha", "note": ""}], "grammar_words": {"cognates": [], "tobe": ["is"], "irregular": [], "phrasal": [], "wh": [], "connectors": ["but", "and"], "comparative": []}, "exercises": {"grammar": [{"point": "want + to + verb", "explanation_pt": "Usamos 'want to' + verbo, como em 'He wants to win the big race'."}], "multiple_choice": [{"question": "What does Leo love to do?", "options": ["Swim", "Run", "Read", "Cook"], "correct_index": 1, "explanation": "Leo adora correr."}, {"question": "Where does Leo train?", "options": ["At home", "In the park", "At school", "At the beach"], "correct_index": 1, "explanation": "Ele treina no parque."}, {"question": "How does Leo feel before the race?", "options": ["Bored", "Nervous but ready", "Angry", "Sleepy"], "correct_index": 1, "explanation": "Ele está nervoso, mas pronto."}, {"question": "What happens when the whistle blows?", "options": ["Everyone sits down", "Everyone runs fast", "Everyone eats", "Everyone sleeps"], "correct_index": 1, "explanation": "O apito toca e todos correm rápido."}, {"question": "What do his friends give him?", "options": ["A book", "A medal", "A hat", "Money"], "correct_index": 1, "explanation": "Seus amigos dão a ele uma medalha."}], "open_questions": [{"question": "Do you like sports? Which one?", "key_points_pt": ["nomear um esporte", "dar uma razão simples"]}, {"question": "How do you feel before a competition?", "key_points_pt": ["descrever sentimentos", "usar adjetivos simples"]}]}}, {"level": "A1", "genre": "slice", "title": "A Day at the Park", "paragraphs": ["Sofia goes to the park after school. She sits on a bench with her book. Birds sing in the trees.", "Her little brother plays with a ball. He laughs and runs around the grass. Sofia watches him and smiles.", "When the sun goes down, they walk home together. Sofia feels calm and happy."], "paragraphs_pt": ["Sofia vai ao parque depois da escola. Ela senta em um banco com seu livro. Os pássaros cantam nas árvores.", "Seu irmãozinho brinca com uma bola. Ele ri e corre pela grama. Sofia o observa e sorri.", "Quando o sol se põe, eles caminham juntos para casa. Sofia se sente calma e feliz."], "hard_words": ["bench", "grass", "calm"], "vocab": [{"word": "park", "meaning": "parque", "note": ""}, {"word": "bench", "meaning": "banco", "note": ""}, {"word": "bird", "meaning": "pássaro", "note": ""}, {"word": "tree", "meaning": "árvore", "note": ""}, {"word": "brother", "meaning": "irmão", "note": ""}, {"word": "ball", "meaning": "bola", "note": ""}, {"word": "grass", "meaning": "grama", "note": ""}, {"word": "calm", "meaning": "calma", "note": ""}], "word_meanings": [{"word": "bench", "meaning": "banco", "note": ""}, {"word": "grass", "meaning": "grama", "note": ""}, {"word": "calm", "meaning": "calma", "note": ""}], "grammar_words": {"cognates": [], "tobe": [], "irregular": [], "phrasal": [], "wh": ["When"], "connectors": ["and"], "comparative": []}, "exercises": {"grammar": [{"point": "Present continuous with -ing actions described in present simple", "explanation_pt": "O texto usa presente simples para ações do dia, como em 'He laughs and runs around the grass'."}], "multiple_choice": [{"question": "Where does Sofia go after school?", "options": ["To the beach", "To the park", "To the market", "To a friend's house"], "correct_index": 1, "explanation": "Ela vai ao parque."}, {"question": "What does Sofia bring to the park?", "options": ["A ball", "A book", "A bag", "A phone"], "correct_index": 1, "explanation": "Ela senta com seu livro."}, {"question": "What does her brother play with?", "options": ["A dog", "A ball", "A bike", "A kite"], "correct_index": 1, "explanation": "Ele brinca com uma bola."}, {"question": "Where does the brother run?", "options": ["On the grass", "On the street", "In the water", "Up a tree"], "correct_index": 0, "explanation": "Ele corre pela grama."}, {"question": "How does Sofia feel at the end?", "options": ["Angry", "Calm and happy", "Tired and sad", "Worried"], "correct_index": 1, "explanation": "Sofia se sente calma e feliz."}], "open_questions": [{"question": "What do you do after school?", "key_points_pt": ["descrever uma rotina simples", "usar presente simples"]}, {"question": "Do you like parks? Why?", "key_points_pt": ["dar opinião", "usar 'because'"]}]}}, {"level": "A1", "genre": "dialogue", "title": "Two Friends Talk", "paragraphs": ["Ben meets his friend Lucy at the park. \"Hi Lucy! How are you today?\" he asks. \"I am fine, thank you,\" she says.", "\"Do you want to play soccer with me?\" Ben asks. \"Yes, I love soccer!\" Lucy answers. They run to get the ball.", "After the game, Lucy says, \"That was fun!\" Ben smiles and says, \"Let's play again tomorrow.\" They both agree happily."], "paragraphs_pt": ["Ben encontra sua amiga Lucy no parque. \"Oi Lucy! Como você está hoje?\" ele pergunta. \"Estou bem, obrigada,\" ela diz.", "\"Você quer jogar futebol comigo?\" Ben pergunta. \"Sim, eu amo futebol!\" Lucy responde. Eles correm para pegar a bola.", "Depois do jogo, Lucy diz: \"Isso foi divertido!\" Ben sorri e diz: \"Vamos jogar de novo amanhã.\" Os dois concordam felizes."], "hard_words": ["agree", "answers", "fun"], "vocab": [{"word": "friend", "meaning": "amigo", "note": ""}, {"word": "ask", "meaning": "perguntar", "note": ""}, {"word": "answer", "meaning": "responder", "note": ""}, {"word": "soccer", "meaning": "futebol", "note": ""}, {"word": "play", "meaning": "jogar", "note": ""}, {"word": "fun", "meaning": "divertido", "note": ""}, {"word": "tomorrow", "meaning": "amanhã", "note": ""}, {"word": "agree", "meaning": "concordar", "note": ""}], "word_meanings": [{"word": "agree", "meaning": "concordar", "note": ""}, {"word": "answers", "meaning": "responde", "note": "verbo 'answer' na 3ª pessoa"}, {"word": "fun", "meaning": "divertido", "note": ""}], "grammar_words": {"cognates": [], "tobe": ["are", "am"], "irregular": [], "phrasal": [], "wh": ["How"], "connectors": [], "comparative": []}, "exercises": {"grammar": [{"point": "Wh-questions with how", "explanation_pt": "Usamos 'how' para perguntar sobre estado ou condição, como em 'How are you today?'."}], "multiple_choice": [{"question": "Where does Ben meet Lucy?", "options": ["At school", "At the park", "At home", "At the beach"], "correct_index": 1, "explanation": "Ben encontra Lucy no parque."}, {"question": "What does Ben ask Lucy to play?", "options": ["Basketball", "Soccer", "Tennis", "Chess"], "correct_index": 1, "explanation": "Ele pergunta se ela quer jogar futebol."}, {"question": "Does Lucy like soccer?", "options": ["No, she doesn't", "Yes, she loves it", "She doesn't know", "She hates it"], "correct_index": 1, "explanation": "Ela diz 'I love soccer!'."}, {"question": "What does Lucy say after the game?", "options": ["\"That was boring\"", "\"That was fun\"", "\"I am tired\"", "\"I am angry\""], "correct_index": 1, "explanation": "Ela diz que foi divertido."}, {"question": "What do they plan to do tomorrow?", "options": ["Study", "Play again", "Sleep", "Travel"], "correct_index": 1, "explanation": "Eles combinam jogar de novo amanhã."}], "open_questions": [{"question": "What do you say when you meet a friend?", "key_points_pt": ["usar cumprimentos simples", "'Hi, how are you?'"]}, {"question": "What games do you like to play with friends?", "key_points_pt": ["nomear um jogo", "usar 'I like to play'"]}]}}, {"level": "A1", "genre": "diary", "title": "My Diary", "paragraphs": ["Monday. Today I wake up late. I eat breakfast fast and go to school. My classes are boring but okay.", "Tuesday. I meet my best friend after school. We walk in the park and talk about music. I feel happy.", "Wednesday. Tonight I write in my diary. I think about my nice week. Tomorrow, I want to study hard."], "paragraphs_pt": ["Segunda-feira. Hoje eu acordo tarde. Eu tomo café da manhã rápido e vou para a escola. Minhas aulas são chatas, mas ok.", "Terça-feira. Eu encontro minha melhor amiga depois da escola. Nós caminhamos no parque e conversamos sobre música. Eu me sinto feliz.", "Quarta-feira. Hoje à noite eu escrevo no meu diário. Eu penso sobre minha semana legal. Amanhã, eu quero estudar bastante."], "hard_words": ["boring", "diary", "tonight"], "vocab": [{"word": "diary", "meaning": "diário", "note": ""}, {"word": "wake up", "meaning": "acordar", "note": ""}, {"word": "breakfast", "meaning": "café da manhã", "note": ""}, {"word": "boring", "meaning": "chato", "note": ""}, {"word": "friend", "meaning": "amigo", "note": ""}, {"word": "music", "meaning": "música", "note": ""}, {"word": "week", "meaning": "semana", "note": ""}, {"word": "study", "meaning": "estudar", "note": ""}], "word_meanings": [{"word": "boring", "meaning": "chato", "note": ""}, {"word": "diary", "meaning": "diário", "note": ""}, {"word": "tonight", "meaning": "hoje à noite", "note": ""}], "grammar_words": {"cognates": [], "tobe": ["are"], "irregular": [], "phrasal": [], "wh": [], "connectors": ["and", "but"], "comparative": []}, "exercises": {"grammar": [{"point": "Simple present with I", "explanation_pt": "Com 'I' o verbo fica na forma base, como em 'I eat breakfast fast'."}], "multiple_choice": [{"question": "What happens on Monday?", "options": ["She wakes up early", "She wakes up late", "She sleeps all day", "She goes to the park"], "correct_index": 1, "explanation": "Ela acorda tarde na segunda-feira."}, {"question": "How are her classes?", "options": ["Fun", "Boring but okay", "Very hard", "Easy"], "correct_index": 1, "explanation": "As aulas são chatas, mas ok."}, {"question": "Who does she meet on Tuesday?", "options": ["Her teacher", "Her best friend", "Her brother", "Her mother"], "correct_index": 1, "explanation": "Ela encontra sua melhor amiga."}, {"question": "What do they talk about in the park?", "options": ["School", "Music", "Sports", "Food"], "correct_index": 1, "explanation": "Elas conversam sobre música."}, {"question": "What does she want to do tomorrow?", "options": ["Sleep all day", "Study hard", "Travel", "Cook"], "correct_index": 1, "explanation": "Amanhã ela quer estudar bastante."}], "open_questions": [{"question": "Do you write a diary? Why or why not?", "key_points_pt": ["dar opinião simples", "usar 'because'"]}, {"question": "What did you do this week?", "key_points_pt": ["descrever atividades", "usar frases curtas"]}]}}, {"level": "A1", "genre": "romance", "title": "A Sweet Letter", "paragraphs": ["Paulo likes Julia very much. Every day, he sees her at the bus stop. He wants to talk to her but he is shy.", "One day, Paulo writes Julia a small letter. He gives it to her with a flower. Julia reads it and smiles.", "Julia says, \"I like you too.\" Paulo is very happy. Now they walk to the bus stop together every day."], "paragraphs_pt": ["Paulo gosta muito de Julia. Todos os dias, ele a vê no ponto de ônibus. Ele quer falar com ela, mas é tímido.", "Um dia, Paulo escreve um bilhete pequeno para Julia. Ele dá o bilhete a ela com uma flor. Julia lê e sorri.", "Julia diz: \"Eu também gosto de você.\" Paulo fica muito feliz. Agora eles caminham juntos para o ponto de ônibus todos os dias."], "hard_words": ["shy", "letter", "flower"], "vocab": [{"word": "like", "meaning": "gostar", "note": ""}, {"word": "bus stop", "meaning": "ponto de ônibus", "note": ""}, {"word": "shy", "meaning": "tímido", "note": ""}, {"word": "letter", "meaning": "carta/bilhete", "note": ""}, {"word": "flower", "meaning": "flor", "note": ""}, {"word": "smile", "meaning": "sorrir", "note": ""}, {"word": "happy", "meaning": "feliz", "note": ""}, {"word": "together", "meaning": "juntos", "note": ""}], "word_meanings": [{"word": "shy", "meaning": "tímido", "note": ""}, {"word": "letter", "meaning": "carta/bilhete", "note": ""}, {"word": "flower", "meaning": "flor", "note": ""}], "grammar_words": {"cognates": [], "tobe": ["is"], "irregular": [], "phrasal": [], "wh": [], "connectors": ["but", "and"], "comparative": []}, "exercises": {"grammar": [{"point": "want to / like to + verb", "explanation_pt": "Usamos 'want to' e 'like' + verbo, como em 'He wants to talk to her'."}], "multiple_choice": [{"question": "Where does Paulo see Julia every day?", "options": ["At school", "At the bus stop", "At the park", "At home"], "correct_index": 1, "explanation": "Ele a vê no ponto de ônibus."}, {"question": "Why doesn't Paulo talk to Julia at first?", "options": ["He is angry", "He is shy", "He is busy", "He is tired"], "correct_index": 1, "explanation": "Ele é tímido."}, {"question": "What does Paulo give Julia?", "options": ["A book", "A letter and a flower", "A phone", "A ball"], "correct_index": 1, "explanation": "Ele dá um bilhete e uma flor."}, {"question": "What does Julia say?", "options": ["\"I don't like you\"", "\"I like you too\"", "\"Go away\"", "\"I am busy\""], "correct_index": 1, "explanation": "Ela diz que também gosta dele."}, {"question": "What do they do every day now?", "options": ["They avoid each other", "They walk together", "They argue", "They study"], "correct_index": 1, "explanation": "Eles caminham juntos todos os dias."}], "open_questions": [{"question": "Do you think Paulo's letter was a good idea? Why?", "key_points_pt": ["dar opinião simples", "usar 'because'"]}, {"question": "How do you show someone you like them?", "key_points_pt": ["descrever um gesto simples", "usar vocabulário básico"]}]}}, {"level": "A2", "genre": "neutral", "title": "A Quiet Morning", "paragraphs": ["Maria woke up early and opened the window. The sky was blue and the air was fresh. She made coffee and sat in the kitchen.", "After breakfast, Maria walked to the park near her house. She saw some birds and a man who was reading a book on a bench. She smiled and kept walking.", "When she got home, Maria cleaned the house and listened to music. It was a simple day, but she felt happy and calm."], "paragraphs_pt": ["Maria acordou cedo e abriu a janela. O céu estava azul e o ar estava fresco. Ela fez café e sentou na cozinha.", "Depois do café da manhã, Maria caminhou até o parque perto da casa dela. Ela viu alguns pássaros e um homem que estava lendo um livro em um banco. Ela sorriu e continuou caminhando.", "Quando chegou em casa, Maria limpou a casa e ouviu música. Foi um dia simples, mas ela se sentiu feliz e calma."], "hard_words": ["fresh", "bench", "calm"], "vocab": [{"word": "wake up", "meaning": "acordar", "note": "phrasal verb comum"}, {"word": "fresh", "meaning": "fresco", "note": ""}, {"word": "breakfast", "meaning": "café da manhã", "note": ""}, {"word": "bench", "meaning": "banco (de praça)", "note": ""}, {"word": "clean", "meaning": "limpar", "note": ""}, {"word": "calm", "meaning": "calmo(a)", "note": ""}, {"word": "simple", "meaning": "simples", "note": ""}], "word_meanings": [{"word": "fresh", "meaning": "fresco", "note": ""}, {"word": "bench", "meaning": "banco (de praça)", "note": ""}, {"word": "calm", "meaning": "calmo(a)", "note": ""}, {"word": "was", "meaning": "estava/foi (forma passada de is)", "note": ""}, {"word": "woke up", "meaning": "acordou", "note": "passado de wake up"}, {"word": "made", "meaning": "fez", "note": "passado irregular de make"}, {"word": "sat", "meaning": "sentou", "note": "passado irregular de sit"}, {"word": "walked", "meaning": "caminhou", "note": "passado regular"}, {"word": "saw", "meaning": "viu", "note": "passado irregular de see"}, {"word": "smiled", "meaning": "sorriu", "note": ""}, {"word": "kept", "meaning": "continuou/manteve", "note": "passado irregular de keep"}, {"word": "got", "meaning": "chegou/ficou", "note": "passado irregular de get"}, {"word": "cleaned", "meaning": "limpou", "note": ""}, {"word": "listened", "meaning": "ouviu/escutou", "note": ""}, {"word": "felt", "meaning": "sentiu", "note": "passado irregular de feel"}, {"word": "who", "meaning": "quem/que", "note": ""}, {"word": "when", "meaning": "quando", "note": ""}, {"word": "and", "meaning": "e", "note": ""}, {"word": "but", "meaning": "mas", "note": ""}], "grammar_words": {"cognates": [], "tobe": ["was"], "irregular": ["woke up", "made", "sat", "walked", "saw", "smiled", "kept", "got", "cleaned", "listened", "felt"], "phrasal": ["woke up"], "wh": ["who", "when"], "connectors": ["and", "but"], "comparative": []}, "exercises": {"grammar": [{"point": "Simple past", "explanation_pt": "Usamos o passado simples para ações terminadas, como em 'Maria woke up early' e 'she made coffee'."}], "multiple_choice": [{"question": "What did Maria do first in the morning?", "options": ["She cleaned the house", "She opened the window", "She walked to the park", "She read a book"], "correct_index": 1, "explanation": "No primeiro parágrafo, Maria abriu a janela primeiro."}, {"question": "Where did Maria walk after breakfast?", "options": ["To the market", "To a friend's house", "To the park", "To school"], "correct_index": 2, "explanation": "O texto diz que ela caminhou até o parque."}, {"question": "Who was reading a book?", "options": ["Maria", "A child", "A man", "A woman"], "correct_index": 2, "explanation": "Um homem estava lendo um livro no banco."}, {"question": "What did Maria do at home in the afternoon?", "options": ["She slept", "She cooked", "She cleaned and listened to music", "She watched TV"], "correct_index": 2, "explanation": "No último parágrafo, ela limpou a casa e ouviu música."}, {"question": "How did Maria feel at the end of the day?", "options": ["Tired", "Angry", "Happy and calm", "Sad"], "correct_index": 2, "explanation": "O texto diz que ela se sentiu feliz e calma."}], "open_questions": [{"question": "Do you like quiet mornings like Maria's? Why or why not?", "key_points_pt": ["Falar se gosta de manhãs calmas", "Explicar o motivo com um exemplo pessoal"]}, {"question": "What do you usually do after breakfast?", "key_points_pt": ["Descrever uma rotina simples", "Usar verbos no presente ou passado"]}]}}, {"level": "A2", "genre": "humor", "title": "The Wrong Cat", "paragraphs": ["Tom lived next to Mrs. Silva. One evening, a small gray cat came into his kitchen through the open window. Tom thought it was his cat, Pepper, so he gave it milk and food.", "The cat ate everything and then jumped on the sofa. Tom laughed and said, 'You are very hungry today, Pepper!' But the cat looked at him strangely and did not answer, of course.", "Later, Mrs. Silva knocked on the door and asked, 'Have you seen my cat, Bolinha?' Tom looked at the gray cat and understood his funny mistake. He laughed and gave Bolinha back to Mrs. Silva."], "paragraphs_pt": ["Tom morava ao lado da Sra. Silva. Uma noite, um gatinho cinza entrou na cozinha dele pela janela aberta. Tom achou que era o gato dele, Pepper, então deu leite e comida ao gato.", "O gato comeu tudo e depois pulou no sofá. Tom riu e disse: 'Você está com muita fome hoje, Pepper!' Mas o gato olhou para ele de um jeito estranho e, claro, não respondeu.", "Mais tarde, a Sra. Silva bateu na porta e perguntou: 'Você viu meu gato, o Bolinha?' Tom olhou para o gato cinza e entendeu o engraçado engano dele. Ele riu e devolveu o Bolinha para a Sra. Silva."], "hard_words": ["strangely", "knocked", "mistake"], "vocab": [{"word": "next to", "meaning": "ao lado de", "note": ""}, {"word": "gray", "meaning": "cinza", "note": ""}, {"word": "hungry", "meaning": "com fome", "note": ""}, {"word": "sofa", "meaning": "sofá", "note": ""}, {"word": "strangely", "meaning": "estranhamente", "note": ""}, {"word": "knocked", "meaning": "bateu (na porta)", "note": ""}, {"word": "mistake", "meaning": "erro/engano", "note": ""}], "word_meanings": [{"word": "strangely", "meaning": "estranhamente", "note": ""}, {"word": "knocked", "meaning": "bateu (na porta)", "note": ""}, {"word": "mistake", "meaning": "erro/engano", "note": ""}, {"word": "lived", "meaning": "morava/morou", "note": ""}, {"word": "came", "meaning": "veio", "note": "passado irregular de come"}, {"word": "thought", "meaning": "pensou/achou", "note": "passado irregular de think"}, {"word": "gave", "meaning": "deu", "note": "passado irregular de give"}, {"word": "ate", "meaning": "comeu", "note": "passado irregular de eat"}, {"word": "jumped", "meaning": "pulou", "note": ""}, {"word": "laughed", "meaning": "riu", "note": ""}, {"word": "said", "meaning": "disse", "note": "passado irregular de say"}, {"word": "looked", "meaning": "olhou", "note": ""}, {"word": "asked", "meaning": "perguntou", "note": ""}, {"word": "understood", "meaning": "entendeu", "note": "passado irregular de understand"}, {"word": "gave back", "meaning": "devolveu", "note": "phrasal verb"}, {"word": "so", "meaning": "então/por isso", "note": ""}, {"word": "but", "meaning": "mas", "note": ""}], "grammar_words": {"cognates": [], "tobe": [], "irregular": ["lived", "came", "thought", "gave", "ate", "jumped", "laughed", "said", "looked", "asked", "understood"], "phrasal": [], "wh": [], "connectors": ["so", "but"], "comparative": []}, "exercises": {"grammar": [{"point": "Simple past with irregular verbs", "explanation_pt": "Verbos irregulares mudam de forma, como 'came' (came) e 'ate' (comeu), diferente do padrão -ed."}], "multiple_choice": [{"question": "How did the cat get into Tom's kitchen?", "options": ["Through the door", "Through the open window", "Tom carried it", "It climbed the wall"], "correct_index": 1, "explanation": "O gato entrou pela janela aberta."}, {"question": "Who did Tom think the cat was?", "options": ["A neighbor's dog", "His own cat, Pepper", "A wild animal", "Mrs. Silva's cat"], "correct_index": 1, "explanation": "Tom achou que era o gato dele, Pepper."}, {"question": "What did the cat do after eating?", "options": ["It ran away", "It jumped on the sofa", "It slept in the kitchen", "It went back outside"], "correct_index": 1, "explanation": "O gato pulou no sofá depois de comer."}, {"question": "Who knocked on Tom's door?", "options": ["Pepper's owner", "A police officer", "Mrs. Silva", "A delivery man"], "correct_index": 2, "explanation": "A Sra. Silva bateu na porta."}, {"question": "What was the cat's real name?", "options": ["Pepper", "Bolinha", "Gray", "Tom"], "correct_index": 1, "explanation": "O nome real do gato era Bolinha."}], "open_questions": [{"question": "Have you ever made a funny mistake like Tom? What happened?", "key_points_pt": ["Contar um engano engraçado", "Explicar como resolveu a situação"]}, {"question": "Do you think Tom should be more careful next time? Why?", "key_points_pt": ["Dar opinião pessoal", "Justificar com um argumento simples"]}]}}, {"level": "A2", "genre": "suspense", "title": "The Locked Room", "paragraphs": ["Ana worked late at the old library. When she tried to leave, she found that the front door was locked. She heard a strange noise from the next room and stopped walking.", "Slowly, Ana walked toward the noise with her phone light. She opened the door and saw a window that was open. The wind was moving the curtains, and a book had fallen on the floor.", "Ana laughed with relief because it was only the wind. She picked up the book, closed the window, and finally found the back door, which was open. She went home quickly and locked her own door that night."], "paragraphs_pt": ["Ana trabalhou até tarde na biblioteca antiga. Quando tentou sair, descobriu que a porta da frente estava trancada. Ela ouviu um barulho estranho vindo da sala ao lado e parou de andar.", "Devagar, Ana caminhou em direção ao barulho com a luz do celular. Ela abriu a porta e viu uma janela aberta. O vento estava movendo as cortinas, e um livro tinha caído no chão.", "Ana riu de alívio porque era só o vento. Ela pegou o livro, fechou a janela e finalmente encontrou a porta dos fundos, que estava aberta. Ela foi para casa rapidamente e trancou a própria porta naquela noite."], "hard_words": ["locked", "curtains", "relief"], "vocab": [{"word": "locked", "meaning": "trancado(a)", "note": ""}, {"word": "noise", "meaning": "barulho", "note": ""}, {"word": "curtains", "meaning": "cortinas", "note": ""}, {"word": "fallen", "meaning": "caído", "note": "particípio de fall"}, {"word": "relief", "meaning": "alívio", "note": ""}, {"word": "picked up", "meaning": "pegou/recolheu", "note": "phrasal verb"}, {"word": "quickly", "meaning": "rapidamente", "note": ""}], "word_meanings": [{"word": "locked", "meaning": "trancado(a)", "note": ""}, {"word": "curtains", "meaning": "cortinas", "note": ""}, {"word": "relief", "meaning": "alívio", "note": ""}, {"word": "worked", "meaning": "trabalhou", "note": ""}, {"word": "tried", "meaning": "tentou", "note": ""}, {"word": "found", "meaning": "encontrou/descobriu", "note": "passado irregular de find"}, {"word": "heard", "meaning": "ouviu", "note": "passado irregular de hear"}, {"word": "stopped", "meaning": "parou", "note": ""}, {"word": "walked", "meaning": "caminhou", "note": ""}, {"word": "opened", "meaning": "abriu", "note": ""}, {"word": "saw", "meaning": "viu", "note": "passado irregular de see"}, {"word": "laughed", "meaning": "riu", "note": ""}, {"word": "picked up", "meaning": "pegou/recolheu", "note": "phrasal verb"}, {"word": "closed", "meaning": "fechou", "note": ""}, {"word": "went", "meaning": "foi", "note": "passado irregular de go"}, {"word": "because", "meaning": "porque", "note": ""}, {"word": "and", "meaning": "e", "note": ""}], "grammar_words": {"cognates": [], "tobe": [], "irregular": ["worked", "tried", "found", "heard", "stopped", "walked", "opened", "saw", "laughed", "picked up", "closed", "went"], "phrasal": ["picked up"], "wh": [], "connectors": ["because", "and"], "comparative": []}, "exercises": {"grammar": [{"point": "Past continuous", "explanation_pt": "Usamos o passado contínuo para uma ação em progresso, como em 'The wind was moving the curtains'."}], "multiple_choice": [{"question": "What did Ana find when she tried to leave?", "options": ["The lights were off", "The front door was locked", "The library was full of people", "A window was broken"], "correct_index": 1, "explanation": "A porta da frente estava trancada."}, {"question": "What did Ana use to see in the dark?", "options": ["A candle", "Her phone light", "A flashlight", "The library lamp"], "correct_index": 1, "explanation": "Ela usou a luz do celular."}, {"question": "What was making the noise?", "options": ["A cat", "Another person", "The wind and an open window", "A machine"], "correct_index": 2, "explanation": "O vento estava movendo as cortinas pela janela aberta."}, {"question": "How did Ana feel when she understood the noise?", "options": ["Scared", "Relieved", "Angry", "Confused"], "correct_index": 1, "explanation": "Ela riu de alívio."}, {"question": "How did Ana finally leave the library?", "options": ["Through a window", "Through the front door", "Through the back door", "She called for help"], "correct_index": 2, "explanation": "Ela encontrou a porta dos fundos aberta."}], "open_questions": [{"question": "Would you be scared in Ana's situation? Why or why not?", "key_points_pt": ["Falar se teria medo", "Justificar a resposta"]}, {"question": "What do you do when you hear a strange noise at home?", "key_points_pt": ["Descrever uma reação pessoal", "Usar vocabulário simples de ação"]}]}}, {"level": "A2", "genre": "fairytale", "title": "The Silver Key", "paragraphs": ["Once upon a time, a poor girl named Lila found a small silver key near a river. The key was old, but it shone brightly in the sun. Lila kept it in her pocket and walked home.", "That night, Lila dreamed about a hidden door in the forest. The next morning, she went to the forest and found a wooden door between two big trees. She used the silver key, and the door slowly opened.", "Inside, there was a beautiful garden full of golden flowers. A kind old woman lived there and gave Lila a basket of flowers as a gift. Lila thanked her and returned home, happier than ever before."], "paragraphs_pt": ["Era uma vez uma garota pobre chamada Lila que encontrou uma pequena chave de prata perto de um rio. A chave era antiga, mas brilhava sob o sol. Lila guardou a chave no bolso e caminhou até em casa.", "Naquela noite, Lila sonhou com uma porta escondida na floresta. Na manhã seguinte, ela foi até a floresta e encontrou uma porta de madeira entre duas árvores grandes. Ela usou a chave de prata, e a porta abriu devagar.", "Lá dentro, havia um jardim lindo cheio de flores douradas. Uma senhora bondosa morava ali e deu a Lila uma cesta de flores como presente. Lila agradeceu e voltou para casa, mais feliz do que nunca."], "hard_words": ["shone", "hidden", "golden"], "vocab": [{"word": "once upon a time", "meaning": "era uma vez", "note": "expressão de contos de fadas"}, {"word": "shone", "meaning": "brilhou", "note": "passado irregular de shine"}, {"word": "hidden", "meaning": "escondido(a)", "note": ""}, {"word": "wooden", "meaning": "de madeira", "note": ""}, {"word": "golden", "meaning": "dourado(a)", "note": ""}, {"word": "kind", "meaning": "gentil/bondoso(a)", "note": ""}, {"word": "gift", "meaning": "presente", "note": ""}, {"word": "happier", "meaning": "mais feliz", "note": "comparativo de happy"}], "word_meanings": [{"word": "shone", "meaning": "brilhou", "note": "passado irregular de shine"}, {"word": "hidden", "meaning": "escondido(a)", "note": ""}, {"word": "golden", "meaning": "dourado(a)", "note": ""}, {"word": "was", "meaning": "era/estava", "note": ""}, {"word": "found", "meaning": "encontrou", "note": "passado irregular de find"}, {"word": "kept", "meaning": "guardou", "note": "passado irregular de keep"}, {"word": "walked", "meaning": "caminhou", "note": ""}, {"word": "dreamed", "meaning": "sonhou", "note": ""}, {"word": "went", "meaning": "foi", "note": "passado irregular de go"}, {"word": "used", "meaning": "usou", "note": ""}, {"word": "opened", "meaning": "abriu", "note": ""}, {"word": "lived", "meaning": "morava", "note": ""}, {"word": "gave", "meaning": "deu", "note": "passado irregular de give"}, {"word": "thanked", "meaning": "agradeceu", "note": ""}, {"word": "returned", "meaning": "voltou", "note": ""}, {"word": "but", "meaning": "mas", "note": ""}, {"word": "and", "meaning": "e", "note": ""}, {"word": "happier", "meaning": "mais feliz", "note": "comparativo de happy"}], "grammar_words": {"cognates": [], "tobe": ["was"], "irregular": ["found", "kept", "walked", "dreamed", "went", "used", "opened", "lived", "gave", "thanked", "returned"], "phrasal": [], "wh": [], "connectors": ["but", "and"], "comparative": ["happier"]}, "exercises": {"grammar": [{"point": "Comparatives", "explanation_pt": "Usamos '-er' para comparar coisas, como em 'happier than ever before' (mais feliz do que nunca)."}], "multiple_choice": [{"question": "Where did Lila find the silver key?", "options": ["In the forest", "Near a river", "In her garden", "In a shop"], "correct_index": 1, "explanation": "Ela encontrou a chave perto de um rio."}, {"question": "What did Lila dream about?", "options": ["A silver key", "A hidden door in the forest", "A garden of flowers", "An old woman"], "correct_index": 1, "explanation": "Ela sonhou com uma porta escondida na floresta."}, {"question": "Where was the wooden door?", "options": ["Near the river", "Between two big trees", "Inside her house", "On top of a hill"], "correct_index": 1, "explanation": "A porta ficava entre duas árvores grandes."}, {"question": "What did Lila find inside the door?", "options": ["A castle", "A beautiful garden", "A treasure box", "An empty room"], "correct_index": 1, "explanation": "Ela encontrou um jardim lindo cheio de flores douradas."}, {"question": "What gift did the old woman give Lila?", "options": ["A silver key", "A basket of flowers", "A new dress", "A book"], "correct_index": 1, "explanation": "A senhora deu a Lila uma cesta de flores."}], "open_questions": [{"question": "What do you think the old woman's garden looked like?", "key_points_pt": ["Descrever o jardim com imaginação", "Usar adjetivos simples"]}, {"question": "If you found a magic key, where would you use it?", "key_points_pt": ["Dar uma resposta imaginativa", "Justificar a escolha"]}]}}, {"level": "A2", "genre": "fable", "title": "The Ant and the Butterfly", "paragraphs": ["A little ant worked hard every day. She carried food to her home under the ground. A beautiful butterfly flew around the garden and laughed at the ant because she never stopped to rest.", "'Why do you work so much?' asked the butterfly. 'Come and fly with me!' But the ant said, 'Winter is coming, and I must be ready.' The butterfly did not listen and kept flying happily.", "When winter came, it was cold and there were no flowers. The butterfly had no food, but the ant had a lot of food in her home. The kind ant shared her food with the butterfly, who learned an important lesson about planning ahead."], "paragraphs_pt": ["Uma formiguinha trabalhava duro todos os dias. Ela carregava comida para a casa dela embaixo da terra. Uma linda borboleta voava pelo jardim e ria da formiga porque ela nunca parava para descansar.", "'Por que você trabalha tanto?' perguntou a borboleta. 'Venha voar comigo!' Mas a formiga disse: 'O inverno está chegando, e eu preciso estar pronta.' A borboleta não ouviu e continuou voando alegremente.", "Quando o inverno chegou, estava frio e não havia flores. A borboleta não tinha comida, mas a formiga tinha muita comida em casa. A formiga gentil dividiu a comida dela com a borboleta, que aprendeu uma lição importante sobre se planejar."], "hard_words": ["carried", "rest", "ahead"], "vocab": [{"word": "ant", "meaning": "formiga", "note": ""}, {"word": "carried", "meaning": "carregou/carregava", "note": ""}, {"word": "rest", "meaning": "descansar", "note": ""}, {"word": "ready", "meaning": "pronto(a)", "note": ""}, {"word": "shared", "meaning": "dividiu/compartilhou", "note": ""}, {"word": "lesson", "meaning": "lição", "note": ""}, {"word": "ahead", "meaning": "com antecedência/à frente", "note": ""}], "word_meanings": [{"word": "carried", "meaning": "carregou/carregava", "note": ""}, {"word": "rest", "meaning": "descansar", "note": ""}, {"word": "ahead", "meaning": "com antecedência/à frente", "note": ""}, {"word": "was", "meaning": "estava", "note": ""}, {"word": "worked", "meaning": "trabalhava", "note": ""}, {"word": "flew", "meaning": "voou/voava", "note": "passado irregular de fly"}, {"word": "laughed", "meaning": "riu", "note": ""}, {"word": "stopped", "meaning": "parou", "note": ""}, {"word": "asked", "meaning": "perguntou", "note": ""}, {"word": "said", "meaning": "disse", "note": "passado irregular de say"}, {"word": "kept", "meaning": "continuou", "note": "passado irregular de keep"}, {"word": "came", "meaning": "chegou/veio", "note": "passado irregular de come"}, {"word": "had", "meaning": "tinha", "note": "passado irregular de have"}, {"word": "shared", "meaning": "dividiu", "note": ""}, {"word": "learned", "meaning": "aprendeu", "note": ""}, {"word": "why", "meaning": "por que", "note": ""}, {"word": "but", "meaning": "mas", "note": ""}, {"word": "because", "meaning": "porque", "note": ""}, {"word": "and", "meaning": "e", "note": ""}], "grammar_words": {"cognates": [], "tobe": ["was"], "irregular": ["worked", "flew", "laughed", "stopped", "asked", "said", "kept", "came", "had", "shared", "learned"], "phrasal": [], "wh": ["why"], "connectors": ["but", "because", "and"], "comparative": []}, "exercises": {"grammar": [{"point": "Simple past vs present continuous", "explanation_pt": "A fábula mistura o passado simples da narrativa com uma frase no presente contínuo, 'Winter is coming', para dar urgência."}], "multiple_choice": [{"question": "What did the ant do every day?", "options": ["She slept a lot", "She worked and carried food", "She flew around", "She talked to flowers"], "correct_index": 1, "explanation": "A formiga trabalhava e carregava comida todos os dias."}, {"question": "Why did the butterfly laugh at the ant?", "options": ["Because the ant was slow", "Because the ant never stopped to rest", "Because the ant was small", "Because the ant could not fly"], "correct_index": 1, "explanation": "A borboleta ria porque a formiga nunca parava para descansar."}, {"question": "What did the ant say about winter?", "options": ["It was far away", "It was coming, so she must be ready", "It would never come", "It was already there"], "correct_index": 1, "explanation": "A formiga disse que o inverno estava chegando e que precisava estar pronta."}, {"question": "What happened to the butterfly in winter?", "options": ["She found a lot of food", "She had no food", "She flew away", "She slept all winter"], "correct_index": 1, "explanation": "A borboleta não tinha comida no inverno."}, {"question": "What did the ant do for the butterfly?", "options": ["She ignored her", "She shared her food", "She sent her away", "She gave her a house"], "correct_index": 1, "explanation": "A formiga dividiu sua comida com a borboleta."}], "open_questions": [{"question": "What lesson does this fable teach us?", "key_points_pt": ["Falar sobre a importância de se planejar", "Comparar trabalho e diversão"]}, {"question": "Are you more like the ant or the butterfly? Why?", "key_points_pt": ["Dar uma opinião pessoal", "Justificar com um exemplo"]}]}}, {"level": "A2", "genre": "adventure", "title": "The Lost Map", "paragraphs": ["Sam and his sister Beth found an old map in their grandfather's box. The map showed a path through the mountains to a hidden cave. They decided to explore it during their summer vacation.", "The next day, they walked up the mountain for three hours. It was difficult, but they helped each other. Finally, they found the cave behind some big rocks, just like the map showed.", "Inside the cave, they discovered old coins and a wooden box. They were not rich, but they were very excited. Sam and Beth took some coins home and told their grandfather about their amazing adventure."], "paragraphs_pt": ["Sam e sua irmã Beth encontraram um mapa antigo na caixa do avô deles. O mapa mostrava um caminho pelas montanhas até uma caverna escondida. Eles decidiram explorar o lugar durante as férias de verão.", "No dia seguinte, eles caminharam montanha acima por três horas. Foi difícil, mas eles se ajudaram um ao outro. Finalmente, encontraram a caverna atrás de umas pedras grandes, exatamente como o mapa mostrava.", "Dentro da caverna, eles descobriram moedas antigas e uma caixa de madeira. Eles não ficaram ricos, mas ficaram muito animados. Sam e Beth levaram algumas moedas para casa e contaram ao avô sobre a aventura incrível deles."], "hard_words": ["cave", "coins", "discovered"], "vocab": [{"word": "map", "meaning": "mapa", "note": ""}, {"word": "path", "meaning": "caminho/trilha", "note": ""}, {"word": "cave", "meaning": "caverna", "note": ""}, {"word": "explore", "meaning": "explorar", "note": ""}, {"word": "discovered", "meaning": "descobriram", "note": ""}, {"word": "coins", "meaning": "moedas", "note": ""}, {"word": "excited", "meaning": "animado(a)/empolgado(a)", "note": ""}], "word_meanings": [{"word": "cave", "meaning": "caverna", "note": ""}, {"word": "coins", "meaning": "moedas", "note": ""}, {"word": "discovered", "meaning": "descobriram", "note": ""}, {"word": "was", "meaning": "estava/foi", "note": ""}, {"word": "were", "meaning": "estavam/eram", "note": ""}, {"word": "found", "meaning": "encontraram", "note": "passado irregular de find"}, {"word": "showed", "meaning": "mostrava", "note": ""}, {"word": "decided", "meaning": "decidiram", "note": ""}, {"word": "walked", "meaning": "caminharam", "note": ""}, {"word": "helped", "meaning": "ajudaram", "note": ""}, {"word": "took", "meaning": "levaram/pegaram", "note": "passado irregular de take"}, {"word": "told", "meaning": "contaram", "note": "passado irregular de tell"}, {"word": "but", "meaning": "mas", "note": ""}, {"word": "finally", "meaning": "finalmente", "note": ""}, {"word": "harder", "meaning": "mais difícil", "note": "comparativo de hard"}], "grammar_words": {"cognates": [], "tobe": ["was", "were"], "irregular": ["found", "showed", "decided", "walked", "helped", "took", "told"], "phrasal": [], "wh": [], "connectors": ["but", "finally"], "comparative": []}, "exercises": {"grammar": [{"point": "Sequencing with time words", "explanation_pt": "Palavras como 'the next day' e 'finally' ajudam a organizar a ordem dos eventos na história."}], "multiple_choice": [{"question": "Where did Sam and Beth find the map?", "options": ["In a book", "In their grandfather's box", "At school", "In the mountains"], "correct_index": 1, "explanation": "Eles encontraram o mapa na caixa do avô."}, {"question": "What did the map show?", "options": ["A path to a city", "A path to a hidden cave", "A path to the beach", "A path to a lake"], "correct_index": 1, "explanation": "O mapa mostrava um caminho até uma caverna escondida."}, {"question": "How long did they walk up the mountain?", "options": ["One hour", "Two hours", "Three hours", "All day"], "correct_index": 2, "explanation": "Eles caminharam por três horas."}, {"question": "Where did they find the cave?", "options": ["Near a river", "Behind some big rocks", "Under a tree", "Next to a lake"], "correct_index": 1, "explanation": "Eles encontraram a caverna atrás de umas pedras grandes."}, {"question": "What did they discover inside the cave?", "options": ["Old books", "Coins and a wooden box", "Animals", "Nothing"], "correct_index": 1, "explanation": "Eles descobriram moedas antigas e uma caixa de madeira."}], "open_questions": [{"question": "Would you like to go on an adventure like Sam and Beth? Why?", "key_points_pt": ["Dar opinião pessoal", "Explicar o motivo"]}, {"question": "What do you think was inside the wooden box?", "key_points_pt": ["Usar a imaginação", "Descrever com palavras simples"]}]}}, {"level": "A2", "genre": "travel", "title": "A Trip to the Mountains", "paragraphs": ["Last July, Carla traveled to a small town in the mountains with her family. They took a bus for five hours, and Carla looked out the window at the green hills the whole time.", "In the town, they stayed in a small hotel with a beautiful view. Every morning, they walked in the mountains and visited local markets. Carla tried new food and bought a colorful scarf for her mother.", "On the last day, Carla climbed a small hill with her father and watched the sunset. It was more beautiful than any picture she had seen before. She promised to return to the mountains again someday."], "paragraphs_pt": ["Em julho passado, Carla viajou para uma cidade pequena nas montanhas com a família dela. Eles pegaram um ônibus por cinco horas, e Carla olhou pela janela para as colinas verdes o tempo todo.", "Na cidade, eles ficaram em um hotel pequeno com uma vista linda. Todas as manhãs, eles caminhavam nas montanhas e visitavam mercados locais. Carla experimentou comidas novas e comprou um lenço colorido para a mãe dela.", "No último dia, Carla subiu uma pequena colina com o pai e assistiu ao pôr do sol. Foi mais bonito do que qualquer foto que ela já tinha visto antes. Ela prometeu voltar para as montanhas de novo algum dia."], "hard_words": ["hills", "scarf", "sunset"], "vocab": [{"word": "traveled", "meaning": "viajou", "note": ""}, {"word": "hills", "meaning": "colinas", "note": ""}, {"word": "view", "meaning": "vista", "note": ""}, {"word": "local", "meaning": "local", "note": ""}, {"word": "scarf", "meaning": "lenço/cachecol", "note": ""}, {"word": "sunset", "meaning": "pôr do sol", "note": ""}, {"word": "promised", "meaning": "prometeu", "note": ""}], "word_meanings": [{"word": "hills", "meaning": "colinas", "note": ""}, {"word": "scarf", "meaning": "lenço/cachecol", "note": ""}, {"word": "sunset", "meaning": "pôr do sol", "note": ""}, {"word": "took", "meaning": "pegaram", "note": "passado irregular de take"}, {"word": "looked", "meaning": "olhou", "note": ""}, {"word": "stayed", "meaning": "ficaram", "note": ""}, {"word": "walked", "meaning": "caminhavam", "note": ""}, {"word": "visited", "meaning": "visitavam", "note": ""}, {"word": "tried", "meaning": "experimentou", "note": ""}, {"word": "bought", "meaning": "comprou", "note": "passado irregular de buy"}, {"word": "climbed", "meaning": "subiu", "note": ""}, {"word": "watched", "meaning": "assistiu", "note": ""}, {"word": "promised", "meaning": "prometeu", "note": ""}, {"word": "and", "meaning": "e", "note": ""}, {"word": "more beautiful", "meaning": "mais bonito(a)", "note": "comparativo"}], "grammar_words": {"cognates": [], "tobe": [], "irregular": ["took", "looked", "stayed", "walked", "visited", "tried", "bought", "climbed", "watched", "promised"], "phrasal": [], "wh": [], "connectors": ["and"], "comparative": ["more beautiful"]}, "exercises": {"grammar": [{"point": "Comparatives with 'more'", "explanation_pt": "Para adjetivos longos, usamos 'more' antes do adjetivo, como em 'more beautiful than any picture'."}], "multiple_choice": [{"question": "How did Carla's family travel to the mountains?", "options": ["By car", "By train", "By bus", "By plane"], "correct_index": 2, "explanation": "Eles pegaram um ônibus por cinco horas."}, {"question": "What did they do every morning in the town?", "options": ["They slept late", "They walked and visited markets", "They stayed at the hotel", "They watched TV"], "correct_index": 1, "explanation": "Todas as manhãs eles caminhavam e visitavam mercados locais."}, {"question": "What did Carla buy for her mother?", "options": ["A hat", "A colorful scarf", "Shoes", "A book"], "correct_index": 1, "explanation": "Ela comprou um lenço colorido para a mãe."}, {"question": "Who did Carla climb the hill with?", "options": ["Her mother", "Her father", "Her friend", "Alone"], "correct_index": 1, "explanation": "Ela subiu a colina com o pai."}, {"question": "What did Carla promise at the end of the trip?", "options": ["To never travel again", "To return to the mountains someday", "To move to the town", "To buy a house there"], "correct_index": 1, "explanation": "Ela prometeu voltar para as montanhas algum dia."}], "open_questions": [{"question": "What is your favorite place to travel? Why?", "key_points_pt": ["Descrever um lugar", "Explicar o motivo da preferência"]}, {"question": "Do you prefer the mountains or the beach for vacation? Why?", "key_points_pt": ["Dar uma opinião", "Comparar as duas opções"]}]}}, {"level": "A2", "genre": "cooking", "title": "Grandma's Recipe", "paragraphs": ["Every Sunday, Paulo visited his grandmother and helped her cook lunch. Last Sunday, she taught him how to make her famous rice and beans with fresh vegetables from her garden.", "First, Paulo washed the vegetables and cut them into small pieces. Then, his grandmother added the rice, beans, and some spices to the pot. They cooked everything slowly and talked about her childhood.", "When the food was ready, the whole family sat at the table together. Everyone said the food was more delicious than usual. Paulo felt proud because he helped cook the meal, and he asked his grandmother for the recipe."], "paragraphs_pt": ["Todo domingo, Paulo visitava a avó dele e ajudava a cozinhar o almoço. No domingo passado, ela ensinou a ele como fazer o famoso arroz e feijão dela com legumes frescos do jardim dela.", "Primeiro, Paulo lavou os legumes e os cortou em pedaços pequenos. Depois, a avó dele adicionou o arroz, o feijão e alguns temperos na panela. Eles cozinharam tudo devagar e conversaram sobre a infância dela.", "Quando a comida ficou pronta, a família toda sentou à mesa junta. Todo mundo disse que a comida estava mais deliciosa do que de costume. Paulo se sentiu orgulhoso porque ajudou a cozinhar a refeição, e pediu a receita para a avó."], "hard_words": ["spices", "pot", "proud"], "vocab": [{"word": "taught", "meaning": "ensinou", "note": "passado irregular de teach"}, {"word": "vegetables", "meaning": "legumes/vegetais", "note": ""}, {"word": "spices", "meaning": "temperos/especiarias", "note": ""}, {"word": "pot", "meaning": "panela", "note": ""}, {"word": "childhood", "meaning": "infância", "note": ""}, {"word": "delicious", "meaning": "delicioso(a)", "note": ""}, {"word": "proud", "meaning": "orgulhoso(a)", "note": ""}, {"word": "recipe", "meaning": "receita", "note": ""}], "word_meanings": [{"word": "spices", "meaning": "temperos/especiarias", "note": ""}, {"word": "pot", "meaning": "panela", "note": ""}, {"word": "proud", "meaning": "orgulhoso(a)", "note": ""}, {"word": "was", "meaning": "estava/ficou", "note": ""}, {"word": "visited", "meaning": "visitava", "note": ""}, {"word": "helped", "meaning": "ajudava/ajudou", "note": ""}, {"word": "taught", "meaning": "ensinou", "note": "passado irregular de teach"}, {"word": "washed", "meaning": "lavou", "note": ""}, {"word": "cut", "meaning": "cortou", "note": "passado irregular de cut (mesma forma)"}, {"word": "added", "meaning": "adicionou", "note": ""}, {"word": "cooked", "meaning": "cozinharam", "note": ""}, {"word": "talked", "meaning": "conversaram", "note": ""}, {"word": "sat", "meaning": "sentou", "note": "passado irregular de sit"}, {"word": "said", "meaning": "disse", "note": "passado irregular de say"}, {"word": "felt", "meaning": "sentiu", "note": "passado irregular de feel"}, {"word": "asked", "meaning": "pediu/perguntou", "note": ""}, {"word": "first", "meaning": "primeiro", "note": ""}, {"word": "then", "meaning": "depois/então", "note": ""}, {"word": "because", "meaning": "porque", "note": ""}, {"word": "and", "meaning": "e", "note": ""}, {"word": "more delicious", "meaning": "mais delicioso(a)", "note": "comparativo"}], "grammar_words": {"cognates": [], "tobe": ["was"], "irregular": ["visited", "helped", "taught", "washed", "cut", "added", "cooked", "talked", "sat", "said", "felt", "asked"], "phrasal": [], "wh": [], "connectors": ["first", "then", "because", "and"], "comparative": ["more delicious"]}, "exercises": {"grammar": [{"point": "Sequence connectors", "explanation_pt": "Palavras como 'first' e 'then' ajudam a explicar a ordem dos passos de uma receita."}], "multiple_choice": [{"question": "What did Paulo's grandmother teach him to make?", "options": ["A cake", "Rice and beans with vegetables", "Soup", "Bread"], "correct_index": 1, "explanation": "Ela ensinou a fazer arroz e feijão com legumes."}, {"question": "What did Paulo do first?", "options": ["He cut the vegetables", "He washed the vegetables", "He cooked the rice", "He set the table"], "correct_index": 1, "explanation": "Primeiro, Paulo lavou os legumes."}, {"question": "What did they talk about while cooking?", "options": ["The weather", "Her childhood", "School", "Music"], "correct_index": 1, "explanation": "Eles conversaram sobre a infância da avó."}, {"question": "How did the family describe the food?", "options": ["Too spicy", "More delicious than usual", "Cold", "Simple"], "correct_index": 1, "explanation": "Todos disseram que a comida estava mais deliciosa do que de costume."}, {"question": "How did Paulo feel at the end?", "options": ["Tired", "Bored", "Proud", "Confused"], "correct_index": 2, "explanation": "Paulo se sentiu orgulhoso por ajudar a cozinhar."}], "open_questions": [{"question": "What is a special recipe in your family? Describe it.", "key_points_pt": ["Descrever uma receita de família", "Usar vocabulário de comida"]}, {"question": "Do you enjoy cooking with your family? Why or why not?", "key_points_pt": ["Dar opinião pessoal", "Explicar o motivo"]}]}}, {"level": "A2", "genre": "sports", "title": "The Final Match", "paragraphs": ["Diego played soccer for his school team. Before the final match, he was very nervous because his team needed to win to become champions. His coach told him, 'Believe in yourself and play with your heart.'", "During the match, the game was difficult and the other team was strong. In the second half, Diego ran fast and scored a beautiful goal. His teammates ran to him and celebrated with big smiles.", "At the end, Diego's team won the match two to one. Everyone was happier than ever, and the coach gave Diego a small trophy for the best player. Diego learned that hard work and teamwork always help."], "paragraphs_pt": ["Diego jogava futebol pelo time da escola dele. Antes da partida final, ele estava muito nervoso porque o time dele precisava vencer para se tornar campeão. O técnico dele disse: 'Acredite em si mesmo e jogue com o coração.'", "Durante a partida, o jogo estava difícil e o outro time era forte. No segundo tempo, Diego correu rápido e marcou um golaço. Os companheiros de time correram até ele e comemoraram com grandes sorrisos.", "No final, o time de Diego venceu a partida por dois a um. Todo mundo estava mais feliz do que nunca, e o técnico deu a Diego um pequeno troféu de melhor jogador. Diego aprendeu que o trabalho duro e o trabalho em equipe sempre ajudam."], "hard_words": ["nervous", "scored", "teamwork"], "vocab": [{"word": "coach", "meaning": "técnico(a)", "note": ""}, {"word": "nervous", "meaning": "nervoso(a)", "note": ""}, {"word": "scored", "meaning": "marcou (um gol)", "note": ""}, {"word": "teammates", "meaning": "companheiros de time", "note": ""}, {"word": "celebrated", "meaning": "comemoraram", "note": ""}, {"word": "trophy", "meaning": "troféu", "note": ""}, {"word": "teamwork", "meaning": "trabalho em equipe", "note": ""}], "word_meanings": [{"word": "nervous", "meaning": "nervoso(a)", "note": ""}, {"word": "scored", "meaning": "marcou (um gol)", "note": ""}, {"word": "teamwork", "meaning": "trabalho em equipe", "note": ""}, {"word": "was", "meaning": "estava/era", "note": ""}, {"word": "played", "meaning": "jogava", "note": ""}, {"word": "needed", "meaning": "precisava", "note": ""}, {"word": "told", "meaning": "disse", "note": "passado irregular de tell"}, {"word": "ran", "meaning": "correu", "note": "passado irregular de run"}, {"word": "celebrated", "meaning": "comemoraram", "note": ""}, {"word": "won", "meaning": "venceu/ganhou", "note": "passado irregular de win"}, {"word": "gave", "meaning": "deu", "note": "passado irregular de give"}, {"word": "learned", "meaning": "aprendeu", "note": ""}, {"word": "because", "meaning": "porque", "note": ""}, {"word": "and", "meaning": "e", "note": ""}, {"word": "happier", "meaning": "mais feliz", "note": "comparativo de happy"}], "grammar_words": {"cognates": [], "tobe": ["was"], "irregular": ["played", "needed", "told", "ran", "celebrated", "won", "gave", "learned"], "phrasal": [], "wh": [], "connectors": ["because", "and"], "comparative": ["happier"]}, "exercises": {"grammar": [{"point": "Simple past for a series of events", "explanation_pt": "A história narra eventos em ordem usando verbos no passado, como 'ran', 'scored' e 'won'."}], "multiple_choice": [{"question": "Why was Diego nervous before the match?", "options": ["He was sick", "His team needed to win to become champions", "He forgot his shoes", "It was raining"], "correct_index": 1, "explanation": "Ele estava nervoso porque o time precisava vencer para ser campeão."}, {"question": "What did the coach tell Diego?", "options": ["To rest more", "To believe in himself and play with his heart", "To stay on the bench", "To change teams"], "correct_index": 1, "explanation": "O técnico disse para acreditar em si mesmo e jogar com o coração."}, {"question": "What did Diego do in the second half?", "options": ["He got injured", "He scored a goal", "He left the game", "He talked to the coach"], "correct_index": 1, "explanation": "No segundo tempo, Diego marcou um golaço."}, {"question": "What was the final score of the match?", "options": ["One to one", "Two to one", "Three to zero", "Zero to zero"], "correct_index": 1, "explanation": "O time de Diego venceu por dois a um."}, {"question": "What did Diego receive at the end?", "options": ["A new ball", "A trophy for the best player", "A medal for participation", "Nothing"], "correct_index": 1, "explanation": "O técnico deu a ele um troféu de melhor jogador."}], "open_questions": [{"question": "Do you play any sports? Which ones?", "key_points_pt": ["Falar sobre esportes praticados", "Descrever com frases simples"]}, {"question": "Why is teamwork important in sports?", "key_points_pt": ["Explicar a importância do trabalho em equipe", "Dar um exemplo"]}]}}, {"level": "A2", "genre": "slice", "title": "A Busy Afternoon", "paragraphs": ["After school, Julia picked up her little brother, Davi, from his classroom. They walked home together and talked about their day. Davi was excited because he drew a picture of a dinosaur.", "At home, Julia helped Davi with his homework while their mother cooked dinner. Davi asked many questions, and Julia answered them patiently. Then, they watched a short cartoon together before dinner.", "During dinner, the family talked about their day and laughed at Davi's funny stories. It was an ordinary afternoon, but Julia felt grateful for these simple moments with her family."], "paragraphs_pt": ["Depois da escola, Julia buscou o irmãozinho dela, Davi, na sala de aula. Eles caminharam juntos até em casa e conversaram sobre o dia deles. Davi estava animado porque desenhou um dinossauro.", "Em casa, Julia ajudou Davi com o dever de casa enquanto a mãe deles cozinhava o jantar. Davi fez muitas perguntas, e Julia respondeu com paciência. Depois, eles assistiram a um desenho animado curto antes do jantar.", "Durante o jantar, a família conversou sobre o dia deles e riu das histórias engraçadas de Davi. Foi uma tarde comum, mas Julia se sentiu grata por esses momentos simples com a família."], "hard_words": ["picked up", "patiently", "grateful"], "vocab": [{"word": "picked up", "meaning": "buscou/pegou", "note": "phrasal verb"}, {"word": "homework", "meaning": "dever de casa", "note": ""}, {"word": "patiently", "meaning": "com paciência", "note": ""}, {"word": "cartoon", "meaning": "desenho animado", "note": ""}, {"word": "laughed", "meaning": "riram", "note": ""}, {"word": "ordinary", "meaning": "comum/normal", "note": ""}, {"word": "grateful", "meaning": "grato(a)", "note": ""}], "word_meanings": [{"word": "picked up", "meaning": "buscou/pegou", "note": "phrasal verb"}, {"word": "patiently", "meaning": "com paciência", "note": ""}, {"word": "grateful", "meaning": "grato(a)", "note": ""}, {"word": "was", "meaning": "estava", "note": ""}, {"word": "walked", "meaning": "caminharam", "note": ""}, {"word": "talked", "meaning": "conversaram", "note": ""}, {"word": "drew", "meaning": "desenhou", "note": "passado irregular de draw"}, {"word": "helped", "meaning": "ajudou", "note": ""}, {"word": "cooked", "meaning": "cozinhava", "note": ""}, {"word": "asked", "meaning": "fez (perguntas)", "note": ""}, {"word": "answered", "meaning": "respondeu", "note": ""}, {"word": "watched", "meaning": "assistiram", "note": ""}, {"word": "laughed", "meaning": "riram", "note": ""}, {"word": "felt", "meaning": "se sentiu", "note": "passado irregular de feel"}, {"word": "while", "meaning": "enquanto", "note": ""}, {"word": "then", "meaning": "depois/então", "note": ""}, {"word": "because", "meaning": "porque", "note": ""}, {"word": "but", "meaning": "mas", "note": ""}, {"word": "and", "meaning": "e", "note": ""}], "grammar_words": {"cognates": [], "tobe": ["was"], "irregular": ["walked", "talked", "drew", "helped", "cooked", "asked", "answered", "watched", "laughed", "felt"], "phrasal": ["picked up"], "wh": [], "connectors": ["while", "then", "because", "but", "and"], "comparative": []}, "exercises": {"grammar": [{"point": "Connectors of time and contrast", "explanation_pt": "A palavra 'while' mostra duas ações ao mesmo tempo, e 'but' mostra contraste, como em 'ordinary afternoon, but... grateful'."}], "multiple_choice": [{"question": "Who did Julia pick up after school?", "options": ["Her friend", "Her little brother, Davi", "Her mother", "Her classmate"], "correct_index": 1, "explanation": "Julia buscou o irmãozinho dela, Davi."}, {"question": "Why was Davi excited?", "options": ["He got a new toy", "He drew a picture of a dinosaur", "He finished his homework", "He watched a movie"], "correct_index": 1, "explanation": "Ele estava animado porque desenhou um dinossauro."}, {"question": "What was their mother doing at home?", "options": ["Cleaning the house", "Cooking dinner", "Watching TV", "Reading a book"], "correct_index": 1, "explanation": "A mãe deles estava cozinhando o jantar."}, {"question": "What did Julia and Davi do before dinner?", "options": ["They played outside", "They watched a short cartoon", "They went shopping", "They slept"], "correct_index": 1, "explanation": "Eles assistiram a um desenho animado curto antes do jantar."}, {"question": "How did Julia feel about the afternoon?", "options": ["Bored", "Grateful", "Angry", "Confused"], "correct_index": 1, "explanation": "Julia se sentiu grata pelos momentos simples com a família."}], "open_questions": [{"question": "Describe a normal afternoon in your life.", "key_points_pt": ["Descrever uma rotina simples", "Usar conectores de tempo"]}, {"question": "Why are simple family moments important?", "key_points_pt": ["Dar opinião pessoal", "Explicar com um exemplo"]}]}}, {"level": "A2", "genre": "diary", "title": "My First Week at Work", "paragraphs": ["Dear diary, today was my first day at the new office. I felt nervous, but everyone was friendly. My boss showed me my desk and explained my new tasks carefully.", "On Wednesday, I met my coworkers during lunch. We talked about our hobbies, and I learned that two of them also like to play the guitar. I felt more comfortable after that conversation.", "Today is Friday, and my first week is finally over. It was tiring, but I am proud of myself. I hope next week will be even better, and I already feel like part of the team."], "paragraphs_pt": ["Querido diário, hoje foi meu primeiro dia no escritório novo. Eu me senti nervoso, mas todo mundo foi simpático. Meu chefe me mostrou minha mesa e explicou minhas novas tarefas com cuidado.", "Na quarta-feira, conheci meus colegas de trabalho durante o almoço. Conversamos sobre nossos hobbies, e eu descobri que dois deles também gostam de tocar violão. Eu me senti mais à vontade depois daquela conversa.", "Hoje é sexta-feira, e minha primeira semana finalmente terminou. Foi cansativo, mas estou orgulhoso de mim mesmo. Espero que a próxima semana seja ainda melhor, e eu já me sinto parte da equipe."], "hard_words": ["coworkers", "tiring", "comfortable"], "vocab": [{"word": "office", "meaning": "escritório", "note": ""}, {"word": "boss", "meaning": "chefe", "note": ""}, {"word": "tasks", "meaning": "tarefas", "note": ""}, {"word": "coworkers", "meaning": "colegas de trabalho", "note": ""}, {"word": "comfortable", "meaning": "confortável/à vontade", "note": ""}, {"word": "tiring", "meaning": "cansativo(a)", "note": ""}, {"word": "proud", "meaning": "orgulhoso(a)", "note": ""}], "word_meanings": [{"word": "coworkers", "meaning": "colegas de trabalho", "note": ""}, {"word": "tiring", "meaning": "cansativo(a)", "note": ""}, {"word": "comfortable", "meaning": "confortável/à vontade", "note": ""}, {"word": "was", "meaning": "foi/estava", "note": ""}, {"word": "is", "meaning": "é", "note": ""}, {"word": "am", "meaning": "estou", "note": ""}, {"word": "felt", "meaning": "senti", "note": "passado irregular de feel"}, {"word": "showed", "meaning": "mostrou", "note": ""}, {"word": "explained", "meaning": "explicou", "note": ""}, {"word": "met", "meaning": "conheci", "note": "passado irregular de meet"}, {"word": "talked", "meaning": "conversamos", "note": ""}, {"word": "learned", "meaning": "descobri/aprendi", "note": ""}, {"word": "but", "meaning": "mas", "note": ""}, {"word": "and", "meaning": "e", "note": ""}, {"word": "more comfortable", "meaning": "mais confortável/à vontade", "note": "comparativo"}, {"word": "better", "meaning": "melhor", "note": "comparativo irregular de good"}], "grammar_words": {"cognates": [], "tobe": ["was", "is", "am"], "irregular": ["felt", "showed", "explained", "met", "talked", "learned"], "phrasal": [], "wh": [], "connectors": ["but", "and"], "comparative": ["more comfortable", "better"]}, "exercises": {"grammar": [{"point": "Diary style with present and past", "explanation_pt": "Diários usam o passado para contar o que aconteceu e o presente para o dia atual, como em 'Today is Friday'."}], "multiple_choice": [{"question": "How did the writer feel on the first day?", "options": ["Bored", "Nervous", "Angry", "Confident"], "correct_index": 1, "explanation": "O escritor se sentiu nervoso no primeiro dia."}, {"question": "Who showed the writer their desk?", "options": ["A coworker", "The boss", "A friend", "The receptionist"], "correct_index": 1, "explanation": "O chefe mostrou a mesa para o escritor."}, {"question": "When did the writer meet coworkers?", "options": ["On Monday", "During lunch on Wednesday", "On the weekend", "After work"], "correct_index": 1, "explanation": "O escritor conheceu os colegas durante o almoço na quarta-feira."}, {"question": "What hobby did some coworkers share?", "options": ["Cooking", "Playing the guitar", "Painting", "Running"], "correct_index": 1, "explanation": "Dois colegas também gostavam de tocar violão."}, {"question": "How did the writer feel at the end of the week?", "options": ["Sad and tired", "Proud, although tired", "Angry", "Bored"], "correct_index": 1, "explanation": "O escritor estava cansado, mas orgulhoso de si mesmo."}], "open_questions": [{"question": "How did you feel on your first day at a new job or school?", "key_points_pt": ["Descrever sentimentos pessoais", "Usar o passado simples"]}, {"question": "What makes you feel comfortable with new people?", "key_points_pt": ["Dar exemplos pessoais", "Explicar o motivo"]}]}}, {"level": "A2", "genre": "superhero", "title": "The Quiet Hero", "paragraphs": ["In the city of Rivera, a young woman named Sofia had a secret power: she could move very fast, faster than any car. At night, she became Flash Girl and helped people who needed her.", "One evening, Sofia heard that a bridge was going to collapse. She ran to the bridge faster than the wind and helped everyone cross safely before it broke. The people did not know who saved them.", "The next day, Sofia went to work like a normal person. Nobody knew her secret, but she felt proud of her night adventure. She smiled quietly, ready to help again whenever the city needed Flash Girl."], "paragraphs_pt": ["Na cidade de Rivera, uma jovem chamada Sofia tinha um poder secreto: ela conseguia se mover muito rápido, mais rápido do que qualquer carro. À noite, ela se tornava a Garota Relâmpago e ajudava pessoas que precisavam dela.", "Certa noite, Sofia ouviu que uma ponte ia desabar. Ela correu até a ponte mais rápido do que o vento e ajudou todo mundo a atravessar em segurança antes que a ponte quebrasse. As pessoas não sabiam quem as salvou.", "No dia seguinte, Sofia foi trabalhar como uma pessoa normal. Ninguém sabia o segredo dela, mas ela se sentiu orgulhosa da aventura noturna dela. Ela sorriu discretamente, pronta para ajudar de novo sempre que a cidade precisasse da Garota Relâmpago."], "hard_words": ["collapse", "safely", "quietly"], "vocab": [{"word": "secret", "meaning": "secreto(a)/segredo", "note": ""}, {"word": "power", "meaning": "poder", "note": ""}, {"word": "bridge", "meaning": "ponte", "note": ""}, {"word": "collapse", "meaning": "desabar", "note": ""}, {"word": "safely", "meaning": "com segurança", "note": ""}, {"word": "saved", "meaning": "salvou", "note": ""}, {"word": "quietly", "meaning": "discretamente/silenciosamente", "note": ""}], "word_meanings": [{"word": "collapse", "meaning": "desabar", "note": ""}, {"word": "safely", "meaning": "com segurança", "note": ""}, {"word": "quietly", "meaning": "discretamente/silenciosamente", "note": ""}, {"word": "had", "meaning": "tinha", "note": "passado irregular de have"}, {"word": "became", "meaning": "se tornou/se tornava", "note": "passado irregular de become"}, {"word": "helped", "meaning": "ajudava/ajudou", "note": ""}, {"word": "heard", "meaning": "ouviu", "note": "passado irregular de hear"}, {"word": "ran", "meaning": "correu", "note": "passado irregular de run"}, {"word": "broke", "meaning": "quebrou", "note": "passado irregular de break"}, {"word": "saved", "meaning": "salvou", "note": ""}, {"word": "went", "meaning": "foi", "note": "passado irregular de go"}, {"word": "knew", "meaning": "sabia", "note": "passado irregular de know"}, {"word": "felt", "meaning": "sentiu", "note": "passado irregular de feel"}, {"word": "smiled", "meaning": "sorriu", "note": ""}, {"word": "who", "meaning": "quem", "note": ""}, {"word": "but", "meaning": "mas", "note": ""}, {"word": "before", "meaning": "antes", "note": ""}, {"word": "faster", "meaning": "mais rápido(a)", "note": "comparativo de fast"}], "grammar_words": {"cognates": [], "tobe": [], "irregular": ["had", "became", "helped", "heard", "ran", "broke", "saved", "went", "knew", "felt", "smiled"], "phrasal": [], "wh": ["who"], "connectors": ["but", "before"], "comparative": ["faster"]}, "exercises": {"grammar": [{"point": "Comparative 'faster than'", "explanation_pt": "Usamos 'faster than' para comparar velocidade, como em 'faster than any car'."}], "multiple_choice": [{"question": "What was Sofia's secret power?", "options": ["She could fly", "She could move very fast", "She was very strong", "She could become invisible"], "correct_index": 1, "explanation": "O poder secreto de Sofia era se mover muito rápido."}, {"question": "What name did Sofia use at night?", "options": ["Super Sofia", "Flash Girl", "The Runner", "Night Hero"], "correct_index": 1, "explanation": "À noite, ela se tornava a Flash Girl."}, {"question": "What was going to happen to the bridge?", "options": ["It was going to be painted", "It was going to collapse", "It was going to open", "It was going to close for repairs"], "correct_index": 1, "explanation": "A ponte ia desabar."}, {"question": "Did the people know who saved them?", "options": ["Yes, everyone knew", "No, they did not know", "Only the children knew", "Only one person knew"], "correct_index": 1, "explanation": "As pessoas não sabiam quem as salvou."}, {"question": "How did Sofia feel the next day?", "options": ["Sad", "Proud", "Angry", "Bored"], "correct_index": 1, "explanation": "Ela se sentiu orgulhosa da aventura noturna dela."}], "open_questions": [{"question": "If you had a superpower, what would it be?", "key_points_pt": ["Descrever um superpoder imaginado", "Explicar como usaria o poder"]}, {"question": "Why do you think Sofia kept her power a secret?", "key_points_pt": ["Dar uma opinião", "Justificar com um argumento simples"]}]}}, {"level": "B1", "genre": "neutral", "title": "The New Neighbor", "paragraphs": ["Marta lived alone in a small apartment on the third floor. She liked her quiet life, but last month a new neighbor moved into the flat next door. His name was Diego, and he had two loud dogs and a lot of boxes.", "At first, Marta was annoyed by the noise. However, one evening Diego knocked on her door. He explained that he was sorry for the mess and offered her some homemade bread. Marta was surprised, but she accepted it politely.", "Over the next few weeks, they started talking whenever they met in the hallway. Diego told her about his job as a teacher, and Marta talked about her garden on the balcony. Although they were very different people, they slowly became friends.", "By the end of the year, Marta no longer minded the dogs barking. In fact, she often walked them when Diego worked late. She realized that a new neighbor could change her life in a good way, and she was thankful for that."], "paragraphs_pt": ["Marta morava sozinha em um pequeno apartamento no terceiro andar. Ela gostava da sua vida tranquila, mas no mês passado um novo vizinho se mudou para o apartamento ao lado. O nome dele era Diego, e ele tinha dois cachorros barulhentos e muitas caixas.", "No início, Marta ficou incomodada com o barulho. No entanto, numa noite Diego bateu na porta dela. Ele explicou que sentia muito pela bagunça e ofereceu a ela um pão caseiro. Marta ficou surpresa, mas aceitou educadamente.", "Nas semanas seguintes, eles começaram a conversar sempre que se encontravam no corredor. Diego contou sobre seu trabalho como professor, e Marta falou sobre seu jardim na varanda. Embora fossem pessoas muito diferentes, aos poucos se tornaram amigos.", "No final do ano, Marta já não se incomodava mais com os cachorros latindo. Na verdade, ela muitas vezes os passeava quando Diego trabalhava até tarde. Ela percebeu que um novo vizinho podia mudar sua vida para melhor, e ela era grata por isso."], "hard_words": ["annoyed", "mess", "hallway", "thankful"], "vocab": [{"word": "neighbor", "meaning": "vizinho(a)", "note": ""}, {"word": "quiet", "meaning": "tranquilo, silencioso", "note": ""}, {"word": "knocked on", "meaning": "bateu na (porta)", "note": ""}, {"word": "homemade", "meaning": "caseiro", "note": ""}, {"word": "hallway", "meaning": "corredor", "note": ""}, {"word": "barking", "meaning": "latindo", "note": ""}, {"word": "thankful", "meaning": "grato(a)", "note": ""}], "grammar_words": {"cognates": [], "tobe": ["was", "were"], "irregular": ["lived", "moved", "explained", "offered", "accepted", "started", "told", "became", "realized"], "phrasal": ["moved into"], "wh": ["whenever"], "connectors": ["but", "However", "Although", "and"], "comparative": []}, "word_meanings": [{"word": "annoyed", "meaning": "incomodado(a), irritado(a)", "note": ""}, {"word": "mess", "meaning": "bagunça", "note": ""}, {"word": "hallway", "meaning": "corredor", "note": ""}, {"word": "thankful", "meaning": "grato(a)", "note": ""}, {"word": "realize", "meaning": "perceber, se dar conta", "note": "falso cognato: não é 'realizar' (fazer)"}, {"word": "actually", "meaning": "na verdade", "note": "falso cognato: não é 'atualmente'"}, {"word": "lived", "meaning": "morou/morava", "note": ""}, {"word": "moved", "meaning": "mudou-se", "note": ""}, {"word": "explained", "meaning": "explicou", "note": ""}, {"word": "offered", "meaning": "ofereceu", "note": ""}, {"word": "accepted", "meaning": "aceitou", "note": ""}, {"word": "started", "meaning": "começou", "note": ""}, {"word": "told", "meaning": "contou", "note": "passado de tell"}, {"word": "became", "meaning": "tornou-se", "note": "passado de become"}, {"word": "realized", "meaning": "percebeu", "note": ""}, {"word": "moved into", "meaning": "mudou-se para", "note": "phrasal verb"}], "exercises": {"grammar": [{"point": "Simple past", "explanation_pt": "Usamos o passado simples para ações concluídas: 'Diego knocked on her door' (Diego bateu na porta dela)."}, {"point": "Although / However", "explanation_pt": "Mostram contraste. Exemplo: 'Although they were very different people, they slowly became friends.'"}], "multiple_choice": [{"question": "What did Diego bring to Marta's door?", "options": ["Flowers", "Homemade bread", "A dog", "A box"], "correct_index": 1, "explanation": "Diego trouxe pão caseiro para se desculpar."}, {"question": "Why was Marta annoyed at first?", "options": ["Diego was rude", "The dogs were loud", "The rent was high", "The apartment was small"], "correct_index": 1, "explanation": "Os cachorros de Diego eram barulhentos."}, {"question": "What is Diego's job?", "options": ["Doctor", "Teacher", "Cook", "Driver"], "correct_index": 1, "explanation": "Diego trabalha como professor."}, {"question": "Where does Marta have a garden?", "options": ["In the yard", "On the balcony", "In the park", "At Diego's house"], "correct_index": 1, "explanation": "O jardim de Marta fica na varanda."}, {"question": "How did Marta feel about Diego by the end of the year?", "options": ["Angry", "Indifferent", "Thankful", "Scared"], "correct_index": 2, "explanation": "No final, Marta ficou grata pela amizade."}], "open_questions": [{"question": "Do you think it is easy to become friends with a neighbor? Why or why not?", "key_points_pt": ["Depende da personalidade e da rotina de cada um", "Pequenos gestos ajudam a criar confiança"]}, {"question": "Describe a time when a first impression of someone changed over time.", "key_points_pt": ["Falar sobre a primeira impressão", "Explicar o que mudou essa opinião"]}]}}, {"level": "B1", "genre": "humor", "title": "The Wrong Suitcase", "paragraphs": ["Pedro was in a hurry at the airport, so he grabbed his suitcase and ran to the gate. He didn't check the tag, and when he opened it at the hotel, he found women's dresses, a pink hairbrush, and a teddy bear instead of his clothes.", "He called the airline immediately, and they told him the real owner, a woman named Sofia, had his suitcase too. Pedro imagined Sofia opening his bag and finding his old socks and a bag of chips he forgot to eat.", "The next day, they met at the airport to switch the suitcases back. Sofia laughed so hard that she could barely speak. \"I actually wore one of your t-shirts to sleep,\" she admitted, and Pedro turned bright red with embarrassment.", "In the end, they exchanged phone numbers and later became good friends. Pedro still jokes that losing his suitcase was the best mistake of his trip, because it gave him a funny story and a new friend."], "paragraphs_pt": ["Pedro estava com pressa no aeroporto, então pegou sua mala e correu para o portão. Ele não conferiu a etiqueta, e quando a abriu no hotel, encontrou vestidos femininos, uma escova de cabelo rosa e um ursinho de pelúcia em vez das suas roupas.", "Ele ligou para a companhia aérea imediatamente, e eles disseram que a verdadeira dona, uma mulher chamada Sofia, também estava com a mala dele. Pedro imaginou Sofia abrindo sua mala e encontrando suas meias velhas e um pacote de batatas fritas que ele esqueceu de comer.", "No dia seguinte, eles se encontraram no aeroporto para trocar as malas de volta. Sofia riu tanto que mal conseguia falar. \"Na verdade, eu usei uma das suas camisetas para dormir\", ela admitiu, e Pedro ficou vermelho de vergonha.", "No final, eles trocaram números de telefone e depois se tornaram bons amigos. Pedro ainda brinca que perder a mala foi o melhor erro da viagem, porque lhe deu uma história engraçada e um novo amigo."], "hard_words": ["suitcase", "tag", "hairbrush", "embarrassment"], "vocab": [{"word": "in a hurry", "meaning": "com pressa", "note": ""}, {"word": "grabbed", "meaning": "pegou (rapidamente)", "note": ""}, {"word": "teddy bear", "meaning": "ursinho de pelúcia", "note": ""}, {"word": "switch", "meaning": "trocar", "note": ""}, {"word": "barely", "meaning": "mal, quase não", "note": ""}, {"word": "admitted", "meaning": "admitiu", "note": ""}, {"word": "turned red", "meaning": "ficou vermelho(a)", "note": ""}], "grammar_words": {"cognates": ["actually"], "tobe": ["was"], "irregular": ["grabbed", "ran", "opened", "found", "called", "told", "imagined", "met", "laughed", "admitted", "turned", "exchanged", "became"], "phrasal": [], "wh": [], "connectors": ["so", "and", "because"], "comparative": ["the best mistake"]}, "word_meanings": [{"word": "suitcase", "meaning": "mala", "note": ""}, {"word": "tag", "meaning": "etiqueta", "note": ""}, {"word": "hairbrush", "meaning": "escova de cabelo", "note": ""}, {"word": "embarrassment", "meaning": "vergonha, constrangimento", "note": ""}, {"word": "actually", "meaning": "na verdade", "note": "falso cognato"}, {"word": "realize", "meaning": "perceber", "note": "falso cognato"}, {"word": "grabbed", "meaning": "pegou", "note": ""}, {"word": "ran", "meaning": "correu", "note": "passado de run"}, {"word": "opened", "meaning": "abriu", "note": ""}, {"word": "found", "meaning": "encontrou", "note": "passado de find"}, {"word": "called", "meaning": "ligou", "note": ""}, {"word": "told", "meaning": "disse/contou", "note": ""}, {"word": "imagined", "meaning": "imaginou", "note": ""}, {"word": "met", "meaning": "encontrou-se", "note": "passado de meet"}, {"word": "laughed", "meaning": "riu", "note": ""}, {"word": "admitted", "meaning": "admitiu", "note": ""}, {"word": "turned", "meaning": "ficou (mudou)", "note": ""}, {"word": "exchanged", "meaning": "trocaram", "note": ""}, {"word": "became", "meaning": "tornaram-se", "note": ""}, {"word": "switch back", "meaning": "trocar de volta", "note": "phrasal verb"}], "exercises": {"grammar": [{"point": "Simple past narration", "explanation_pt": "O passado simples conta eventos em sequência: 'Pedro called the airline immediately.'"}, {"point": "Direct speech", "explanation_pt": "Usamos aspas para reproduzir a fala: '\"I actually wore one of your t-shirts to sleep,\" she admitted.'"}], "multiple_choice": [{"question": "What did Pedro find in the wrong suitcase?", "options": ["Books", "Women's dresses", "Shoes", "Tools"], "correct_index": 1, "explanation": "Ele encontrou vestidos femininos."}, {"question": "Who had Pedro's suitcase?", "options": ["The airline", "Sofia", "A hotel worker", "No one"], "correct_index": 1, "explanation": "Sofia estava com a mala de Pedro."}, {"question": "What did Sofia wear to sleep?", "options": ["Her own pajamas", "A hotel robe", "One of Pedro's t-shirts", "Nothing special"], "correct_index": 2, "explanation": "Ela admitiu ter usado uma camiseta de Pedro."}, {"question": "How did Pedro react when Sofia told him this?", "options": ["He got angry", "He turned red", "He left immediately", "He didn't believe her"], "correct_index": 1, "explanation": "Pedro ficou vermelho de vergonha."}, {"question": "What happened between Pedro and Sofia in the end?", "options": ["They never spoke again", "They became friends", "They argued", "They lost the suitcases again"], "correct_index": 1, "explanation": "Eles se tornaram amigos."}], "open_questions": [{"question": "Have you ever made a funny mistake while traveling? What happened?", "key_points_pt": ["Descrever a situação e o erro cometido", "Explicar como terminou"]}, {"question": "Do you think mistakes can sometimes lead to good things? Give an example.", "key_points_pt": ["Comentar sobre erros que trazem resultados positivos", "Usar exemplo pessoal ou da história"]}]}}, {"level": "B1", "genre": "suspense", "title": "The Locked Room", "paragraphs": ["Ana worked late at the museum, cataloging old paintings. Around midnight, she heard a strange noise coming from the storage room, a room that was always locked. Her heart began to beat faster, and she slowly walked toward the door.", "The door was slightly open, although she was sure she had locked it herself that morning. Inside, a single lamp was on, and papers were scattered across the floor. Someone had clearly been searching for something.", "Ana looked for her phone to call security, but it wasn't in her pocket. Then she noticed a shadow move behind a large painting. She froze, unsure whether to run or to find out who was hiding there.", "Finally, a security guard stepped out from behind the painting, looking embarrassed. He explained that he had lost his keys and was searching for them quietly so he wouldn't wake the other staff. Ana let out a long breath of relief, though her hands were still shaking."], "paragraphs_pt": ["Ana trabalhava até tarde no museu, catalogando pinturas antigas. Por volta da meia-noite, ela ouviu um barulho estranho vindo da sala de armazenamento, uma sala que estava sempre trancada. Seu coração começou a bater mais rápido, e ela caminhou devagar em direção à porta.", "A porta estava levemente aberta, embora ela tivesse certeza de que a havia trancado ela mesma naquela manhã. Lá dentro, uma única lâmpada estava acesa, e papéis estavam espalhados pelo chão. Alguém claramente estivera procurando por algo.", "Ana procurou o celular para chamar a segurança, mas ele não estava no bolso. Então ela notou uma sombra se mover atrás de um grande quadro. Ela congelou, sem saber se corria ou descobria quem estava se escondendo ali.", "Finalmente, um segurança saiu de trás do quadro, parecendo envergonhado. Ele explicou que havia perdido as chaves e estava procurando por elas em silêncio para não acordar os outros funcionários. Ana soltou um longo suspiro de alívio, embora suas mãos ainda estivessem tremendo."], "hard_words": ["cataloging", "scattered", "froze", "shaking"], "vocab": [{"word": "storage room", "meaning": "sala de armazenamento/depósito", "note": ""}, {"word": "heart began to beat faster", "meaning": "coração começou a bater mais rápido", "note": ""}, {"word": "shadow", "meaning": "sombra", "note": ""}, {"word": "froze", "meaning": "congelou (de medo)", "note": "passado de freeze"}, {"word": "find out", "meaning": "descobrir", "note": ""}, {"word": "let out a breath", "meaning": "soltou um suspiro", "note": ""}, {"word": "relief", "meaning": "alívio", "note": ""}], "grammar_words": {"cognates": [], "tobe": ["was", "were", "wasn't"], "irregular": ["worked", "heard", "began", "walked", "was", "noticed", "froze", "stepped", "explained", "lost", "let"], "phrasal": ["find out"], "wh": ["who", "whether"], "connectors": ["although", "but", "Then", "So", "though"], "comparative": ["faster"]}, "word_meanings": [{"word": "cataloging", "meaning": "catalogando", "note": ""}, {"word": "scattered", "meaning": "espalhados", "note": ""}, {"word": "froze", "meaning": "congelou", "note": ""}, {"word": "shaking", "meaning": "tremendo", "note": ""}, {"word": "actually", "meaning": "na verdade", "note": "falso cognato"}, {"word": "realize", "meaning": "perceber", "note": "falso cognato"}, {"word": "worked", "meaning": "trabalhou", "note": ""}, {"word": "heard", "meaning": "ouviu", "note": "passado de hear"}, {"word": "began", "meaning": "começou", "note": "passado de begin"}, {"word": "walked", "meaning": "caminhou", "note": ""}, {"word": "was", "meaning": "era/estava", "note": ""}, {"word": "noticed", "meaning": "notou", "note": ""}, {"word": "stepped", "meaning": "deu um passo/saiu", "note": ""}, {"word": "explained", "meaning": "explicou", "note": ""}, {"word": "lost", "meaning": "perdeu", "note": ""}, {"word": "let", "meaning": "deixou/soltou", "note": ""}, {"word": "find out", "meaning": "descobrir", "note": "phrasal verb"}, {"word": "step out", "meaning": "sair", "note": "phrasal verb"}], "exercises": {"grammar": [{"point": "Past continuous vs simple past", "explanation_pt": "O passado contínuo descreve uma ação em progresso: 'Someone had clearly been searching for something' mostra ação anterior contínua."}, {"point": "Whether", "explanation_pt": "'Whether' introduz uma dúvida entre duas opções: 'unsure whether to run or to find out'."}], "multiple_choice": [{"question": "What time did Ana hear the strange noise?", "options": ["Morning", "Afternoon", "Midnight", "Evening"], "correct_index": 2, "explanation": "O barulho aconteceu por volta da meia-noite."}, {"question": "What did Ana find on the floor of the storage room?", "options": ["Broken glass", "Scattered papers", "Water", "Money"], "correct_index": 1, "explanation": "Havia papéis espalhados pelo chão."}, {"question": "Why couldn't Ana call security right away?", "options": ["The phone was broken", "She didn't have her phone", "Security didn't answer", "There was no signal"], "correct_index": 1, "explanation": "Seu celular não estava no bolso."}, {"question": "Who was hiding behind the painting?", "options": ["A thief", "Another curator", "A security guard", "No one"], "correct_index": 2, "explanation": "Era um segurança procurando suas chaves."}, {"question": "Why was the guard searching quietly?", "options": ["He was stealing something", "He didn't want to wake the staff", "He was testing the alarm", "He was hiding from Ana"], "correct_index": 1, "explanation": "Ele não queria acordar os outros funcionários."}], "open_questions": [{"question": "How would you have reacted if you were in Ana's position?", "key_points_pt": ["Falar sobre medo ou coragem", "Comparar com a reação de Ana"]}, {"question": "Why do you think suspense stories often end with a simple explanation?", "key_points_pt": ["Discutir tensão seguida de alívio", "Comentar o efeito na história"]}]}}, {"level": "B1", "genre": "detective", "title": "The Missing Necklace", "paragraphs": ["Detective Silva arrived at the mansion after the owner reported that a diamond necklace had disappeared from her bedroom. Five people had been in the house that night: the maid, the cook, the gardener, the owner's nephew, and a family friend.", "Silva questioned each person carefully, and he noticed that the gardener's hands were shaking. However, he decided not to jump to conclusions. Instead, he examined the bedroom window, which was unlocked despite the cold weather outside.", "He found a small piece of fabric caught on the window frame. It matched the nephew's jacket exactly. When Silva confronted him, the nephew finally confessed that he had taken the necklace because he needed money to pay off a debt.", "The owner was relieved to get her necklace back, although she was sad to learn that her own nephew had stolen it. Silva reminded her that people sometimes make bad choices when they feel desperate, but that didn't make the theft acceptable."], "paragraphs_pt": ["O detetive Silva chegou à mansão depois que a dona relatou que um colar de diamantes havia desaparecido do seu quarto. Cinco pessoas estiveram na casa naquela noite: a empregada, a cozinheira, o jardineiro, o sobrinho da dona e um amigo da família.", "Silva interrogou cada pessoa com cuidado, e notou que as mãos do jardineiro estavam tremendo. No entanto, ele decidiu não tirar conclusões precipitadas. Em vez disso, examinou a janela do quarto, que estava destrancada apesar do frio lá fora.", "Ele encontrou um pequeno pedaço de tecido preso na moldura da janela. Combinava exatamente com o casaco do sobrinho. Quando Silva o confrontou, o sobrinho finalmente confessou que havia pegado o colar porque precisava de dinheiro para pagar uma dívida.", "A dona ficou aliviada por recuperar o colar, embora tenha ficado triste ao saber que seu próprio sobrinho o havia roubado. Silva lembrou a ela que as pessoas às vezes fazem escolhas erradas quando se sentem desesperadas, mas isso não tornava o roubo aceitável."], "hard_words": ["mansion", "fabric", "confessed", "desperate"], "vocab": [{"word": "necklace", "meaning": "colar", "note": ""}, {"word": "maid", "meaning": "empregada", "note": ""}, {"word": "jump to conclusions", "meaning": "tirar conclusões precipitadas", "note": ""}, {"word": "unlocked", "meaning": "destrancado", "note": ""}, {"word": "caught on", "meaning": "preso em", "note": ""}, {"word": "confronted", "meaning": "confrontou", "note": ""}, {"word": "pay off a debt", "meaning": "pagar uma dívida", "note": ""}], "grammar_words": {"cognates": [], "tobe": ["was", "were"], "irregular": ["arrived", "reported", "questioned", "noticed", "decided", "examined", "found", "confronted", "confessed", "reminded"], "phrasal": ["jump to", "pay off"], "wh": ["which"], "connectors": ["However", "Instead", "although", "but", "because"], "comparative": []}, "word_meanings": [{"word": "mansion", "meaning": "mansão", "note": ""}, {"word": "fabric", "meaning": "tecido", "note": ""}, {"word": "confessed", "meaning": "confessou", "note": ""}, {"word": "desperate", "meaning": "desesperado(a)", "note": ""}, {"word": "actually", "meaning": "na verdade", "note": "falso cognato"}, {"word": "realize", "meaning": "perceber", "note": "falso cognato"}, {"word": "arrived", "meaning": "chegou", "note": ""}, {"word": "reported", "meaning": "relatou", "note": ""}, {"word": "questioned", "meaning": "interrogou", "note": ""}, {"word": "noticed", "meaning": "notou", "note": ""}, {"word": "decided", "meaning": "decidiu", "note": ""}, {"word": "examined", "meaning": "examinou", "note": ""}, {"word": "found", "meaning": "encontrou", "note": ""}, {"word": "confronted", "meaning": "confrontou", "note": ""}, {"word": "took", "meaning": "pegou", "note": "passado de take"}, {"word": "learned", "meaning": "soube/aprendeu", "note": ""}, {"word": "reminded", "meaning": "lembrou", "note": ""}, {"word": "felt", "meaning": "sentiu", "note": "passado de feel"}, {"word": "jump to", "meaning": "tirar (conclusões) precipitadamente", "note": "phrasal verb"}, {"word": "pay off", "meaning": "quitar, pagar totalmente", "note": "phrasal verb"}], "exercises": {"grammar": [{"point": "Past perfect", "explanation_pt": "Usamos o past perfect para uma ação anterior a outra no passado: 'a diamond necklace had disappeared' (o colar já havia desaparecido antes da chegada de Silva)."}, {"point": "Despite", "explanation_pt": "'Despite' + substantivo mostra contraste: 'unlocked despite the cold weather' (destrancada apesar do frio)."}], "multiple_choice": [{"question": "What went missing from the bedroom?", "options": ["A ring", "A diamond necklace", "A watch", "Money"], "correct_index": 1, "explanation": "Um colar de diamantes desapareceu."}, {"question": "Who did Silva notice was shaking?", "options": ["The maid", "The cook", "The gardener", "The nephew"], "correct_index": 2, "explanation": "As mãos do jardineiro estavam tremendo, mas isso não o tornava culpado."}, {"question": "Where did Silva find a piece of fabric?", "options": ["On the door", "On the window frame", "On the floor", "In the garden"], "correct_index": 1, "explanation": "O tecido estava preso na moldura da janela."}, {"question": "Who had taken the necklace?", "options": ["The gardener", "The maid", "The nephew", "The cook"], "correct_index": 2, "explanation": "O sobrinho confessou ter pegado o colar."}, {"question": "Why did the nephew take the necklace?", "options": ["He wanted to sell it as art", "He needed money for a debt", "He was angry at his aunt", "He wanted to hide it"], "correct_index": 1, "explanation": "Ele precisava de dinheiro para pagar uma dívida."}], "open_questions": [{"question": "Do you think Silva was right not to suspect the gardener immediately? Why?", "key_points_pt": ["Discutir a importância de evidências antes de acusar alguém", "Comentar sobre julgar por aparências"]}, {"question": "Do you agree with Silva that desperation doesn't excuse stealing? Why or why not?", "key_points_pt": ["Expressar opinião pessoal sobre ética e necessidade", "Considerar diferentes pontos de vista"]}]}}, {"level": "B1", "genre": "romance", "title": "Letters from the Train", "paragraphs": ["Every Monday, Lucas took the same train to work, and every Monday, he saw the same woman reading a book by the window. He never spoke to her, but he always wondered what she was reading and what her name was.", "One rainy morning, she accidentally left her book on the seat when she got off the train. Lucas picked it up and found a small note inside with her name, Camila, and a line from her favorite poem. He decided to write her a short letter and leave it at the same seat the next Monday.", "To his surprise, Camila found the letter and wrote back the following week. For two months, they exchanged letters through the same book, sharing thoughts about life, music, and their dreams, although they had still never spoken face to face.", "Finally, one Monday, Camila sat down next to Lucas instead of by the window. \"I think it's time we actually talked,\" she said with a smile. Lucas laughed nervously, and from that day, they never needed to write letters again because they simply talked every morning on the train."], "paragraphs_pt": ["Toda segunda-feira, Lucas pegava o mesmo trem para o trabalho, e toda segunda-feira via a mesma mulher lendo um livro perto da janela. Ele nunca falou com ela, mas sempre se perguntava o que ela estava lendo e qual era o nome dela.", "Numa manhã chuvosa, ela acidentalmente esqueceu o livro no banco quando desceu do trem. Lucas o pegou e encontrou um pequeno bilhete dentro com o nome dela, Camila, e um verso do poema favorito dela. Ele decidiu escrever um bilhete curto para ela e deixá-lo no mesmo banco na segunda-feira seguinte.", "Para sua surpresa, Camila encontrou o bilhete e respondeu na semana seguinte. Por dois meses, eles trocaram bilhetes através do mesmo livro, compartilhando pensamentos sobre a vida, música e seus sonhos, embora ainda nunca tivessem se falado pessoalmente.", "Finalmente, numa segunda-feira, Camila sentou-se ao lado de Lucas em vez de perto da janela. \"Acho que é hora de a gente realmente conversar\", ela disse com um sorriso. Lucas riu nervosamente, e a partir daquele dia, eles nunca mais precisaram escrever bilhetes, porque simplesmente conversavam toda manhã no trem."], "hard_words": ["accidentally", "note", "poem", "nervously"], "vocab": [{"word": "wondered", "meaning": "perguntava-se, imaginava", "note": ""}, {"word": "got off", "meaning": "desceu (de um veículo)", "note": ""}, {"word": "picked it up", "meaning": "pegou", "note": ""}, {"word": "to his surprise", "meaning": "para sua surpresa", "note": ""}, {"word": "wrote back", "meaning": "respondeu por escrito", "note": ""}, {"word": "face to face", "meaning": "cara a cara, pessoalmente", "note": ""}, {"word": "smile", "meaning": "sorriso", "note": ""}], "grammar_words": {"cognates": ["actually"], "tobe": ["was"], "irregular": ["took", "saw", "spoke", "wondered", "left", "got", "found", "decided", "wrote", "exchanged", "sat", "said", "laughed"], "phrasal": ["got off"], "wh": ["what"], "connectors": ["but", "although", "because"], "comparative": []}, "word_meanings": [{"word": "accidentally", "meaning": "acidentalmente", "note": ""}, {"word": "note", "meaning": "bilhete", "note": ""}, {"word": "poem", "meaning": "poema", "note": ""}, {"word": "nervously", "meaning": "nervosamente", "note": ""}, {"word": "actually", "meaning": "na verdade, de fato", "note": "falso cognato"}, {"word": "realize", "meaning": "perceber", "note": "falso cognato"}, {"word": "took", "meaning": "pegou/tomou", "note": ""}, {"word": "saw", "meaning": "viu", "note": "passado de see"}, {"word": "spoke", "meaning": "falou", "note": "passado de speak"}, {"word": "wondered", "meaning": "perguntava-se", "note": ""}, {"word": "left", "meaning": "deixou", "note": "passado de leave"}, {"word": "got", "meaning": "ficou/obteve", "note": ""}, {"word": "found", "meaning": "encontrou", "note": ""}, {"word": "decided", "meaning": "decidiu", "note": ""}, {"word": "wrote", "meaning": "escreveu", "note": "passado de write"}, {"word": "exchanged", "meaning": "trocaram", "note": ""}, {"word": "sat", "meaning": "sentou-se", "note": "passado de sit"}, {"word": "said", "meaning": "disse", "note": "passado de say"}, {"word": "laughed", "meaning": "riu", "note": ""}, {"word": "got off", "meaning": "desceu", "note": "phrasal verb"}, {"word": "picked up", "meaning": "pegou", "note": "phrasal verb"}, {"word": "write back", "meaning": "responder por escrito", "note": "phrasal verb"}], "exercises": {"grammar": [{"point": "Simple past for a routine broken by an event", "explanation_pt": "'Every Monday' descreve rotina, mas 'One rainy morning, she accidentally left her book' mostra um evento específico no passado simples."}, {"point": "Instead of + gerúndio", "explanation_pt": "'Instead of' é seguido de verbo com -ing ou substantivo: 'sat down next to Lucas instead of by the window'."}], "multiple_choice": [{"question": "What did Lucas notice about the woman every Monday?", "options": ["She talked loudly", "She read a book", "She slept", "She listened to music"], "correct_index": 1, "explanation": "Ela lia um livro toda segunda-feira."}, {"question": "What did Camila leave behind on the train?", "options": ["Her phone", "Her umbrella", "Her book", "Her bag"], "correct_index": 2, "explanation": "Ela esqueceu o livro no banco."}, {"question": "What did Lucas find inside the book?", "options": ["Money", "A photo", "A note with her name", "A ticket"], "correct_index": 2, "explanation": "Havia um bilhete com o nome dela, Camila."}, {"question": "How long did they exchange letters before speaking?", "options": ["One week", "Two months", "One year", "They never wrote letters"], "correct_index": 1, "explanation": "Eles trocaram bilhetes por dois meses."}, {"question": "What did Camila do on the final Monday in the story?", "options": ["She stopped taking the train", "She sat next to Lucas", "She left another note", "She moved away"], "correct_index": 1, "explanation": "Ela sentou-se ao lado de Lucas em vez da janela."}], "open_questions": [{"question": "Do you think writing letters is a romantic way to get to know someone? Why?", "key_points_pt": ["Comparar comunicação escrita e conversa direta", "Falar sobre vantagens e desvantagens de cada uma"]}, {"question": "Have you ever had a memorable moment with a stranger? Describe it.", "key_points_pt": ["Descrever brevemente a situação", "Explicar por que foi memorável"]}]}}, {"level": "B1", "genre": "scifi", "title": "The Last Signal", "paragraphs": ["In the year 2185, Captain Rina flew a small research ship near the edge of known space. Her mission was simple: find the source of a strange radio signal that scientists on Earth had been receiving for months. No one knew if it came from a machine or something alive.", "As her ship approached a quiet, gray planet, the signal grew louder. Rina landed carefully and walked outside in her heavy suit. She found an old satellite, broken and covered in dust, still sending its weak signal into space after decades of silence.", "Inside the satellite's memory, she discovered recorded messages from a human colony that had lived on the planet many years earlier. The colony had run out of resources and had to leave, but they left the satellite behind so that someone, someday, might find their story.", "Rina sat quietly for a moment, thinking about the people who had once called this cold planet home. She recorded a new message for anyone who might come after her, then returned to her ship, carrying a piece of history that connected the past to the future."], "paragraphs_pt": ["No ano de 2185, a capitã Rina pilotava uma pequena nave de pesquisa perto do limite do espaço conhecido. Sua missão era simples: encontrar a origem de um sinal de rádio estranho que os cientistas na Terra vinham recebendo havia meses. Ninguém sabia se vinha de uma máquina ou de algo vivo.", "Enquanto sua nave se aproximava de um planeta cinza e silencioso, o sinal ficava mais forte. Rina pousou com cuidado e caminhou lá fora com seu traje pesado. Ela encontrou um satélite antigo, quebrado e coberto de poeira, ainda enviando seu sinal fraco para o espaço depois de décadas de silêncio.", "Dentro da memória do satélite, ela descobriu mensagens gravadas de uma colônia humana que havia vivido no planeta muitos anos antes. A colônia havia ficado sem recursos e teve que partir, mas deixaram o satélite para trás para que alguém, algum dia, pudesse encontrar a história deles.", "Rina ficou sentada em silêncio por um momento, pensando nas pessoas que um dia chamaram aquele planeta frio de lar. Ela gravou uma nova mensagem para quem viesse depois dela, e então voltou para sua nave, carregando um pedaço de história que conectava o passado ao futuro."], "hard_words": ["signal", "satellite", "decades", "colony"], "vocab": [{"word": "research ship", "meaning": "nave de pesquisa", "note": ""}, {"word": "source", "meaning": "origem, fonte", "note": ""}, {"word": "approached", "meaning": "aproximou-se", "note": ""}, {"word": "covered in dust", "meaning": "coberto de poeira", "note": ""}, {"word": "run out of", "meaning": "ficar sem (algo)", "note": ""}, {"word": "leave behind", "meaning": "deixar para trás", "note": ""}, {"word": "call home", "meaning": "chamar de lar", "note": ""}], "grammar_words": {"cognates": [], "tobe": ["was"], "irregular": ["flew", "knew", "grew", "landed", "walked", "found", "discovered", "had", "left", "sat", "recorded", "returned"], "phrasal": ["run out of"], "wh": ["who"], "connectors": ["but", "so that", "then"], "comparative": ["louder", "the past to the future"]}, "word_meanings": [{"word": "signal", "meaning": "sinal", "note": ""}, {"word": "satellite", "meaning": "satélite", "note": ""}, {"word": "decades", "meaning": "décadas", "note": ""}, {"word": "colony", "meaning": "colônia", "note": ""}, {"word": "actually", "meaning": "na verdade", "note": "falso cognato"}, {"word": "realize", "meaning": "perceber", "note": "falso cognato"}, {"word": "flew", "meaning": "pilotou/voou", "note": "passado de fly"}, {"word": "knew", "meaning": "sabia", "note": "passado de know"}, {"word": "grew", "meaning": "cresceu/ficou", "note": "passado de grow"}, {"word": "landed", "meaning": "pousou", "note": ""}, {"word": "walked", "meaning": "caminhou", "note": ""}, {"word": "found", "meaning": "encontrou", "note": ""}, {"word": "discovered", "meaning": "descobriu", "note": ""}, {"word": "had", "meaning": "tinha", "note": ""}, {"word": "left", "meaning": "partiu/deixou", "note": ""}, {"word": "sat", "meaning": "sentou-se", "note": ""}, {"word": "recorded", "meaning": "gravou", "note": ""}, {"word": "returned", "meaning": "voltou", "note": ""}, {"word": "run out of", "meaning": "ficar sem", "note": "phrasal verb"}, {"word": "leave behind", "meaning": "deixar para trás", "note": "phrasal verb"}], "exercises": {"grammar": [{"point": "Past perfect for background events", "explanation_pt": "Usamos past perfect para eventos anteriores a outros no passado: 'scientists had been receiving' e 'a colony that had lived on the planet' mostram ações anteriores à chegada de Rina."}, {"point": "So that + purpose", "explanation_pt": "'So that' explica um propósito: 'they left the satellite behind so that someone might find their story'."}], "multiple_choice": [{"question": "What was Rina's mission?", "options": ["To find the source of a radio signal", "To build a new colony", "To repair her ship", "To meet aliens"], "correct_index": 0, "explanation": "Sua missão era encontrar a origem do sinal."}, {"question": "What did Rina find on the planet?", "options": ["A living alien", "An old satellite", "A new colony", "Nothing at all"], "correct_index": 1, "explanation": "Ela encontrou um satélite antigo e quebrado."}, {"question": "Why did the colony leave the planet?", "options": ["They were attacked", "They found a better planet", "They ran out of resources", "They wanted to return to Earth"], "correct_index": 2, "explanation": "A colônia ficou sem recursos."}, {"question": "Why did the colony leave the satellite behind?", "options": ["It was too heavy to carry", "So someone might find their story", "They forgot about it", "It stopped working"], "correct_index": 1, "explanation": "Para que alguém pudesse encontrar a história deles."}, {"question": "What did Rina do before returning to her ship?", "options": ["She repaired the satellite", "She destroyed the satellite", "She recorded a new message", "She called Earth"], "correct_index": 2, "explanation": "Ela gravou uma nova mensagem."}], "open_questions": [{"question": "Why do you think the colony wanted to leave a message for the future?", "key_points_pt": ["Discutir o desejo humano de deixar um legado", "Comentar sobre a importância da memória e história"]}, {"question": "If you found an old message from the past, what would you want it to say?", "key_points_pt": ["Imaginar o conteúdo de uma mensagem pessoal ou histórica", "Justificar a escolha"]}]}}, {"level": "B1", "genre": "fantasy", "title": "The Silver Forest", "paragraphs": ["In the kingdom of Ardyn, there was a forest where the trees glowed silver at night. Villagers believed the forest was cursed, so no one dared to enter it after sunset. A young girl named Wren, however, had always been curious rather than afraid.", "One night, her little brother wandered into the forest chasing a rabbit and didn't come back. Wren grabbed a torch and ran after him, ignoring the warnings of the villagers. Inside, the trees whispered softly, and strange lights floated between the branches like tiny stars.", "She found her brother sitting calmly beside an old spirit made of silver light, who explained that the forest protected lost children rather than harming them. The spirit had simply been waiting for someone brave enough to learn the truth and break the old, false legend.", "Wren carried her brother home and told the villagers what she had discovered. Although some people still doubted her story, others slowly began to walk through the forest during the day. Over time, the silver forest became a peaceful place instead of a frightening one."], "paragraphs_pt": ["No reino de Ardyn, havia uma floresta onde as árvores brilhavam prateadas à noite. Os moradores acreditavam que a floresta era amaldiçoada, então ninguém ousava entrar nela depois do pôr do sol. Uma jovem chamada Wren, no entanto, sempre foi curiosa em vez de medrosa.", "Numa noite, seu irmãozinho vagou pela floresta perseguindo um coelho e não voltou. Wren pegou uma tocha e correu atrás dele, ignorando os avisos dos moradores. Lá dentro, as árvores sussurravam suavemente, e luzes estranhas flutuavam entre os galhos como pequenas estrelas.", "Ela encontrou o irmão sentado calmamente ao lado de um velho espírito feito de luz prateada, que explicou que a floresta protegia crianças perdidas em vez de machucá-las. O espírito estivera simplesmente esperando por alguém corajoso o bastante para descobrir a verdade e quebrar a antiga e falsa lenda.", "Wren carregou o irmão para casa e contou aos moradores o que havia descoberto. Embora algumas pessoas ainda duvidassem de sua história, outras aos poucos começaram a caminhar pela floresta durante o dia. Com o tempo, a floresta prateada se tornou um lugar tranquilo em vez de assustador."], "hard_words": ["cursed", "dared", "wandered", "whispered"], "vocab": [{"word": "kingdom", "meaning": "reino", "note": ""}, {"word": "glowed", "meaning": "brilhava", "note": ""}, {"word": "villagers", "meaning": "moradores da vila", "note": ""}, {"word": "torch", "meaning": "tocha", "note": ""}, {"word": "branches", "meaning": "galhos", "note": ""}, {"word": "spirit", "meaning": "espírito", "note": ""}, {"word": "legend", "meaning": "lenda", "note": ""}], "grammar_words": {"cognates": [], "tobe": ["was"], "irregular": ["was", "believed", "wandered", "grabbed", "ran", "found", "explained", "carried", "told", "began", "became"], "phrasal": ["ran after"], "wh": ["who"], "connectors": ["so", "however", "Although", "instead of"], "comparative": []}, "word_meanings": [{"word": "cursed", "meaning": "amaldiçoado(a)", "note": ""}, {"word": "dared", "meaning": "ousava", "note": ""}, {"word": "wandered", "meaning": "vagou", "note": ""}, {"word": "whispered", "meaning": "sussurravam", "note": ""}, {"word": "actually", "meaning": "na verdade", "note": "falso cognato"}, {"word": "realize", "meaning": "perceber", "note": "falso cognato"}, {"word": "was", "meaning": "era/estava", "note": ""}, {"word": "believed", "meaning": "acreditavam", "note": ""}, {"word": "grabbed", "meaning": "pegou", "note": ""}, {"word": "ran", "meaning": "correu", "note": ""}, {"word": "found", "meaning": "encontrou", "note": ""}, {"word": "explained", "meaning": "explicou", "note": ""}, {"word": "carried", "meaning": "carregou", "note": ""}, {"word": "told", "meaning": "contou", "note": ""}, {"word": "began", "meaning": "começaram", "note": ""}, {"word": "became", "meaning": "tornou-se", "note": ""}, {"word": "ran after", "meaning": "correu atrás de", "note": "phrasal verb"}], "exercises": {"grammar": [{"point": "Rather than", "explanation_pt": "'Rather than' compara duas opções, preferindo uma: 'curious rather than afraid' (curiosa em vez de medrosa)."}, {"point": "Past perfect continuous", "explanation_pt": "'had simply been waiting' mostra uma ação contínua que aconteceu antes de outro momento no passado."}], "multiple_choice": [{"question": "Why didn't villagers enter the forest at night?", "options": ["They believed it was cursed", "It was too dark", "There were wild animals", "It was against the law"], "correct_index": 0, "explanation": "Eles acreditavam que a floresta era amaldiçoada."}, {"question": "Why did Wren's brother go into the forest?", "options": ["He was lost", "He was chasing a rabbit", "He wanted to see the lights", "He was running from someone"], "correct_index": 1, "explanation": "Ele perseguia um coelho."}, {"question": "Who did Wren find with her brother?", "options": ["Another villager", "A wolf", "A silver spirit", "No one"], "correct_index": 2, "explanation": "Ela encontrou um espírito feito de luz prateada."}, {"question": "What did the spirit actually do to lost children?", "options": ["It scared them away", "It protected them", "It ignored them", "It turned them to silver"], "correct_index": 1, "explanation": "O espírito protegia as crianças perdidas."}, {"question": "What happened to the forest's reputation by the end?", "options": ["It became more dangerous", "It stayed frightening", "It became peaceful for the villagers", "It disappeared"], "correct_index": 2, "explanation": "Com o tempo, tornou-se um lugar tranquilo."}], "open_questions": [{"question": "Why do you think people often fear things they don't understand?", "key_points_pt": ["Falar sobre medo do desconhecido", "Relacionar com a lenda da floresta"]}, {"question": "What lesson can we learn from Wren's story?", "key_points_pt": ["Comentar sobre coragem e curiosidade", "Falar sobre questionar crenças antigas"]}]}}, {"level": "B1", "genre": "adventure", "title": "The River Crossing", "paragraphs": ["Tomas and his two friends decided to hike through the mountains to reach a hidden waterfall that locals had talked about for years. The trail was long and difficult, but they carried enough food and water for three days.", "On the second day, they reached a wide river with strong currents. The old wooden bridge that used to cross it had collapsed years earlier, so they had to find another way across. Tomas suggested that they build a small raft using fallen branches and rope.", "It took them several hours, but they finally built a raft strong enough to hold their bags. Although the current pushed them further downstream than they expected, they made it safely to the other side, soaked but excited.", "When they finally reached the waterfall the next morning, they understood why people talked about it so much. The water fell from an incredible height into a clear pool below. Tired but proud, they agreed it was the best trip they had ever taken together."], "paragraphs_pt": ["Tomas e seus dois amigos decidiram fazer uma trilha pelas montanhas para chegar a uma cachoeira escondida sobre a qual os moradores locais falavam havia anos. A trilha era longa e difícil, mas eles carregavam comida e água suficientes para três dias.", "No segundo dia, chegaram a um rio largo com correntes fortes. A velha ponte de madeira que costumava cruzá-lo havia desabado anos antes, então tiveram que encontrar outra forma de atravessar. Tomas sugeriu que construíssem uma pequena jangada usando galhos caídos e corda.", "Levou várias horas, mas finalmente construíram uma jangada forte o bastante para carregar suas mochilas. Embora a correnteza os tenha empurrado mais rio abaixo do que esperavam, eles chegaram em segurança ao outro lado, encharcados mas animados.", "Quando finalmente chegaram à cachoeira na manhã seguinte, entenderam por que as pessoas falavam tanto sobre ela. A água caía de uma altura incrível em uma piscina clara abaixo. Cansados mas orgulhosos, concordaram que era a melhor viagem que já haviam feito juntos."], "hard_words": ["currents", "collapsed", "raft", "downstream"], "vocab": [{"word": "hike", "meaning": "caminhada, trilha", "note": ""}, {"word": "waterfall", "meaning": "cachoeira", "note": ""}, {"word": "trail", "meaning": "trilha", "note": ""}, {"word": "rope", "meaning": "corda", "note": ""}, {"word": "soaked", "meaning": "encharcado(a)", "note": ""}, {"word": "pool", "meaning": "piscina natural, poça", "note": ""}, {"word": "proud", "meaning": "orgulhoso(a)", "note": ""}], "grammar_words": {"cognates": [], "tobe": ["was"], "irregular": ["decided", "carried", "reached", "collapsed", "had", "suggested", "took", "built", "pushed", "made", "understood", "fell", "agreed"], "phrasal": [], "wh": ["why"], "connectors": ["but", "so", "Although"], "comparative": ["further downstream", "the best trip"]}, "word_meanings": [{"word": "currents", "meaning": "correntezas", "note": ""}, {"word": "collapsed", "meaning": "desabou", "note": ""}, {"word": "raft", "meaning": "jangada", "note": ""}, {"word": "downstream", "meaning": "rio abaixo", "note": ""}, {"word": "actually", "meaning": "na verdade", "note": "falso cognato"}, {"word": "realize", "meaning": "perceber", "note": "falso cognato"}, {"word": "decided", "meaning": "decidiram", "note": ""}, {"word": "carried", "meaning": "carregavam", "note": ""}, {"word": "reached", "meaning": "chegaram", "note": ""}, {"word": "had", "meaning": "tiveram/tinham", "note": ""}, {"word": "suggested", "meaning": "sugeriu", "note": ""}, {"word": "took", "meaning": "levou", "note": ""}, {"word": "built", "meaning": "construíram", "note": "passado de build"}, {"word": "pushed", "meaning": "empurrou", "note": ""}, {"word": "made", "meaning": "fizeram/conseguiram", "note": "passado de make"}, {"word": "understood", "meaning": "entenderam", "note": "passado de understand"}, {"word": "fell", "meaning": "caía", "note": "passado de fall"}, {"word": "agreed", "meaning": "concordaram", "note": ""}], "exercises": {"grammar": [{"point": "Used to", "explanation_pt": "'Used to' descreve um hábito ou estado do passado que não existe mais: 'The old wooden bridge that used to cross it had collapsed' (A ponte que costumava cruzá-lo havia desabado)."}, {"point": "Enough + adjetivo/substantivo", "explanation_pt": "'Strong enough to hold their bags' significa 'forte o suficiente para carregar as mochilas'."}], "multiple_choice": [{"question": "What was the group's destination?", "options": ["A hidden waterfall", "A cave", "A mountain peak", "A lake"], "correct_index": 0, "explanation": "Eles queriam chegar a uma cachoeira escondida."}, {"question": "What had happened to the old bridge?", "options": ["It was never built", "It had collapsed", "It was too small", "It was blocked"], "correct_index": 1, "explanation": "A ponte havia desabado anos antes."}, {"question": "What did Tomas suggest they build?", "options": ["A boat", "A new bridge", "A raft", "A tent"], "correct_index": 2, "explanation": "Ele sugeriu construir uma jangada."}, {"question": "How did they feel after crossing the river?", "options": ["Angry and tired", "Soaked but excited", "Bored", "Scared and confused"], "correct_index": 1, "explanation": "Ficaram encharcados mas animados."}, {"question": "How did the group describe the trip at the end?", "options": ["Not worth it", "Disappointing", "The best trip they had ever taken", "Too dangerous"], "correct_index": 2, "explanation": "Concordaram que foi a melhor viagem que já haviam feito."}], "open_questions": [{"question": "What would you do if you faced an obstacle like the broken bridge during a trip?", "key_points_pt": ["Propor soluções criativas", "Falar sobre trabalho em equipe"]}, {"question": "Do you enjoy adventurous trips, or do you prefer relaxing vacations? Why?", "key_points_pt": ["Expressar preferência pessoal", "Justificar com exemplos"]}]}}, {"level": "B1", "genre": "travel", "title": "A Wrong Turn in Lisbon", "paragraphs": ["Beatriz visited Lisbon for the first time last summer, and she decided to explore the old neighborhoods without using her phone's map. She wanted to feel like a real local, walking through narrow streets and discovering things by chance.", "After an hour, however, she realized she had taken a wrong turn and had no idea where her hotel was. Instead of panicking, she sat down at a small square and asked an elderly man for directions. He didn't speak much English, but he kindly drew a map on a napkin.", "Following his drawing, Beatriz walked past colorful buildings, a small church, and a viewpoint with an amazing view of the river. She stopped there for twenty minutes, just enjoying the wind and the orange rooftops below her.", "By the time she finally found her hotel, she had walked much farther than planned, and her feet hurt badly. Still, she said it was one of the best afternoons of her trip because getting lost had shown her parts of the city she never would have found otherwise."], "paragraphs_pt": ["Beatriz visitou Lisboa pela primeira vez no verão passado, e decidiu explorar os bairros antigos sem usar o mapa do celular. Ela queria se sentir como uma moradora local, caminhando por ruas estreitas e descobrindo coisas por acaso.", "Depois de uma hora, porém, ela percebeu que havia pegado o caminho errado e não fazia ideia de onde ficava o hotel. Em vez de entrar em pânico, ela se sentou em uma pequena praça e pediu informações a um senhor idoso. Ele não falava muito inglês, mas gentilmente desenhou um mapa em um guardanapo.", "Seguindo o desenho dele, Beatriz passou por prédios coloridos, uma pequena igreja e um mirante com uma vista incrível do rio. Ela parou ali por vinte minutos, apenas aproveitando o vento e os telhados alaranjados abaixo dela.", "Quando finalmente encontrou o hotel, ela havia caminhado muito mais do que planejado, e os pés doíam muito. Ainda assim, ela disse que foi uma das melhores tardes da viagem, porque se perder havia mostrado partes da cidade que ela nunca teria encontrado de outra forma."], "hard_words": ["neighborhoods", "napkin", "viewpoint", "rooftops"], "vocab": [{"word": "by chance", "meaning": "por acaso", "note": ""}, {"word": "took a wrong turn", "meaning": "pegou o caminho errado", "note": ""}, {"word": "panicking", "meaning": "entrando em pânico", "note": ""}, {"word": "asked for directions", "meaning": "pediu informações (de rota)", "note": ""}, {"word": "farther", "meaning": "mais longe", "note": ""}, {"word": "got lost", "meaning": "se perdeu", "note": ""}, {"word": "otherwise", "meaning": "de outra forma", "note": ""}], "grammar_words": {"cognates": [], "tobe": ["was"], "irregular": ["visited", "decided", "wanted", "had", "sat", "drew", "walked", "stopped", "found", "hurt", "said", "shown"], "phrasal": [], "wh": ["where"], "connectors": ["however", "Instead of", "but", "because", "Still"], "comparative": ["farther", "the best afternoons"]}, "word_meanings": [{"word": "neighborhoods", "meaning": "bairros", "note": ""}, {"word": "napkin", "meaning": "guardanapo", "note": ""}, {"word": "viewpoint", "meaning": "mirante", "note": ""}, {"word": "rooftops", "meaning": "telhados", "note": ""}, {"word": "actually", "meaning": "na verdade", "note": "falso cognato"}, {"word": "realize", "meaning": "perceber", "note": "falso cognato"}, {"word": "visited", "meaning": "visitou", "note": ""}, {"word": "decided", "meaning": "decidiu", "note": ""}, {"word": "wanted", "meaning": "queria", "note": ""}, {"word": "took", "meaning": "pegou", "note": ""}, {"word": "had", "meaning": "tinha", "note": ""}, {"word": "sat", "meaning": "sentou-se", "note": ""}, {"word": "drew", "meaning": "desenhou", "note": "passado de draw"}, {"word": "walked", "meaning": "caminhou", "note": ""}, {"word": "stopped", "meaning": "parou", "note": ""}, {"word": "found", "meaning": "encontrou", "note": ""}, {"word": "hurt", "meaning": "doíam", "note": "passado de hurt (mesma forma)"}, {"word": "said", "meaning": "disse", "note": ""}, {"word": "shown", "meaning": "mostrado", "note": "particípio de show"}], "exercises": {"grammar": [{"point": "Conditional (would have)", "explanation_pt": "'She never would have found otherwise' expressa um resultado imaginário no passado: se não tivesse se perdido, nunca teria encontrado esses lugares."}, {"point": "Instead of + gerúndio", "explanation_pt": "'Instead of panicking, she sat down' mostra uma ação alternativa: em vez de entrar em pânico."}], "multiple_choice": [{"question": "Why didn't Beatriz use her phone's map?", "options": ["It was broken", "She wanted to feel like a local", "She had no signal", "She forgot her phone"], "correct_index": 1, "explanation": "Ela queria se sentir como uma moradora local."}, {"question": "Who helped Beatriz with directions?", "options": ["A police officer", "An elderly man", "A tour guide", "A hotel worker"], "correct_index": 1, "explanation": "Um senhor idoso desenhou um mapa para ela."}, {"question": "What did the man draw the map on?", "options": ["A piece of paper", "His hand", "A napkin", "A postcard"], "correct_index": 2, "explanation": "Ele desenhou o mapa em um guardanapo."}, {"question": "What did Beatriz see from the viewpoint?", "options": ["The airport", "A view of the river", "A museum", "The train station"], "correct_index": 1, "explanation": "Ela viu uma vista incrível do rio."}, {"question": "How did Beatriz feel about getting lost by the end of the day?", "options": ["Angry", "Regretful", "Positive about the experience", "Indifferent"], "correct_index": 2, "explanation": "Ela achou que foi uma das melhores tardes da viagem."}], "open_questions": [{"question": "Do you prefer traveling with a map/app or exploring without one? Why?", "key_points_pt": ["Expressar preferência pessoal sobre planejamento de viagens", "Justificar com vantagens e desvantagens"]}, {"question": "Tell about a time you got lost somewhere. What happened?", "key_points_pt": ["Descrever a situação pessoal", "Explicar como se resolveu"]}]}}, {"level": "B1", "genre": "corporate", "title": "The Failed Product Launch", "paragraphs": ["Claudia had worked for six months on a new app for her company, and the launch day finally arrived. She and her team gathered in the meeting room, nervous but excited, waiting for the download numbers to appear on the screen.", "Unfortunately, the numbers were much lower than expected. Worse, users began posting complaints because the app crashed every time someone tried to upload a photo. Claudia's manager called an emergency meeting and asked her to explain what had gone wrong.", "Instead of making excuses, Claudia admitted the mistake honestly. She explained that the testing team hadn't had enough time before the deadline, and she suggested a plan to fix the bug within 48 hours. Her manager appreciated her honesty and agreed to give the team more time.", "The team worked through the weekend and released an update that solved the problem. Although the launch hadn't gone as planned, Claudia learned that admitting a mistake quickly and offering a solution was far more valuable than pretending everything was fine."], "paragraphs_pt": ["Claudia havia trabalhado seis meses em um novo aplicativo para sua empresa, e o dia do lançamento finalmente chegou. Ela e sua equipe se reuniram na sala de reuniões, nervosos mas animados, esperando os números de downloads aparecerem na tela.", "Infelizmente, os números foram muito menores do que o esperado. Pior, os usuários começaram a postar reclamações porque o aplicativo travava toda vez que alguém tentava enviar uma foto. O gerente de Claudia convocou uma reunião de emergência e pediu que ela explicasse o que havia dado errado.", "Em vez de arranjar desculpas, Claudia admitiu o erro honestamente. Ela explicou que a equipe de testes não havia tido tempo suficiente antes do prazo, e sugeriu um plano para corrigir o problema em 48 horas. Seu gerente valorizou sua honestidade e concordou em dar mais tempo à equipe.", "A equipe trabalhou durante o fim de semana e lançou uma atualização que resolveu o problema. Embora o lançamento não tivesse saído como planejado, Claudia aprendeu que admitir um erro rapidamente e oferecer uma solução era muito mais valioso do que fingir que tudo estava bem."], "hard_words": ["launch", "crashed", "deadline", "pretending"], "vocab": [{"word": "gathered", "meaning": "reuniram-se", "note": ""}, {"word": "complaints", "meaning": "reclamações", "note": ""}, {"word": "upload", "meaning": "enviar, fazer upload", "note": ""}, {"word": "emergency meeting", "meaning": "reunião de emergência", "note": ""}, {"word": "make excuses", "meaning": "arranjar desculpas", "note": ""}, {"word": "bug", "meaning": "erro (de software)", "note": ""}, {"word": "honesty", "meaning": "honestidade", "note": ""}], "grammar_words": {"cognates": [], "tobe": ["was", "were"], "irregular": ["worked", "arrived", "gathered", "began", "called", "asked", "admitted", "explained", "suggested", "agreed", "released", "solved", "learned"], "phrasal": [], "wh": ["what"], "connectors": ["but", "Unfortunately", "Instead of", "Although", "because"], "comparative": ["lower", "Worse", "more valuable", "far more valuable"]}, "word_meanings": [{"word": "launch", "meaning": "lançamento", "note": ""}, {"word": "crashed", "meaning": "travava/falhava", "note": ""}, {"word": "deadline", "meaning": "prazo final", "note": ""}, {"word": "pretending", "meaning": "fingindo", "note": ""}, {"word": "actually", "meaning": "na verdade", "note": "falso cognato"}, {"word": "realize", "meaning": "perceber", "note": "falso cognato"}, {"word": "attend", "meaning": "comparecer, participar", "note": "falso cognato: não é 'atender'"}, {"word": "eventually", "meaning": "finalmente, no final", "note": "falso cognato: não é 'eventualmente'"}, {"word": "push", "meaning": "empurrar", "note": "falso cognato: não é 'puxar'"}, {"word": "parents", "meaning": "pais (mãe e pai)", "note": "falso cognato: não é 'parentes'"}, {"word": "worked", "meaning": "trabalhou", "note": ""}, {"word": "arrived", "meaning": "chegou", "note": ""}, {"word": "gathered", "meaning": "reuniram-se", "note": ""}, {"word": "began", "meaning": "começaram", "note": ""}, {"word": "called", "meaning": "convocou", "note": ""}, {"word": "asked", "meaning": "pediu", "note": ""}, {"word": "admitted", "meaning": "admitiu", "note": ""}, {"word": "explained", "meaning": "explicou", "note": ""}, {"word": "suggested", "meaning": "sugeriu", "note": ""}, {"word": "agreed", "meaning": "concordou", "note": ""}, {"word": "released", "meaning": "lançou", "note": ""}, {"word": "solved", "meaning": "resolveu", "note": ""}, {"word": "learned", "meaning": "aprendeu", "note": ""}], "exercises": {"grammar": [{"point": "Past perfect for explanations", "explanation_pt": "'the testing team hadn't had enough time' usa past perfect para explicar a causa de um problema anterior ao lançamento."}, {"point": "Comparatives of value", "explanation_pt": "'far more valuable than pretending' compara duas atitudes, mostrando qual é melhor."}], "multiple_choice": [{"question": "How long had Claudia worked on the app?", "options": ["Two weeks", "Six months", "One year", "Three days"], "correct_index": 1, "explanation": "Ela trabalhou seis meses no aplicativo."}, {"question": "Why did users complain about the app?", "options": ["It was too expensive", "It crashed when uploading photos", "It had no features", "It was too slow to download"], "correct_index": 1, "explanation": "O aplicativo travava ao enviar fotos."}, {"question": "What did Claudia do when her manager asked what went wrong?", "options": ["She blamed her team", "She admitted the mistake honestly", "She said nothing", "She quit her job"], "correct_index": 1, "explanation": "Ela admitiu o erro honestamente."}, {"question": "How long did Claudia say the team needed to fix the bug?", "options": ["24 hours", "48 hours", "One week", "One month"], "correct_index": 1, "explanation": "Ela sugeriu um prazo de 48 horas."}, {"question": "What did Claudia learn from this experience?", "options": ["To hide mistakes", "To blame others", "That honesty and solutions matter more than excuses", "To quit when things go wrong"], "correct_index": 2, "explanation": "Ela aprendeu que admitir o erro e oferecer solução é mais valioso."}], "open_questions": [{"question": "Do you think it is always better to admit mistakes at work? Why or why not?", "key_points_pt": ["Discutir os riscos e benefícios de admitir erros", "Relacionar com confiança e reputação profissional"]}, {"question": "How would you have reacted if you were Claudia's manager?", "key_points_pt": ["Imaginar-se no papel de gestor", "Explicar como lidaria com a situação"]}]}}, {"level": "B1", "genre": "dialogue", "title": "Choosing a Restaurant", "paragraphs": ["\"Where do you want to eat tonight?\" asked Bruno, scrolling through his phone. \"I really don't mind,\" replied Carla, \"but I don't want anything too heavy. We ate a huge lunch, remember?\" Bruno laughed and said, \"Right, I forgot about that enormous pizza.\"", "\"What about that new Thai place downtown?\" Carla suggested. \"I've heard the food is amazing, and it's not too far from here.\" Bruno hesitated. \"Honestly, spicy food isn't really my thing. Could we find something a little milder?\" \"Sure,\" Carla answered, \"how about the Italian restaurant instead? They have pasta that isn't spicy at all.\"", "\"That sounds better,\" Bruno agreed, \"although we go there quite often. Let's try something we've never had before.\" After a few more minutes of searching, they finally found a small Japanese restaurant with great reviews. \"This looks perfect,\" Carla said. \"Should I make a reservation?\"", "\"Yes, please,\" Bruno answered, smiling. \"And this time, let's actually stick to appetizers so we're not too full afterward.\" Carla laughed. \"You always say that, and we always order dessert anyway.\" They both laughed, grabbed their coats, and headed out the door."], "paragraphs_pt": ["\"Onde você quer comer hoje à noite?\", perguntou Bruno, rolando a tela do celular. \"Eu realmente não me importo\", respondeu Carla, \"mas não quero nada muito pesado. Comemos um almoço enorme, lembra?\" Bruno riu e disse: \"É verdade, esqueci daquela pizza enorme.\"", "\"Que tal aquele novo lugar tailandês no centro?\", sugeriu Carla. \"Ouvi dizer que a comida é incrível, e não é muito longe daqui.\" Bruno hesitou. \"Sinceramente, comida apimentada não é muito a minha praia. Poderíamos encontrar algo um pouco mais suave?\" \"Claro\", respondeu Carla, \"que tal o restaurante italiano então? Eles têm massas que não são nada apimentadas.\"", "\"Isso parece melhor\", Bruno concordou, \"embora a gente vá lá com bastante frequência. Vamos tentar algo que nunca comemos antes.\" Depois de mais alguns minutos procurando, finalmente encontraram um pequeno restaurante japonês com ótimas avaliações. \"Esse parece perfeito\", disse Carla. \"Eu faço a reserva?\"", "\"Sim, por favor\", respondeu Bruno, sorrindo. \"E dessa vez, vamos realmente nos limitar às entradas para não ficarmos muito cheios depois.\" Carla riu. \"Você sempre fala isso, e a gente sempre pede sobremesa mesmo assim.\" Os dois riram, pegaram os casacos e saíram pela porta."], "hard_words": ["scrolling", "hesitated", "appetizers", "reservation"], "vocab": [{"word": "I don't mind", "meaning": "não me importo", "note": ""}, {"word": "heavy (food)", "meaning": "pesado(a)", "note": ""}, {"word": "downtown", "meaning": "no centro (da cidade)", "note": ""}, {"word": "milder", "meaning": "mais suave", "note": ""}, {"word": "stick to", "meaning": "se limitar a", "note": ""}, {"word": "reservation", "meaning": "reserva", "note": ""}, {"word": "headed out", "meaning": "saíram", "note": ""}], "grammar_words": {"cognates": ["actually"], "tobe": ["isn't"], "irregular": ["asked", "replied", "said", "laughed", "forgot", "suggested", "heard", "answered", "agreed", "found", "grabbed"], "phrasal": ["stick to"], "wh": ["Where", "What", "how"], "connectors": ["but", "although", "so", "and"], "comparative": ["milder", "better"]}, "word_meanings": [{"word": "scrolling", "meaning": "rolando a tela", "note": ""}, {"word": "hesitated", "meaning": "hesitou", "note": ""}, {"word": "appetizers", "meaning": "entradas, aperitivos", "note": ""}, {"word": "reservation", "meaning": "reserva", "note": ""}, {"word": "actually", "meaning": "na verdade", "note": "falso cognato"}, {"word": "realize", "meaning": "perceber", "note": "falso cognato"}, {"word": "asked", "meaning": "perguntou", "note": ""}, {"word": "replied", "meaning": "respondeu", "note": ""}, {"word": "said", "meaning": "disse", "note": ""}, {"word": "laughed", "meaning": "riu", "note": ""}, {"word": "forgot", "meaning": "esqueceu", "note": "passado de forget"}, {"word": "suggested", "meaning": "sugeriu", "note": ""}, {"word": "heard", "meaning": "ouviu", "note": ""}, {"word": "answered", "meaning": "respondeu", "note": ""}, {"word": "agreed", "meaning": "concordou", "note": ""}, {"word": "found", "meaning": "encontraram", "note": ""}, {"word": "grabbed", "meaning": "pegaram", "note": ""}, {"word": "stick to", "meaning": "se limitar a", "note": "phrasal verb"}, {"word": "head out", "meaning": "sair", "note": "phrasal verb"}], "exercises": {"grammar": [{"point": "Reported vs direct speech in dialogue", "explanation_pt": "Em diálogos usamos aspas para o discurso direto: '\"Where do you want to eat tonight?\" asked Bruno.' Verbos como 'asked', 'replied', 'suggested' introduzem a fala."}, {"point": "Present perfect with ever/never", "explanation_pt": "'something we've never had before' usa present perfect para experiências até agora, sem tempo específico."}], "multiple_choice": [{"question": "Why didn't Carla want anything too heavy?", "options": ["She was on a diet", "They had eaten a huge lunch", "She didn't like the restaurant", "She wasn't hungry"], "correct_index": 1, "explanation": "Eles tinham comido um almoço enorme."}, {"question": "Why didn't Bruno want to go to the Thai restaurant?", "options": ["It was too expensive", "He doesn't like spicy food", "It was closed", "It was too far"], "correct_index": 1, "explanation": "Comida apimentada não é a praia dele."}, {"question": "Why did they decide not to go to the Italian restaurant?", "options": ["It was closed", "They go there often", "It was too spicy", "It was too expensive"], "correct_index": 1, "explanation": "Eles já vão lá com frequência e queriam algo novo."}, {"question": "What type of restaurant did they finally choose?", "options": ["Thai", "Italian", "Japanese", "Mexican"], "correct_index": 2, "explanation": "Eles escolheram um restaurante japonês."}, {"question": "What does Carla say they always do despite Bruno's plan?", "options": ["Arrive late", "Order dessert anyway", "Forget the reservation", "Argue about the menu"], "correct_index": 1, "explanation": "Eles sempre acabam pedindo sobremesa mesmo assim."}], "open_questions": [{"question": "How do you usually decide where to eat with friends or family?", "key_points_pt": ["Descrever o processo de decisão em grupo", "Comentar sobre preferências alimentares"]}, {"question": "Do you prefer trying new restaurants or going to familiar ones? Why?", "key_points_pt": ["Expressar preferência pessoal", "Justificar com exemplos"]}]}}, {"level": "B1", "genre": "horror", "title": "The Attic Door", "paragraphs": ["When Julia and her husband bought the old farmhouse, the real estate agent mentioned that the attic door should stay locked because the wood was weak and unsafe. For the first few weeks, they simply forgot about it and focused on unpacking.", "One night, Julia woke up because she heard slow, heavy footsteps directly above the bedroom ceiling. She told herself it was probably just an animal that had gotten into the attic through a crack in the roof, although the sound seemed far too heavy for that.", "The footsteps continued every night for a week, always starting around the same time. Finally, unable to sleep, Julia decided to check the attic herself. When she reached the top of the stairs, she found the locked door standing wide open, even though the key was still in her husband's drawer downstairs.", "She never found out what had opened the door, and no animal was ever found inside. Julia and her husband eventually sold the house to another family, and they never mentioned the attic door again, though neither of them ever forgot the sound of those heavy footsteps."], "paragraphs_pt": ["Quando Julia e o marido compraram a antiga fazenda, o corretor de imóveis mencionou que a porta do sótão deveria ficar trancada porque a madeira estava fraca e insegura. Nas primeiras semanas, eles simplesmente se esqueceram disso e se concentraram em desfazer as malas.", "Numa noite, Julia acordou porque ouviu passos lentos e pesados bem acima do teto do quarto. Ela disse a si mesma que provavelmente era apenas um animal que havia entrado no sótão por uma fresta no telhado, embora o som parecesse pesado demais para isso.", "Os passos continuaram todas as noites durante uma semana, sempre começando por volta do mesmo horário. Finalmente, incapaz de dormir, Julia decidiu verificar o sótão sozinha. Quando chegou ao topo da escada, encontrou a porta trancada bem aberta, mesmo com a chave ainda na gaveta do marido, lá embaixo.", "Ela nunca descobriu o que havia aberto a porta, e nenhum animal foi encontrado lá dentro. Julia e o marido acabaram vendendo a casa para outra família, e nunca mais mencionaram a porta do sótão, embora nenhum dos dois jamais tenha esquecido o som daqueles passos pesados."], "hard_words": ["attic", "footsteps", "ceiling", "crack"], "vocab": [{"word": "farmhouse", "meaning": "casa de fazenda", "note": ""}, {"word": "real estate agent", "meaning": "corretor de imóveis", "note": ""}, {"word": "unpacking", "meaning": "desfazendo as malas", "note": ""}, {"word": "woke up", "meaning": "acordou", "note": ""}, {"word": "unable to", "meaning": "incapaz de", "note": ""}, {"word": "drawer", "meaning": "gaveta", "note": ""}, {"word": "found out", "meaning": "descobriu", "note": ""}], "grammar_words": {"cognates": [], "tobe": ["was"], "irregular": ["bought", "mentioned", "forgot", "woke", "heard", "told", "gotten", "continued", "decided", "reached", "found", "sold"], "phrasal": [], "wh": ["what"], "connectors": ["because", "although", "though"], "comparative": ["too heavy"]}, "word_meanings": [{"word": "attic", "meaning": "sótão", "note": ""}, {"word": "footsteps", "meaning": "passos", "note": ""}, {"word": "ceiling", "meaning": "teto", "note": ""}, {"word": "crack", "meaning": "fresta, fenda", "note": ""}, {"word": "actually", "meaning": "na verdade", "note": "falso cognato"}, {"word": "realize", "meaning": "perceber", "note": "falso cognato"}, {"word": "bought", "meaning": "compraram", "note": "passado de buy"}, {"word": "mentioned", "meaning": "mencionou", "note": ""}, {"word": "forgot", "meaning": "esqueceram", "note": ""}, {"word": "woke", "meaning": "acordou", "note": "passado de wake"}, {"word": "heard", "meaning": "ouviu", "note": ""}, {"word": "told", "meaning": "disse", "note": ""}, {"word": "gotten", "meaning": "entrado (particípio de get)", "note": ""}, {"word": "continued", "meaning": "continuaram", "note": ""}, {"word": "decided", "meaning": "decidiu", "note": ""}, {"word": "reached", "meaning": "chegou", "note": ""}, {"word": "found", "meaning": "encontrou", "note": ""}, {"word": "sold", "meaning": "venderam", "note": "passado de sell"}, {"word": "find out", "meaning": "descobrir", "note": "phrasal verb"}, {"word": "get into", "meaning": "entrar em", "note": "phrasal verb"}], "exercises": {"grammar": [{"point": "Past perfect for unexplained events", "explanation_pt": "'what had opened the door' usa past perfect para um evento misterioso anterior à descoberta, o que aumenta a tensão da história."}, {"point": "Even though / Though", "explanation_pt": "'even though the key was still in her husband's drawer' mostra um contraste surpreendente: apesar de a chave estar guardada, a porta estava aberta."}], "multiple_choice": [{"question": "What did the real estate agent say about the attic door?", "options": ["It should stay open", "It should stay locked", "It led to another house", "It was already broken"], "correct_index": 1, "explanation": "Ele disse que a porta deveria ficar trancada."}, {"question": "What woke Julia up one night?", "options": ["A phone call", "Heavy footsteps above the ceiling", "A storm", "Her husband snoring"], "correct_index": 1, "explanation": "Ela ouviu passos pesados acima do teto."}, {"question": "What did Julia find when she reached the attic?", "options": ["An animal", "The door wide open", "Nothing unusual", "Her husband"], "correct_index": 1, "explanation": "Ela encontrou a porta trancada bem aberta."}, {"question": "Where was the key while the door was open?", "options": ["In the lock", "Lost", "In her husband's drawer downstairs", "In Julia's pocket"], "correct_index": 2, "explanation": "A chave estava na gaveta do marido, lá embaixo."}, {"question": "What happened to Julia and her husband in the end?", "options": ["They stayed in the house forever", "They sold the house", "They found the source of the noise", "They called the police"], "correct_index": 1, "explanation": "Eles acabaram vendendo a casa."}], "open_questions": [{"question": "What do you think opened the attic door?", "key_points_pt": ["Especular livremente sobre a causa", "Não há resposta certa, incentivar a imaginação"]}, {"question": "Would you have gone to check the attic alone like Julia did? Why or why not?", "key_points_pt": ["Refletir sobre coragem versus medo", "Justificar a decisão pessoal"]}]}}, {"level": "B2", "genre": "neutral", "title": "The Last Seat on the Train", "paragraphs": ["Marta had been standing on the platform for almost an hour, and the delay was starting to wear her down. She checked her phone again, hoping for an update, but the app simply said the train was still running late. Around her, other passengers were growing restless, shifting their bags from one shoulder to the other and glancing anxiously at the empty tracks.", "When the train finally pulled in, everyone rushed forward at once, and Marta found herself caught in a wave of elbows and suitcases. She managed to squeeze through the doors just before they closed, only to discover that the carriage was already packed. Every seat seemed to be taken, and she resigned herself to standing for the entire journey.", "Then she noticed an elderly man waving at her from a row near the window. He explained that he had saved the seat next to him for his granddaughter, but she had missed the train because of the same delay. Grateful, Marta sat down and thanked him, and the two of them ended up talking for the rest of the trip, swapping stories about their families and their jobs.", "By the time the train reached the final station, Marta realized she had barely noticed the journey pass. What had started as an incredibly frustrating morning had turned, quite unexpectedly, into one of the most pleasant conversations she had had in months. She said goodbye to the old man, wished him luck finding his granddaughter, and stepped off the train with a small, genuine smile."], "paragraphs_pt": ["Marta estava na plataforma havia quase uma hora, e o atraso começava a esgotá-la. Ela checou o celular de novo, esperando uma atualização, mas o aplicativo apenas dizia que o trem continuava atrasado. Ao seu redor, os outros passageiros ficavam cada vez mais impacientes, trocando as bolsas de ombro e olhando ansiosamente para os trilhos vazios.", "Quando o trem finalmente chegou, todo mundo avançou de uma vez, e Marta se viu presa em uma onda de cotovelos e malas. Ela conseguiu se espremer pelas portas bem antes de fecharem, só para descobrir que o vagão já estava lotado. Todos os assentos pareciam ocupados, e ela se resignou a ficar em pé durante toda a viagem.", "Então ela percebeu um senhor idoso acenando para ela em uma fileira perto da janela. Ele explicou que tinha guardado o lugar ao lado para a neta, mas ela havia perdido o trem por causa do mesmo atraso. Agradecida, Marta se sentou e o agradeceu, e os dois acabaram conversando pelo resto da viagem, trocando histórias sobre suas famílias e seus empregos.", "Quando o trem chegou à estação final, Marta percebeu que mal tinha notado a viagem passar. O que havia começado como uma manhã extremamente frustrante havia se transformado, de forma bem inesperada, em uma das conversas mais agradáveis que ela tivera em meses. Ela se despediu do senhor, desejou sorte para ele encontrar a neta e desceu do trem com um sorriso pequeno e sincero."], "hard_words": ["wear her down", "resigned herself", "squeeze", "restless"], "vocab": [{"word": "platform", "meaning": "plataforma", "note": ""}, {"word": "delay", "meaning": "atraso", "note": ""}, {"word": "restless", "meaning": "inquieto, impaciente", "note": ""}, {"word": "wear (someone) down", "meaning": "desgastar, esgotar aos poucos", "note": "phrasal verb"}, {"word": "squeeze through", "meaning": "espremer-se por", "note": "phrasal verb"}, {"word": "resign oneself to", "meaning": "resignar-se a", "note": ""}, {"word": "grateful", "meaning": "grato", "note": ""}, {"word": "genuine", "meaning": "sincero, autêntico", "note": ""}], "word_meanings": [{"word": "wear her down", "meaning": "esgotá-la aos poucos", "note": ""}, {"word": "resigned herself", "meaning": "se resignou", "note": ""}, {"word": "squeeze", "meaning": "espremer-se", "note": ""}, {"word": "restless", "meaning": "inquieto, impaciente", "note": ""}, {"word": "actually", "meaning": "na verdade", "note": "não significa 'atualmente'"}, {"word": "realize", "meaning": "perceber", "note": "falso cognato de 'realizar'"}, {"word": "had been standing", "meaning": "estava em pé (passado perfeito contínuo)", "note": ""}, {"word": "pulled in", "meaning": "chegou, entrou (na estação)", "note": "phrasal verb"}, {"word": "squeeze through", "meaning": "espremer-se por", "note": "phrasal verb"}, {"word": "ended up", "meaning": "acabou, terminou fazendo algo", "note": "phrasal verb"}, {"word": "noticed", "meaning": "notou", "note": ""}, {"word": "stepped off", "meaning": "desceu", "note": ""}, {"word": "managed", "meaning": "conseguiu", "note": ""}, {"word": "checked", "meaning": "checou", "note": ""}, {"word": "said", "meaning": "disse", "note": ""}, {"word": "discovered", "meaning": "descobriu", "note": ""}, {"word": "found", "meaning": "encontrou", "note": ""}], "grammar_words": {"cognates": [], "tobe": ["was", "were"], "irregular": ["had been standing", "checked", "said", "pulled in", "found", "managed", "noticed"], "phrasal": ["pulled in", "squeeze through", "ended up", "stepped off"], "wh": ["what"], "connectors": ["and", "but", "then", "only to"], "comparative": ["one of the most pleasant"]}, "exercises": {"grammar": [{"point": "Past perfect continuous", "explanation_pt": "Usamos 'had been standing' para mostrar uma ação contínua que aconteceu antes de outro momento no passado, como em 'Marta had been standing on the platform for almost an hour'."}, {"point": "Phrasal verbs de movimento", "explanation_pt": "Verbos como 'pulled in' e 'stepped off' descrevem a chegada e a saída do trem; é útil memorizá-los juntos, pois aparecem com frequência em textos sobre viagens."}], "multiple_choice": [{"question": "Why was Marta waiting on the platform for so long?", "options": ["The train was delayed", "The train was cancelled", "She arrived too early", "She missed the previous train"], "correct_index": 0, "explanation": "O texto diz que o trem estava atrasado (delayed)."}, {"question": "What happened when the train arrived?", "options": ["Marta got on easily", "Passengers pushed forward all at once", "Nobody else wanted to board", "The doors stayed open for a long time"], "correct_index": 1, "explanation": "Todos avançaram de uma vez, causando confusão."}, {"question": "Why had the old man saved a seat?", "options": ["For a friend", "For his wife", "For his granddaughter", "For no one"], "correct_index": 2, "explanation": "Ele guardou o assento para a neta."}, {"question": "Why couldn't the granddaughter use the seat?", "options": ["She changed her mind", "She sat somewhere else", "She never planned to travel", "She missed the train because of the delay"], "correct_index": 3, "explanation": "Ela também perdeu o trem por causa do atraso."}, {"question": "How did Marta feel by the end of the journey?", "options": ["Pleasantly surprised", "Still frustrated", "Bored", "Angry at the old man"], "correct_index": 0, "explanation": "A viagem se tornou uma das conversas mais agradáveis que ela teve em meses."}], "open_questions": [{"question": "Do you think small, unplanned conversations with strangers can change your day? Why or why not?", "key_points_pt": ["Mencionar experiências pessoais com estranhos", "Comparar expectativa versus realidade da viagem"]}, {"question": "How would you have reacted if you were in Marta's situation on the crowded train?", "key_points_pt": ["Descrever reação à demora e à lotação", "Explicar se aceitaria ou recusaria o convite do senhor"]}]}}, {"level": "B2", "genre": "humor", "title": "The Cat Who Ran the Meeting", "paragraphs": ["Diego worked from home, and his cat, Waffles, had developed a strange habit of walking across the keyboard during every video call. At first it was mildly annoying, but Diego had learned to mute himself quickly whenever Waffles approached. Unfortunately, on the day of the company's most important meeting, he forgot.", "Halfway through his presentation about quarterly sales, Waffles leapt onto the desk, sat directly in front of the camera, and began grooming himself with total confidence. Diego tried to nudge him away, but the cat refused to move, staring at the screen as if he, too, had opinions about the sales figures. His colleagues, rather than being annoyed, burst out laughing.", "To make matters worse, Waffles' tail brushed against the keyboard and accidentally shared Diego's screen full of vacation photos instead of the sales chart. The room went silent for a moment, then erupted into even louder laughter. Diego, red-faced, apologized repeatedly while trying to regain control of both his cat and his presentation.", "In the end, the meeting turned out to be surprisingly memorable, and Diego's boss admitted it was the most entertaining quarterly review she had ever attended. From then on, colleagues jokingly asked whether Waffles would be joining every call, and Diego, despite the embarrassment, couldn't help but agree that his cat deserved a promotion."], "paragraphs_pt": ["Diego trabalhava de casa, e seu gato, Waffles, tinha desenvolvido o estranho hábito de andar sobre o teclado durante toda videochamada. No começo era levemente irritante, mas Diego tinha aprendido a se silenciar rapidamente sempre que Waffles se aproximava. Infelizmente, no dia da reunião mais importante da empresa, ele esqueceu.", "No meio da apresentação sobre as vendas trimestrais, Waffles pulou sobre a mesa, sentou-se bem na frente da câmera e começou a se limpar com total confiança. Diego tentou empurrá-lo delicadamente para longe, mas o gato se recusou a sair, encarando a tela como se ele também tivesse opiniões sobre os números de vendas. Os colegas, em vez de ficarem irritados, caíram na gargalhada.", "Para piorar, o rabo de Waffles esbarrou no teclado e compartilhou sem querer a tela de Diego cheia de fotos de férias em vez do gráfico de vendas. A sala ficou em silêncio por um instante, e então explodiu em uma risada ainda mais alta. Diego, com o rosto vermelho, pediu desculpas repetidamente enquanto tentava retomar o controle do gato e da apresentação.", "No final, a reunião acabou sendo surpreendentemente memorável, e a chefe de Diego admitiu que aquela foi a revisão trimestral mais divertida que ela já tinha assistido. Dali em diante, os colegas perguntavam de brincadeira se Waffles participaria de todas as chamadas, e Diego, apesar do constrangimento, não pôde deixar de concordar que seu gato merecia uma promoção."], "hard_words": ["grooming", "nudge", "erupted", "red-faced"], "vocab": [{"word": "mute", "meaning": "silenciar, mudo", "note": ""}, {"word": "groom oneself", "meaning": "se limpar/arrumar (animal)", "note": ""}, {"word": "nudge", "meaning": "empurrar de leve, cutucar", "note": ""}, {"word": "burst out laughing", "meaning": "cair na gargalhada", "note": "expressão"}, {"word": "brush against", "meaning": "esbarrar em", "note": ""}, {"word": "erupt", "meaning": "explodir, estourar", "note": ""}, {"word": "regain control", "meaning": "retomar o controle", "note": ""}, {"word": "couldn't help but", "meaning": "não pôde deixar de", "note": "expressão"}], "word_meanings": [{"word": "grooming", "meaning": "se limpando/arrumando", "note": ""}, {"word": "nudge", "meaning": "empurrar de leve", "note": ""}, {"word": "erupted", "meaning": "explodiu", "note": ""}, {"word": "red-faced", "meaning": "com o rosto vermelho (envergonhado)", "note": ""}, {"word": "college", "meaning": "faculdade", "note": "falso cognato de 'colégio'"}, {"word": "eventually", "meaning": "finalmente, por fim", "note": "falso cognato de 'eventualmente'"}, {"word": "leapt", "meaning": "pulou", "note": ""}, {"word": "refused", "meaning": "recusou", "note": ""}, {"word": "burst out laughing", "meaning": "caiu na gargalhada", "note": ""}, {"word": "brushed against", "meaning": "esbarrou em", "note": ""}, {"word": "erupted into", "meaning": "explodiu em", "note": ""}, {"word": "apologized", "meaning": "pediu desculpas", "note": ""}, {"word": "turned out to be", "meaning": "acabou sendo", "note": ""}, {"word": "admitted", "meaning": "admitiu", "note": ""}, {"word": "brush against", "meaning": "esbarrar em", "note": ""}, {"word": "regain control", "meaning": "retomar o controle", "note": ""}], "grammar_words": {"cognates": [], "tobe": ["was", "being"], "irregular": ["leapt", "refused", "erupted", "apologized", "admitted"], "phrasal": ["burst out laughing", "regain control"], "wh": ["whether"], "connectors": ["but", "and", "then"], "comparative": ["most entertaining", "louder"]}, "exercises": {"grammar": [{"point": "Superlativo com 'most'", "explanation_pt": "Para adjetivos longos usamos 'the most' + adjetivo, como em 'the most entertaining quarterly review'."}, {"point": "'couldn't help but' + verbo", "explanation_pt": "Essa estrutura indica algo inevitável: 'Diego couldn't help but agree' significa que ele não conseguiu evitar concordar."}], "multiple_choice": [{"question": "What habit did Waffles have during video calls?", "options": ["Walking across the keyboard", "Meowing loudly", "Sleeping under the desk", "Scratching the chair"], "correct_index": 0, "explanation": "O texto diz que Waffles andava sobre o teclado."}, {"question": "What did Waffles do during the important meeting?", "options": ["Hid under the sofa", "Sat in front of the camera", "Knocked over a plant", "Left the room"], "correct_index": 1, "explanation": "Ele se sentou na frente da câmera."}, {"question": "What accidentally happened because of the cat's tail?", "options": ["The call disconnected", "The microphone turned off", "Vacation photos were shared instead of the chart", "The screen went black"], "correct_index": 2, "explanation": "O rabo do gato compartilhou as fotos de férias sem querer."}, {"question": "How did Diego's colleagues react?", "options": ["They complained to HR", "They left the call", "They ignored it completely", "They laughed"], "correct_index": 3, "explanation": "Eles caíram na gargalhada."}, {"question": "What did Diego's boss think of the meeting afterward?", "options": ["It was the most entertaining review she'd attended", "It was unprofessional", "It should never happen again", "She didn't notice anything"], "correct_index": 0, "explanation": "Ela admitiu que foi a revisão mais divertida que já assistiu."}], "open_questions": [{"question": "Have you ever had an embarrassing moment during an online call or meeting? What happened?", "key_points_pt": ["Descrever a situação", "Explicar como reagiu"]}, {"question": "Do you think pets appearing in work calls makes meetings more human, or is it unprofessional? Explain your view.", "key_points_pt": ["Dar opinião com justificativa", "Considerar contexto profissional versus informal"]}]}}, {"level": "B2", "genre": "detective", "title": "The Missing Painting", "paragraphs": ["Detective Ruiz arrived at the gallery just after midnight, when the alarm had gone off but no one could explain why. The famous painting, a portrait worth millions, had vanished from its frame, leaving only an empty rectangle on the wall. The curator, pale and visibly shaken, insisted that the security system had never failed before.", "Ruiz examined the room carefully, looking for anything that seemed out of place. She noticed that the window latch had been tampered with, though it was still locked from the inside, which struck her as odd. Furthermore, the security footage showed static for exactly six minutes, right when the theft must have occurred, suggesting the thief had inside knowledge of the system.", "As she questioned the staff, one guard kept avoiding eye contact and fidgeting with his keys. Ruiz decided to check his locker and, although he protested loudly, she found a rolled-up canvas hidden beneath his uniform. The guard finally broke down and admitted he had been paid to disable the cameras for a few minutes, never realizing his accomplice intended to steal the painting outright.", "By dawn, the painting had been recovered undamaged, and the guard was arrested along with the mastermind behind the plan, a former employee with access to old security codes. Ruiz filed her report, satisfied that justice had been served, though she couldn't help wondering how many other thefts had gone unnoticed because of similarly clever tricks."], "paragraphs_pt": ["A detetive Ruiz chegou à galeria logo depois da meia-noite, quando o alarme tinha disparado, mas ninguém conseguia explicar o motivo. A famosa pintura, um retrato que valia milhões, tinha desaparecido da moldura, deixando apenas um retângulo vazio na parede. O curador, pálido e visivelmente abalado, insistia que o sistema de segurança nunca tinha falhado antes.", "Ruiz examinou a sala com cuidado, procurando qualquer coisa fora do lugar. Ela notou que a trava da janela tinha sido violada, embora ainda estivesse trancada por dentro, o que lhe pareceu estranho. Além disso, as imagens de segurança mostravam apenas estática durante exatamente seis minutos, bem no momento em que o roubo deve ter acontecido, sugerindo que o ladrão tinha conhecimento interno do sistema.", "Enquanto interrogava os funcionários, um segurança evitava contato visual e mexia nervosamente nas chaves. Ruiz decidiu verificar o armário dele e, apesar de ele protestar em voz alta, encontrou uma tela enrolada escondida sob o uniforme. O segurança finalmente se entregou e admitiu que tinha sido pago para desativar as câmeras por alguns minutos, sem nunca imaginar que seu cúmplice pretendia simplesmente roubar a pintura.", "Ao amanhecer, a pintura já tinha sido recuperada intacta, e o segurança foi preso junto com o mentor do plano, um ex-funcionário que tinha acesso aos códigos antigos de segurança. Ruiz arquivou seu relatório, satisfeita por ver a justiça feita, embora não pudesse deixar de se perguntar quantos outros roubos tinham passado despercebidos por causa de truques igualmente espertos."], "hard_words": ["tampered with", "fidgeting", "outright", "mastermind"], "vocab": [{"word": "vanish", "meaning": "desaparecer", "note": ""}, {"word": "curator", "meaning": "curador (de museu/galeria)", "note": ""}, {"word": "tamper with", "meaning": "adulterar, mexer indevidamente", "note": "phrasal verb"}, {"word": "fidget", "meaning": "mexer-se nervosamente", "note": ""}, {"word": "break down", "meaning": "desmoronar, ceder emocionalmente", "note": "phrasal verb"}, {"word": "accomplice", "meaning": "cúmplice", "note": ""}, {"word": "mastermind", "meaning": "mentor, cérebro do plano", "note": ""}, {"word": "go unnoticed", "meaning": "passar despercebido", "note": ""}], "word_meanings": [{"word": "tampered with", "meaning": "adulterada, violada", "note": ""}, {"word": "fidgeting", "meaning": "mexendo nervosamente", "note": ""}, {"word": "outright", "meaning": "completamente, simplesmente", "note": ""}, {"word": "mastermind", "meaning": "mentor do plano", "note": ""}, {"word": "realize", "meaning": "perceber", "note": "falso cognato de 'realizar'"}, {"word": "actually", "meaning": "na verdade", "note": "falso cognato"}, {"word": "arrived", "meaning": "chegou", "note": ""}, {"word": "went off", "meaning": "disparou (alarme)", "note": "phrasal verb"}, {"word": "vanished", "meaning": "desapareceu", "note": ""}, {"word": "found", "meaning": "encontrou", "note": ""}, {"word": "broke down", "meaning": "se entregou/desmoronou", "note": "phrasal verb"}, {"word": "check", "meaning": "verificar", "note": ""}, {"word": "had vanished", "meaning": "tinha desaparecido", "note": ""}, {"word": "could", "meaning": "conseguia/podia", "note": ""}, {"word": "had gone off", "meaning": "tinha disparado", "note": ""}, {"word": "go unnoticed", "meaning": "passar despercebido", "note": ""}, {"word": "tamper with", "meaning": "adulterar, mexer indevidamente", "note": ""}, {"word": "noticed", "meaning": "notou", "note": ""}, {"word": "insisted", "meaning": "insistiu", "note": ""}, {"word": "examined", "meaning": "examinou", "note": ""}, {"word": "break down", "meaning": "desmoronar, ceder emocionalmente", "note": ""}, {"word": "had never failed", "meaning": "nunca tinha falhado", "note": ""}], "grammar_words": {"cognates": [], "tobe": ["was", "had been"], "irregular": ["arrived", "had gone off", "could", "had vanished", "insisted", "had never failed", "examined", "noticed"], "phrasal": [], "wh": ["why", "how"], "connectors": ["but", "though", "furthermore", "although", "because"], "comparative": ["similarly clever"]}, "exercises": {"grammar": [{"point": "Passado perfeito (had + particípio)", "explanation_pt": "Usamos o past perfect para mostrar que uma ação aconteceu antes de outra no passado, como em 'the painting had vanished' antes da chegada da detetive."}, {"point": "Modal 'must have' para dedução", "explanation_pt": "'must have occurred' expressa uma conclusão lógica sobre o passado, muito comum em histórias de investigação."}], "multiple_choice": [{"question": "What had happened to the painting when Ruiz arrived?", "options": ["It had disappeared", "It was damaged", "It had been sold", "It had been moved to another room"], "correct_index": 0, "explanation": "A pintura tinha desaparecido da moldura."}, {"question": "What seemed odd about the window?", "options": ["It was broken", "It was tampered with but still locked", "It was open", "It had no latch"], "correct_index": 1, "explanation": "A trava tinha sido violada, mas a janela continuava trancada."}, {"question": "What did Ruiz find in the guard's locker?", "options": ["A weapon", "Money", "The rolled-up painting", "A key to the gallery"], "correct_index": 2, "explanation": "Ela encontrou a tela enrolada escondida."}, {"question": "What had the guard been paid to do?", "options": ["Steal the painting himself", "Open the window", "Warn the thief", "Disable the cameras"], "correct_index": 3, "explanation": "Ele foi pago para desativar as câmeras."}, {"question": "Who turned out to be the mastermind?", "options": ["A former employee", "The curator", "A current employee", "Ruiz's colleague"], "correct_index": 0, "explanation": "Um ex-funcionário com acesso aos códigos antigos."}], "open_questions": [{"question": "What clues helped Ruiz realize the guard was involved?", "key_points_pt": ["Mencionar o comportamento nervoso", "Mencionar a decisão de checar o armário"]}, {"question": "Do you think the guard deserved the same punishment as the mastermind? Why or why not?", "key_points_pt": ["Justificar opinião", "Comparar responsabilidades dos dois personagens"]}]}}, {"level": "B2", "genre": "romance", "title": "Letters from the Lighthouse", "paragraphs": ["Every summer, Clara spent two weeks at her grandmother's cottage near the lighthouse, and every summer she wrote a letter she never sent to the boy who ran the small bookshop in town. Tomás, for his part, had noticed her from the very first year, always browsing the poetry section, always leaving without buying anything.", "This particular summer, however, something shifted. Clara walked in, soaked from an unexpected storm, and Tomás handed her a towel before she even asked. They ended up talking for hours about books neither of them had actually read, both too nervous to admit it, laughing at how ridiculous their opinions sounded once spoken aloud.", "Over the following days, Clara found excuses to visit the shop, and Tomás found excuses to close early so they could walk along the cliffs together. Neither mentioned the letters Clara had written over the years, though she sometimes wondered whether he suspected. When he finally confessed that he had saved a poem she once left behind by accident, she realized he had cared far longer than she imagined.", "On her last evening before returning home, they climbed the lighthouse together and watched the sun disappear into the sea. Tomás admitted he had been dreading this moment all summer, afraid she would simply vanish again until next year. Clara smiled and promised that, this time, she would leave with his address instead of another unsent letter."], "paragraphs_pt": ["Todo verão, Clara passava duas semanas na casa de campo da avó perto do farol, e todo verão escrevia uma carta que nunca enviava para o rapaz que trabalhava na pequena livraria da cidade. Tomás, por sua vez, tinha reparado nela desde o primeiro ano, sempre folheando a seção de poesia, sempre saindo sem comprar nada.", "Naquele verão específico, porém, algo mudou. Clara entrou encharcada por uma tempestade inesperada, e Tomás lhe entregou uma toalha antes mesmo que ela pedisse. Eles acabaram conversando por horas sobre livros que nenhum dos dois tinha lido de verdade, ambos nervosos demais para admitir isso, rindo de como suas opiniões soavam ridículas ao serem ditas em voz alta.", "Nos dias seguintes, Clara encontrava desculpas para visitar a livraria, e Tomás encontrava desculpas para fechar mais cedo para poderem caminhar juntos pelos penhascos. Nenhum dos dois mencionou as cartas que Clara tinha escrito ao longo dos anos, embora ela às vezes se perguntasse se ele suspeitava. Quando ele finalmente confessou que tinha guardado um poema que ela deixara por acidente, ela percebeu que ele se importava havia muito mais tempo do que imaginava.", "Na última noite antes de voltar para casa, eles subiram juntos ao farol e observaram o sol desaparecer no mar. Tomás admitiu que temia esse momento durante todo o verão, com medo de que ela simplesmente sumisse de novo até o ano seguinte. Clara sorriu e prometeu que, dessa vez, partiria com o endereço dele em vez de mais uma carta não enviada."], "hard_words": ["browsing", "soaked", "dreading", "cliffs"], "vocab": [{"word": "cottage", "meaning": "casa de campo, chalé", "note": ""}, {"word": "browse", "meaning": "folhear, dar uma olhada", "note": ""}, {"word": "soaked", "meaning": "encharcado", "note": ""}, {"word": "cliff", "meaning": "penhasco", "note": ""}, {"word": "confess", "meaning": "confessar", "note": ""}, {"word": "dread", "meaning": "temer profundamente", "note": ""}, {"word": "vanish", "meaning": "sumir, desaparecer", "note": ""}, {"word": "unsent", "meaning": "não enviado", "note": ""}], "word_meanings": [{"word": "browsing", "meaning": "folheando", "note": ""}, {"word": "soaked", "meaning": "encharcada", "note": ""}, {"word": "dreading", "meaning": "temendo", "note": ""}, {"word": "cliffs", "meaning": "penhascos", "note": ""}, {"word": "actually", "meaning": "na verdade", "note": "falso cognato"}, {"word": "realized", "meaning": "percebeu", "note": ""}, {"word": "spent", "meaning": "passou (tempo)", "note": ""}, {"word": "wrote", "meaning": "escreveu", "note": ""}, {"word": "had noticed", "meaning": "tinha reparado", "note": ""}, {"word": "walked in", "meaning": "entrou", "note": "phrasal verb"}, {"word": "handed", "meaning": "entregou", "note": ""}, {"word": "ended up", "meaning": "acabou", "note": "phrasal verb"}, {"word": "found", "meaning": "encontrou", "note": ""}, {"word": "confessed", "meaning": "confessou", "note": ""}, {"word": "left behind", "meaning": "deixou para trás", "note": "phrasal verb"}], "grammar_words": {"cognates": ["actually", "realized"], "tobe": ["been"], "irregular": ["spent", "wrote", "had noticed", "walked in", "handed", "ended up", "found", "confessed", "left behind", "realized"], "phrasal": ["walked in", "ended up", "left behind"], "wh": ["whether", "how"], "connectors": ["however", "though", "and", "so"], "comparative": ["far longer"]}, "exercises": {"grammar": [{"point": "Uso de 'far' para intensificar comparativos", "explanation_pt": "'far longer' intensifica a comparação, mostrando uma diferença grande, como em 'he had cared far longer than she imagined'."}, {"point": "Past perfect para eventos anteriores", "explanation_pt": "'she had written over the years' mostra uma ação que já vinha acontecendo antes do momento principal da história."}], "multiple_choice": [{"question": "What did Clara do every summer before this particular one?", "options": ["She wrote letters but never sent them", "She sent letters to Tomás", "She avoided the bookshop", "She worked at the lighthouse"], "correct_index": 0, "explanation": "Ela escrevia cartas que nunca enviava."}, {"question": "How did Clara and Tomás's conversation start this summer?", "options": ["At a party", "When she entered the shop soaked from a storm", "On the beach", "During a poetry reading"], "correct_index": 1, "explanation": "Ela entrou encharcada por causa da tempestade."}, {"question": "What had Tomás secretly kept?", "options": ["A photo of Clara", "One of her letters", "A poem she left behind by accident", "A book she bought"], "correct_index": 2, "explanation": "Ele guardou um poema que ela deixou por acidente."}, {"question": "Where did they watch the sunset on Clara's last evening?", "options": ["On the beach", "At the bookshop", "On a boat", "At the lighthouse"], "correct_index": 3, "explanation": "Eles subiram ao farol juntos."}, {"question": "What did Clara promise before leaving?", "options": ["To leave with his address", "To return next week", "To write more letters", "To move to the town"], "correct_index": 0, "explanation": "Ela prometeu deixar o endereço dele em vez de outra carta não enviada."}], "open_questions": [{"question": "Why do you think Clara never sent her letters to Tomás in previous years?", "key_points_pt": ["Falar sobre medo de rejeição ou timidez", "Relacionar com a mudança de comportamento nesse verão"]}, {"question": "Do you believe small coincidences, like a sudden storm, can change the course of a relationship? Share an example.", "key_points_pt": ["Dar opinião pessoal", "Citar exemplo próprio ou hipotético"]}]}}, {"level": "B2", "genre": "scifi", "title": "The Last Signal from Kepler Station", "paragraphs": ["Commander Ines had been monitoring the same silence for three days when the signal finally flickered back to life. Kepler Station, orbiting a distant moon, had gone dark after an unexplained power surge, and Mission Control had feared the worst. Now, a faint transmission crackled through the speakers, barely audible above the static.", "The voice belonged to Dr. Okafor, the station's only remaining crew member, who explained that the surge had fried most of the ship's systems and knocked out life support in two of the three modules. He had spent the last seventy-two hours rerouting power manually, sealing himself into the smallest module to conserve oxygen while he worked.", "Ines coordinated a rescue shuttle immediately, though she knew it would take almost a week to arrive, far longer than Okafor's remaining oxygen supply would normally allow. Fortunately, he had discovered an overlooked reserve tank hidden behind a maintenance panel, something the original engineers had installed decades earlier as an emergency backup nobody remembered.", "When the shuttle finally docked, the crew found Okafor exhausted but alive, having rationed both oxygen and hope in equal measure. Back on Earth, his account of the ordeal became required reading for every new astronaut, a reminder that even the most advanced technology could fail, and that sometimes survival depended on nothing more than patience and a forgotten tank of air."], "paragraphs_pt": ["A comandante Ines já vinha monitorando o mesmo silêncio havia três dias quando o sinal finalmente voltou a piscar. A Estação Kepler, orbitando uma lua distante, tinha ficado às escuras depois de um pico de energia inexplicável, e o Controle da Missão temia o pior. Agora, uma transmissão fraca chiava pelos alto-falantes, mal audível em meio à estática.", "A voz pertencia ao Dr. Okafor, o único tripulante restante da estação, que explicou que o pico havia queimado a maior parte dos sistemas da nave e desligado o suporte de vida em dois dos três módulos. Ele tinha passado as últimas setenta e duas horas redirecionando energia manualmente, isolando-se no menor módulo para economizar oxigênio enquanto trabalhava.", "Ines coordenou um resgate imediatamente, embora soubesse que levaria quase uma semana para chegar, muito mais tempo do que o oxigênio restante de Okafor normalmente permitiria. Felizmente, ele tinha descoberto um tanque de reserva esquecido, escondido atrás de um painel de manutenção, algo que os engenheiros originais tinham instalado décadas antes como um backup de emergência que ninguém mais lembrava.", "Quando a nave de resgate finalmente atracou, a tripulação encontrou Okafor exausto, mas vivo, tendo racionado tanto oxigênio quanto esperança em igual medida. De volta à Terra, o relato dele sobre a provação se tornou leitura obrigatória para todo novo astronauta, um lembrete de que até a tecnologia mais avançada podia falhar, e que às vezes a sobrevivência dependia de nada mais do que paciência e um tanque de ar esquecido."], "hard_words": ["flickered", "fried", "rerouting", "ordeal"], "vocab": [{"word": "power surge", "meaning": "pico de energia", "note": ""}, {"word": "flicker", "meaning": "piscar, tremeluzir", "note": ""}, {"word": "fry (systems)", "meaning": "queimar (circuitos)", "note": "uso informal"}, {"word": "reroute", "meaning": "redirecionar", "note": ""}, {"word": "conserve", "meaning": "economizar, conservar", "note": ""}, {"word": "dock", "meaning": "atracar", "note": ""}, {"word": "ration", "meaning": "racionar", "note": ""}, {"word": "ordeal", "meaning": "provação, experiência difícil", "note": ""}], "word_meanings": [{"word": "flickered", "meaning": "piscou, tremeluziu", "note": ""}, {"word": "fried", "meaning": "queimou (circuitos)", "note": ""}, {"word": "rerouting", "meaning": "redirecionando", "note": ""}, {"word": "ordeal", "meaning": "provação", "note": ""}, {"word": "actually", "meaning": "na verdade", "note": "falso cognato"}, {"word": "eventually", "meaning": "finalmente", "note": "falso cognato"}, {"word": "had been monitoring", "meaning": "vinha monitorando", "note": ""}, {"word": "had gone dark", "meaning": "tinha ficado às escuras", "note": ""}, {"word": "explained", "meaning": "explicou", "note": ""}, {"word": "knocked out", "meaning": "desligou, derrubou", "note": "phrasal verb"}, {"word": "had spent", "meaning": "tinha passado (tempo)", "note": ""}, {"word": "coordinated", "meaning": "coordenou", "note": ""}, {"word": "discovered", "meaning": "descobriu", "note": ""}, {"word": "found", "meaning": "encontrou", "note": ""}, {"word": "became", "meaning": "se tornou", "note": ""}], "grammar_words": {"cognates": [], "tobe": ["had been"], "irregular": ["had been monitoring", "flickered", "had gone dark", "explained", "knocked out", "had spent", "coordinated", "found", "became"], "phrasal": ["knocked out"], "wh": ["who"], "connectors": ["though", "and", "but", "while", "fortunately"], "comparative": ["far longer", "most advanced", "smallest"]}, "exercises": {"grammar": [{"point": "Past perfect continuous", "explanation_pt": "'had been monitoring' mostra uma ação contínua antes de outro evento passado, criando tensão narrativa desde a primeira frase."}, {"point": "Superlativos irregulares e com 'most'", "explanation_pt": "'the smallest module' e 'the most advanced technology' mostram as duas formas de superlativo em inglês, curta e com 'most'."}], "multiple_choice": [{"question": "Why had Kepler Station gone silent?", "options": ["An unexplained power surge", "A meteor strike", "A communication error on Earth", "The crew abandoned it"], "correct_index": 0, "explanation": "Um pico de energia inexplicável causou o silêncio."}, {"question": "What did Dr. Okafor do to conserve oxygen?", "options": ["He left the station", "He sealed himself in the smallest module", "He turned off all communication", "He slept for three days"], "correct_index": 1, "explanation": "Ele se isolou no menor módulo."}, {"question": "What allowed Okafor to survive longer than expected?", "options": ["A second rescue shuttle", "Help from another station", "An overlooked reserve oxygen tank", "Reduced gravity"], "correct_index": 2, "explanation": "Ele encontrou um tanque de reserva esquecido."}, {"question": "How long did the rescue shuttle take to arrive?", "options": ["A few hours", "Three days", "A month", "Almost a week"], "correct_index": 3, "explanation": "O texto diz que levaria quase uma semana."}, {"question": "What lesson did new astronauts learn from Okafor's story?", "options": ["Patience can matter as much as technology", "Technology never fails", "Rescue missions are always fast", "Space stations don't need backups"], "correct_index": 0, "explanation": "O relato virou leitura obrigatória sobre paciência e sobrevivência."}], "open_questions": [{"question": "What personal qualities do you think helped Dr. Okafor survive alone for so long?", "key_points_pt": ["Mencionar paciência, disciplina, criatividade", "Justificar com exemplos do texto"]}, {"question": "Would you be willing to work on a space mission with this level of risk? Why or why not?", "key_points_pt": ["Expressar opinião pessoal", "Justificar considerando riscos e recompensas"]}]}}, {"level": "B2", "genre": "medieval", "title": "The Blacksmith's Apprentice", "paragraphs": ["Aldric had served as the village blacksmith's apprentice for three years, though he still felt clumsy every time he lifted the heavy hammer. The old smith, Master Cedric, rarely praised anyone, and Aldric had grown used to silent nods being the highest compliment he could expect. Still, he dreamed of forging a blade worthy of the knights who occasionally passed through the village.", "One autumn evening, a wounded knight arrived at the forge, his sword shattered after a skirmish near the border. He needed a new blade before dawn, when he was expected to ride to the capital and warn the king of an approaching threat. Master Cedric, exhausted from a long day's work, reluctantly allowed Aldric to attempt the forging himself, watching closely but saying nothing.", "Aldric worked through the night, hammering the glowing steel again and again, adjusting the balance until his arms ached beyond feeling. He thought of every lesson Cedric had ever given him, however brief, and poured all of it into the blade. As dawn approached, he plunged the finished sword into water, and the hiss of steam filled the forge like a held breath finally released.", "The knight tested the blade, swinging it twice before nodding with clear approval, and rode off toward the capital without another word. Master Cedric, watching him disappear over the hill, finally turned to Aldric and said simply that the sword had been well made. It was the longest sentence of praise Aldric had ever received, and he treasured it far more than any coin."], "paragraphs_pt": ["Aldric era aprendiz do ferreiro da vila havia três anos, embora ainda se sentisse desajeitado toda vez que erguia o martelo pesado. O velho ferreiro, Mestre Cedric, raramente elogiava alguém, e Aldric tinha se acostumado a considerar acenos silenciosos como o maior elogio que podia esperar. Ainda assim, ele sonhava em forjar uma lâmina digna dos cavaleiros que ocasionalmente passavam pela vila.", "Numa noite de outono, um cavaleiro ferido chegou à forja, com a espada estilhaçada depois de uma escaramuça perto da fronteira. Ele precisava de uma lâmina nova antes do amanhecer, quando era esperado que cavalgasse até a capital para avisar o rei sobre uma ameaça se aproximando. Mestre Cedric, exausto depois de um longo dia de trabalho, relutantemente permitiu que Aldric tentasse forjá-la sozinho, observando de perto, mas sem dizer nada.", "Aldric trabalhou a noite toda, martelando o aço incandescente repetidas vezes, ajustando o equilíbrio até seus braços doerem além do suportável. Ele pensou em cada lição que Cedric já lhe tinha dado, por mais breve que fosse, e colocou tudo isso na lâmina. Quando o amanhecer se aproximava, ele mergulhou a espada pronta na água, e o silvo do vapor encheu a forja como uma respiração presa finalmente solta.", "O cavaleiro testou a lâmina, brandindo-a duas vezes antes de acenar com clara aprovação, e partiu rumo à capital sem mais palavras. Mestre Cedric, observando-o desaparecer sobre a colina, finalmente se virou para Aldric e disse simplesmente que a espada tinha sido bem feita. Foi a frase de elogio mais longa que Aldric já tinha recebido, e ele a guardou como um tesouro muito maior do que qualquer moeda."], "hard_words": ["clumsy", "skirmish", "reluctantly", "plunged"], "vocab": [{"word": "blacksmith", "meaning": "ferreiro", "note": ""}, {"word": "apprentice", "meaning": "aprendiz", "note": ""}, {"word": "forge (verb/noun)", "meaning": "forjar / forja", "note": ""}, {"word": "skirmish", "meaning": "escaramuça, combate curto", "note": ""}, {"word": "reluctantly", "meaning": "relutantemente", "note": ""}, {"word": "plunge", "meaning": "mergulhar", "note": ""}, {"word": "hiss", "meaning": "silvo, chiado", "note": ""}, {"word": "treasure (verb)", "meaning": "valorizar muito, guardar como tesouro", "note": ""}], "word_meanings": [{"word": "clumsy", "meaning": "desajeitado", "note": ""}, {"word": "skirmish", "meaning": "escaramuça", "note": ""}, {"word": "reluctantly", "meaning": "relutantemente", "note": ""}, {"word": "plunged", "meaning": "mergulhou", "note": ""}, {"word": "eventually", "meaning": "finalmente", "note": "falso cognato"}, {"word": "actually", "meaning": "na verdade", "note": "falso cognato"}, {"word": "had served", "meaning": "tinha servido/era", "note": ""}, {"word": "felt", "meaning": "sentiu/sentia", "note": ""}, {"word": "had grown used to", "meaning": "tinha se acostumado a", "note": ""}, {"word": "arrived", "meaning": "chegou", "note": ""}, {"word": "allowed", "meaning": "permitiu", "note": ""}, {"word": "worked through", "meaning": "trabalhou durante", "note": "phrasal verb"}, {"word": "poured into", "meaning": "colocou tudo em", "note": "phrasal verb"}, {"word": "rode off", "meaning": "partiu cavalgando", "note": "phrasal verb"}, {"word": "treasured", "meaning": "valorizou/guardou como tesouro", "note": ""}], "grammar_words": {"cognates": [], "tobe": ["had served", "was", "being"], "irregular": ["had served", "felt", "arrived", "allowed", "plunged", "rode off", "treasured"], "phrasal": ["worked through", "rode off"], "wh": ["when", "who"], "connectors": ["though", "still", "however", "and", "but", "as"], "comparative": ["longest", "far more"]}, "exercises": {"grammar": [{"point": "Past perfect para dar contexto", "explanation_pt": "'had grown used to' mostra um hábito formado antes do momento principal da história, algo comum em narrativas no passado."}, {"point": "Superlativo 'longest' e comparativo 'far more'", "explanation_pt": "'the longest sentence of praise' e 'far more than any coin' mostram formas diferentes de comparação em inglês."}], "multiple_choice": [{"question": "How long had Aldric been the blacksmith's apprentice?", "options": ["Three years", "One year", "Five years", "Ten years"], "correct_index": 0, "explanation": "O texto diz três anos."}, {"question": "Why did the wounded knight need a new sword?", "options": ["His sword was stolen", "His sword shattered in a skirmish", "He wanted a gift for the king", "He lost a bet"], "correct_index": 1, "explanation": "A espada dele estilhaçou numa escaramuça."}, {"question": "Who actually forged the new sword?", "options": ["Master Cedric", "The knight himself", "Aldric", "A traveling merchant"], "correct_index": 2, "explanation": "Cedric permitiu que Aldric forjasse a espada."}, {"question": "What did the knight do after testing the blade?", "options": ["He complained about it", "He paid double the price", "He stayed in the village", "He rode off toward the capital"], "correct_index": 3, "explanation": "Ele partiu rumo à capital sem mais palavras."}, {"question": "How did Aldric feel about Cedric's final words?", "options": ["He treasured them deeply", "Disappointed", "Indifferent", "Confused"], "correct_index": 0, "explanation": "Ele guardou aquelas palavras como um tesouro."}], "open_questions": [{"question": "Why do you think Master Cedric rarely praised his apprentice before this event?", "key_points_pt": ["Discutir estilo de ensino rigoroso", "Relacionar com valorização do elogio raro"]}, {"question": "Describe a moment when a small amount of recognition or praise meant a lot to you.", "key_points_pt": ["Compartilhar experiência pessoal", "Explicar por que aquele elogio foi significativo"]}]}}, {"level": "B2", "genre": "mythology", "title": "The Weaver Who Outwitted the River God", "paragraphs": ["In the village beside the great river, everyone knew better than to insult the river god, who was said to flood the fields whenever his pride was wounded. Yet Sana, the village's finest weaver, had grown tired of the yearly tribute demanded in exchange for calm waters, a tribute that left her neighbors with barely enough grain to survive winter.", "One evening, Sana wove a cloak so beautiful that it seemed to shimmer like moving water itself, and she left it folded on the riverbank as an offering. The river god, vain and easily flattered, emerged to claim it, delighted by his own reflection in the shifting fabric. He declared that no mortal had ever created anything so magnificent, and he wrapped the cloak around his shoulders at once.", "What the god failed to notice, however, was that the cloak had been woven from threads soaked in river clay, threads that grew heavier the longer they touched water. As he admired himself, the cloak slowly pulled him toward the muddy bank, anchoring him just long enough for Sana to strike a bargain: he would lower the yearly tribute permanently, or she would leave him stuck in the mud until the next full moon.", "Furious but trapped, the river god agreed to her terms, and from that day forward the village paid only a fraction of what it once had. Sana never boasted about her trick, though the villagers whispered the story for generations, calling her the woman clever enough to out-weave a god."], "paragraphs_pt": ["Na vila ao lado do grande rio, todos sabiam que era melhor não insultar o deus do rio, que dizia-se inundar os campos sempre que seu orgulho fosse ferido. Ainda assim, Sana, a melhor tecelã da vila, tinha se cansado do tributo anual exigido em troca de águas calmas, um tributo que deixava seus vizinhos com grãos mal suficientes para sobreviver ao inverno.", "Certa noite, Sana teceu um manto tão bonito que parecia brilhar como a própria água em movimento, e o deixou dobrado na margem do rio como oferenda. O deus do rio, vaidoso e facilmente lisonjeado, emergiu para reivindicá-lo, encantado com seu próprio reflexo no tecido cambiante. Ele declarou que nenhum mortal jamais tinha criado algo tão magnífico, e envolveu o manto em seus ombros imediatamente.", "O que o deus não percebeu, porém, foi que o manto tinha sido tecido com fios embebidos em argila do rio, fios que ficavam mais pesados quanto mais tempo tocavam a água. Enquanto ele se admirava, o manto lentamente o puxava em direção à margem lamacenta, prendendo-o tempo suficiente para Sana fechar um acordo: ele reduziria o tributo anual permanentemente, ou ela o deixaria preso na lama até a próxima lua cheia.", "Furioso, mas preso, o deus do rio aceitou os termos dela, e a partir daquele dia a vila pagava apenas uma fração do que pagava antes. Sana nunca se gabou de seu truque, embora os aldeões sussurrassem a história por gerações, chamando-a de a mulher esperta o bastante para superar um deus tecendo."], "hard_words": ["shimmer", "flattered", "anchoring", "boasted"], "vocab": [{"word": "tribute", "meaning": "tributo", "note": ""}, {"word": "weave / wove / woven", "meaning": "tecer / teceu / tecido", "note": "verbo irregular"}, {"word": "shimmer", "meaning": "brilhar, cintilar", "note": ""}, {"word": "flatter", "meaning": "lisonjear", "note": ""}, {"word": "anchor (verb)", "meaning": "prender, ancorar", "note": ""}, {"word": "strike a bargain", "meaning": "fechar um acordo", "note": "expressão"}, {"word": "boast", "meaning": "gabar-se", "note": ""}, {"word": "out-weave", "meaning": "superar tecendo", "note": "palavra inventada no texto, com prefixo 'out-'"}], "word_meanings": [{"word": "shimmer", "meaning": "brilhar, cintilar", "note": ""}, {"word": "flattered", "meaning": "lisonjeado", "note": ""}, {"word": "anchoring", "meaning": "prendendo", "note": ""}, {"word": "boasted", "meaning": "se gabou", "note": ""}, {"word": "actually", "meaning": "na verdade", "note": "falso cognato"}, {"word": "eventually", "meaning": "finalmente", "note": "falso cognato"}, {"word": "knew", "meaning": "sabiam", "note": ""}, {"word": "had grown tired", "meaning": "tinha se cansado", "note": ""}, {"word": "wove", "meaning": "teceu", "note": ""}, {"word": "left", "meaning": "deixou", "note": ""}, {"word": "emerged", "meaning": "emergiu", "note": ""}, {"word": "declared", "meaning": "declarou", "note": ""}, {"word": "wrapped", "meaning": "envolveu", "note": ""}, {"word": "failed to notice", "meaning": "não percebeu", "note": ""}, {"word": "grew", "meaning": "cresciam/ficavam", "note": ""}, {"word": "agreed", "meaning": "concordou", "note": ""}, {"word": "strike a bargain", "meaning": "fechar um acordo", "note": ""}], "grammar_words": {"cognates": [], "tobe": ["was"], "irregular": ["knew", "had grown tired", "left", "wove", "emerged", "declared", "wrapped", "grew", "agreed", "boasted"], "phrasal": ["strike a bargain"], "wh": ["whenever", "who"], "connectors": ["yet", "however", "though", "and", "but", "or"], "comparative": ["so magnificent", "heavier", "clever enough"]}, "exercises": {"grammar": [{"point": "Voz passiva com 'had been woven'", "explanation_pt": "A voz passiva no past perfect, 'had been woven from threads soaked in river clay', esconde quem fez a ação e enfatiza o objeto, comum em mitos e lendas."}, {"point": "'so...that' para consequência", "explanation_pt": "'so beautiful that it seemed to shimmer' liga uma qualidade extrema a uma consequência, estrutura muito usada em narrativas."}], "multiple_choice": [{"question": "Why was Sana tired of the yearly tribute?", "options": ["It left villagers with barely enough grain", "She didn't believe in the god", "She wanted to be famous", "The god never accepted it"], "correct_index": 0, "explanation": "O tributo deixava os vizinhos com grãos mal suficientes."}, {"question": "What did Sana leave on the riverbank?", "options": ["A basket of food", "A beautiful woven cloak", "A letter", "A statue"], "correct_index": 1, "explanation": "Ela deixou um manto tecido lindamente."}, {"question": "Why was the river god vulnerable to the trick?", "options": ["He was blind", "He was asleep", "He was vain and easily flattered", "He didn't like gifts"], "correct_index": 2, "explanation": "Ele era vaidoso e facilmente lisonjeado."}, {"question": "What made the cloak dangerous to the god?", "options": ["It was cursed", "It was too small", "It caught fire", "It grew heavier when wet, from clay threads"], "correct_index": 3, "explanation": "Os fios embebidos em argila ficavam mais pesados com a água."}, {"question": "What did the river god agree to do in the end?", "options": ["Lower the tribute permanently", "Leave the village forever", "Give Sana his powers", "Flood the fields once more"], "correct_index": 0, "explanation": "Ele concordou em reduzir o tributo anual permanentemente."}], "open_questions": [{"question": "What does this myth suggest about cleverness versus brute strength or power?", "key_points_pt": ["Comparar esperteza e poder físico/divino", "Relacionar com o desfecho da história"]}, {"question": "Do you know a story or myth from Brazilian folklore with a similarly clever trickster character? Describe it briefly.", "key_points_pt": ["Citar personagem do folclore brasileiro (ex: Saci, Curupira)", "Fazer comparação com a história lida"]}]}}, {"level": "B2", "genre": "western", "title": "The Debt at Crescent Ridge", "paragraphs": ["Sheriff Colton rode into Crescent Ridge just as the sun dipped below the mesa, kicking up dust that clung to his worn boots. He had been tracking a gang of cattle thieves for nearly two weeks, and every lead had pointed toward this dusty little town. What he hadn't expected was to find his old friend Wade running the local saloon.", "Wade insisted he had left his outlaw days behind, but Colton noticed the nervous way his friend's eyes darted toward the back room whenever a stranger walked in. Still, loyalty ran deep between them, and Colton decided to give Wade a chance to explain before jumping to conclusions, even as the evidence quietly piled up against him.", "That night, the gang's leader stormed into the saloon demanding Wade hand over the stolen cattle he had apparently been hiding for a cut of the profit. Colton stepped out from the shadows, revealing his badge, and gave Wade one last choice: stand with the law or stand with the thieves. After a long, tense silence, Wade knocked the leader's gun aside and sided with his old friend.", "The gang scattered once they realized they were outnumbered, and by morning most had been rounded up and locked away. Wade, shaken but relieved, admitted he had gotten involved out of desperation rather than greed, and Colton, choosing mercy over strict justice, gave him one chance to start over far from Crescent Ridge, on the condition that he never touched another man's cattle again."], "paragraphs_pt": ["O xerife Colton chegou a Crescent Ridge bem quando o sol se punha atrás da mesa rochosa, levantando poeira que grudava em suas botas gastas. Ele vinha rastreando uma quadrilha de ladrões de gado havia quase duas semanas, e toda pista apontava para aquela cidadezinha empoeirada. O que ele não esperava era encontrar seu velho amigo Wade administrando o saloon local.", "Wade insistiu que tinha deixado seus dias de fora da lei para trás, mas Colton notou o jeito nervoso como os olhos do amigo desviavam para os fundos sempre que um estranho entrava. Ainda assim, a lealdade entre eles era profunda, e Colton decidiu dar a Wade a chance de se explicar antes de tirar conclusões precipitadas, mesmo enquanto as evidências se acumulavam silenciosamente contra ele.", "Naquela noite, o líder da quadrilha invadiu o saloon exigindo que Wade entregasse o gado roubado que aparentemente vinha escondendo em troca de uma parte do lucro. Colton saiu das sombras, revelando seu distintivo, e deu a Wade uma última escolha: ficar do lado da lei ou do lado dos ladrões. Depois de um longo e tenso silêncio, Wade derrubou a arma do líder e ficou ao lado do velho amigo.", "A quadrilha se espalhou ao perceber que estava em desvantagem numérica, e pela manhã a maioria já tinha sido capturada e presa. Wade, abalado mas aliviado, admitiu que tinha se envolvido por desespero, e não por ganância, e Colton, escolhendo a misericórdia em vez da justiça rígida, deu a ele uma chance de recomeçar longe de Crescent Ridge, com a condição de nunca mais tocar no gado de outro homem."], "hard_words": ["mesa", "darted", "stormed", "scattered"], "vocab": [{"word": "saloon", "meaning": "bar/taverna do velho oeste", "note": ""}, {"word": "outlaw", "meaning": "fora da lei", "note": ""}, {"word": "dart (eyes)", "meaning": "desviar rapidamente (olhar)", "note": ""}, {"word": "storm in", "meaning": "entrar irrompendo, furioso", "note": "phrasal verb"}, {"word": "hand over", "meaning": "entregar", "note": "phrasal verb"}, {"word": "outnumbered", "meaning": "em desvantagem numérica", "note": ""}, {"word": "round up", "meaning": "capturar, reunir (à força)", "note": "phrasal verb"}, {"word": "greed", "meaning": "ganância", "note": ""}], "word_meanings": [{"word": "mesa", "meaning": "platô rochoso (formação geológica)", "note": ""}, {"word": "darted", "meaning": "desviaram rapidamente", "note": ""}, {"word": "stormed", "meaning": "invadiu furiosamente", "note": ""}, {"word": "scattered", "meaning": "se espalhou", "note": ""}, {"word": "actually", "meaning": "na verdade", "note": "falso cognato"}, {"word": "eventually", "meaning": "finalmente", "note": "falso cognato"}, {"word": "rode", "meaning": "cavalgou", "note": ""}, {"word": "had been tracking", "meaning": "vinha rastreando", "note": ""}, {"word": "hadn't expected", "meaning": "não esperava", "note": ""}, {"word": "found", "meaning": "encontrou", "note": ""}, {"word": "insisted", "meaning": "insistiu", "note": ""}, {"word": "noticed", "meaning": "notou", "note": ""}, {"word": "decided", "meaning": "decidiu", "note": ""}, {"word": "gave", "meaning": "deu", "note": ""}, {"word": "knocked aside", "meaning": "derrubou/afastou com um golpe", "note": "phrasal verb"}, {"word": "sided with", "meaning": "ficou do lado de", "note": ""}, {"word": "realized", "meaning": "perceberam", "note": ""}, {"word": "admitted", "meaning": "admitiu", "note": ""}, {"word": "storm in", "meaning": "entrar irrompendo, furioso", "note": ""}, {"word": "round up", "meaning": "capturar, reunir à força", "note": ""}, {"word": "hand over", "meaning": "entregar", "note": ""}], "grammar_words": {"cognates": [], "tobe": ["was", "were"], "irregular": ["rode", "had been tracking", "hadn't expected", "insisted", "noticed", "darted", "decided", "gave", "stormed"], "phrasal": ["hand over", "sided with"], "wh": ["what", "whenever"], "connectors": ["but", "still", "even as", "and", "or", "rather than"], "comparative": ["nearly two weeks"]}, "exercises": {"grammar": [{"point": "Past perfect continuous para ações prolongadas", "explanation_pt": "'had been tracking' mostra uma ação contínua que já durava antes do momento presente da história, dando ideia de esforço prolongado."}, {"point": "Phrasal verbs de ação e conflito", "explanation_pt": "Expressões como 'storm in', 'hand over' e 'round up' são comuns em histórias de ação e ajudam a descrever eventos rápidos."}], "multiple_choice": [{"question": "Why had Colton come to Crescent Ridge?", "options": ["To track a gang of cattle thieves", "To visit Wade", "To retire", "To open a saloon"], "correct_index": 0, "explanation": "Ele vinha rastreando ladrões de gado."}, {"question": "What made Colton suspicious of Wade?", "options": ["Wade's clothes", "Wade's nervous glances toward the back room", "Wade's accent", "Wade's new horse"], "correct_index": 1, "explanation": "Os olhos de Wade desviavam nervosamente para os fundos."}, {"question": "What did the gang leader demand from Wade?", "options": ["Money", "A place to sleep", "The stolen cattle Wade had been hiding", "Information about Colton"], "correct_index": 2, "explanation": "Ele exigiu o gado roubado que Wade escondia."}, {"question": "What choice did Wade ultimately make?", "options": ["He ran away", "He sided with the gang", "He stayed neutral", "He sided with Colton and the law"], "correct_index": 3, "explanation": "Ele derrubou a arma do líder e ficou do lado de Colton."}, {"question": "How did Colton treat Wade in the end?", "options": ["He gave him a chance to start over", "He arrested him anyway", "He ignored him completely", "He exiled him publicly"], "correct_index": 0, "explanation": "Colton escolheu misericórdia e deu a ele uma chance de recomeçar."}], "open_questions": [{"question": "Do you think Colton was right to give Wade a second chance instead of arresting him? Why or why not?", "key_points_pt": ["Discutir justiça versus lealdade", "Justificar opinião com base na história"]}, {"question": "What would you have done if you discovered an old friend was secretly involved in a crime?", "key_points_pt": ["Refletir sobre lealdade pessoal versus princípios", "Dar exemplo hipotético"]}]}}, {"level": "B2", "genre": "spy", "title": "The Courier's Umbrella", "paragraphs": ["Agent Voss had memorized every detail of the meeting: a rainy afternoon, a crowded train station, and an umbrella with a chipped wooden handle that would identify the courier. What she hadn't anticipated was that three people in the terminal would be carrying nearly identical umbrellas, each one innocently unaware of the chaos their fashion choice was about to cause.", "She approached the first man cautiously, murmuring the agreed-upon phrase about the weather in Lisbon. He simply looked at her, confused, and hurried away, clearly just an ordinary commuter. The second attempt went slightly better, until the man laughed and explained he had bought the umbrella that same morning at a shop down the street, utterly unaware of any secret meaning behind it.", "Running out of time, Voss noticed a woman standing unusually still near the ticket booth, watching the crowd rather than checking the departure board like everyone else. When Voss repeated the phrase, the woman's expression barely changed, but she tilted her umbrella just enough to reveal a small folded note taped beneath the handle. The exchange took less than four seconds.", "Only once she was safely on a departing train did Voss allow herself to unfold the note, which contained coordinates for a shipment far more dangerous than anyone at headquarters had suspected. She realized, not for the first time, that the most difficult part of espionage was rarely the danger itself, but the sheer amount of patience required to sort chance from design in a crowd of ordinary strangers."], "paragraphs_pt": ["A agente Voss tinha memorizado cada detalhe do encontro: uma tarde chuvosa, uma estação de trem lotada e um guarda-chuva com o cabo de madeira lascado que identificaria a correio. O que ela não tinha previsto era que três pessoas no terminal estariam carregando guarda-chuvas quase idênticos, cada uma inocentemente alheia ao caos que sua escolha de acessório estava prestes a causar.", "Ela se aproximou do primeiro homem com cautela, murmurando a frase combinada sobre o tempo em Lisboa. Ele apenas olhou para ela, confuso, e se afastou apressado, claramente apenas um passageiro comum. A segunda tentativa foi um pouco melhor, até o homem rir e explicar que tinha comprado o guarda-chuva naquela mesma manhã numa loja perto dali, completamente alheio a qualquer significado secreto por trás dele.", "Sem tempo a perder, Voss notou uma mulher parada de forma incomumente imóvel perto da bilheteria, observando a multidão em vez de checar o painel de partidas como todo mundo. Quando Voss repetiu a frase, a expressão da mulher quase não mudou, mas ela inclinou o guarda-chuva o suficiente para revelar um pequeno bilhete dobrado colado sob o cabo. A troca durou menos de quatro segundos.", "Só depois de estar em segurança num trem já partindo é que Voss se permitiu desdobrar o bilhete, que continha coordenadas de um carregamento muito mais perigoso do que qualquer pessoa na sede tinha suspeitado. Ela percebeu, não pela primeira vez, que a parte mais difícil da espionagem raramente era o perigo em si, mas a enorme quantidade de paciência necessária para separar o acaso do plano em meio a uma multidão de estranhos comuns."], "hard_words": ["chipped", "murmuring", "commuter", "espionage"], "vocab": [{"word": "courier", "meaning": "correio, mensageiro", "note": ""}, {"word": "chipped", "meaning": "lascado", "note": ""}, {"word": "murmur", "meaning": "murmurar", "note": ""}, {"word": "commuter", "meaning": "passageiro que viaja regularmente", "note": ""}, {"word": "utterly", "meaning": "completamente", "note": ""}, {"word": "ticket booth", "meaning": "bilheteria", "note": ""}, {"word": "tilt", "meaning": "inclinar", "note": ""}, {"word": "espionage", "meaning": "espionagem", "note": ""}], "word_meanings": [{"word": "chipped", "meaning": "lascado", "note": ""}, {"word": "murmuring", "meaning": "murmurando", "note": ""}, {"word": "commuter", "meaning": "passageiro regular", "note": ""}, {"word": "espionage", "meaning": "espionagem", "note": ""}, {"word": "actually", "meaning": "na verdade", "note": "falso cognato"}, {"word": "realize", "meaning": "perceber", "note": "falso cognato de 'realizar'"}, {"word": "had memorized", "meaning": "tinha memorizado", "note": ""}, {"word": "hadn't anticipated", "meaning": "não tinha previsto", "note": ""}, {"word": "approached", "meaning": "se aproximou", "note": ""}, {"word": "hurried away", "meaning": "se afastou apressado", "note": "phrasal verb"}, {"word": "found out", "meaning": "descobriu", "note": "phrasal verb (não usada no texto mas relevante)"}, {"word": "noticed", "meaning": "notou", "note": ""}, {"word": "realized", "meaning": "percebeu", "note": ""}, {"word": "sort", "meaning": "separar, classificar", "note": ""}], "grammar_words": {"cognates": [], "tobe": ["was"], "irregular": ["had memorized", "hadn't anticipated", "approached", "murmuring", "hurried away", "noticed", "realized"], "phrasal": ["hurried away"], "wh": ["what"], "connectors": ["but", "until", "rather than"], "comparative": ["slightly better", "far more dangerous", "most difficult"]}, "exercises": {"grammar": [{"point": "Past perfect para expectativas frustradas", "explanation_pt": "'What she hadn't anticipated was...' mostra uma expectativa que não se confirmou, técnica comum em histórias de suspense."}, {"point": "Comparativos de grau variado", "explanation_pt": "'slightly better' e 'far more dangerous' mostram como advérbios como 'slightly' e 'far' ajustam a intensidade da comparação."}], "multiple_choice": [{"question": "What object would identify the courier?", "options": ["An umbrella with a chipped handle", "A red scarf", "A newspaper", "A specific hat"], "correct_index": 0, "explanation": "Um guarda-chuva com o cabo lascado identificaria a correio."}, {"question": "Why did the first attempt fail?", "options": ["The man ran away in fear", "He was just an ordinary commuter", "He recognized Voss", "He didn't speak the language"], "correct_index": 1, "explanation": "Ele era apenas um passageiro comum, confuso com a frase."}, {"question": "What made the woman near the ticket booth suspicious?", "options": ["Her clothing", "She was talking loudly", "She stood still, watching the crowd", "She was running"], "correct_index": 2, "explanation": "Ela observava a multidão em vez de checar o painel."}, {"question": "How was the note hidden?", "options": ["Inside a book", "In a pocket", "Under a hat", "Taped beneath the umbrella handle"], "correct_index": 3, "explanation": "O bilhete estava colado sob o cabo do guarda-chuva."}, {"question": "What did Voss conclude about espionage at the end?", "options": ["It mostly requires patience to sort chance from design", "It is mostly about danger", "It requires no planning", "It is easy once you memorize details"], "correct_index": 0, "explanation": "Ela percebeu que a parte mais difícil era a paciência necessária."}], "open_questions": [{"question": "Why do you think the mission relied on such a simple and everyday object like an umbrella?", "key_points_pt": ["Discutir discrição e disfarce em missões secretas", "Relacionar com o risco de confusão"]}, {"question": "Have you ever mistaken a stranger for someone you were expecting to meet? Describe what happened.", "key_points_pt": ["Compartilhar experiência pessoal", "Comparar com a confusão da história"]}]}}, {"level": "B2", "genre": "timetravel", "title": "Thirty Years Too Soon", "paragraphs": ["When the machine finally hummed to life, Priya expected fireworks, or at least a dramatic flash of light. Instead, the lab around her simply flickered, and when it steadied again, the equipment looked older, dustier, and strangely familiar. She checked the calibration panel and realized, with a jolt of panic, that she had traveled thirty years into the past rather than the future she had intended.", "Careful not to interact with anyone who might recognize her, Priya wandered the university halls, astonished to see her own mentor, Professor Liu, decades younger and full of an energy she barely remembered him having. She resisted the urge to speak to him, terrified of disrupting events that had already shaped the future she came from, though the temptation grew stronger with every familiar hallway she passed.", "Her plan to quietly repair the machine and return unnoticed fell apart when she overheard Professor Liu discussing an experiment that, in her own timeline, had famously failed and set the entire field back a decade. Torn between scientific ethics and a desperate wish to prevent years of wasted research, she finally left an anonymous note pointing out a flaw she knew, from hindsight, would doom the experiment.", "Back in her own present, Priya found the timeline eerily unchanged in most respects, except for one small detail: Professor Liu's award now included a line thanking an anonymous colleague whose insight had saved his career. She never told anyone what she had done, but she kept that framed award clipping on her desk as a quiet reminder that even a whisper across time could matter."], "paragraphs_pt": ["Quando a máquina finalmente zumbiu e entrou em funcionamento, Priya esperava fogos de artifício, ou pelo menos um flash dramático de luz. Em vez disso, o laboratório ao seu redor simplesmente tremeluziu, e quando se estabilizou de novo, o equipamento parecia mais antigo, empoeirado e estranhamente familiar. Ela checou o painel de calibração e percebeu, com um susto de pânico, que tinha viajado trinta anos para o passado, em vez do futuro que pretendia.", "Cuidadosa para não interagir com ninguém que pudesse reconhecê-la, Priya vagou pelos corredores da universidade, espantada ao ver seu próprio mentor, o Professor Liu, décadas mais jovem e cheio de uma energia que ela mal lembrava ele ter tido. Ela resistiu ao impulso de falar com ele, apavorada com a ideia de atrapalhar eventos que já tinham moldado o futuro de onde ela vinha, embora a tentação crescesse a cada corredor familiar que ela passava.", "Seu plano de consertar a máquina discretamente e voltar sem ser notada desmoronou quando ela ouviu por acaso o Professor Liu discutindo um experimento que, em sua própria linha do tempo, tinha famosamente fracassado e atrasado toda a área em uma década. Dividida entre a ética científica e o desejo desesperado de evitar anos de pesquisa desperdiçada, ela finalmente deixou um bilhete anônimo apontando uma falha que ela sabia, em retrospecto, que condenaria o experimento.", "De volta ao seu próprio presente, Priya encontrou a linha do tempo assustadoramente inalterada na maioria dos aspectos, exceto por um pequeno detalhe: o prêmio do Professor Liu agora incluía uma linha agradecendo a um colega anônimo cuja perspicácia tinha salvado sua carreira. Ela nunca contou a ninguém o que tinha feito, mas guardou aquele recorte emoldurado do prêmio em sua mesa como um lembrete silencioso de que até um sussurro através do tempo podia importar."], "hard_words": ["hummed", "jolt", "hindsight", "eerily"], "vocab": [{"word": "hum (verb)", "meaning": "zumbir", "note": ""}, {"word": "jolt", "meaning": "susto, choque repentino", "note": ""}, {"word": "astonished", "meaning": "espantado", "note": ""}, {"word": "overhear", "meaning": "ouvir por acaso", "note": ""}, {"word": "hindsight", "meaning": "retrospecto, visão retrospectiva", "note": ""}, {"word": "doom (verb)", "meaning": "condenar, sentenciar ao fracasso", "note": ""}, {"word": "eerily", "meaning": "de forma assustadora/estranha", "note": ""}, {"word": "insight", "meaning": "perspicácia, percepção profunda", "note": ""}], "word_meanings": [{"word": "hummed", "meaning": "zumbiu", "note": ""}, {"word": "jolt", "meaning": "susto repentino", "note": ""}, {"word": "hindsight", "meaning": "retrospecto", "note": ""}, {"word": "eerily", "meaning": "de forma estranha/assustadora", "note": ""}, {"word": "actually", "meaning": "na verdade", "note": "falso cognato"}, {"word": "realize", "meaning": "perceber", "note": "falso cognato de 'realizar'"}, {"word": "expected", "meaning": "esperava", "note": ""}, {"word": "flickered", "meaning": "tremeluziu", "note": ""}, {"word": "checked", "meaning": "checou", "note": ""}, {"word": "realized", "meaning": "percebeu", "note": ""}, {"word": "had traveled", "meaning": "tinha viajado", "note": ""}, {"word": "wandered", "meaning": "vagou", "note": ""}, {"word": "resisted", "meaning": "resistiu", "note": ""}, {"word": "fell apart", "meaning": "desmoronou", "note": "phrasal verb"}, {"word": "overheard", "meaning": "ouviu por acaso", "note": ""}, {"word": "left", "meaning": "deixou", "note": ""}, {"word": "found", "meaning": "encontrou", "note": ""}, {"word": "kept", "meaning": "guardou", "note": ""}], "grammar_words": {"cognates": [], "tobe": [], "irregular": ["hummed", "expected", "flickered", "checked", "realized", "had traveled", "wandered", "resisted", "fell apart", "overheard"], "phrasal": ["fell apart"], "wh": ["who", "what"], "connectors": ["instead", "though", "but", "except"], "comparative": ["older", "younger", "stronger"]}, "exercises": {"grammar": [{"point": "Past perfect para eventos antes da viagem no tempo", "explanation_pt": "'she had traveled thirty years into the past' mostra uma ação concluída antes do momento em que ela percebe o erro, típico de histórias de viagem no tempo."}, {"point": "Comparativos simples com '-er'", "explanation_pt": "'older', 'younger' e 'stronger' são comparativos formados com o sufixo '-er', comuns em adjetivos curtos."}], "multiple_choice": [{"question": "What did Priya expect when the machine activated?", "options": ["Fireworks or a dramatic flash", "Nothing at all", "A loud alarm", "An explosion"], "correct_index": 0, "explanation": "Ela esperava fogos de artifício ou um flash dramático."}, {"question": "What mistake did Priya realize she had made?", "options": ["She traveled to the wrong city", "She traveled into the past instead of the future", "She broke the machine completely", "She brought the wrong equipment"], "correct_index": 1, "explanation": "Ela tinha viajado para o passado em vez do futuro pretendido."}, {"question": "Why didn't Priya speak to young Professor Liu?", "options": ["She didn't recognize him", "He didn't speak her language", "She was afraid of disrupting the future", "She had no time"], "correct_index": 2, "explanation": "Ela temia atrapalhar eventos que moldaram o futuro."}, {"question": "What did Priya do about the failed experiment she knew about?", "options": ["She ignored it completely", "She told Professor Liu directly", "She destroyed his notes", "She left an anonymous note about the flaw"], "correct_index": 3, "explanation": "Ela deixou um bilhete anônimo apontando a falha."}, {"question": "What changed when Priya returned to her present?", "options": ["The professor's award mentioned an anonymous colleague", "Nothing changed", "She lost her job", "The machine disappeared"], "correct_index": 0, "explanation": "O prêmio passou a agradecer a um colega anônimo."}], "open_questions": [{"question": "Do you think Priya was right to leave the anonymous note, even though it meant interfering with the past? Why or why not?", "key_points_pt": ["Discutir ética da interferência no tempo", "Justificar opinião"]}, {"question": "If you could travel thirty years into the past, what is one thing you would be tempted to change, and why?", "key_points_pt": ["Compartilhar ideia pessoal", "Explicar motivo e possíveis consequências"]}]}}, {"level": "B2", "genre": "news", "title": "City Council Approves Controversial Park Redesign", "paragraphs": ["After nearly eight months of heated public debate, the city council voted 6-3 on Tuesday night to approve a controversial redesign of Fairview Park, one of the oldest green spaces in the city. The plan, first proposed last winter, replaces several aging playground structures and adds a new community garden, but critics argue that it also removes a significant number of mature trees.", "Supporters of the redesign, including several local business owners, claim the changes will attract more families and boost foot traffic to nearby shops, which have struggled since a nearby mall opened five years ago. \"This park has been neglected for far too long,\" said council member Diane Foster during the meeting. \"We finally have a plan that balances recreation, accessibility, and community input.\"", "Opponents, however, remain unconvinced. A grassroots group called Save Fairview Trees collected over four thousand signatures opposing the removal of what they describe as irreplaceable century-old oaks. \"You cannot simply replant a hundred years of shade,\" argued group spokesperson Marcus Bell outside city hall. \"Once these trees are gone, this neighborhood loses something it can never fully get back.\"", "Construction is expected to begin in early spring and take roughly fourteen months to complete, according to city planners. The council has promised additional public meetings throughout the process to address ongoing concerns, though it remains unclear whether any further changes to the original plan are still possible at this stage."], "paragraphs_pt": ["Depois de quase oito meses de acalorado debate público, a câmara municipal votou 6 a 3 na terça-feira à noite para aprovar uma polêmica reforma do Parque Fairview, um dos espaços verdes mais antigos da cidade. O plano, proposto pela primeira vez no inverno passado, substitui diversas estruturas de playground envelhecidas e acrescenta uma nova horta comunitária, mas críticos argumentam que também remove um número significativo de árvores maduras.", "Apoiadores da reforma, incluindo diversos comerciantes locais, afirmam que as mudanças vão atrair mais famílias e aumentar o movimento de pedestres nas lojas próximas, que enfrentam dificuldades desde que um shopping próximo abriu há cinco anos. \"Esse parque foi negligenciado por tempo demais\", disse a vereadora Diane Foster durante a reunião. \"Finalmente temos um plano que equilibra recreação, acessibilidade e participação da comunidade.\"", "Os opositores, porém, continuam sem se convencer. Um grupo de base chamado Save Fairview Trees coletou mais de quatro mil assinaturas se opondo à remoção do que descrevem como carvalhos centenários insubstituíveis. \"Você não pode simplesmente replantar cem anos de sombra\", argumentou o porta-voz do grupo, Marcus Bell, do lado de fora da prefeitura. \"Assim que essas árvores desaparecerem, esse bairro perde algo que nunca vai recuperar totalmente.\"", "A construção deve começar no início da primavera e levar aproximadamente quatorze meses para ser concluída, segundo os planejadores da cidade. A câmara prometeu reuniões públicas adicionais ao longo do processo para tratar das preocupações contínuas, embora ainda não esteja claro se mais alguma mudança no plano original ainda é possível nesta etapa."], "hard_words": ["grassroots", "spokesperson", "neglected", "irreplaceable"], "vocab": [{"word": "council", "meaning": "câmara, conselho municipal", "note": ""}, {"word": "controversial", "meaning": "polêmico", "note": ""}, {"word": "boost", "meaning": "impulsionar, aumentar", "note": ""}, {"word": "grassroots", "meaning": "de base, popular", "note": ""}, {"word": "spokesperson", "meaning": "porta-voz", "note": ""}, {"word": "neglected", "meaning": "negligenciado", "note": ""}, {"word": "irreplaceable", "meaning": "insubstituível", "note": ""}, {"word": "ongoing", "meaning": "contínuo, em andamento", "note": ""}], "word_meanings": [{"word": "grassroots", "meaning": "de base, popular", "note": ""}, {"word": "spokesperson", "meaning": "porta-voz", "note": ""}, {"word": "neglected", "meaning": "negligenciado", "note": ""}, {"word": "irreplaceable", "meaning": "insubstituível", "note": ""}, {"word": "actually", "meaning": "na verdade", "note": "falso cognato"}, {"word": "eventually", "meaning": "finalmente", "note": "falso cognato"}, {"word": "voted", "meaning": "votou", "note": ""}, {"word": "proposed", "meaning": "proposto", "note": ""}, {"word": "argue", "meaning": "argumentar", "note": ""}, {"word": "claim", "meaning": "afirmar", "note": ""}, {"word": "struggled", "meaning": "enfrentaram dificuldades", "note": ""}, {"word": "said", "meaning": "disse", "note": ""}, {"word": "collected", "meaning": "coletou", "note": ""}, {"word": "describe", "meaning": "descrever", "note": ""}, {"word": "is expected", "meaning": "espera-se que", "note": ""}, {"word": "promised", "meaning": "prometeu", "note": ""}], "grammar_words": {"cognates": [], "tobe": ["is", "has been"], "irregular": ["voted", "argue", "claim", "said", "collected", "describe", "is expected"], "phrasal": [], "wh": ["whether", "what"], "connectors": ["but", "however", "though", "since"], "comparative": ["oldest", "more families", "far too long"]}, "exercises": {"grammar": [{"point": "Presente perfeito com relevância no presente", "explanation_pt": "'has been neglected' e 'has promised' conectam ações passadas com a situação atual, comum em textos jornalísticos."}, {"point": "Discurso direto em reportagens", "explanation_pt": "Aspas com falas exatas, como '\"This park has been neglected for far too long,\" said council member Diane Foster', são típicas do gênero notícia para dar credibilidade."}], "multiple_choice": [{"question": "How did the city council vote on the park redesign?", "options": ["6-3 in favor", "Unanimously in favor", "5-4 against", "The vote was postponed"], "correct_index": 0, "explanation": "O texto diz que a votação foi 6 a 3."}, {"question": "What do critics say the redesign removes?", "options": ["Parking spaces", "A significant number of mature trees", "The community garden", "The playground entirely"], "correct_index": 1, "explanation": "Críticos dizem que remove árvores maduras."}, {"question": "Why do supporters believe the redesign will help local businesses?", "options": ["It lowers taxes", "It removes the mall", "It will attract more families and foot traffic", "It creates parking lots"], "correct_index": 2, "explanation": "Eles acreditam que vai atrair mais famílias e movimento."}, {"question": "What did the group Save Fairview Trees do?", "options": ["Filed a lawsuit", "Organized a protest march", "Met with the mayor privately", "Collected over four thousand signatures"], "correct_index": 3, "explanation": "O grupo coletou mais de quatro mil assinaturas."}, {"question": "When is construction expected to begin?", "options": ["In early spring", "Immediately", "Next winter", "In two years"], "correct_index": 0, "explanation": "A construção deve começar no início da primavera."}], "open_questions": [{"question": "Do you agree with the council's decision to prioritize new facilities over preserving old trees? Explain your reasoning.", "key_points_pt": ["Ponderar valor ambiental versus infraestrutura nova", "Justificar opinião pessoal"]}, {"question": "How could the city have handled the disagreement between supporters and opponents differently?", "key_points_pt": ["Sugerir formas de diálogo ou compromisso", "Considerar interesses de ambos os lados"]}]}}, {"level": "B2", "genre": "interview", "title": "A Conversation with a Marathon Runner Who Started at 50", "paragraphs": ["Q: You didn't start running until you were fifty. What finally pushed you to try it? A: Honestly, it was almost an accident. My doctor suggested I walk more after a routine check-up, and one day I just started jogging the last block home instead of walking it. It felt ridiculous at first, but something about it stuck with me, and I kept adding a little more distance each week.", "Q: Was it difficult to keep going, especially in the beginning? A: Incredibly difficult, yes. My knees ached, I was embarrassingly slow, and I remember feeling self-conscious whenever younger runners passed me. But I told myself that comparing my pace to theirs was pointless; I was competing against the version of myself from the week before, not against anyone else.", "Q: What was the turning point that made you consider running an actual marathon? A: I think it was finishing my first ten-kilometer race without stopping. I crossed that line and just started crying, which surprised me completely. I realized I had spent decades assuming certain things were simply not for me, and that assumption had quietly limited everything I attempted.", "Q: What would you say to someone who thinks it's too late to start something like this? A: I would say the only thing you actually lose by starting late is the years you already spent not starting. Those years are gone either way. The only real question left is whether you're going to spend the next ones on the sidelines or not, and honestly, that answer is completely up to you."], "paragraphs_pt": ["P: Você só começou a correr aos cinquenta anos. O que finalmente te motivou a tentar? R: Sinceramente, foi quase um acidente. Meu médico sugeriu que eu andasse mais depois de um check-up de rotina, e um dia eu simplesmente comecei a trotar o último quarteirão até em casa em vez de andar. Pareceu ridículo no começo, mas algo naquilo ficou comigo, e fui acrescentando um pouco mais de distância a cada semana.", "P: Foi difícil continuar, especialmente no início? R: Incrivelmente difícil, sim. Meus joelhos doíam, eu era constrangedoramente lenta, e me lembro de me sentir insegura sempre que corredores mais jovens me ultrapassavam. Mas eu dizia a mim mesma que comparar meu ritmo com o deles não fazia sentido; eu estava competindo com a versão de mim mesma da semana anterior, não com ninguém mais.", "P: Qual foi o ponto de virada que fez você considerar correr uma maratona de verdade? R: Acho que foi terminar minha primeira prova de dez quilômetros sem parar. Cruzei aquela linha e simplesmente comecei a chorar, o que me surpreendeu completamente. Percebi que tinha passado décadas presumindo que certas coisas simplesmente não eram para mim, e essa suposição tinha limitado silenciosamente tudo o que eu tentava.", "P: O que você diria para alguém que acha que é tarde demais para começar algo assim? R: Eu diria que a única coisa que você realmente perde ao começar tarde são os anos que você já passou sem começar. Esses anos já se foram de qualquer jeito. A única pergunta real que resta é se você vai passar os próximos anos na plateia ou não, e sinceramente, essa resposta é totalmente sua."], "hard_words": ["self-conscious", "pointless", "sidelines", "assuming"], "vocab": [{"word": "routine check-up", "meaning": "check-up de rotina", "note": ""}, {"word": "self-conscious", "meaning": "inseguro, constrangido", "note": ""}, {"word": "pointless", "meaning": "sem sentido, inútil", "note": ""}, {"word": "turning point", "meaning": "ponto de virada", "note": ""}, {"word": "assume", "meaning": "presumir, supor", "note": ""}, {"word": "sidelines", "meaning": "à margem, de fora (não participando)", "note": ""}, {"word": "up to you", "meaning": "depende de você", "note": "expressão"}, {"word": "stuck with", "meaning": "ficou marcado/gravado", "note": "phrasal verb"}], "word_meanings": [{"word": "self-conscious", "meaning": "inseguro, constrangido", "note": ""}, {"word": "pointless", "meaning": "sem sentido", "note": ""}, {"word": "sidelines", "meaning": "à margem", "note": ""}, {"word": "assuming", "meaning": "presumindo", "note": ""}, {"word": "actually", "meaning": "na verdade", "note": "falso cognato"}, {"word": "eventually", "meaning": "finalmente", "note": "falso cognato"}, {"word": "started", "meaning": "começou", "note": ""}, {"word": "suggested", "meaning": "sugeriu", "note": ""}, {"word": "felt", "meaning": "pareceu/sentiu", "note": ""}, {"word": "stuck with", "meaning": "ficou marcado com", "note": "phrasal verb"}, {"word": "kept adding", "meaning": "continuou acrescentando", "note": ""}, {"word": "ached", "meaning": "doíam", "note": ""}, {"word": "told", "meaning": "disse", "note": ""}, {"word": "crossed", "meaning": "cruzou", "note": ""}, {"word": "realized", "meaning": "percebeu", "note": ""}, {"word": "had spent", "meaning": "tinha passado", "note": ""}, {"word": "had limited", "meaning": "tinha limitado", "note": ""}], "grammar_words": {"cognates": ["actually"], "tobe": ["was", "were", "is"], "irregular": ["suggested", "started", "felt", "stuck with", "kept adding", "ached", "told", "crossed", "started", "realized"], "phrasal": ["stuck with"], "wh": ["what", "who", "whether"], "connectors": ["but", "and", "either way", "honestly"], "comparative": ["more distance", "younger"]}, "exercises": {"grammar": [{"point": "Perguntas e respostas em formato de entrevista", "explanation_pt": "Note como as perguntas usam inversão sujeito-verbo ('What finally pushed you...') enquanto as respostas usam frases mais longas e conectores para explicar o raciocínio."}, {"point": "Present perfect e past perfect combinados", "explanation_pt": "'I had spent decades assuming' usa o past perfect para mostrar algo anterior à percepção descrita, um padrão comum em relatos pessoais."}], "multiple_choice": [{"question": "What motivated the runner to start jogging?", "options": ["A doctor's suggestion to walk more", "A friend's challenge", "A marathon advertisement", "A weight-loss goal"], "correct_index": 0, "explanation": "O médico sugeriu que ela andasse mais."}, {"question": "How did she deal with feeling slower than younger runners?", "options": ["She stopped running", "She compared herself only to her past self", "She trained harder to beat them", "She avoided running near others"], "correct_index": 1, "explanation": "Ela competia com a versão de si mesma da semana anterior."}, {"question": "What was her turning point toward running a marathon?", "options": ["Winning a local race", "Watching a marathon on TV", "Finishing her first ten-kilometer race without stopping", "A conversation with her doctor"], "correct_index": 2, "explanation": "Foi terminar os dez quilômetros sem parar."}, {"question": "What realization did she have after that race?", "options": ["She should quit running", "She needed a coach", "She was too old to continue", "She had wrongly assumed some things weren't for her"], "correct_index": 3, "explanation": "Ela percebeu que tinha presumido erroneamente que certas coisas não eram para ela."}, {"question": "What does she say people actually lose by starting late?", "options": ["Only the years already spent not starting", "Nothing at all", "Their health", "Their confidence"], "correct_index": 0, "explanation": "Ela diz que só se perde os anos já passados sem começar."}], "open_questions": [{"question": "Do you agree that it's never too late to start something new? Why or why not?", "key_points_pt": ["Dar opinião justificada", "Citar exemplo pessoal ou de terceiros"]}, {"question": "Is there something you have been putting off starting because you think you're 'too old' or 'too late' for it? What is it?", "key_points_pt": ["Refletir sobre experiência pessoal", "Explicar o que impede de começar"]}]}}, {"level": "C1", "genre": "neutral", "title": "The Last Ferry", "paragraphs": ["Every evening, Marta caught the last ferry across the bay, even though a faster bus route had opened the previous year. She could have shaved twenty minutes off her commute, but she preferred the slow rhythm of the water and the way the city lights blurred into gold as the boat pulled away from the dock.", "One rainy Thursday, the ferry was delayed, and she ended up sitting beside an elderly man who claimed to have crossed that same bay for forty years. He spoke with a quiet confidence, recounting storms he had survived and passengers he had befriended, and Marta realized, somewhat sheepishly, that she had never once struck up a conversation with a stranger on board.", "By the time the boat docked, the rain had eased, and the old man handed her a folded paper crane before disembarking. He said it was a habit he had picked up decades ago, a small gesture to remind fellow travelers that the journey itself was worth savoring, not merely the destination.", "Marta kept the crane on her desk for years afterward. Whenever deadlines piled up and she felt tempted to abandon the ferry for the sake of efficiency, she glanced at the little paper bird and chose, instead, to slow down."], "paragraphs_pt": ["Todas as noites, Marta pegava a última balsa para atravessar a baía, mesmo com uma rota de ônibus mais rápida que tinha sido inaugurada no ano anterior. Ela poderia ter economizado vinte minutos no trajeto, mas preferia o ritmo lento da água e o jeito como as luzes da cidade se misturavam num tom dourado quando o barco se afastava do cais.", "Numa quinta-feira chuvosa, a balsa atrasou, e ela acabou sentando ao lado de um senhor idoso que dizia atravessar aquela mesma baía havia quarenta anos. Ele falava com uma calma confiante, contando tempestades que tinha sobrevivido e passageiros com quem tinha feito amizade, e Marta percebeu, um tanto encabulada, que nunca havia puxado conversa com um desconhecido a bordo.", "Quando o barco atracou, a chuva já tinha diminuído, e o velho lhe entregou um origami de tsuru antes de desembarcar. Ele disse que era um hábito adquirido décadas atrás, um pequeno gesto para lembrar aos outros viajantes que a própria jornada valia a pena ser apreciada, não só o destino.", "Marta guardou o origami na mesa dela por anos. Sempre que os prazos se acumulavam e ela sentia vontade de abandonar a balsa em nome da eficiência, ela olhava para o passarinho de papel e, em vez disso, escolhia desacelerar."], "hard_words": ["shaved", "sheepishly", "disembarking", "savoring"], "vocab": [{"word": "commute", "meaning": "trajeto diário (casa-trabalho)", "note": ""}, {"word": "struck up a conversation", "meaning": "puxar conversa", "note": "expressão idiomática"}, {"word": "quiet confidence", "meaning": "confiança tranquila", "note": ""}, {"word": "handed her", "meaning": "entregou a ela", "note": ""}, {"word": "worth savoring", "meaning": "que vale a pena apreciar", "note": ""}, {"word": "piled up", "meaning": "se acumularam", "note": "phrasal verb"}, {"word": "for the sake of", "meaning": "em nome de, por causa de", "note": ""}, {"word": "slow down", "meaning": "desacelerar", "note": "phrasal verb"}], "word_meanings": [{"word": "shaved", "meaning": "reduzido/cortado (tempo)", "note": ""}, {"word": "sheepishly", "meaning": "com timidez/encabulado", "note": ""}, {"word": "disembarking", "meaning": "desembarcando", "note": ""}, {"word": "savoring", "meaning": "saboreando/apreciando", "note": ""}, {"word": "struck up", "meaning": "iniciar (uma conversa)", "note": "phrasal verb"}, {"word": "piled up", "meaning": "acumularam-se", "note": "phrasal verb"}, {"word": "opened", "meaning": "abriu/inaugurou", "note": "passado simples"}, {"word": "caught", "meaning": "pegou", "note": "passado irregular"}, {"word": "spoke", "meaning": "falou", "note": "passado irregular"}, {"word": "handed", "meaning": "entregou", "note": "passado regular"}, {"word": "realize", "meaning": "perceber (não 'realizar')", "note": "falso cognato"}, {"word": "actually", "meaning": "na verdade (não 'atualmente')", "note": "falso cognato"}, {"word": "felt", "meaning": "sentiu", "note": "passado irregular"}, {"word": "kept", "meaning": "manteve/continuou", "note": "passado irregular"}], "grammar_words": {"cognates": [], "tobe": ["was"], "irregular": ["caught", "spoke", "handed", "opened", "kept", "felt"], "phrasal": ["struck up", "piled up"], "wh": [], "connectors": ["even though", "but", "and", "instead"], "comparative": ["faster"]}, "exercises": {"grammar": [{"point": "Past perfect", "explanation_pt": "Usamos o past perfect para uma ação anterior a outra no passado: 'a faster bus route had opened the previous year' aconteceu antes do hábito de Marta continuar."}, {"point": "Simple past narrativo", "explanation_pt": "A história usa o simple past para narrar eventos em sequência, como em 'the old man handed her a folded paper crane before disembarking'."}], "multiple_choice": [{"question": "Why did Marta keep taking the ferry instead of the bus?", "options": ["She enjoyed the slow pace and the view", "It was cheaper", "The bus was unsafe", "She had no other option"], "correct_index": 0, "explanation": "Ela preferia o ritmo lento e a vista da balsa."}, {"question": "What happened one rainy Thursday?", "options": ["The ferry sank", "The ferry was delayed", "Marta missed the ferry", "The old man got lost"], "correct_index": 1, "explanation": "A balsa atrasou naquele dia."}, {"question": "How long had the old man been crossing the bay?", "options": ["Ten years", "Twenty years", "Forty years", "His whole life"], "correct_index": 2, "explanation": "Ele dizia atravessar havia quarenta anos."}, {"question": "What did the old man give Marta?", "options": ["A book", "A photograph", "A ticket", "A paper crane"], "correct_index": 3, "explanation": "Ele deu um origami em forma de pássaro (tsuru)."}, {"question": "What did Marta do whenever she felt tempted to skip the ferry?", "options": ["She looked at the paper crane and slowed down", "She called the old man", "She took the bus anyway", "She quit her job"], "correct_index": 0, "explanation": "Ela olhava para o origami e escolhia desacelerar."}], "open_questions": [{"question": "Do you think small rituals like Marta's ferry ride matter in daily life? Why or why not?", "key_points_pt": ["mencionar o valor de rituais pessoais", "conectar com exemplos da própria rotina"]}, {"question": "What lesson did the old man's gift teach Marta about efficiency versus enjoyment?", "key_points_pt": ["explicar a ideia de valorizar o percurso, não só o destino", "citar o hábito do origami"]}]}}, {"level": "C1", "genre": "suspense", "title": "The Sound Upstairs", "paragraphs": ["Renata had lived alone in the old apartment for three years, and she had grown accustomed to its creaks, its groaning pipes, and the occasional shudder of the elevator shaft. So when she heard footsteps directly above her ceiling at two in the morning, she told herself it was nothing, since the flat upstairs had been vacant since the previous tenant moved out.", "The footsteps returned the following night, slower this time, pausing right above her bedroom before dragging toward the far wall. Renata lay rigid beneath the blanket, straining to convince herself that pipes could not possibly account for such a deliberate, measured pace, yet she was too unsettled to switch on the light.", "On the third night, she finally worked up the nerve to knock on the building superintendent's door. He admitted, almost reluctantly, that a contractor had been given a spare key to inspect the empty unit for a leak, but insisted the man only worked during the day. Renata's stomach tightened as she realized that whoever paced above her at night was not authorized to be there at all.", "She reported it to the police, who found the upstairs window pried open and a sleeping bag tucked behind the water tank; someone had apparently been squatting there for weeks, careful enough to leave during daylight hours. Though the intruder was never caught, Renata moved out within the month, unable to shake the memory of those slow, deliberate footsteps pacing above her bed."], "paragraphs_pt": ["Renata morava sozinha naquele apartamento antigo havia três anos e já tinha se acostumado com os rangidos, os canos que gemiam e o estremecimento ocasional do poço do elevador. Então, quando ouviu passos bem acima do teto às duas da manhã, disse a si mesma que não era nada, já que o apartamento de cima estava vazio desde que o inquilino anterior tinha se mudado.", "Os passos voltaram na noite seguinte, mais lentos dessa vez, parando bem acima do quarto dela antes de se arrastar em direção à parede do fundo. Renata ficou rígida debaixo do cobertor, se esforçando para se convencer de que canos não poderiam explicar um ritmo tão deliberado e medido, mas estava perturbada demais para acender a luz.", "Na terceira noite, ela finalmente criou coragem para bater na porta do zelador do prédio. Ele admitiu, quase a contragosto, que um empreiteiro tinha recebido uma cópia da chave para inspecionar o apartamento vazio por causa de um vazamento, mas garantiu que o homem só trabalhava durante o dia. O estômago de Renata se apertou ao perceber que quem andava de um lado para o outro à noite ali em cima não tinha autorização nenhuma para estar lá.", "Ela denunciou o caso à polícia, que encontrou a janela do andar de cima arrombada e um saco de dormir escondido atrás da caixa d'água; alguém aparentemente estava morando ali às escondidas fazia semanas, cuidadoso o bastante para sair durante o dia. Embora o intruso nunca tenha sido pego, Renata se mudou dentro de um mês, incapaz de esquecer aqueles passos lentos e deliberados andando acima da cama dela."], "hard_words": ["shudder", "rigid", "reluctantly", "pried", "squatting"], "vocab": [{"word": "grown accustomed to", "meaning": "se acostumado com", "note": ""}, {"word": "worked up the nerve", "meaning": "criar coragem", "note": "expressão idiomática"}, {"word": "spare key", "meaning": "chave reserva", "note": ""}, {"word": "her stomach tightened", "meaning": "o estômago se apertou (de medo)", "note": ""}, {"word": "pried open", "meaning": "arrombada/forçada", "note": ""}, {"word": "tucked behind", "meaning": "escondido atrás de", "note": ""}, {"word": "unable to shake", "meaning": "incapaz de esquecer/se livrar de", "note": ""}], "word_meanings": [{"word": "shudder", "meaning": "estremecimento", "note": ""}, {"word": "rigid", "meaning": "rígida, dura", "note": ""}, {"word": "reluctantly", "meaning": "a contragosto", "note": ""}, {"word": "pried", "meaning": "arrombou/forçou", "note": ""}, {"word": "squatting", "meaning": "morando ilegalmente/ocupando sem permissão", "note": ""}, {"word": "realize", "meaning": "perceber (não 'realizar')", "note": "falso cognato"}, {"word": "eventually", "meaning": "finalmente, com o tempo (não 'eventualmente')", "note": "falso cognato"}, {"word": "was", "meaning": "era/estava", "note": "to be"}, {"word": "were", "meaning": "eram/estavam", "note": "to be"}, {"word": "moved", "meaning": "mudou-se", "note": "passado regular"}, {"word": "found", "meaning": "encontrou", "note": "passado irregular"}, {"word": "worked up", "meaning": "criou (coragem)", "note": "phrasal verb"}, {"word": "switch on", "meaning": "acender/ligar", "note": "phrasal verb"}, {"word": "whoever", "meaning": "quem quer que", "note": "wh-word"}, {"word": "lay", "meaning": "estava deitado(a)", "note": "passado irregular"}, {"word": "heard", "meaning": "ouviu", "note": "passado irregular"}, {"word": "told", "meaning": "disse/contou", "note": "passado irregular"}], "grammar_words": {"cognates": [], "tobe": ["was"], "irregular": ["moved", "found", "heard", "told", "lay"], "phrasal": ["worked up", "switch on"], "wh": ["whoever"], "connectors": ["since", "so", "yet", "though"], "comparative": ["slower"]}, "exercises": {"grammar": [{"point": "Past continuous vs simple past", "explanation_pt": "Usamos o passado contínuo para uma ação em andamento interrompida por outra: 'she heard footsteps' (simples) enquanto algo acontecia acima dela."}, {"point": "Modal 'could not possibly'", "explanation_pt": "Expressa impossibilidade forte, como em 'pipes could not possibly account for such a deliberate pace'."}], "multiple_choice": [{"question": "Why did Renata initially ignore the footsteps?", "options": ["She thought the apartment above was empty", "She was not home", "She was used to loud neighbors", "She could not hear well"], "correct_index": 0, "explanation": "Ela achava que o apartamento de cima estava vazio."}, {"question": "What did the superintendent say about the contractor?", "options": ["He worked only at night", "He worked only during the day", "He had never been given a key", "He no longer worked there"], "correct_index": 1, "explanation": "O contratado só trabalhava de dia, segundo o zelador."}, {"question": "What did the police find in the empty apartment?", "options": ["A broken pipe", "Nothing unusual", "A sleeping bag and a pried-open window", "A missing person"], "correct_index": 2, "explanation": "Encontraram a janela arrombada e um saco de dormir."}, {"question": "What can be inferred about the intruder?", "options": ["They were caught immediately", "They were a former tenant", "They were the superintendent", "They were careful to avoid being seen during the day"], "correct_index": 3, "explanation": "O intruso saía durante o dia para não ser visto."}, {"question": "What did Renata ultimately decide to do?", "options": ["Move out of the apartment", "Install cameras", "Confront the intruder herself", "Ignore the situation"], "correct_index": 0, "explanation": "Ela se mudou dentro de um mês."}], "open_questions": [{"question": "How does the author build suspense before revealing the truth about the footsteps?", "key_points_pt": ["mencionar os detalhes sensoriais e o ritmo lento da revelação", "citar a reação física de Renata"]}, {"question": "Would you have reacted the same way Renata did? What would you have done differently?", "key_points_pt": ["dar opinião pessoal", "justificar com exemplo do texto ou experiência própria"]}]}}, {"level": "C1", "genre": "detective", "title": "The Vanishing Signature", "paragraphs": ["Detective Alves had seen plenty of forged paintings during her career, but none had been quite as brazen as the one hanging in the Coutinho gallery. The insurance company suspected fraud the moment the claimed value tripled overnight, and they called her in to determine whether the celebrated seascape was genuine or an elaborate hoax.", "She began, as she always did, by interrogating the least obvious suspect: the gallery's soft-spoken restorer, who insisted he had merely cleaned the varnish. Alves noticed, however, that his hands trembled whenever she mentioned the artist's signature, a telltale sign that something did not quite add up.", "Under ultraviolet light, the signature revealed a faint discrepancy: the ink beneath it was decades newer than the paint surrounding it, meaning someone had painstakingly added the artist's name long after the canvas had dried. The restorer finally confessed, explaining that the gallery owner had pressured him into signing an unattributed painting to inflate its resale value.", "Alves handed the case over to the fraud unit, though she took a quiet satisfaction in having outsmarted a scheme so meticulously disguised. As she left the gallery, she reflected that forgers rarely failed at the brushwork; it was almost always the smallest, most overlooked detail, like a signature, that gave them away."], "paragraphs_pt": ["A detetive Alves já tinha visto muitas pinturas falsificadas ao longo da carreira, mas nenhuma fora tão descarada quanto aquela pendurada na galeria Coutinho. A seguradora suspeitou de fraude assim que o valor declarado triplicou da noite para o dia, e a chamaram para determinar se a célebre marinha era autêntica ou uma farsa elaborada.", "Ela começou, como sempre fazia, interrogando o suspeito menos óbvio: o restaurador discreto da galeria, que insistia ter apenas limpado o verniz. Alves notou, porém, que as mãos dele tremiam sempre que ela mencionava a assinatura do artista, um sinal revelador de que algo não batia.", "Sob luz ultravioleta, a assinatura revelou uma discrepância sutil: a tinta por baixo dela era décadas mais nova do que a tinta ao redor, o que significava que alguém tinha acrescentado cuidadosamente o nome do artista muito depois de a tela já estar seca. O restaurador finalmente confessou, explicando que o dono da galeria o havia pressionado a assinar uma pintura sem autoria para inflar o valor de revenda.", "Alves entregou o caso à unidade de fraudes, embora sentisse uma satisfação silenciosa por ter sido mais esperta que um esquema tão meticulosamente disfarçado. Ao sair da galeria, refletiu que falsificadores raramente erravam nas pinceladas; era quase sempre o detalhe menor e mais negligenciado, como uma assinatura, que os denunciava."], "hard_words": ["brazen", "hoax", "telltale", "painstakingly", "meticulously"], "vocab": [{"word": "called her in", "meaning": "a chamaram (para o caso)", "note": "phrasal verb"}, {"word": "something did not quite add up", "meaning": "algo não batia/fazia sentido", "note": "expressão idiomática"}, {"word": "gave them away", "meaning": "os denunciou/entregou", "note": "phrasal verb"}, {"word": "inflate", "meaning": "inflar/aumentar artificialmente", "note": ""}, {"word": "outsmarted", "meaning": "foi mais esperto(a) que", "note": ""}, {"word": "resale value", "meaning": "valor de revenda", "note": ""}, {"word": "handed over", "meaning": "entregou/repassou", "note": "phrasal verb"}], "word_meanings": [{"word": "brazen", "meaning": "descarado, ousado", "note": ""}, {"word": "hoax", "meaning": "farsa, embuste", "note": ""}, {"word": "telltale", "meaning": "revelador, denunciador", "note": ""}, {"word": "painstakingly", "meaning": "cuidadosamente, com esmero", "note": ""}, {"word": "meticulously", "meaning": "meticulosamente", "note": ""}, {"word": "called in", "meaning": "chamada/convocada", "note": "phrasal verb"}, {"word": "add up", "meaning": "fazer sentido", "note": "phrasal verb"}, {"word": "gave away", "meaning": "denunciou", "note": "phrasal verb"}, {"word": "handed over", "meaning": "entregou", "note": "phrasal verb"}, {"word": "realize", "meaning": "perceber (não 'realizar')", "note": "falso cognato"}, {"word": "eventually", "meaning": "finalmente (não 'eventualmente')", "note": "falso cognato"}, {"word": "was", "meaning": "era/foi", "note": "to be"}, {"word": "began", "meaning": "começou", "note": "passado irregular"}, {"word": "confessed", "meaning": "confessou", "note": "passado regular"}, {"word": "left", "meaning": "deixou", "note": "passado irregular"}, {"word": "handed", "meaning": "entregou", "note": "passado irregular"}, {"word": "noticed", "meaning": "notou", "note": "passado irregular"}, {"word": "took", "meaning": "levou/pegou", "note": "passado irregular"}], "grammar_words": {"cognates": [], "tobe": ["had been", "was"], "irregular": ["began", "noticed", "confessed", "left", "took", "handed"], "phrasal": ["add up"], "wh": ["whether", "who"], "connectors": ["but", "however", "though", "as"], "comparative": ["newer", "smallest", "most overlooked"]}, "exercises": {"grammar": [{"point": "Past perfect para eventos anteriores", "explanation_pt": "Usamos o past perfect para algo que aconteceu antes de outro evento passado: 'someone had painstakingly added the artist's name long after the canvas had dried'."}, {"point": "Comparativos e superlativos", "explanation_pt": "A história usa formas como 'newer' e 'the smallest, most overlooked detail' para comparar elementos da investigação."}], "multiple_choice": [{"question": "Why did the insurance company get suspicious?", "options": ["The claimed value tripled overnight", "The painting disappeared", "The gallery closed", "The artist complained"], "correct_index": 0, "explanation": "O valor declarado triplicou de repente."}, {"question": "Who did Alves interrogate first?", "options": ["The gallery owner", "The restorer", "The artist", "A random visitor"], "correct_index": 1, "explanation": "Ela começou pelo restaurador, o suspeito menos óbvio."}, {"question": "What did the ultraviolet light reveal?", "options": ["A hidden painting underneath", "Fingerprints", "That the signature's ink was newer than the paint", "Nothing unusual"], "correct_index": 2, "explanation": "A tinta da assinatura era mais nova que a tinta ao redor."}, {"question": "Why did the restorer add the signature?", "options": ["He wanted fame", "He made a mistake", "He was the real artist", "The gallery owner pressured him to inflate the price"], "correct_index": 3, "explanation": "O dono da galeria o pressionou para aumentar o valor de revenda."}, {"question": "What lesson does Alves draw at the end of the story?", "options": ["Small overlooked details usually expose forgers", "Forgers are always caught quickly", "Paintings should never be restored", "Insurance companies are always wrong"], "correct_index": 0, "explanation": "Ela reflete que o menor detalhe costuma denunciar o falsificador."}], "open_questions": [{"question": "What details in the story hinted that the restorer was involved before he confessed?", "key_points_pt": ["mencionar as mãos trêmulas e outros sinais sutis", "explicar como esses sinais levaram à suspeita"]}, {"question": "Do you think the gallery owner deserves a harsher punishment than the restorer? Why?", "key_points_pt": ["dar opinião justificada", "considerar quem pressionou quem no esquema"]}]}}, {"level": "C1", "genre": "romance", "title": "Two Left Shoes", "paragraphs": ["Luiza had sworn off blind dates after a string of awkward dinners, yet she found herself, against her better judgment, agreeing to meet a friend of a friend at a dance studio downtown. She arrived ten minutes early, only to discover that she had grabbed two left shoes in her rush out the door, a mismatch that left her hobbling comically across the polished floor.", "Thiago, the man she was supposed to meet, spotted her struggling and offered, without a trace of mockery, to swap one of his own shoes for hers. It was an absurd sight, the two of them dancing a clumsy tango in mismatched pairs, but the laughter it provoked dissolved whatever awkwardness might otherwise have hung over their first conversation.", "Over the following weeks, they kept finding excuses to see each other again, each date more effortless than the last, as though the initial shoe mishap had somehow granted them permission to be unguarded with one another. Luiza, who had always approached romance with a certain wary detachment, was startled to notice how readily she looked forward to his messages.", "A year later, when Thiago proposed, he did so kneeling in the very same dance studio, holding up a single left shoe as a quiet joke only the two of them would understand. Luiza laughed until she cried, then said yes before he had even finished the question."], "paragraphs_pt": ["Luiza havia jurado nunca mais aceitar encontros às cegas depois de uma sequência de jantares constrangedores, mas se viu, contra o próprio bom senso, concordando em conhecer o amigo de uma amiga numa academia de dança no centro. Ela chegou dez minutos adiantada, só para descobrir que tinha pegado dois sapatos esquerdos na correria para sair de casa, um erro que a deixou mancando de forma cômica pelo piso encerado.", "Thiago, o homem que ela deveria encontrar, percebeu que ela estava tendo dificuldade e se ofereceu, sem nenhum sinal de deboche, para trocar um dos próprios sapatos pelo dela. Foi uma cena absurda, os dois dançando um tango desajeitado com pares trocados, mas a risada que isso provocou dissolveu qualquer constrangimento que pudesse pairar sobre a primeira conversa deles.", "Nas semanas seguintes, eles continuavam inventando desculpas para se ver de novo, cada encontro mais natural que o anterior, como se o incidente inicial dos sapatos tivesse de alguma forma lhes dado permissão para serem despretensiosos um com o outro. Luiza, que sempre tinha encarado o romance com certo distanciamento cauteloso, ficou surpresa ao perceber com que facilidade passou a esperar pelas mensagens dele.", "Um ano depois, quando Thiago pediu-a em casamento, ele o fez ajoelhado naquela mesma academia de dança, segurando um único sapato esquerdo como uma piada silenciosa que só os dois entenderiam. Luiza riu até chorar, e disse sim antes mesmo de ele terminar a pergunta."], "hard_words": ["sworn off", "hobbling", "mismatch", "unguarded", "wary"], "vocab": [{"word": "against her better judgment", "meaning": "contra o próprio bom senso", "note": "expressão idiomática"}, {"word": "without a trace of mockery", "meaning": "sem nenhum sinal de deboche", "note": ""}, {"word": "hung over", "meaning": "pairado sobre (uma situação)", "note": "phrasal verb"}, {"word": "kept finding excuses", "meaning": "continuavam inventando desculpas", "note": ""}, {"word": "looked forward to", "meaning": "aguardar com expectativa", "note": "phrasal verb"}, {"word": "kneeling", "meaning": "ajoelhado", "note": ""}, {"word": "swap", "meaning": "trocar", "note": ""}], "word_meanings": [{"word": "sworn off", "meaning": "jurado abandonar/nunca mais fazer", "note": ""}, {"word": "hobbling", "meaning": "mancando", "note": ""}, {"word": "mismatch", "meaning": "combinação errada, par desencontrado", "note": ""}, {"word": "unguarded", "meaning": "desprevenido, sem defesas, espontâneo", "note": ""}, {"word": "wary", "meaning": "cauteloso, desconfiado", "note": ""}, {"word": "hung over", "meaning": "pairou sobre", "note": "phrasal verb"}, {"word": "looked forward to", "meaning": "esperava ansiosamente por", "note": "phrasal verb"}, {"word": "actually", "meaning": "na verdade (não 'atualmente')", "note": "falso cognato"}, {"word": "eventually", "meaning": "finalmente (não 'eventualmente')", "note": "falso cognato"}, {"word": "was", "meaning": "era/estava", "note": "to be"}, {"word": "were", "meaning": "eram/estavam", "note": "to be"}, {"word": "spotted", "meaning": "avistou", "note": "passado regular"}, {"word": "proposed", "meaning": "pediu em casamento", "note": "passado regular"}, {"word": "found", "meaning": "encontrou", "note": "passado irregular"}, {"word": "held", "meaning": "segurou", "note": "passado irregular"}, {"word": "kept", "meaning": "manteve/continuou", "note": "passado irregular"}, {"word": "said", "meaning": "disse", "note": "passado irregular"}], "grammar_words": {"cognates": [], "tobe": ["was"], "irregular": ["found", "spotted", "kept", "said"], "phrasal": ["hung over", "looked forward to"], "wh": [], "connectors": ["yet", "but", "as though", "so"], "comparative": ["more effortless", "the last"]}, "exercises": {"grammar": [{"point": "Comparativos progressivos", "explanation_pt": "A frase 'each date more effortless than the last' mostra uma comparação progressiva entre os encontros."}, {"point": "'As though' + passado", "explanation_pt": "Usamos 'as though' com verbo no passado para expressar uma situação hipotética: 'as though the initial shoe mishap had somehow granted them permission'."}], "multiple_choice": [{"question": "Why was Luiza hobbling at the dance studio?", "options": ["She was wearing two left shoes", "She hurt her foot", "Her shoes were too tight", "She had never danced before"], "correct_index": 0, "explanation": "Ela pegou dois sapatos esquerdos sem perceber."}, {"question": "How did Thiago react to Luiza's shoe problem?", "options": ["He laughed at her", "He offered to swap one of his shoes", "He left immediately", "He ignored it"], "correct_index": 1, "explanation": "Ele se ofereceu para trocar um dos sapatos com ela."}, {"question": "How did Luiza usually approach romance before meeting Thiago?", "options": ["Very enthusiastically", "She never dated", "With wary detachment", "She always fell in love quickly"], "correct_index": 2, "explanation": "Ela costumava ser cautelosa e reservada com relacionamentos."}, {"question": "Where did Thiago propose to Luiza?", "options": ["At a restaurant", "At her house", "On a trip", "At the dance studio"], "correct_index": 3, "explanation": "Ele pediu-a em casamento na mesma academia de dança."}, {"question": "What object did Thiago hold up during the proposal?", "options": ["A single left shoe", "A ring box", "A photograph", "Dance shoes for both"], "correct_index": 0, "explanation": "Ele segurou um único sapato esquerdo como piada."}], "open_questions": [{"question": "How did the awkward beginning of the story end up bringing Luiza and Thiago closer together?", "key_points_pt": ["explicar como o erro dos sapatos gerou risada e conexão", "relacionar com a ideia de vulnerabilidade compartilhada"]}, {"question": "Do you believe small, embarrassing moments can sometimes strengthen a relationship? Why?", "key_points_pt": ["dar opinião pessoal", "usar o exemplo da história ou experiência própria"]}]}}, {"level": "C1", "genre": "scifi", "title": "The Memory Archivist", "paragraphs": ["In the year 2184, Dr. Yuki Tanaka's job was to preserve dying languages by digitizing the memories of their last living speakers, a process that involved threading a neural filament through the subject's temporal lobe while a quantum archive recorded every association a word carried. Most sessions were routine, but the one scheduled with a hundred-and-twelve-year-old man named Elias, the final fluent speaker of a nearly extinct dialect, felt different from the moment he sat down.", "As the filament activated, Yuki expected to retrieve tidy definitions, yet what flooded the archive instead were entire scenes: a childhood kitchen thick with the smell of bread, an argument between parents that had shaped how the boy later spoke of anger, a wedding song sung slightly off-key. She realized, with a jolt of unease, that a language could not be separated from the life that had spoken it, no matter how sophisticated the recording technology became.", "Midway through the extraction, the archive's stabilizers flickered, warning that Elias's neural patterns were destabilizing under the strain; continuing risked erasing the very memories she was meant to save. Yuki faced an impossible choice between completing the historic archive and protecting the fragile old man in front of her, and after a long, agonizing pause, she withdrew the filament, letting the recording remain forever incomplete.", "The institute reprimanded her for abandoning a project decades in the making, but Elias, breathing easier once the device was removed, thanked her quietly for choosing him over the archive. Yuki never regretted the decision; she had learned, in that single afternoon, that some knowledge was never meant to survive its keeper, and that preserving a voice sometimes meant knowing when to let it rest."], "paragraphs_pt": ["No ano de 2184, o trabalho da Dra. Yuki Tanaka era preservar línguas moribundas digitalizando as memórias de seus últimos falantes vivos, um processo que envolvia inserir um filamento neural pelo lobo temporal do sujeito enquanto um arquivo quântico registrava cada associação carregada por uma palavra. A maioria das sessões era rotineira, mas a que estava marcada com um homem de cento e doze anos chamado Elias, o último falante fluente de um dialeto quase extinto, pareceu diferente desde o momento em que ele se sentou.", "Quando o filamento foi ativado, Yuki esperava recuperar definições organizadas, mas o que inundou o arquivo, em vez disso, foram cenas inteiras: uma cozinha de infância impregnada do cheiro de pão, uma discussão entre os pais que tinha moldado a forma como o menino mais tarde falava sobre raiva, uma canção de casamento cantada levemente desafinada. Ela percebeu, com um sobressalto de inquietação, que uma língua não podia ser separada da vida que a havia falado, por mais sofisticada que a tecnologia de gravação se tornasse.", "No meio da extração, os estabilizadores do arquivo oscilaram, avisando que os padrões neurais de Elias estavam se desestabilizando sob a tensão; continuar arriscava apagar justamente as memórias que ela deveria salvar. Yuki se viu diante de uma escolha impossível entre concluir o arquivo histórico e proteger o senhor frágil à sua frente, e depois de uma longa e angustiante pausa, ela retirou o filamento, deixando a gravação para sempre incompleta.", "O instituto a repreendeu por abandonar um projeto décadas em construção, mas Elias, respirando mais aliviado assim que o aparelho foi removido, agradeceu-lhe em voz baixa por tê-lo escolhido em vez do arquivo. Yuki nunca se arrependeu da decisão; ela tinha aprendido, naquela única tarde, que certos conhecimentos nunca deveriam sobreviver a quem os guardava, e que preservar uma voz às vezes significava saber a hora de deixá-la descansar."], "hard_words": ["filament", "temporal lobe", "flooded", "destabilizing", "reprimanded"], "vocab": [{"word": "dying languages", "meaning": "línguas em extinção", "note": ""}, {"word": "a jolt of unease", "meaning": "um sobressalto de inquietação", "note": ""}, {"word": "midway through", "meaning": "no meio de, na metade de", "note": ""}, {"word": "agonizing pause", "meaning": "pausa angustiante", "note": ""}, {"word": "breathing easier", "meaning": "respirando mais aliviado", "note": ""}, {"word": "let it rest", "meaning": "deixar descansar/em paz", "note": "expressão idiomática"}, {"word": "no matter how", "meaning": "não importa o quão", "note": ""}], "word_meanings": [{"word": "filament", "meaning": "filamento", "note": ""}, {"word": "temporal lobe", "meaning": "lobo temporal", "note": ""}, {"word": "flooded", "meaning": "inundou", "note": ""}, {"word": "destabilizing", "meaning": "se desestabilizando", "note": ""}, {"word": "reprimanded", "meaning": "repreendeu", "note": ""}, {"word": "realize", "meaning": "perceber (não 'realizar')", "note": "falso cognato"}, {"word": "eventually", "meaning": "finalmente (não 'eventualmente')", "note": "falso cognato"}, {"word": "was", "meaning": "era", "note": "to be"}, {"word": "were", "meaning": "eram/estavam", "note": "to be"}, {"word": "withdrew", "meaning": "retirou", "note": "passado irregular"}, {"word": "learned", "meaning": "aprendeu", "note": "passado regular"}, {"word": "faced", "meaning": "enfrentou/se deparou com", "note": "passado regular"}, {"word": "felt", "meaning": "sentiu", "note": "passado irregular"}, {"word": "sat", "meaning": "sentou", "note": "passado irregular"}, {"word": "thanked", "meaning": "agradeceu", "note": "passado irregular"}], "grammar_words": {"cognates": [], "tobe": ["was", "were"], "irregular": ["withdrew", "faced", "learned", "sat", "felt", "thanked"], "phrasal": [], "wh": [], "connectors": ["yet", "but", "no matter how", "and"], "comparative": ["easier"]}, "exercises": {"grammar": [{"point": "Cláusulas concessivas com 'no matter how'", "explanation_pt": "'no matter how sophisticated the recording technology became' expressa que, mesmo com tecnologia avançada, o resultado não mudava."}, {"point": "Passivo com 'was meant to'", "explanation_pt": "'the very memories she was meant to save' indica o propósito original da ação, usando a construção passiva 'be meant to'."}], "multiple_choice": [{"question": "What was Dr. Yuki Tanaka's profession?", "options": ["An archivist who preserves dying languages", "A neurosurgeon", "A historian", "A translator"], "correct_index": 0, "explanation": "Ela preservava línguas moribundas digitalizando memórias."}, {"question": "What surprised Yuki about the recorded memories?", "options": ["They were empty", "They included whole life scenes, not just definitions", "They were in the wrong language", "They were corrupted"], "correct_index": 1, "explanation": "Vieram cenas inteiras de vida, não apenas definições."}, {"question": "What warning appeared during the extraction?", "options": ["The archive was full", "The filament broke", "Elias's neural patterns were destabilizing", "The power failed"], "correct_index": 2, "explanation": "Os padrões neurais de Elias estavam se desestabilizando."}, {"question": "What did Yuki decide to do?", "options": ["Continue despite the risk", "Call for backup", "Restart the process", "Withdraw the filament and leave the recording incomplete"], "correct_index": 3, "explanation": "Ela retirou o filamento para proteger Elias."}, {"question": "How did the institute react to her decision?", "options": ["They reprimanded her", "They praised her", "They fired her", "They ignored it"], "correct_index": 0, "explanation": "O instituto a repreendeu por abandonar o projeto."}], "open_questions": [{"question": "Do you agree with Yuki's choice to prioritize Elias's well-being over the archive? Why?", "key_points_pt": ["dar opinião justificada", "considerar o dilema ético entre ciência e cuidado humano"]}, {"question": "What does this story suggest about the relationship between language and personal memory?", "key_points_pt": ["mencionar que a língua carrega experiências pessoais, não só palavras", "citar exemplos do texto"]}]}}, {"level": "C1", "genre": "fantasy", "title": "The Weight of the Crown", "paragraphs": ["When Princess Iselda's father died without a male heir, the council reluctantly crowned her, though many nobles muttered that the enchanted crown itself would reject her, since legend held that it recognized only the truest ruler's blood. To everyone's astonishment, the crown settled on her brow without so much as a flicker, yet within days she began hearing faint whispers whenever she wore it, as though the crown itself were alive and unwilling to stay silent.", "The whispers grew bolder, warning her of a famine brewing in the eastern provinces long before any messenger arrived with the news, and cautioning her against a treaty her advisors had urged her to sign, one that would have secretly ceded half the kingdom's mines to a rival lord. Iselda began to suspect that every monarch before her had heard these same warnings and had simply chosen, out of pride or fear, not to listen.", "Determined not to repeat their mistakes, she convened her council and revealed the crown's counsel openly, risking ridicule from nobles who already doubted a young queen's judgment. Several lords scoffed, insisting she was inventing voices to justify her own decisions, but when the famine struck precisely where the crown had predicted, their scorn curdled into uneasy respect.", "Years later, historians would debate whether the crown had truly been enchanted or whether Iselda had simply trusted her own instincts and attributed them to something greater than herself. Iselda never bothered to correct them; what mattered, she often said, was not where wisdom came from, but whether a ruler was humble enough to listen to it."], "paragraphs_pt": ["Quando o pai da princesa Iselda morreu sem deixar um herdeiro homem, o conselho a coroou a contragosto, embora muitos nobres murmurassem que a própria coroa encantada a rejeitaria, já que a lenda dizia que ela reconhecia apenas o sangue do verdadeiro governante. Para espanto de todos, a coroa se assentou em sua testa sem sequer vacilar, mas em poucos dias ela começou a ouvir sussurros fracos sempre que a usava, como se a própria coroa estivesse viva e não quisesse ficar em silêncio.", "Os sussurros ficaram mais ousados, avisando-a de uma fome que se formava nas províncias do leste muito antes de qualquer mensageiro chegar com a notícia, e alertando-a contra um tratado que seus conselheiros a pressionavam a assinar, um que teria cedido secretamente metade das minas do reino a um senhor rival. Iselda começou a suspeitar que todos os monarcas antes dela tinham ouvido esses mesmos avisos e simplesmente escolhido, por orgulho ou medo, não escutá-los.", "Decidida a não repetir os erros deles, ela convocou o conselho e revelou abertamente os conselhos da coroa, arriscando o ridículo de nobres que já duvidavam do julgamento de uma rainha jovem. Vários senhores zombaram, insistindo que ela inventava vozes para justificar as próprias decisões, mas quando a fome atingiu exatamente onde a coroa tinha previsto, o escárnio deles se transformou em um respeito incômodo.", "Anos depois, historiadores debateriam se a coroa realmente fora encantada ou se Iselda simplesmente confiara nos próprios instintos e os atribuíra a algo maior do que ela mesma. Iselda nunca se importou em corrigi-los; o que importava, ela costumava dizer, não era de onde vinha a sabedoria, mas se um governante era humilde o bastante para escutá-la."], "hard_words": ["muttered", "brow", "ceded", "scoffed", "curdled"], "vocab": [{"word": "without so much as a flicker", "meaning": "sem sequer vacilar", "note": "expressão idiomática"}, {"word": "brewing", "meaning": "se formando/gestando", "note": ""}, {"word": "convened her council", "meaning": "convocou o conselho", "note": ""}, {"word": "scorn", "meaning": "desprezo", "note": ""}, {"word": "uneasy respect", "meaning": "respeito incômodo", "note": ""}, {"word": "bothered to", "meaning": "se importou/deu-se ao trabalho de", "note": ""}, {"word": "humble", "meaning": "humilde", "note": ""}], "word_meanings": [{"word": "muttered", "meaning": "murmuraram", "note": ""}, {"word": "brow", "meaning": "testa", "note": ""}, {"word": "ceded", "meaning": "cedido", "note": ""}, {"word": "scoffed", "meaning": "zombaram", "note": ""}, {"word": "curdled", "meaning": "se transformou/azedou (fig.)", "note": ""}, {"word": "realize", "meaning": "perceber (não 'realizar')", "note": "falso cognato"}, {"word": "actually", "meaning": "na verdade (não 'atualmente')", "note": "falso cognato"}, {"word": "was", "meaning": "era/foi", "note": "to be"}, {"word": "were", "meaning": "eram/estavam", "note": "to be"}, {"word": "began", "meaning": "começou", "note": "passado irregular"}, {"word": "struck", "meaning": "atingiu", "note": "passado irregular"}, {"word": "convened", "meaning": "convocou", "note": "passado regular"}, {"word": "heard", "meaning": "ouviu", "note": "passado irregular"}, {"word": "chose", "meaning": "escolheu", "note": "passado irregular"}, {"word": "grew", "meaning": "cresceu/ficou", "note": "passado irregular"}], "grammar_words": {"cognates": [], "tobe": ["was", "were"], "irregular": ["began", "struck", "grew", "heard"], "phrasal": [], "wh": ["whether"], "connectors": ["though", "since", "yet", "but", "as though"], "comparative": ["bolder", "greater"]}, "exercises": {"grammar": [{"point": "'As though' + past subjunctive", "explanation_pt": "'as though the crown itself were alive' usa o passado subjuntivo para descrever uma situação irreal ou hipotética."}, {"point": "Discurso indireto com 'whether'", "explanation_pt": "'historians would debate whether the crown had truly been enchanted' introduz uma dúvida indireta usando 'whether'."}], "multiple_choice": [{"question": "Why were the nobles surprised when Iselda was crowned?", "options": ["They expected the crown to reject her", "She refused the crown", "She was too young", "The crown was stolen"], "correct_index": 0, "explanation": "A lenda dizia que a coroa reconheceria só o verdadeiro governante."}, {"question": "What did the crown's whispers warn Iselda about?", "options": ["A war", "A famine and a bad treaty", "A betrayal by her family", "Nothing important"], "correct_index": 1, "explanation": "Avisaram sobre uma fome e um tratado prejudicial."}, {"question": "How did the nobles initially react when Iselda revealed the crown's warnings?", "options": ["They believed her immediately", "They exiled her", "They scoffed at her", "They crowned someone else"], "correct_index": 2, "explanation": "Vários nobres zombaram, achando que ela inventava."}, {"question": "What changed the nobles' attitude toward Iselda?", "options": ["A royal decree", "A war victory", "Her marriage", "The famine happening exactly as predicted"], "correct_index": 3, "explanation": "A fome ocorreu exatamente onde a coroa previra."}, {"question": "What did Iselda believe mattered most about wisdom?", "options": ["Whether a ruler was humble enough to listen to it", "Its magical origin", "How old the ruler was", "How powerful the ruler was"], "correct_index": 0, "explanation": "Ela dizia que importava a humildade de escutar, não a origem da sabedoria."}], "open_questions": [{"question": "Do you think the crown was truly magical, or was Iselda simply trusting her own instincts? Explain your view.", "key_points_pt": ["discutir a ambiguidade proposital da história", "justificar com base no texto"]}, {"question": "What does this story suggest about leadership and the willingness to listen to advice?", "key_points_pt": ["mencionar a diferença entre orgulho e humildade nos governantes anteriores e Iselda", "conectar com exemplos de liderança reais ou fictícios"]}]}}, {"level": "C1", "genre": "dystopia", "title": "The Silence Quota", "paragraphs": ["In the district of Meridian, every citizen was allotted exactly two hundred words of unmonitored speech per day; anything beyond the quota was flagged, transcribed, and reviewed by the Ministry of Cohesion, whose official mandate was to prevent the kind of unchecked rhetoric that had, decades earlier, plunged the region into civil unrest. Nadia had learned, like everyone else, to ration her sentences carefully, saving her quota for what genuinely mattered and communicating the rest through gestures, half-smiles, and silences that the monitors could not quantify.", "Her grandmother, who remembered the years before the quota system, used to say that the government had not so much silenced dissent as trained people to silence themselves, since fear of exceeding the limit made citizens second-guess even harmless remarks. Nadia dismissed this at first as nostalgic exaggeration, until she noticed how rarely she now finished an argument or asked a difficult question, having grown accustomed to abandoning sentences the instant they threatened to run long.", "The turning point came when her closest friend was detained for three days after a routine audit revealed she had been lending unused portions of her quota to neighbors through an illegal word-sharing network, a practice the Ministry classified as unauthorized speech redistribution. Watching her friend released, shaken and reluctant to speak even within her own allotted limit, Nadia finally understood what her grandmother had meant: the quota's true purpose was never merely to prevent unrest, but to make people forget how to trust their own voices.", "Quietly, deliberately, Nadia began spending her entire quota each day on one uncomfortable truth after another, small acts of resistance too minor to prosecute yet too consistent to ignore. She had no illusions that her words alone would dismantle the system, but she had decided, at last, that silence bought at the cost of her own convictions was a currency she was no longer willing to spend."], "paragraphs_pt": ["No distrito de Meridian, cada cidadão recebia exatamente duzentas palavras de fala não monitorada por dia; qualquer coisa além da cota era sinalizada, transcrita e revisada pelo Ministério da Coesão, cujo mandato oficial era prevenir o tipo de retórica descontrolada que, décadas antes, havia mergulhado a região em uma revolta civil. Nadia tinha aprendido, como todo mundo, a racionar as frases com cuidado, guardando a cota para o que realmente importava e comunicando o resto por gestos, meios-sorrisos e silêncios que os monitores não conseguiam quantificar.", "A avó dela, que se lembrava dos anos antes do sistema de cotas, costumava dizer que o governo não tinha exatamente silenciado a dissidência, mas treinado as pessoas a se silenciarem sozinhas, já que o medo de ultrapassar o limite fazia os cidadãos questionarem até os comentários mais inofensivos. Nadia descartou isso a princípio como exagero nostálgico, até perceber com que raridade agora terminava um argumento ou fazia uma pergunta difícil, tendo se acostumado a abandonar frases no instante em que ameaçavam se alongar.", "O ponto de virada veio quando sua amiga mais próxima foi detida por três dias depois que uma auditoria de rotina revelou que ela vinha emprestando porções não usadas da própria cota a vizinhos por meio de uma rede ilegal de compartilhamento de palavras, uma prática que o Ministério classificava como redistribuição não autorizada de fala. Ao ver a amiga ser solta, abalada e relutante em falar até mesmo dentro do próprio limite permitido, Nadia finalmente entendeu o que a avó quisera dizer: o verdadeiro propósito da cota nunca fora apenas prevenir revoltas, mas fazer as pessoas esquecerem como confiar na própria voz.", "Silenciosa e deliberadamente, Nadia começou a gastar toda a cota diária dizendo uma verdade incômoda atrás da outra, pequenos atos de resistência demais insignificantes para serem processados, mas consistentes demais para serem ignorados. Ela não tinha ilusões de que suas palavras sozinhas desmantelariam o sistema, mas tinha decidido, finalmente, que o silêncio comprado às custas das próprias convicções era uma moeda que ela não estava mais disposta a gastar."], "hard_words": ["allotted", "quota", "rhetoric", "ration", "dismantle"], "vocab": [{"word": "unmonitored speech", "meaning": "fala não monitorada", "note": ""}, {"word": "second-guess", "meaning": "questionar/duvidar de si mesmo", "note": ""}, {"word": "turning point", "meaning": "ponto de virada", "note": ""}, {"word": "grown accustomed to", "meaning": "se acostumado a", "note": ""}, {"word": "no illusions", "meaning": "sem ilusões", "note": ""}, {"word": "at the cost of", "meaning": "às custas de", "note": ""}, {"word": "willing to", "meaning": "disposto(a) a", "note": ""}], "word_meanings": [{"word": "allotted", "meaning": "concedida/atribuída (cota)", "note": ""}, {"word": "quota", "meaning": "cota", "note": ""}, {"word": "rhetoric", "meaning": "retórica", "note": ""}, {"word": "ration", "meaning": "racionar", "note": ""}, {"word": "dismantle", "meaning": "desmantelar", "note": ""}, {"word": "realize", "meaning": "perceber (não 'realizar')", "note": "falso cognato"}, {"word": "actually", "meaning": "na verdade (não 'atualmente')", "note": "falso cognato"}, {"word": "was", "meaning": "era/foi", "note": "to be"}, {"word": "were", "meaning": "eram", "note": "to be"}, {"word": "began", "meaning": "começou", "note": "passado irregular"}, {"word": "understood", "meaning": "entendeu", "note": "passado irregular"}, {"word": "dismissed", "meaning": "descartou", "note": "passado regular"}, {"word": "had", "meaning": "tinha/teve", "note": "passado irregular"}, {"word": "came", "meaning": "veio", "note": "passado irregular"}, {"word": "grew", "meaning": "cresceu/ficou", "note": "passado irregular"}], "grammar_words": {"cognates": [], "tobe": ["was"], "irregular": ["began", "understood", "came", "had"], "phrasal": [], "wh": [], "connectors": ["since", "but", "yet", "until", "so"], "comparative": []}, "exercises": {"grammar": [{"point": "Not so much... but", "explanation_pt": "'the government had not so much silenced dissent as trained people to silence themselves' compara duas ideias, destacando a segunda como a mais precisa."}, {"point": "Gerúndio após preposição", "explanation_pt": "'the instant they threatened to run long' e 'a currency she was no longer willing to spend' mostram estruturas com infinitivo/gerúndio típicas do nível C1."}], "multiple_choice": [{"question": "What was the daily word quota in Meridian?", "options": ["Two hundred words", "One hundred words", "Five hundred words", "There was no limit"], "correct_index": 0, "explanation": "Cada cidadão tinha duzentas palavras de fala não monitorada por dia."}, {"question": "According to Nadia's grandmother, what was the quota's real effect?", "options": ["It improved communication", "It trained people to silence themselves", "It had no effect", "It increased civil unrest"], "correct_index": 1, "explanation": "O sistema treinava as pessoas a se autocensurarem."}, {"question": "Why was Nadia's friend detained?", "options": ["She insulted the Ministry", "She exceeded her quota once", "She shared her unused quota with neighbors", "She refused to speak"], "correct_index": 2, "explanation": "Ela compartilhava a cota não usada por meio de uma rede ilegal."}, {"question": "What did Nadia decide to do after her friend's detention?", "options": ["Stop speaking entirely", "Leave the district", "Report her grandmother", "Spend her whole quota on uncomfortable truths"], "correct_index": 3, "explanation": "Ela passou a gastar toda a cota dizendo verdades incômodas."}, {"question": "What did Nadia conclude was the quota system's true purpose?", "options": ["To make people forget how to trust their own voices", "To save resources", "To improve education", "To reward loyal citizens"], "correct_index": 0, "explanation": "Ela concluiu que o objetivo era fazer as pessoas desconfiarem da própria voz."}], "open_questions": [{"question": "What parallels, if any, do you see between the word quota and forms of self-censorship in the real world?", "key_points_pt": ["discutir autocensura, redes sociais ou vigilância", "relacionar com o sistema descrito na história"]}, {"question": "Do you think Nadia's small act of resistance can make a real difference? Why or why not?", "key_points_pt": ["dar opinião justificada", "considerar o poder de pequenos atos coletivos"]}]}}, {"level": "C1", "genre": "postapoc", "title": "Seeds in the Ash", "paragraphs": ["Ten years after the ash clouds had blotted out the sun for what survivors still called the Grey Winter, Coren led scavenging parties through the ruined outskirts of what had once been a thriving agricultural valley, searching not for food or fuel but for something far rarer: uncontaminated seeds. Most of the old seed banks had been looted or destroyed in the chaotic years immediately following the collapse, and the settlement's soil, though slowly recovering, remained too depleted to sustain anything beyond the hardiest weeds.", "On the seventh day of an expedition that had yielded little but disappointment, Coren's team stumbled upon a collapsed farmhouse whose cellar, sealed by fallen beams, had somehow kept its contents dry and undisturbed. Inside, wrapped in wax paper that had brittled with age but not crumbled, lay dozens of carefully labeled envelopes, a farmer's private collection preserved by nothing more than sheer, improbable luck.", "Word of the discovery spread through the settlement faster than Coren could organize a proper inventory, and within days, arguments broke out over who deserved priority access to the seeds, some insisting they belonged to whoever had the strongest claim to farming experience, others arguing they should be rationed equally regardless of skill. Coren, exhausted by the infighting, finally proposed a compromise that satisfied almost no one entirely: a communal plot, tended collectively, whose harvest would belong to the settlement as a whole rather than to any single family.", "The first tomatoes ripened months later, small and imperfect, yet undeniably real, and the settlement gathered to share them in portions barely larger than a mouthful each. Coren, watching children taste an actual vegetable for the first time in their short lives, understood that the true harvest was not the fruit itself but the fragile, hard-won agreement that had made growing it possible at all."], "paragraphs_pt": ["Dez anos depois de as nuvens de cinzas terem obscurecido o sol naquilo que os sobreviventes ainda chamavam de Inverno Cinzento, Coren liderava grupos de busca pelos arredores arruinados do que fora outrora um vale agrícola próspero, procurando não por comida ou combustível, mas por algo bem mais raro: sementes não contaminadas. A maioria dos antigos bancos de sementes tinha sido saqueada ou destruída nos caóticos anos imediatamente após o colapso, e o solo do assentamento, embora se recuperando lentamente, ainda estava esgotado demais para sustentar qualquer coisa além das ervas daninhas mais resistentes.", "No sétimo dia de uma expedição que tinha rendido pouco além de decepção, a equipe de Coren deu de cara com uma casa de fazenda desmoronada cujo porão, lacrado por vigas caídas, de alguma forma tinha mantido o conteúdo seco e intocado. Dentro, embrulhados em papel encerado que tinha ficado quebradiço com o tempo mas não se esfarelara, havia dezenas de envelopes cuidadosamente etiquetados, a coleção particular de um fazendeiro preservada por nada além de pura e improvável sorte.", "A notícia da descoberta se espalhou pelo assentamento mais rápido do que Coren conseguia organizar um inventário adequado, e em poucos dias surgiram discussões sobre quem merecia acesso prioritário às sementes, alguns insistindo que elas pertenciam a quem tivesse a experiência agrícola mais sólida, outros argumentando que deveriam ser racionadas igualmente, independentemente da habilidade. Coren, esgotado pelas brigas internas, finalmente propôs um meio-termo que não satisfez ninguém completamente: um terreno comunitário, cultivado coletivamente, cuja colheita pertenceria ao assentamento como um todo, e não a nenhuma família isoladamente.", "Os primeiros tomates amadureceram meses depois, pequenos e imperfeitos, mas inegavelmente reais, e o assentamento se reuniu para compartilhá-los em porções mal maiores que uma bocada cada. Coren, observando crianças provarem um vegetal de verdade pela primeira vez em suas curtas vidas, entendeu que a verdadeira colheita não era o fruto em si, mas o acordo frágil e duramente conquistado que tinha tornado o cultivo possível."], "hard_words": ["blotted out", "depleted", "brittled", "crumbled", "infighting"], "vocab": [{"word": "scavenging parties", "meaning": "grupos de busca/catação", "note": ""}, {"word": "stumbled upon", "meaning": "deu de cara com, encontrou por acaso", "note": "phrasal verb"}, {"word": "sheer luck", "meaning": "pura sorte", "note": ""}, {"word": "broke out", "meaning": "estourou/começou (conflito)", "note": "phrasal verb"}, {"word": "regardless of", "meaning": "independentemente de", "note": ""}, {"word": "hard-won", "meaning": "duramente conquistado", "note": ""}, {"word": "a mouthful", "meaning": "uma bocada", "note": ""}], "word_meanings": [{"word": "blotted out", "meaning": "obscureceram/encobriram", "note": "phrasal verb"}, {"word": "depleted", "meaning": "esgotado", "note": ""}, {"word": "brittled", "meaning": "ficou quebradiço", "note": ""}, {"word": "crumbled", "meaning": "se esfarelou", "note": ""}, {"word": "infighting", "meaning": "brigas internas", "note": ""}, {"word": "stumbled upon", "meaning": "encontrou por acaso", "note": "phrasal verb"}, {"word": "broke out", "meaning": "estourou", "note": "phrasal verb"}, {"word": "realize", "meaning": "perceber (não 'realizar')", "note": "falso cognato"}, {"word": "actual", "meaning": "real/verdadeiro (não 'atual')", "note": "falso cognato"}, {"word": "was", "meaning": "era/foi", "note": "to be"}, {"word": "were", "meaning": "eram", "note": "to be"}, {"word": "led", "meaning": "liderou", "note": "passado irregular"}, {"word": "understood", "meaning": "entendeu", "note": "passado irregular"}, {"word": "grew", "meaning": "cresceu/ficou", "note": "passado irregular"}, {"word": "lay", "meaning": "estava deitado(a)", "note": "passado irregular"}, {"word": "spread", "meaning": "se espalhou", "note": "passado irregular"}], "grammar_words": {"cognates": ["actual"], "tobe": ["was"], "irregular": ["led", "understood", "spread", "lay"], "phrasal": ["stumbled upon", "broke out"], "wh": ["who"], "connectors": ["though", "yet", "and", "rather than"], "comparative": ["rarer", "faster", "larger"]}, "exercises": {"grammar": [{"point": "'Not X but Y'", "explanation_pt": "'searching not for food or fuel but for something far rarer' contrasta duas ideias, dando ênfase à segunda opção."}, {"point": "Comparativo com 'far'", "explanation_pt": "'far rarer' intensifica o comparativo, indicando uma diferença grande entre as opções comparadas."}], "multiple_choice": [{"question": "What was Coren searching for during the expeditions?", "options": ["Uncontaminated seeds", "Fuel", "Weapons", "Survivors"], "correct_index": 0, "explanation": "Ele procurava sementes não contaminadas."}, {"question": "Where did the team find the preserved seeds?", "options": ["In an underground bunker", "In a collapsed farmhouse's cellar", "In an abandoned store", "Buried in the ash"], "correct_index": 1, "explanation": "Encontraram no porão de uma casa de fazenda desmoronada."}, {"question": "What caused arguments in the settlement after the discovery?", "options": ["Who should lead the expedition", "Where to store the seeds", "Who deserved priority access to the seeds", "Whether the seeds were real"], "correct_index": 2, "explanation": "Discutiram sobre quem merecia acesso prioritário às sementes."}, {"question": "What compromise did Coren propose?", "options": ["Selling the seeds", "Giving all seeds to the most experienced farmer", "Destroying the extra seeds", "A communal plot with shared harvest"], "correct_index": 3, "explanation": "Ele propôs um terreno comunitário com colheita compartilhada."}, {"question": "What did Coren realize while watching children eat the tomatoes?", "options": ["The true harvest was the agreement that made it possible", "The harvest was too small", "Farming was too difficult", "The seeds should be sold"], "correct_index": 0, "explanation": "Ele entendeu que o verdadeiro valor era o acordo coletivo, não só o fruto."}], "open_questions": [{"question": "Why do you think Coren's compromise satisfied 'almost no one entirely,' yet still worked?", "key_points_pt": ["discutir a ideia de meio-termo em situações de escassez", "relacionar com cooperação versus interesse individual"]}, {"question": "In a post-apocalyptic scenario, how might scarce resources be fairly distributed? Give your own idea.", "key_points_pt": ["propor um critério de distribuição justo", "justificar com base em equidade ou necessidade"]}]}}, {"level": "C1", "genre": "spy", "title": "The Cellist's Signal", "paragraphs": ["For six months, Ivana had posed as a visiting cellist with the national orchestra, a cover meticulously constructed to grant her access to a diplomat suspected of funneling classified shipping routes to a rival intelligence service. Her tradecraft depended on a single, unglamorous ritual: after each rehearsal, she left her instrument case in a specific corner of the green room, its clasps arranged in a pattern that signaled, to anyone trained to notice, whether a meeting was safe to proceed.", "The diplomat, a courteous man who lingered after concerts to discuss Brahms with an enthusiasm Ivana suspected was genuine, had no idea that their conversations about tempo and phrasing were, for her, an elaborate exercise in extracting fragments of information he let slip without realizing it. She found herself, uncomfortably, growing fond of him, a complication her handler had warned her about but that she had dismissed as a risk reserved for less disciplined agents.", "Everything unraveled the night her case's clasps were discovered rearranged by someone other than herself, a silent warning that her cover had been compromised and that continuing the operation would place her, and possibly the diplomat, in immediate danger. Rather than fleeing immediately, as protocol demanded, Ivana lingered long enough to leave him an anonymous note hidden inside his music stand, a small act of mercy that violated every rule she had been trained to follow.", "She was extracted within the hour, bundled onto a cargo plane before dawn, and never learned whether the diplomat had heeded her warning or dismissed it as an admirer's strange gesture. Years later, reading a brief intelligence report noting that he had quietly defected and requested asylum, Ivana allowed herself, for the first time since the operation, a small and complicated satisfaction."], "paragraphs_pt": ["Por seis meses, Ivana se passou por uma violoncelista visitante da orquestra nacional, uma fachada meticulosamente construída para lhe dar acesso a um diplomata suspeito de repassar rotas marítimas classificadas a um serviço de inteligência rival. Sua técnica de espionagem dependia de um único e nada glamouroso ritual: depois de cada ensaio, ela deixava o estojo do instrumento num canto específico da sala verde, com os fechos arranjados num padrão que sinalizava, para quem estivesse treinado a notar, se um encontro era seguro para prosseguir.", "O diplomata, um homem cortês que ficava depois dos concertos para discutir Brahms com um entusiasmo que Ivana suspeitava ser genuíno, não fazia ideia de que as conversas sobre andamento e fraseado eram, para ela, um exercício elaborado de extrair fragmentos de informação que ele deixava escapar sem perceber. Ela se percebeu, desconfortavelmente, se afeiçoando a ele, uma complicação sobre a qual sua superiora a tinha alertado, mas que ela havia descartado como um risco reservado a agentes menos disciplinados.", "Tudo desmoronou na noite em que os fechos do estojo foram encontrados rearranjados por alguém que não ela mesma, um aviso silencioso de que sua fachada tinha sido comprometida e que continuar a operação a colocaria, e possivelmente ao diplomata, em perigo imediato. Em vez de fugir imediatamente, como o protocolo exigia, Ivana demorou o suficiente para deixar-lhe um bilhete anônimo escondido dentro da estante de partituras dele, um pequeno ato de misericórdia que violava toda regra que ela tinha sido treinada a seguir.", "Ela foi extraída em menos de uma hora, colocada às pressas num avião de carga antes do amanhecer, e nunca soube se o diplomata tinha atendido ao aviso dela ou o descartado como um gesto estranho de uma admiradora. Anos depois, lendo um breve relatório de inteligência que mencionava que ele desertara discretamente e pedira asilo, Ivana permitiu-se, pela primeira vez desde a operação, uma satisfação pequena e complicada."], "hard_words": ["funneling", "clasps", "unraveled", "heeded", "defected"], "vocab": [{"word": "cover", "meaning": "fachada/disfarce (espionagem)", "note": ""}, {"word": "let slip", "meaning": "deixar escapar (informação)", "note": "expressão idiomática"}, {"word": "growing fond of", "meaning": "se afeiçoando a", "note": ""}, {"word": "compromised", "meaning": "comprometida", "note": ""}, {"word": "act of mercy", "meaning": "ato de misericórdia", "note": ""}, {"word": "extracted", "meaning": "retirada/resgatada (operação)", "note": ""}, {"word": "asylum", "meaning": "asilo", "note": ""}], "word_meanings": [{"word": "funneling", "meaning": "repassando/canalizando", "note": ""}, {"word": "clasps", "meaning": "fechos", "note": ""}, {"word": "unraveled", "meaning": "desmoronou/se desfez", "note": ""}, {"word": "heeded", "meaning": "atendeu/deu ouvidos a", "note": ""}, {"word": "defected", "meaning": "desertou", "note": ""}, {"word": "realizing", "meaning": "percebendo (não 'realizando')", "note": "falso cognato"}, {"word": "actually", "meaning": "na verdade (não 'atualmente')", "note": "falso cognato"}, {"word": "was", "meaning": "era/foi", "note": "to be"}, {"word": "were", "meaning": "eram/foram", "note": "to be"}, {"word": "left", "meaning": "deixou", "note": "passado irregular"}, {"word": "found", "meaning": "encontrou/percebeu", "note": "passado irregular"}, {"word": "lingered", "meaning": "demorou-se", "note": "passado regular"}, {"word": "let slip", "meaning": "deixou escapar", "note": "phrasal verb"}, {"word": "had", "meaning": "tinha/teve", "note": "passado irregular"}, {"word": "heard", "meaning": "ouviu", "note": "passado irregular"}, {"word": "grew", "meaning": "cresceu/ficou", "note": "passado irregular"}], "grammar_words": {"cognates": ["realizing"], "tobe": ["was", "were"], "irregular": ["left", "found", "had"], "phrasal": ["let slip"], "wh": ["whether"], "connectors": ["rather than", "but", "and", "since"], "comparative": ["less disciplined"]}, "exercises": {"grammar": [{"point": "Gerúndio após preposição", "explanation_pt": "'without realizing it' e 'growing fond of him' mostram o uso do gerúndio depois de preposições, comum em inglês avançado."}, {"point": "Discurso indireto com 'whether'", "explanation_pt": "'never learned whether the diplomat had heeded her warning' introduz uma incerteza usando 'whether' + past perfect."}], "multiple_choice": [{"question": "What was Ivana's cover identity?", "options": ["A visiting cellist", "A journalist", "A diplomat's assistant", "A music teacher"], "correct_index": 0, "explanation": "Ela se passava por uma violoncelista visitante."}, {"question": "How did Ivana signal whether a meeting was safe?", "options": ["A coded phone call", "The arrangement of her instrument case's clasps", "A specific song she played", "A note under a chair"], "correct_index": 1, "explanation": "O padrão dos fechos do estojo sinalizava a segurança do encontro."}, {"question": "What complication did Ivana's handler warn her about?", "options": ["Getting caught by police", "Losing her cello", "Growing fond of the diplomat", "Missing rehearsals"], "correct_index": 2, "explanation": "A superiora a alertou sobre o risco de se afeiçoar ao alvo."}, {"question": "What did Ivana do despite the danger, before being extracted?", "options": ["She confronted the diplomat directly", "She destroyed all evidence", "She called her handler", "She left him an anonymous warning note"], "correct_index": 3, "explanation": "Ela deixou um bilhete anônimo escondido na estante de partituras."}, {"question": "What did Ivana eventually learn about the diplomat?", "options": ["He quietly defected and requested asylum", "He was arrested", "He never found the note", "He continued working for the rival service"], "correct_index": 0, "explanation": "Anos depois, ela leu que ele desertara e pedira asilo."}], "open_questions": [{"question": "Why do you think Ivana risked breaking protocol to warn the diplomat?", "key_points_pt": ["discutir o conflito entre dever profissional e afeto pessoal", "citar a decisão dela de deixar o bilhete"]}, {"question": "Do you think spies can maintain emotional detachment from the people they investigate? Why or why not?", "key_points_pt": ["dar opinião pessoal", "relacionar com o exemplo de Ivana"]}]}}, {"level": "C1", "genre": "corporate", "title": "The Quiet Resignation", "paragraphs": ["When Renato was passed over for the regional director position for the third consecutive year, in favor of a candidate who had joined the firm eighteen months earlier, he did not storm into his manager's office or fire off an indignant email, as several colleagues privately expected. Instead, he spent a weekend drafting a resignation letter so measured and professional that his manager later admitted it made her far more uneasy than any outburst could have.", "The letter thanked the company for a decade of opportunities while noting, without a trace of bitterness, that promotion decisions had consistently rewarded visibility over substance, and that he no longer wished to compete in a system where self-promotion mattered more than results. Word of the letter circulated quietly through the office, and several colleagues confided that they had drafted similar letters themselves, though none had found the nerve to actually submit one.", "Senior leadership, alarmed at the prospect of losing someone whose departure might expose uncomfortable truths about the promotion process, offered Renato a counteroffer that included the very title he had been denied, along with a hastily arranged apology from the executive who had overlooked him. He turned it down politely, explaining that accepting would only validate the assumption that leaving, rather than merit, was what finally got people heard.", "Renato's departure prompted an internal review of the promotion criteria, a change he never witnessed firsthand since he had already moved to a competitor by the time the new policy was announced. He later joked, with the same restraint that had defined his resignation letter, that quitting gracefully had accomplished more for his former colleagues than years of diligent, uncomplaining work ever had."], "paragraphs_pt": ["Quando Renato foi preterido para o cargo de diretor regional pelo terceiro ano consecutivo, em favor de um candidato que tinha entrado na empresa apenas dezoito meses antes, ele não invadiu a sala da gerente nem disparou um e-mail indignado, como vários colegas esperavam em particular. Em vez disso, passou um fim de semana redigindo uma carta de demissão tão ponderada e profissional que sua gerente depois admitiu que isso a deixou muito mais incomodada do que qualquer explosão de raiva poderia ter deixado.", "A carta agradecia à empresa por uma década de oportunidades enquanto observava, sem nenhum traço de amargura, que as decisões de promoção tinham recompensado consistentemente a visibilidade em vez da substância, e que ele não desejava mais competir num sistema em que autopromoção importava mais do que resultados. A notícia da carta circulou discretamente pelo escritório, e vários colegas confidenciaram que também tinham redigido cartas parecidas, embora nenhum tivesse tido coragem de realmente entregá-las.", "A alta liderança, alarmada com a perspectiva de perder alguém cuja saída poderia expor verdades incômodas sobre o processo de promoção, ofereceu a Renato uma contraproposta que incluía exatamente o cargo que lhe tinha sido negado, junto com um pedido de desculpas apressado do executivo que o tinha ignorado. Ele recusou educadamente, explicando que aceitar apenas validaria a suposição de que sair, e não o mérito, era o que finalmente fazia as pessoas serem ouvidas.", "A saída de Renato provocou uma revisão interna dos critérios de promoção, uma mudança que ele nunca testemunhou pessoalmente, já que já tinha ido para um concorrente quando a nova política foi anunciada. Ele depois brincou, com a mesma contenção que tinha marcado sua carta de demissão, que sair com elegância tinha conseguido mais para seus antigos colegas do que anos de trabalho diligente e sem reclamações jamais haviam conseguido."], "hard_words": ["passed over", "outburst", "bitterness", "counteroffer", "restraint"], "vocab": [{"word": "passed over for", "meaning": "preterido para (um cargo)", "note": "expressão de trabalho"}, {"word": "storm into", "meaning": "invadir (com raiva)", "note": ""}, {"word": "fire off", "meaning": "disparar (um e-mail, com raiva)", "note": "phrasal verb"}, {"word": "found the nerve", "meaning": "teve coragem", "note": "expressão idiomática"}, {"word": "turned it down", "meaning": "recusou", "note": "phrasal verb"}, {"word": "firsthand", "meaning": "em primeira mão/pessoalmente", "note": ""}, {"word": "gracefully", "meaning": "com elegância", "note": ""}], "word_meanings": [{"word": "passed over", "meaning": "preterido", "note": ""}, {"word": "outburst", "meaning": "explosão (de raiva)", "note": ""}, {"word": "bitterness", "meaning": "amargura", "note": ""}, {"word": "counteroffer", "meaning": "contraproposta", "note": ""}, {"word": "restraint", "meaning": "contenção, comedimento", "note": ""}, {"word": "fire off", "meaning": "disparar", "note": "phrasal verb"}, {"word": "turned down", "meaning": "recusou", "note": "phrasal verb"}, {"word": "actually", "meaning": "na verdade (não 'atualmente')", "note": "falso cognato"}, {"word": "eventually", "meaning": "finalmente (não 'eventualmente')", "note": "falso cognato"}, {"word": "was", "meaning": "era/foi", "note": "to be"}, {"word": "were", "meaning": "eram", "note": "to be"}, {"word": "spent", "meaning": "passou (tempo)", "note": "passado irregular"}, {"word": "offered", "meaning": "ofereceu", "note": "passado regular"}, {"word": "had", "meaning": "tinha/teve", "note": "passado irregular"}, {"word": "took", "meaning": "levou/pegou", "note": "passado irregular"}], "grammar_words": {"cognates": ["actually"], "tobe": ["was"], "irregular": ["spent", "offered", "had"], "phrasal": ["fire off"], "wh": [], "connectors": ["instead", "though", "since", "rather than", "while"], "comparative": ["far more uneasy", "more than"]}, "exercises": {"grammar": [{"point": "Comparativos enfáticos com 'far'", "explanation_pt": "'far more uneasy than any outburst could have' usa 'far' para intensificar o comparativo, mostrando um contraste forte."}, {"point": "Cláusulas com 'rather than'", "explanation_pt": "'leaving, rather than merit, was what finally got people heard' contrasta duas causas possíveis usando 'rather than'."}], "multiple_choice": [{"question": "How many times was Renato passed over for the director position?", "options": ["Three times", "Once", "Twice", "Four times"], "correct_index": 0, "explanation": "Ele foi preterido pelo terceiro ano consecutivo."}, {"question": "How did Renato react to being passed over again?", "options": ["He shouted at his manager", "He wrote a calm, professional resignation letter", "He immediately quit without notice", "He complained publicly"], "correct_index": 1, "explanation": "Ele escreveu uma carta de demissão ponderada e profissional."}, {"question": "What did the resignation letter criticize?", "options": ["The company's salaries", "The office location", "The promotion system rewarding visibility over substance", "His manager's personality"], "correct_index": 2, "explanation": "A carta criticava um sistema que recompensava visibilidade em vez de substância."}, {"question": "Why did Renato refuse the counteroffer?", "options": ["The salary was too low", "He had already accepted another job", "He disliked the new title", "Accepting would validate that leaving mattered more than merit"], "correct_index": 3, "explanation": "Ele não queria validar a ideia de que sair era o que fazia as pessoas serem ouvidas."}, {"question": "What happened after Renato's departure?", "options": ["The promotion criteria were reviewed", "The company collapsed", "Nothing changed", "He was rehired immediately"], "correct_index": 0, "explanation": "A empresa fez uma revisão interna dos critérios de promoção."}], "open_questions": [{"question": "Do you think Renato's calm approach was more effective than an angry confrontation would have been? Why?", "key_points_pt": ["discutir a eficácia de uma saída educada versus uma reação impulsiva", "citar o impacto que a carta teve na empresa"]}, {"question": "Have you or someone you know ever left a job or situation on principle? What happened?", "key_points_pt": ["compartilhar exemplo pessoal ou hipotético", "relacionar com a decisão de Renato"]}]}}, {"level": "C1", "genre": "diary", "title": "March Entries", "paragraphs": ["March 3rd. I keep putting off writing about the diagnosis, as though avoiding the page might somehow delay the reality it describes, but tonight I finally forced myself to sit down and admit, at least to this notebook, that Mom's doctors are no longer speaking in terms of treatment but of comfort. I don't know how to hold both truths at once: that she seems entirely herself at dinner, cracking the same dry jokes she always has, and that the prognosis in the folder on the kitchen counter says otherwise.", "March 11th. Today she asked me, out of nowhere, whether I remembered the summer we got lost driving to the coast and ended up, three hours late, at a beach nobody else wanted because the tide pools smelled faintly of rotten eggs. I said of course I remembered, and she smiled in that way that made me suspect she was cataloguing memories on purpose now, handing them to me deliberately before she loses the chance.", "March 19th. I caught myself, for the first time, rehearsing what I might say at a funeral that hasn't happened yet, and I hated myself a little for it, as though preparing were a kind of betrayal, a way of giving up on her before she has given up on herself. And yet some pragmatic, exhausted part of me knows that grief postponed is still grief, and that I am only trying to spread mine out so it doesn't arrive all at once.", "March 27th. She had a good day today, good enough that we sat on the porch for an hour without either of us mentioning doctors or prognoses at all, just the weather and a neighbor's ridiculous new dog. I am learning, slowly and imperfectly, that loving someone through this means holding the ordinary and the unbearable in the same hand, and setting neither of them down."], "paragraphs_pt": ["3 de março. Continuo adiando escrever sobre o diagnóstico, como se evitar a página pudesse de algum modo atrasar a realidade que ela descreve, mas hoje à noite finalmente me obriguei a sentar e admitir, ao menos para este caderno, que os médicos da mamãe não falam mais em termos de tratamento, e sim de conforto. Não sei como segurar as duas verdades ao mesmo tempo: que ela parece completamente ela mesma no jantar, soltando as mesmas piadas secas de sempre, e que o prognóstico na pasta sobre a bancada da cozinha diz o contrário.", "11 de março. Hoje ela me perguntou, do nada, se eu me lembrava do verão em que nos perdemos indo para o litoral e acabamos, três horas atrasados, numa praia que ninguém mais queria porque as poças de maré tinham um leve cheiro de ovo podre. Eu disse que claro que lembrava, e ela sorriu daquele jeito que me fez desconfiar que estava catalogando memórias de propósito agora, entregando-as a mim deliberadamente antes de perder a chance.", "19 de março. Me peguei, pela primeira vez, ensaiando o que poderia dizer num funeral que ainda não aconteceu, e me odiei um pouco por isso, como se me preparar fosse uma espécie de traição, uma forma de desistir dela antes de ela desistir de si mesma. E, no entanto, alguma parte pragmática e exausta em mim sabe que luto adiado ainda é luto, e que só estou tentando espalhar o meu para que ele não chegue de uma vez só.", "27 de março. Ela teve um bom dia hoje, bom o suficiente para ficarmos sentadas na varanda por uma hora sem nenhuma de nós mencionar médicos ou prognósticos, só o tempo e o cachorro novo e ridículo de um vizinho. Estou aprendendo, devagar e de forma imperfeita, que amar alguém através disso significa segurar o comum e o insuportável na mesma mão, sem largar nenhum dos dois."], "hard_words": ["putting off", "prognosis", "cataloguing", "rehearsing", "unbearable"], "vocab": [{"word": "putting off", "meaning": "adiando", "note": "phrasal verb"}, {"word": "out of nowhere", "meaning": "do nada", "note": "expressão idiomática"}, {"word": "on purpose", "meaning": "de propósito", "note": ""}, {"word": "caught myself", "meaning": "me peguei (fazendo algo)", "note": ""}, {"word": "giving up on", "meaning": "desistir de", "note": "phrasal verb"}, {"word": "all at once", "meaning": "de uma vez só", "note": ""}, {"word": "setting neither down", "meaning": "sem largar nenhum dos dois", "note": ""}], "word_meanings": [{"word": "putting off", "meaning": "adiando", "note": "phrasal verb"}, {"word": "prognosis", "meaning": "prognóstico", "note": ""}, {"word": "cataloguing", "meaning": "catalogando", "note": ""}, {"word": "rehearsing", "meaning": "ensaiando", "note": ""}, {"word": "unbearable", "meaning": "insuportável", "note": ""}, {"word": "giving up on", "meaning": "desistindo de", "note": "phrasal verb"}, {"word": "actually", "meaning": "na verdade (não 'atualmente')", "note": "falso cognato"}, {"word": "eventually", "meaning": "finalmente (não 'eventualmente')", "note": "falso cognato"}, {"word": "was", "meaning": "era/estava", "note": "to be"}, {"word": "were", "meaning": "eram/estavam", "note": "to be"}, {"word": "caught", "meaning": "pegou", "note": "passado irregular"}, {"word": "said", "meaning": "disse", "note": "passado irregular"}, {"word": "knew", "meaning": "sabia", "note": "passado irregular"}, {"word": "had", "meaning": "tinha/teve", "note": "passado irregular"}, {"word": "lose", "meaning": "perder", "note": "passado irregular"}], "grammar_words": {"cognates": [], "tobe": ["was", "were"], "irregular": ["caught", "said", "had"], "phrasal": ["putting off", "giving up on"], "wh": ["whether"], "connectors": ["but", "as though", "and yet", "so", "because"], "comparative": ["good enough"]}, "exercises": {"grammar": [{"point": "'As though' com passado", "explanation_pt": "'as though avoiding the page might somehow delay the reality' expressa uma ideia hipotética ou irreal usando 'as though' + modal no passado."}, {"point": "Gerúndio como sujeito", "explanation_pt": "'Loving someone through this means holding the ordinary and the unbearable' usa o gerúndio ('loving', 'holding') como sujeito e complemento da frase."}], "multiple_choice": [{"question": "What difficult truth does the narrator admit on March 3rd?", "options": ["Mom's doctors are focusing on comfort, not treatment", "Mom is fully recovering", "Mom refuses to see doctors", "The narrator is also sick"], "correct_index": 0, "explanation": "Os médicos passaram a falar em conforto, não tratamento."}, {"question": "What memory does Mom bring up on March 11th?", "options": ["A wedding", "Getting lost driving to the coast", "A birthday party", "Moving to a new house"], "correct_index": 1, "explanation": "Ela lembra do dia em que se perderam indo para o litoral."}, {"question": "Why does the narrator feel guilty on March 19th?", "options": ["She forgot Mom's birthday", "She argued with Mom", "She caught herself rehearsing a funeral speech", "She missed a doctor's appointment"], "correct_index": 2, "explanation": "Ela se pegou ensaiando o que diria num funeral."}, {"question": "What happened on March 27th?", "options": ["Mom went to the hospital", "The narrator moved away", "Mom got worse", "They had a peaceful day without mentioning the illness"], "correct_index": 3, "explanation": "Elas tiveram um bom dia sem falar de médicos ou prognósticos."}, {"question": "What does the narrator learn about loving someone who is dying?", "options": ["It means holding both the ordinary and the unbearable together", "It means avoiding difficult topics entirely", "It means preparing only for the worst", "It means pretending everything is fine"], "correct_index": 0, "explanation": "Ela aprende a segurar o comum e o insuportável ao mesmo tempo."}], "open_questions": [{"question": "Why might writing in a diary help someone process a painful situation like this one?", "key_points_pt": ["discutir o papel da escrita como forma de processar emoções", "citar exemplos das entradas do diário"]}, {"question": "Do you think it is wrong to prepare emotionally for a loss before it happens? Why or why not?", "key_points_pt": ["dar opinião pessoal", "considerar a culpa da narradora e a ideia de luto antecipado"]}]}}, {"level": "C1", "genre": "news", "title": "City Council Reverses Course on Riverside Development", "paragraphs": ["The city council voted unanimously on Tuesday to withdraw approval for the long-contested Riverside Commons development, reversing a decision it had upheld as recently as February despite mounting opposition from environmental groups and residents of the adjacent Alameda neighborhood. The reversal follows the release of an independent hydrological survey indicating that the proposed twelve-story complex would have significantly worsened flood risk downstream, a finding the developer's own consultants had reportedly downplayed in earlier filings.", "Councilwoman Priya Deshmukh, who had cast the deciding vote in favor of the project last year, acknowledged during Tuesday's session that she had relied too heavily on assurances from the developer rather than commissioning an independent assessment sooner. \"We owe residents an apology for how long this took,\" she said, adding that the council would introduce stricter disclosure requirements for future large-scale developments near the floodplain.", "Representatives for Meridian Property Group, the firm behind the project, expressed disappointment with the decision but stopped short of confirming whether they would pursue legal action, noting only that they were \"reviewing all available options.\" Residents who had spent nearly two years organizing petitions and attending council meetings described the vote as long overdue, though several cautioned that similar developments elsewhere in the city still lack comparable scrutiny.", "The council has asked city planners to draft updated floodplain guidelines within ninety days, a timeline environmental advocates called ambitious but necessary given projections of increasingly severe seasonal flooding. For now, the Riverside Commons site remains undeveloped, its future uncertain, though residents say Tuesday's vote has at least restored some of their confidence that public concerns can still outweigh a well-funded developer's plans."], "paragraphs_pt": ["O conselho municipal votou por unanimidade na terça-feira para retirar a aprovação do contestado empreendimento Riverside Commons, revertendo uma decisão que havia mantido ainda em fevereiro apesar da crescente oposição de grupos ambientais e moradores do bairro vizinho de Alameda. A reversão vem após a divulgação de um estudo hidrológico independente indicando que o complexo proposto, de doze andares, teria piorado significativamente o risco de enchentes rio abaixo, uma constatação que os próprios consultores da construtora teriam minimizado em relatórios anteriores.", "A vereadora Priya Deshmukh, que havia dado o voto decisivo a favor do projeto no ano passado, reconheceu durante a sessão de terça-feira que havia confiado demais nas garantias da construtora em vez de encomendar uma avaliação independente mais cedo. \"Devemos um pedido de desculpas aos moradores pelo tempo que isso levou\", disse ela, acrescentando que o conselho introduziria exigências de divulgação mais rígidas para futuros empreendimentos de grande porte perto da planície de inundação.", "Representantes do Meridian Property Group, a empresa por trás do projeto, expressaram decepção com a decisão, mas evitaram confirmar se entrariam com ação judicial, observando apenas que estavam \"analisando todas as opções disponíveis\". Moradores que passaram quase dois anos organizando abaixo-assinados e comparecendo a reuniões do conselho descreveram a votação como atrasada havia muito tempo, embora vários tenham alertado que empreendimentos semelhantes em outras partes da cidade ainda carecem de fiscalização comparável.", "O conselho pediu que os urbanistas municipais elaborem diretrizes atualizadas para a planície de inundação em até noventa dias, um prazo que defensores do meio ambiente classificaram como ambicioso, mas necessário, diante das projeções de enchentes sazonais cada vez mais severas. Por enquanto, o terreno do Riverside Commons continua sem construção, com futuro incerto, embora os moradores digam que a votação de terça-feira ao menos restaurou parte da confiança de que preocupações públicas ainda podem se sobrepor aos planos de uma construtora bem financiada."], "hard_words": ["hydrological", "downplayed", "floodplain", "overdue", "scrutiny"], "vocab": [{"word": "withdraw approval", "meaning": "retirar a aprovação", "note": ""}, {"word": "mounting opposition", "meaning": "oposição crescente", "note": ""}, {"word": "cast the deciding vote", "meaning": "dar o voto decisivo", "note": ""}, {"word": "stopped short of", "meaning": "evitaram/não chegaram a fazer algo", "note": "expressão idiomática"}, {"word": "long overdue", "meaning": "atrasado(a) havia muito tempo", "note": ""}, {"word": "outweigh", "meaning": "sobrepor-se a, pesar mais que", "note": ""}, {"word": "well-funded", "meaning": "bem financiado(a)", "note": ""}], "word_meanings": [{"word": "hydrological", "meaning": "hidrológico", "note": ""}, {"word": "downplayed", "meaning": "minimizaram", "note": ""}, {"word": "floodplain", "meaning": "planície de inundação", "note": ""}, {"word": "overdue", "meaning": "atrasado, pendente há tempo", "note": ""}, {"word": "scrutiny", "meaning": "fiscalização, escrutínio", "note": ""}, {"word": "stopped short of", "meaning": "evitaram fazer", "note": "expressão idiomática"}, {"word": "actually", "meaning": "na verdade (não 'atualmente')", "note": "falso cognato"}, {"word": "eventually", "meaning": "finalmente (não 'eventualmente')", "note": "falso cognato"}, {"word": "was", "meaning": "era/foi", "note": "to be"}, {"word": "were", "meaning": "eram/foram", "note": "to be"}, {"word": "voted", "meaning": "votou", "note": "passado regular"}, {"word": "acknowledged", "meaning": "reconheceu", "note": "passado regular"}, {"word": "spent", "meaning": "passou/gastou", "note": "passado irregular"}, {"word": "had", "meaning": "tinha/teve", "note": "passado irregular"}, {"word": "did", "meaning": "fez", "note": "passado irregular"}, {"word": "said", "meaning": "disse", "note": "passado irregular"}, {"word": "cast", "meaning": "lançou/deu (voto)", "note": "passado irregular"}], "grammar_words": {"cognates": [], "tobe": ["were"], "irregular": ["cast", "said", "spent", "had"], "phrasal": ["stopped short of"], "wh": ["whether"], "connectors": ["despite", "though", "but", "rather than", "given"], "comparative": ["stricter", "increasingly severe"]}, "exercises": {"grammar": [{"point": "Voz passiva em contexto jornalístico", "explanation_pt": "'a finding the developer's own consultants had reportedly downplayed' usa a voz passiva/reportada, comum em notícias para atribuir informação sem confirmar diretamente."}, {"point": "Cláusulas concessivas com 'despite' e 'though'", "explanation_pt": "'despite mounting opposition' e 'though several cautioned' introduzem ideias contrastantes dentro da mesma frase."}], "multiple_choice": [{"question": "What did the city council decide on Tuesday?", "options": ["To withdraw approval for the development", "To approve the development", "To postpone the vote", "To fund the development further"], "correct_index": 0, "explanation": "O conselho votou para retirar a aprovação do empreendimento."}, {"question": "What prompted the reversal of the earlier decision?", "options": ["A public protest", "An independent hydrological survey on flood risk", "A change in city leadership", "A lawsuit"], "correct_index": 1, "explanation": "Um estudo hidrológico independente indicou risco elevado de enchentes."}, {"question": "What did Councilwoman Deshmukh acknowledge?", "options": ["She had never supported the project", "She wanted to resign", "She had relied too heavily on the developer's assurances", "She disagreed with the reversal"], "correct_index": 2, "explanation": "Ela reconheceu ter confiado demais nas garantias da construtora."}, {"question": "How did Meridian Property Group respond to the decision?", "options": ["They immediately filed a lawsuit", "They agreed with the council fully", "They withdrew from the city entirely", "They expressed disappointment but did not confirm legal action"], "correct_index": 3, "explanation": "Expressaram decepção, mas não confirmaram ação judicial."}, {"question": "What did the council ask city planners to do?", "options": ["Draft updated floodplain guidelines within ninety days", "Cancel all future developments", "Approve a new developer", "Reduce the building height only"], "correct_index": 0, "explanation": "Pediram diretrizes atualizadas para a planície de inundação em noventa dias."}], "open_questions": [{"question": "Why might independent studies be important before approving large development projects?", "key_points_pt": ["discutir a importância de avaliações imparciais", "citar o exemplo do estudo hidrológico"]}, {"question": "Do you think the council's apology was sufficient given how long the process took? Why or why not?", "key_points_pt": ["dar opinião justificada", "considerar o impacto sobre os moradores durante o período de espera"]}]}}, {"level": "C2", "genre": "neutral", "title": "The Weight of Silence", "paragraphs": ["Eleanor had spent thirty-one years restoring manuscripts, and she still marveled at how a single water stain could obliterate a sentence someone had labored over for hours. The letter before her, brittle and the color of weak tea, belonged to a merchant who had written to his estranged daughter in 1863, pleading for reconciliation he would never receive. She worked with tweezers and a magnifying lens, coaxing the fibers back into alignment, as though patience alone could undo the decades of neglect that had nearly reduced the page to dust.", "What struck her most, after all this time, was not the content of such letters but their futility. The merchant had died within the year, and the daughter, according to the archive's notes, never opened the envelope at all; it had been found sealed among her belongings, its wax seal unbroken. Eleanor wondered whether the woman had recognized the handwriting and simply refused to relive an old wound, or whether grief had rendered the letter irrelevant long before it arrived. Either way, the silence between them had outlasted both correspondents.", "She thought of her own sister, from whom she had been estranged for nearly a decade over a dispute so trivial that she could no longer reconstruct its origins with any confidence. Pride, she supposed, was a peculiarly durable substance, more resistant to erosion than the paper fibers she spent her days repairing. It occurred to her, not for the first time, that she was devoting her career to preserving the remnants of other people's unfinished conversations while conspicuously neglecting her own.", "That evening, rather than driving straight home, Eleanor stopped at a stationer's shop and bought a single sheet of cream-colored paper, the kind she would never have used on an actual restoration. She sat at her kitchen table for a long while before writing anything, acutely aware of the irony of her hesitation. Eventually she wrote only a few lines, nothing elaborate, an invitation rather than an apology, and sealed the envelope before she could talk herself out of sending it.", "Whether her sister would open it immediately, delay for years, or leave it sealed forever, as the merchant's daughter had done, was entirely beyond her control. Eleanor understood this now with a clarity that her profession had quietly taught her: preservation was never a guarantee of resolution, only of possibility. She dropped the letter into the mailbox on the corner and walked home slowly, feeling, for the first time in a long while, that she had done something irrevocable and necessary."], "paragraphs_pt": ["Eleanor havia passado trinta e um anos restaurando manuscritos, e ainda se maravilhava com o modo como uma simples mancha de água podia obliterar uma frase em que alguém trabalhara arduamente por horas. A carta diante dela, quebradiça e da cor de chá fraco, pertencia a um comerciante que escrevera à filha, de quem estava afastado, em 1863, implorando por uma reconciliação que jamais receberia. Ela trabalhava com pinças e uma lente de aumento, realinhando as fibras do papel, como se apenas a paciência pudesse desfazer as décadas de descaso que quase haviam reduzido a página a pó.", "O que mais a impressionava, depois de tanto tempo, não era o conteúdo dessas cartas, mas a sua inutilidade. O comerciante morrera dentro daquele mesmo ano, e a filha, segundo as anotações do arquivo, nunca chegara a abrir o envelope; ele fora encontrado lacrado entre seus pertences, o selo de cera intacto. Eleanor se perguntava se a mulher reconhecera a caligrafia e simplesmente se recusara a reviver uma velha ferida, ou se o luto tornara a carta irrelevante muito antes de ela chegar. De qualquer forma, o silêncio entre os dois havia sobrevivido a ambos os correspondentes.", "Ela pensou na própria irmã, de quem estava afastada havia quase uma década por uma discussão tão trivial que já não conseguia reconstruir sua origem com confiança. O orgulho, ela supunha, era uma substância peculiarmente duradoura, mais resistente à erosão do que as fibras de papel que ela passava os dias consertando. Ocorreu-lhe, não pela primeira vez, que dedicava a carreira a preservar os vestígios de conversas alheias inacabadas enquanto negligenciava, de forma flagrante, a sua própria.", "Naquela noite, em vez de ir direto para casa, Eleanor parou numa papelaria e comprou uma única folha de papel cor de creme, do tipo que jamais usaria numa restauração de verdade. Sentou-se à mesa da cozinha por um bom tempo antes de escrever qualquer coisa, plenamente consciente da ironia de sua hesitação. Por fim, escreveu apenas algumas linhas, nada elaborado, um convite em vez de um pedido de desculpas, e lacrou o envelope antes que pudesse se convencer a não enviá-lo.", "Se a irmã abriria a carta imediatamente, adiaria por anos, ou a deixaria lacrada para sempre, como fizera a filha do comerciante, estava inteiramente fora de seu controle. Eleanor compreendia isso agora com uma clareza que sua profissão lhe ensinara silenciosamente: a preservação nunca era garantia de resolução, apenas de possibilidade. Ela deixou a carta na caixa de correio da esquina e voltou para casa devagar, sentindo, pela primeira vez em muito tempo, que havia feito algo irrevogável e necessário."], "hard_words": ["obliterate", "estranged", "futility", "reconciliation", "erosion", "irrevocable"], "vocab": [{"word": "brittle", "meaning": "quebradiço, frágil", "note": "usado para papel, ossos, materiais que quebram facilmente"}, {"word": "estranged", "meaning": "afastado, distanciado (de um familiar)", "note": ""}, {"word": "futility", "meaning": "inutilidade, futilidade (no sentido de ser em vão)", "note": "falso cognato parcial: não é 'futilidade' frívola"}, {"word": "coax", "meaning": "persuadir suavemente, manejar com cuidado", "note": ""}, {"word": "outlast", "meaning": "durar mais que, sobreviver a", "note": ""}, {"word": "erosion", "meaning": "erosão, desgaste gradual", "note": ""}, {"word": "irrevocable", "meaning": "irrevogável", "note": ""}, {"word": "reconciliation", "meaning": "reconciliação", "note": ""}], "word_meanings": [{"word": "obliterate", "meaning": "obliterar, apagar completamente", "note": ""}, {"word": "estranged", "meaning": "afastado, distanciado (de um familiar)", "note": ""}, {"word": "futility", "meaning": "inutilidade", "note": ""}, {"word": "reconciliation", "meaning": "reconciliação", "note": ""}, {"word": "erosion", "meaning": "erosão, desgaste gradual", "note": ""}, {"word": "irrevocable", "meaning": "irrevogável", "note": ""}, {"word": "actually", "meaning": "na verdade", "note": "falso amigo: não é 'atualmente'"}, {"word": "eventually", "meaning": "finalmente, por fim", "note": "falso amigo: não é 'eventualmente'"}, {"word": "was", "meaning": "era/estava (passado de 'to be')", "note": ""}, {"word": "were", "meaning": "eram/estavam (passado de 'to be')", "note": ""}, {"word": "worked", "meaning": "trabalhou", "note": ""}, {"word": "belonged", "meaning": "pertenceu", "note": ""}, {"word": "wrote", "meaning": "escreveu", "note": "passado irregular de write"}, {"word": "found", "meaning": "encontrado/encontrou", "note": "passado irregular de find"}, {"word": "talk herself out of", "meaning": "convencer-se a não fazer algo", "note": ""}, {"word": "who", "meaning": "quem/que", "note": ""}, {"word": "whom", "meaning": "quem (objeto)", "note": ""}, {"word": "whether", "meaning": "se (indicando dúvida)", "note": ""}, {"word": "rather than", "meaning": "em vez de", "note": ""}], "grammar_words": {"cognates": ["eventually"], "tobe": ["was"], "irregular": ["worked", "belonged", "wrote", "found"], "phrasal": ["talk herself out of"], "wh": ["who", "whom", "whether"], "connectors": ["rather than"], "comparative": []}, "exercises": {"grammar": [{"point": "Past perfect", "explanation_pt": "Usa-se o past perfect (had + particípio) para indicar uma ação anterior a outra no passado, como em 'the daughter... never opened the envelope' e 'it had been found sealed', mostrando que o lacre já existia antes da descoberta."}], "multiple_choice": [{"question": "What did the merchant write to his daughter?", "options": ["A letter pleading for reconciliation", "A business proposal", "An invitation to a wedding", "A complaint"], "correct_index": 0, "explanation": "O texto diz que ele escreveu 'pleading for reconciliation'."}, {"question": "What happened to the merchant's letter?", "options": ["It was answered", "It was never opened", "It was destroyed", "It was lost in the mail"], "correct_index": 1, "explanation": "A carta foi encontrada lacrada, nunca aberta."}, {"question": "Why is Eleanor estranged from her sister?", "options": ["A serious betrayal", "Money problems", "A trivial dispute she barely remembers", "A disagreement about work"], "correct_index": 2, "explanation": "O texto descreve a disputa como trivial e quase esquecida."}, {"question": "What does Eleanor do at the end of the story?", "options": ["She calls her sister", "She visits the archive again", "She ignores her feelings", "She writes and sends a letter to her sister"], "correct_index": 3, "explanation": "Ela escreve poucas linhas e envia a carta pelo correio."}, {"question": "What is Eleanor's profession?", "options": ["Historian", "Manuscript restorer", "Postal worker", "Novelist"], "correct_index": 1, "explanation": "Ela restaura manuscritos há 31 anos."}], "open_questions": [{"question": "Why do you think the merchant's daughter never opened the letter?", "key_points_pt": ["Pode ter reconhecido a caligrafia e evitado reviver a dor", "O luto pode ter tornado a carta irrelevante"]}, {"question": "Do you think Eleanor's decision to send the letter was brave? Why or why not?", "key_points_pt": ["Envolve vulnerabilidade e risco de rejeição", "Ela age apesar da incerteza sobre o resultado"]}]}}, {"level": "C2", "genre": "humor", "title": "A Masterclass in Overconfidence", "paragraphs": ["Dennis had never assembled furniture in his life, yet he approached the flat-pack wardrobe with the swagger of a man who had built cathedrals. He tossed the instruction booklet aside almost contemptuously, muttering something about how pictograms were for people who lacked spatial intuition, and began sorting the screws into piles based on a classification system comprehensible only to himself. His girlfriend, Priya, watched from the doorway with the resigned expression of someone who had witnessed this particular brand of self-sabotage before.", "Forty minutes in, the wardrobe bore an unsettling resemblance to a Cubist interpretation of a wardrobe rather than an actual one. One door hung at an angle that suggested it had opinions of its own, and a shelf, inexplicably, protruded from the side panel like a diving board. Dennis, undeterred, declared that this was simply 'an alternative configuration' and that the manufacturers had clearly underestimated the market for asymmetry. Priya offered, not for the first time, to retrieve the instructions from the recycling bin, and was again politely rebuffed.", "The turning point arrived when Dennis, attempting to lever the crooked door into submission with a butter knife, sent the entire structure listing sideways with a groan that seemed almost sentient. He leapt backward with a yelp that startled the cat, who had been observing the proceedings from a safe distance with what could only be described as professional interest. The wardrobe settled into a diagonal repose against the wall, magnificently, irreparably wrong, and Dennis stood surveying the wreckage with the crestfallen dignity of a general accepting defeat.", "Priya, mercifully, resisted the urge to say 'I told you so' aloud, though her eyebrows communicated the sentiment with considerable eloquence. She retrieved the instruction booklet, smoothed its slightly damp pages, and sat down cross-legged beside the ruins, patting the floor beside her. Dennis, deflated but not entirely without humor, admitted that perhaps pictograms existed for a reason, possibly several reasons, and possibly all of them applied to him specifically.", "It took the two of them barely twenty minutes, working from the actual diagrams, to disassemble Dennis's improvised masterpiece and rebuild it correctly. The finished wardrobe stood perfectly upright, doors aligned, shelf exactly where the manufacturer had intended, and thoroughly, infuriatingly unremarkable. Dennis regarded it for a long moment before conceding, with the air of a man making a great personal sacrifice, that competence was occasionally underrated."], "paragraphs_pt": ["Dennis nunca havia montado móvel algum na vida, mas se aproximou do guarda-roupa desmontável com a arrogância de quem já havia construído catedrais. Jogou o manual de instruções de lado, quase com desprezo, resmungando algo sobre como pictogramas eram para pessoas sem intuição espacial, e começou a separar os parafusos em pilhas segundo um sistema de classificação compreensível apenas para ele mesmo. A namorada, Priya, observava da porta com a expressão resignada de quem já havia testemunhado esse tipo específico de autossabotagem antes.", "Quarenta minutos depois, o guarda-roupa apresentava uma semelhança inquietante com uma interpretação cubista de um guarda-roupa, em vez de um de verdade. Uma porta pendia em um ângulo que sugeria ter opiniões próprias, e uma prateleira, inexplicavelmente, projetava-se do painel lateral como um trampolim. Dennis, impassível, declarou que aquilo era simplesmente 'uma configuração alternativa' e que os fabricantes claramente haviam subestimado o mercado para a assimetria. Priya se ofereceu, não pela primeira vez, para resgatar as instruções da lixeira de reciclagem, e foi mais uma vez gentilmente recusada.", "O ponto de virada chegou quando Dennis, tentando alavancar a porta torta com uma faca de manteiga, fez toda a estrutura inclinar-se para o lado com um gemido quase senciente. Ele saltou para trás com um grito que assustou o gato, que vinha observando o processo a uma distância segura com o que só poderia ser descrito como interesse profissional. O guarda-roupa se acomodou numa posição diagonal contra a parede, magnificamente e irreparavelmente errado, e Dennis ficou contemplando os destroços com a dignidade abatida de um general aceitando a derrota.", "Priya, misericordiosamente, resistiu ao impulso de dizer 'eu te avisei' em voz alta, embora suas sobrancelhas comunicassem o sentimento com considerável eloquência. Ela pegou o manual de instruções, alisou as páginas ligeiramente úmidas, e sentou-se de pernas cruzadas ao lado das ruínas, batendo de leve no chão ao seu lado. Dennis, desanimado mas não totalmente sem senso de humor, admitiu que talvez pictogramas existissem por um motivo, possivelmente vários motivos, e possivelmente todos se aplicassem especificamente a ele.", "Levou pouco menos de vinte minutos, trabalhando com os diagramas reais, para os dois desmontarem a obra-prima improvisada de Dennis e reconstruí-la corretamente. O guarda-roupa pronto ficou perfeitamente reto, as portas alinhadas, a prateleira exatamente onde o fabricante havia planejado, e completa, irritantemente comum. Dennis o contemplou por um longo momento antes de admitir, com o ar de quem faz um grande sacrifício pessoal, que competência era, ocasionalmente, subestimada."], "hard_words": ["swagger", "contemptuously", "asymmetry", "undeterred", "rebuffed", "crestfallen"], "vocab": [{"word": "flat-pack", "meaning": "móvel desmontável, vendido em caixa plana", "note": ""}, {"word": "swagger", "meaning": "andar/atitude arrogante e confiante", "note": ""}, {"word": "undeterred", "meaning": "sem se deixar dissuadir", "note": ""}, {"word": "rebuffed", "meaning": "recusado, rejeitado", "note": ""}, {"word": "crestfallen", "meaning": "abatido, desanimado", "note": ""}, {"word": "listing sideways", "meaning": "inclinando-se para o lado", "note": "termo náutico usado figurativamente"}, {"word": "underrated", "meaning": "subestimado", "note": ""}, {"word": "deflated", "meaning": "desanimado, murcho (fig.)", "note": ""}], "word_meanings": [{"word": "swagger", "meaning": "andar/atitude arrogante e confiante", "note": ""}, {"word": "contemptuously", "meaning": "com desprezo", "note": ""}, {"word": "asymmetry", "meaning": "assimetria", "note": ""}, {"word": "undeterred", "meaning": "sem se deixar dissuadir", "note": ""}, {"word": "rebuffed", "meaning": "recusado, rejeitado", "note": ""}, {"word": "crestfallen", "meaning": "abatido, desanimado", "note": ""}, {"word": "actually", "meaning": "na verdade", "note": "falso amigo"}, {"word": "eventually", "meaning": "finalmente", "note": "falso amigo"}, {"word": "was", "meaning": "era/estava", "note": ""}, {"word": "were", "meaning": "eram/estavam", "note": ""}, {"word": "tossed", "meaning": "jogou", "note": ""}, {"word": "began", "meaning": "começou", "note": "passado irregular de begin"}, {"word": "sent", "meaning": "enviou/fez (aqui: causou)", "note": "passado irregular de send"}, {"word": "leapt", "meaning": "saltou", "note": "passado irregular de leap"}, {"word": "stood", "meaning": "ficou de pé", "note": "passado irregular de stand"}, {"word": "took", "meaning": "levou/tomou", "note": "passado irregular de take"}, {"word": "told", "meaning": "disse/contou", "note": "passado irregular de tell"}, {"word": "gave up", "meaning": "desistiu", "note": "conceito relacionado (não está no texto literalmente, usado como referência)"}, {"word": "leveled off", "meaning": "estabilizou", "note": ""}, {"word": "however", "meaning": "porém, no entanto", "note": ""}, {"word": "though", "meaning": "embora", "note": ""}], "grammar_words": {"cognates": [], "tobe": ["was", "were"], "irregular": ["tossed", "began", "sent", "leapt", "stood", "took", "told"], "phrasal": [], "wh": [], "connectors": ["though"], "comparative": []}, "exercises": {"grammar": [{"point": "Past continuous vs simple past", "explanation_pt": "O past continuous descreve uma ação em progresso interrompida por outra no simple past, como em 'the cat, who had been observing the proceedings' (ação contínua) versus 'Dennis leapt backward' (ação pontual)."}], "multiple_choice": [{"question": "What did Dennis do with the instruction booklet at first?", "options": ["He read it carefully", "He tossed it aside", "He gave it to Priya", "He memorized it"], "correct_index": 1, "explanation": "Ele jogou o manual de lado com desprezo."}, {"question": "What was wrong with the wardrobe after forty minutes?", "options": ["A door hung crooked and a shelf stuck out", "It was perfect", "It was too small", "It had missing screws"], "correct_index": 0, "explanation": "A porta estava torta e a prateleira se projetava para fora."}, {"question": "What caused the wardrobe to collapse sideways?", "options": ["A strong wind", "The cat jumped on it", "Priya pushed it", "Dennis using a butter knife on the door"], "correct_index": 3, "explanation": "Ele tentou forçar a porta com uma faca de manteiga."}, {"question": "How did Priya react to the disaster?", "options": ["She yelled at Dennis", "She left the room", "She calmly got the instructions and sat down to fix it", "She called a professional"], "correct_index": 2, "explanation": "Ela pegou o manual e sentou-se para consertar com calma."}, {"question": "What did Dennis finally admit at the end?", "options": ["That competence is occasionally underrated", "That Priya was better at everything", "That the wardrobe was defective", "That he needed a new cat"], "correct_index": 0, "explanation": "Ele admite que competência é, às vezes, subestimada."}], "open_questions": [{"question": "Why do you think Dennis refused to use the instructions at first?", "key_points_pt": ["Excesso de autoconfiança", "Orgulho de não parecer incompetente"]}, {"question": "Have you ever tried to do something without instructions and failed? What happened?", "key_points_pt": ["Resposta pessoal livre", "Pode mencionar consequências e aprendizado"]}]}}, {"level": "C2", "genre": "suspense", "title": "The 11:47 to Ashgrove", "paragraphs": ["The carriage was nearly empty when the man sat down across the aisle from Marta, close enough that she could hear the faint rustle of his coat but not so close as to seem overtly threatening, which she found, on reflection, more unsettling than if he had. He said nothing, offered no apologetic nod for choosing a seat when so many others stood vacant, and simply stared at the window as though the darkened glass held something worth studying. Marta returned to her book, or pretended to, her eyes tracking the same paragraph without absorbing a single word of it.", "At the second stop, nobody boarded, and nobody left. The man's reflection in the window, she noticed, was watching her rather than the scenery, a discrepancy so faint she might have imagined it, except that she hadn't, and some animal part of her brain insisted on the distinction. She shifted her bag onto her lap, a movement she told herself was mere comfort, though she was quietly calculating the distance to the emergency cord and rehearsing, with mounting absurdity, what she would actually say if she pulled it and nothing was wrong.", "Between the third and fourth stops, the lights flickered, dimmed, and the train slowed without the customary announcement. In the sudden near-darkness, she heard him shift in his seat, and every rational explanation she had constructed evaporated at once. Her hand found the cord before conscious thought caught up with instinct, and she pulled it just as the lights stuttered back on, flooding the carriage with an ordinary, faintly embarrassing brightness.", "The train halted with a lurch that sent a paperback sliding off an empty seat, and a conductor appeared almost immediately, visibly unimpressed, demanding to know who had triggered the alarm. Marta, mortified, began to explain, then stopped, because the man across the aisle was no longer merely watching the window; he was pointing, urgently, wordlessly, at something beneath his own seat, a small case with wires just visible through a gap in the fabric.", "It transpired, in the chaos of evacuation and the arrival of a bomb disposal unit some forty minutes later, that the device had been inert, a hoax left by someone the police would spend weeks trying to identify, but Marta never learned to distinguish, afterward, between the two versions of that night: the one in which her instincts had saved a carriage full of strangers, and the one in which she had simply panicked over a man who, in the end, had been trying to warn her the entire time."], "paragraphs_pt": ["O vagão estava quase vazio quando o homem se sentou do outro lado do corredor, perto o suficiente de Marta para que ela ouvisse o leve farfalhar de seu casaco, mas não tão perto a ponto de parecer abertamente ameaçador, o que ela achou, pensando bem, ainda mais perturbador do que se tivesse sido. Ele não disse nada, não fez nenhum aceno de desculpa por escolher aquele assento quando tantos outros estavam vazios, e simplesmente fitou a janela como se o vidro escurecido guardasse algo digno de estudo. Marta voltou ao livro, ou fingiu voltar, os olhos percorrendo o mesmo parágrafo sem absorver uma única palavra.", "Na segunda parada, ninguém embarcou e ninguém desceu. O reflexo do homem na janela, ela notou, a observava em vez de observar a paisagem, uma discrepância tão sutil que ela poderia tê-la imaginado, exceto que não imaginara, e alguma parte animal do seu cérebro insistia na distinção. Ela ajeitou a bolsa no colo, um movimento que dizia a si mesma ser mero conforto, embora estivesse calculando silenciosamente a distância até o cordão de emergência e ensaiando, com crescente absurdo, o que diria de fato se o puxasse e nada estivesse errado.", "Entre a terceira e a quarta parada, as luzes piscaram, escureceram, e o trem desacelerou sem o costumeiro anúncio. Na súbita quase escuridão, ela o ouviu se mexer no assento, e toda explicação racional que havia construído se evaporou de uma vez. Sua mão encontrou o cordão antes que o pensamento consciente alcançasse o instinto, e ela o puxou bem quando as luzes voltaram a piscar e se firmaram, inundando o vagão com uma claridade comum, levemente constrangedora.", "O trem parou com um solavanco que fez um livro de bolso deslizar de um assento vazio, e um fiscal apareceu quase imediatamente, visivelmente contrariado, exigindo saber quem havia acionado o alarme. Marta, mortificada, começou a explicar, então parou, porque o homem do outro lado do corredor já não apenas observava a janela; ele apontava, com urgência, sem palavras, para algo sob o próprio assento, uma pequena maleta com fios visíveis por uma fresta no tecido.", "Veio à tona, no caos da evacuação e na chegada de uma unidade de desativação de bombas cerca de quarenta minutos depois, que o dispositivo era inerte, um trote deixado por alguém que a polícia levaria semanas para tentar identificar, mas Marta nunca conseguiu, depois daquilo, distinguir entre as duas versões daquela noite: aquela em que seus instintos haviam salvado um vagão cheio de estranhos, e aquela em que ela simplesmente entrara em pânico por causa de um homem que, no fim, estivera o tempo todo tentando avisá-la."], "hard_words": ["discrepancy", "mortified", "transpired", "inert", "hoax", "lurch"], "vocab": [{"word": "rustle", "meaning": "farfalhar, som suave de tecido/papel", "note": ""}, {"word": "discrepancy", "meaning": "discrepância, inconsistência", "note": ""}, {"word": "mortified", "meaning": "extremamente envergonhado", "note": ""}, {"word": "transpired", "meaning": "veio à tona, revelou-se (que)", "note": ""}, {"word": "inert", "meaning": "inerte, inativo", "note": ""}, {"word": "hoax", "meaning": "trote, farsa", "note": ""}, {"word": "lurch", "meaning": "solavanco, movimento brusco", "note": ""}, {"word": "flicker", "meaning": "piscar, tremeluzir (luz)", "note": ""}], "word_meanings": [{"word": "discrepancy", "meaning": "discrepância", "note": ""}, {"word": "mortified", "meaning": "extremamente envergonhado", "note": ""}, {"word": "transpired", "meaning": "veio à tona, revelou-se", "note": ""}, {"word": "inert", "meaning": "inerte", "note": ""}, {"word": "hoax", "meaning": "trote, farsa", "note": ""}, {"word": "lurch", "meaning": "solavanco", "note": ""}, {"word": "actually", "meaning": "na verdade", "note": "falso amigo"}, {"word": "eventually", "meaning": "finalmente", "note": "não usado literalmente aqui mas incluído por padrão de lista"}, {"word": "was", "meaning": "era/estava", "note": ""}, {"word": "were", "meaning": "eram/estavam", "note": ""}, {"word": "sat", "meaning": "sentou", "note": "passado irregular de sit"}, {"word": "said", "meaning": "disse", "note": "passado irregular de say"}, {"word": "heard", "meaning": "ouviu", "note": "passado irregular de hear"}, {"word": "found", "meaning": "encontrou", "note": "passado irregular de find"}, {"word": "pulled", "meaning": "puxou", "note": ""}, {"word": "appeared", "meaning": "apareceu", "note": ""}, {"word": "caught up with", "meaning": "alcançou, colocou-se em dia com", "note": ""}, {"word": "though", "meaning": "embora", "note": ""}, {"word": "except that", "meaning": "exceto que", "note": ""}], "grammar_words": {"cognates": ["actually"], "tobe": ["was"], "irregular": ["sat", "said", "heard", "found", "pulled", "appeared"], "phrasal": ["caught up with"], "wh": [], "connectors": ["though", "except that"], "comparative": []}, "exercises": {"grammar": [{"point": "Past perfect for background events", "explanation_pt": "O past perfect ('had constructed', 'had saved') é usado para eventos anteriores a outro ponto do passado, criando camadas temporais, como em 'every rational explanation she had constructed evaporated at once'."}], "multiple_choice": [{"question": "Where did the man sit in relation to Marta?", "options": ["Right next to her", "Behind her", "Across the aisle", "In another carriage"], "correct_index": 2, "explanation": "Ele se sentou do outro lado do corredor."}, {"question": "What made Marta suspicious of the man?", "options": ["He spoke to her rudely", "He took her bag", "He was shouting", "His reflection seemed to be watching her"], "correct_index": 3, "explanation": "O reflexo dele na janela parecia observá-la."}, {"question": "What did Marta do when the lights flickered and the train slowed?", "options": ["She pulled the emergency cord", "She fell asleep", "She called the police", "She moved to another seat"], "correct_index": 0, "explanation": "Ela puxou o cordão de emergência."}, {"question": "What was the man actually pointing at?", "options": ["A lost phone", "A suspicious case under his own seat", "The conductor", "The window"], "correct_index": 1, "explanation": "Ele apontava para uma maleta com fios sob seu assento."}, {"question": "What turned out to be true about the device?", "options": ["It was a real bomb", "It was never found", "It belonged to Marta", "It was inert, a hoax"], "correct_index": 3, "explanation": "O dispositivo era inerte, um trote."}], "open_questions": [{"question": "Do you think Marta's instincts were right to be suspicious, even though the device was a hoax?", "key_points_pt": ["A intuição pode ser válida mesmo sem confirmação posterior", "Segurança pessoal justifica cautela"]}, {"question": "How do you think the story would have been different if the man had spoken to Marta earlier?", "key_points_pt": ["Poderia ter evitado o mal-entendido", "Mudaria a tensão e o suspense da narrativa"]}]}}, {"level": "C2", "genre": "detective", "title": "The Vanishing Violinist", "paragraphs": ["Inspector Halloway had interrogated liars of every conceivable variety, but the orchestra's principal cellist, Mr. Arnaud, possessed a particular species of composure that struck him as almost professionally rehearsed. The missing violinist, Elise Renard, had disappeared after the gala rehearsal, leaving behind an empty case, a half-finished glass of wine, and no discernible sign of struggle, which was, in Halloway's considerable experience, more suspicious than chaos would have been. Arnaud claimed he had left the concert hall before anyone else, a claim the ledger at the stage door flatly contradicted.", "The theater itself yielded little; its acoustics, ironically, made it nearly impossible to determine who had been where, since sound traveled in ways that confounded every witness's account of footsteps and voices. Halloway found himself instead scrutinizing the mundane: a torn concert program, a receipt for two coffees when only one musician admitted to buying anything, and a peculiar burn mark on the conductor's podium that nobody could adequately explain. He had learned, over two decades of investigation, that the truth rarely announced itself; it accumulated, almost imperceptibly, in the discrepancies people assumed were too trivial to matter.", "It was the receipt that eventually unraveled everything. The second coffee, purchased twenty minutes after Elise was last seen, had been bought by the conductor's assistant, a mild, unremarkable young man named Petrov who had, until that moment, barely registered as a suspect at all. Confronted, Petrov's composure fractured almost instantly, revealing not a murderer but a co-conspirator: Elise had staged her own disappearance to escape a controlling patron who had, unbeknownst to the rest of the orchestra, been financially coercing her into an engagement she despised.", "Halloway found her three days later, in a modest boarding house two towns over, rehearsing scales on a borrowed violin with an expression of relief so profound it was almost indistinguishable from grief. She had not anticipated, she admitted, quite how thoroughly her absence would be investigated, nor how readily suspicion would fall on colleagues who had done nothing more sinister than help her vanish. The patron, confronted with evidence of coercion rather than kidnapping, was quietly prosecuted for a lesser charge, and the case closed with the particular anticlimax that Halloway had come to associate with cases where nobody, in the end, had actually meant any harm.", "What lingered with him afterward was not the resolution itself but Arnaud's composure, which he eventually understood as simple loyalty rather than guilt; the cellist had known the truth from the beginning and had lied, convincingly, to protect a friend. Halloway closed the file with a grudging respect he rarely extended to people who had obstructed his investigation, reflecting that the most difficult cases were seldom the ones involving genuine villainy, but rather the ones where every party involved had been, in their own compromised way, trying to do right by someone else."], "paragraphs_pt": ["O inspetor Halloway já havia interrogado mentirosos de todo tipo concebível, mas o violoncelista principal da orquestra, o senhor Arnaud, possuía uma espécie particular de compostura que lhe pareceu quase ensaiada profissionalmente. A violinista desaparecida, Elise Renard, sumira após o ensaio da gala, deixando para trás um estojo vazio, uma taça de vinho pela metade e nenhum sinal perceptível de luta, o que, na considerável experiência de Halloway, era mais suspeito do que o caos teria sido. Arnaud afirmava ter deixado a sala de concertos antes de todos os outros, afirmação que o livro de registro da porta dos artistas contradizia categoricamente.", "O próprio teatro rendeu pouco; sua acústica, ironicamente, tornava quase impossível determinar quem estivera onde, já que o som viajava de maneiras que confundiam o relato de cada testemunha sobre passos e vozes. Halloway se viu, em vez disso, examinando o banal: um programa de concerto rasgado, um recibo de dois cafés quando apenas um músico admitira ter comprado algo, e uma marca de queimadura peculiar no pódio do regente que ninguém conseguia explicar adequadamente. Ele aprendera, em duas décadas de investigação, que a verdade raramente se anunciava; ela se acumulava, quase imperceptivelmente, nas discrepâncias que as pessoas presumiam ser triviais demais para importar.", "Foi o recibo que, por fim, desvendou tudo. O segundo café, comprado vinte minutos depois da última vez que Elise fora vista, havia sido comprado pelo assistente do regente, um jovem discreto e nada notável chamado Petrov que, até aquele momento, mal havia sido considerado suspeito. Confrontado, o autocontrole de Petrov se rompeu quase instantaneamente, revelando não um assassino, mas um cúmplice: Elise havia forjado o próprio desaparecimento para escapar de um patrono controlador que, sem que o resto da orquestra soubesse, vinha coagindo-a financeiramente a um noivado que ela detestava.", "Halloway a encontrou três dias depois, numa modesta pensão a duas cidades de distância, ensaiando escalas num violino emprestado com uma expressão de alívio tão profunda que era quase indistinguível de luto. Ela não havia previsto, admitiu, o quão minuciosamente sua ausência seria investigada, nem o quão prontamente a suspeita recairia sobre colegas que não haviam feito nada mais grave do que ajudá-la a sumir. O patrono, confrontado com evidências de coação em vez de sequestro, foi discretamente processado por uma acusação menor, e o caso se encerrou com o anticlímax particular que Halloway passara a associar a casos em que, no fim, ninguém de fato pretendera causar mal.", "O que permaneceu com ele depois não foi a resolução em si, mas a compostura de Arnaud, que ele finalmente entendeu como simples lealdade, e não culpa; o violoncelista sabia a verdade desde o início e mentira, de forma convincente, para proteger uma amiga. Halloway fechou o arquivo com um respeito relutante que raramente concedia a pessoas que haviam obstruído sua investigação, refletindo que os casos mais difíceis raramente eram os que envolviam vilania genuína, mas sim aqueles em que todas as partes envolvidas haviam, cada uma à sua maneira comprometida, tentado fazer o bem por outra pessoa."], "hard_words": ["composure", "discernible", "confounded", "unraveled", "unbeknownst", "anticlimax"], "vocab": [{"word": "composure", "meaning": "compostura, calma", "note": ""}, {"word": "discernible", "meaning": "perceptível, discernível", "note": ""}, {"word": "confounded", "meaning": "confundiu, desconcertou", "note": ""}, {"word": "unraveled", "meaning": "desvendou, desenrolou", "note": ""}, {"word": "unbeknownst", "meaning": "sem o conhecimento de", "note": "expressão formal/literária"}, {"word": "anticlimax", "meaning": "anticlímax", "note": ""}, {"word": "grudging", "meaning": "relutante, dado a contragosto", "note": ""}, {"word": "coercing", "meaning": "coagindo", "note": ""}], "word_meanings": [{"word": "composure", "meaning": "compostura, calma", "note": ""}, {"word": "discernible", "meaning": "perceptível", "note": ""}, {"word": "confounded", "meaning": "confundiu", "note": ""}, {"word": "unraveled", "meaning": "desvendou", "note": ""}, {"word": "unbeknownst", "meaning": "sem o conhecimento de", "note": ""}, {"word": "anticlimax", "meaning": "anticlímax", "note": ""}, {"word": "actually", "meaning": "na verdade", "note": "falso amigo"}, {"word": "eventually", "meaning": "finalmente", "note": "falso amigo"}, {"word": "was", "meaning": "era/estava", "note": ""}, {"word": "were", "meaning": "eram/estavam", "note": ""}, {"word": "found", "meaning": "encontrou", "note": "passado irregular de find"}, {"word": "left", "meaning": "deixou/saiu", "note": "passado irregular de leave"}, {"word": "bought", "meaning": "comprou", "note": "passado irregular de buy"}, {"word": "knew", "meaning": "sabia", "note": "passado irregular de know"}, {"word": "closed", "meaning": "fechou/encerrou", "note": ""}, {"word": "fell on", "meaning": "recaiu sobre", "note": "phrasal verb: fall on"}, {"word": "who", "meaning": "quem/que", "note": ""}, {"word": "which", "meaning": "que/o qual", "note": ""}, {"word": "rather than", "meaning": "em vez de", "note": ""}], "grammar_words": {"cognates": ["actually", "eventually"], "tobe": ["was", "were"], "irregular": ["found", "left", "bought", "closed"], "phrasal": [], "wh": ["who", "which"], "connectors": ["rather than"], "comparative": []}, "exercises": {"grammar": [{"point": "Reported/embedded clauses with 'that'", "explanation_pt": "Orações subordinadas iniciadas por 'that' relatam afirmações ou fatos, como em 'a claim the ledger... flatly contradicted' e 'He had learned... that the truth rarely announced itself', comuns em narrativas investigativas formais."}], "multiple_choice": [{"question": "What did Halloway find suspicious about the crime scene?", "options": ["Signs of a violent struggle", "A ransom note", "Broken windows", "The lack of any struggle"], "correct_index": 3, "explanation": "A ausência de sinais de luta era mais suspeita, segundo Halloway."}, {"question": "What clue eventually broke the case open?", "options": ["A torn program", "A burn mark", "A coffee receipt", "A witness statement"], "correct_index": 2, "explanation": "O recibo dos dois cafés levou à descoberta."}, {"question": "Why did Elise Renard disappear?", "options": ["She was kidnapped", "She staged it to escape a controlling patron", "She had amnesia", "She quit music"], "correct_index": 1, "explanation": "Ela forjou o desaparecimento para escapar da coação do patrono."}, {"question": "Why did Arnaud lie to Halloway?", "options": ["He was protecting Elise out of loyalty", "He was guilty of the crime", "He wanted money", "He hated the police"], "correct_index": 0, "explanation": "Ele mentiu por lealdade, para proteger a amiga."}, {"question": "What happened to the patron in the end?", "options": ["He was released with no charge", "He disappeared too", "He was prosecuted for a lesser charge", "He became the conductor"], "correct_index": 2, "explanation": "Ele foi processado por uma acusação menor de coação."}], "open_questions": [{"question": "Do you think Arnaud was right to lie to protect Elise? Why or why not?", "key_points_pt": ["Lealdade versus obstrução da justiça", "Depende da gravidade da mentira e da intenção"]}, {"question": "What does this story suggest about the nature of 'difficult' criminal cases?", "key_points_pt": ["Nem todo caso envolve vilania genuína", "Pessoas boas podem cometer erros tentando proteger outras"]}]}}, {"level": "C2", "genre": "romance", "title": "Letters to Nowhere in Particular", "paragraphs": ["For eleven months, Noah had been corresponding with someone he knew only as 'R,' an anonymous pen pal assigned to him through a literacy charity's letter-exchange program, and he had grown embarrassingly attached to a person whose handwriting he could recognize instantly but whose face remained a complete mystery. R wrote with a wit that consistently undercut its own melancholy, describing a job she disliked and a city she loved with equal, exasperated affection, and Noah found himself rereading her letters far more often than the program's coordinators presumably intended.", "He had considered, more than once, requesting her actual identity, a request the program discouraged but did not strictly forbid, yet something about the anonymity felt essential to whatever this correspondence had become. There was an honesty in writing to someone who couldn't yet judge you by your face or your circumstances, an intimacy that felt, paradoxically, easier to sustain precisely because it remained incomplete. He wondered, occasionally, whether R felt the same reluctance, or whether she simply hadn't considered him worth the trouble of unmasking.", "The charity's annual gathering, an event Noah had previously dismissed as an unnecessary formality, suddenly acquired an unbearable significance once he learned that pen pals were, this year, encouraged to attend and identify themselves if they wished. He spent an embarrassing amount of time deciding what to wear, second-guessing the decision entirely, and arriving twenty minutes late specifically so that he wouldn't be standing awkwardly alone when other people's reunions began.", "He recognized her before she recognized him, though he couldn't afterward explain how, given that he had no photograph and no description beyond his own imagination; something in the way she stood, slightly apart from the crowd, holding her drink like it was a prop rather than a beverage, matched some instinct he hadn't known he possessed. When he finally introduced himself, stammering through a joke he had rehearsed and immediately mangled, she laughed, the exact laugh he had imagined from her letters, and admitted she had spotted him twenty minutes earlier and had been too nervous to approach.", "They stayed at that gathering far longer than either had intended, talking with the specific ease of people who had already exchanged their most honest selves on paper and were now simply attaching faces and voices to something that had existed, quite thoroughly, before either of them arrived. Walking her to her train afterward, Noah realized that he no longer wanted to call her 'R'; he wanted her actual name, which she gave him, laughing, as though it were the most unnecessary formality in a friendship that had never really needed one."], "paragraphs_pt": ["Por onze meses, Noah trocara cartas com alguém que conhecia apenas como 'R', uma correspondente anônima designada a ele por um programa de troca de cartas de uma instituição de alfabetização, e ele havia se apegado, de forma embaraçosa, a uma pessoa cuja caligrafia reconhecia instantaneamente, mas cujo rosto permanecia um completo mistério. R escrevia com um humor que constantemente contrariava sua própria melancolia, descrevendo um emprego de que não gostava e uma cidade que amava com igual afeto, exasperado, e Noah se via relendo as cartas dela com muito mais frequência do que os coordenadores do programa presumivelmente pretendiam.", "Ele já havia considerado, mais de uma vez, pedir a identidade real dela, um pedido que o programa desencorajava, mas não proibia estritamente, mas algo no anonimato parecia essencial para o que aquela correspondência havia se tornado. Havia uma honestidade em escrever para alguém que ainda não podia julgá-lo pelo rosto ou pelas circunstâncias, uma intimidade que parecia, paradoxalmente, mais fácil de sustentar justamente por permanecer incompleta. Ele se perguntava, ocasionalmente, se R sentia a mesma relutância, ou se simplesmente não o considerava digno do trabalho de se revelar.", "O encontro anual da instituição, um evento que Noah antes considerava uma formalidade desnecessária, adquiriu de repente uma importância insuportável quando ele soube que, naquele ano, os correspondentes eram incentivados a comparecer e se identificar, se assim desejassem. Ele passou um tempo embaraçoso decidindo o que vestir, questionando totalmente a decisão, e chegou vinte minutos atrasado justamente para não ficar sozinho, sem jeito, enquanto os reencontros de outras pessoas aconteciam.", "Ele a reconheceu antes que ela o reconhecesse, embora não conseguisse explicar depois como, já que não tinha fotografia nem descrição além da própria imaginação; algo no jeito como ela ficava, ligeiramente afastada da multidão, segurando a bebida como se fosse um adereço em vez de uma bebida, correspondia a um instinto que ele nem sabia possuir. Quando finalmente se apresentou, gaguejando uma piada que havia ensaiado e imediatamente estragou, ela riu, exatamente a risada que ele havia imaginado a partir das cartas, e admitiu que o notara vinte minutos antes e estivera nervosa demais para se aproximar.", "Eles ficaram naquele encontro muito mais tempo do que qualquer um dos dois pretendia, conversando com a naturalidade específica de pessoas que já haviam trocado seus eus mais sinceros no papel e agora simplesmente atribuíam rostos e vozes a algo que já existia, bastante consolidado, antes mesmo de qualquer um dos dois chegar. Ao acompanhá-la até o trem depois, Noah percebeu que não queria mais chamá-la de 'R'; queria o nome verdadeiro dela, que ela lhe deu, rindo, como se fosse a formalidade mais desnecessária numa amizade que nunca havia precisado de uma."], "hard_words": ["undercut", "melancholy", "unmasking", "mangled", "stammering", "exasperated"], "vocab": [{"word": "undercut", "meaning": "contrariar, minar (sutilmente)", "note": ""}, {"word": "melancholy", "meaning": "melancolia", "note": ""}, {"word": "unmasking", "meaning": "desmascarar, revelar identidade", "note": ""}, {"word": "mangled", "meaning": "estragou, bagunçou (fig.)", "note": ""}, {"word": "stammering", "meaning": "gaguejando", "note": ""}, {"word": "exasperated", "meaning": "exasperado", "note": "falso amigo: não é 'exasperado' no sentido de raiva forte apenas, mas frustração intensa"}, {"word": "prop", "meaning": "adereço, objeto de cena", "note": ""}, {"word": "spotted", "meaning": "avistou, notou", "note": ""}], "word_meanings": [{"word": "undercut", "meaning": "contrariar, minar", "note": ""}, {"word": "melancholy", "meaning": "melancolia", "note": ""}, {"word": "unmasking", "meaning": "desmascarar", "note": ""}, {"word": "mangled", "meaning": "estragou", "note": ""}, {"word": "stammering", "meaning": "gaguejando", "note": ""}, {"word": "exasperated", "meaning": "exasperado, frustrado", "note": ""}, {"word": "actually", "meaning": "na verdade", "note": "falso amigo"}, {"word": "eventually", "meaning": "finalmente", "note": "não aparece literalmente, mas listado por padrão de cognato comum"}, {"word": "was", "meaning": "era/estava", "note": ""}, {"word": "were", "meaning": "eram/estavam", "note": ""}, {"word": "knew", "meaning": "sabia/conhecia", "note": "passado irregular de know"}, {"word": "grew", "meaning": "cresceu, tornou-se", "note": "passado irregular de grow"}, {"word": "gave", "meaning": "deu", "note": "passado irregular de give"}, {"word": "held", "meaning": "segurou", "note": "passado irregular de hold"}, {"word": "spotted", "meaning": "avistou", "note": ""}, {"word": "found himself", "meaning": "se via/se percebia", "note": "expressão idiomática"}, {"word": "though", "meaning": "embora", "note": ""}, {"word": "whether", "meaning": "se (dúvida)", "note": ""}], "grammar_words": {"cognates": [], "tobe": ["was", "were"], "irregular": ["knew", "gave", "spotted"], "phrasal": ["found himself"], "wh": ["whether"], "connectors": ["though"], "comparative": []}, "exercises": {"grammar": [{"point": "Cleft-like emphasis with 'It was... that'", "explanation_pt": "Estruturas como 'something about the anonymity felt essential' usam o sujeito abstrato para enfatizar uma ideia central, comum em prosa reflexiva sofisticada de nível C2."}], "multiple_choice": [{"question": "How did Noah and R first start communicating?", "options": ["Through a literacy charity's pen pal program", "Through social media", "At work", "At school"], "correct_index": 0, "explanation": "Eles se conheceram por meio de um programa de troca de cartas de uma instituição de alfabetização."}, {"question": "Why didn't Noah ask for R's identity earlier?", "options": ["It was strictly forbidden", "He wasn't interested", "The anonymity felt essential to their connection", "He forgot"], "correct_index": 2, "explanation": "O anonimato parecia essencial ao que a correspondência havia se tornado."}, {"question": "Why did Noah arrive twenty minutes late to the gathering?", "options": ["He got lost", "So he wouldn't stand alone during other reunions", "His train was delayed", "He changed his mind about going"], "correct_index": 1, "explanation": "Ele chegou atrasado de propósito para não ficar sozinho e sem jeito."}, {"question": "How did Noah recognize R at the event?", "options": ["She wore a name tag", "A friend pointed her out", "She called his name", "By an instinct about how she stood and held her drink"], "correct_index": 3, "explanation": "Algo no jeito dela ficar de pé correspondeu a um instinto que ele possuía."}, {"question": "What did Noah want at the end of the story?", "options": ["To know her real name", "To stop writing to her", "To leave without talking to her", "To join a different program"], "correct_index": 0, "explanation": "Ele percebeu que queria o nome verdadeiro dela."}], "open_questions": [{"question": "Why do you think anonymity made Noah and R's relationship feel more honest?", "key_points_pt": ["Sem julgamento baseado na aparência", "Foco no conteúdo emocional das cartas"]}, {"question": "Would you participate in an anonymous pen pal program? Why or why not?", "key_points_pt": ["Resposta pessoal livre", "Pode mencionar curiosidade, insegurança ou desejo de conexão genuína"]}]}}, {"level": "C2", "genre": "scifi", "title": "The Last Signal", "paragraphs": ["Commander Isolde Reyes had rehearsed this transmission a hundred times in her head, yet standing before the console with Earth's reply finally decrypting on the screen, every carefully composed sentence evaporated. The colony ship Meridian had drifted beyond reliable contact eleven years earlier, a consequence of a navigational error nobody had fully explained, and the crew had long since stopped expecting any response at all, treating their daily logs as messages to a future that might never read them. Now, impossibly, Earth was answering, though the delay meant the words on her screen had been sent before her own daughter was born.", "The message itself was maddeningly bureaucratic, a status update from a mission control staffed by people whose grandparents had likely written the original launch protocols, informing the Meridian that Earth's own situation had changed considerably and that reunion, should it ever occur, would happen on terms nobody aboard the ship had been trained to anticipate. Isolde read the technical appendices twice before the implication settled: the technology Earth now possessed made the Meridian's entire eleven-year voyage almost irrelevant, a slower, costlier path to a destination that faster ships had since reached and, in some cases, already begun to colonize.", "She gathered the crew in the observation deck rather than announcing it over the intercom, feeling that news capable of unmaking an entire mission's sense of purpose deserved to be delivered to faces rather than speakers. The reactions varied more than she expected: relief from those who had quietly dreaded the isolation for years, indignation from those who had built their identities around being first, and a peculiar, weary amusement from the ship's eldest engineer, who observed that humanity's compulsion to declare things obsolete the moment something newer existed was, if anything, reassuringly familiar.", "What the message did not resolve, and what occupied Isolde far more than questions of technological obsolescence, was what the Meridian's mission had actually meant if its practical purpose had already been superseded elsewhere. She found herself, over the following days, returning to the ship's accumulated logs, eleven years of small observations, minor disputes, births, one death, an entire community that had built something real regardless of whether anyone on Earth would ever consider it necessary.", "In her eventual reply, transmitted knowing it would not be received for over a decade, Isolde chose not to dwell on obsolescence at all. She wrote instead about the community the Meridian had become, the systems they had improvised, the children who had never known any world but the ship's corridors and considered them entirely ordinary, and closed by noting that a mission's worth was never really determined by whoever arrived first, but by what its people had managed to build along the way, a sentiment she suspected Earth's mission control, eleven years and several technological generations removed, might no longer be equipped to fully understand."], "paragraphs_pt": ["A comandante Isolde Reyes havia ensaiado aquela transmissão cem vezes na cabeça, mas, diante do console com a resposta da Terra finalmente sendo decodificada na tela, cada frase cuidadosamente composta se evaporou. A nave colonizadora Meridian havia se afastado de um contato confiável onze anos antes, consequência de um erro de navegação que ninguém explicara por completo, e a tripulação já havia deixado de esperar qualquer resposta, tratando seus registros diários como mensagens para um futuro que talvez nunca as lesse. Agora, incrivelmente, a Terra respondia, embora o atraso significasse que as palavras na tela haviam sido enviadas antes mesmo de sua própria filha nascer.", "A mensagem em si era irritantemente burocrática, uma atualização de status vinda de um controle de missão formado por pessoas cujos avós provavelmente haviam escrito os protocolos originais de lançamento, informando à Meridian que a situação da Terra havia mudado consideravelmente e que o reencontro, caso viesse a ocorrer, aconteceria em termos para os quais ninguém a bordo da nave fora treinado. Isolde leu os anexos técnicos duas vezes antes que a implicação se assentasse: a tecnologia que a Terra agora possuía tornava toda a viagem de onze anos da Meridian quase irrelevante, um caminho mais lento e mais caro até um destino que naves mais rápidas já haviam alcançado e, em alguns casos, já começado a colonizar.", "Ela reuniu a tripulação no convés de observação em vez de anunciar pelo interfone, sentindo que uma notícia capaz de desfazer o sentido de propósito de toda uma missão merecia ser entregue a rostos, e não a alto-falantes. As reações variaram mais do que ela esperava: alívio dos que temiam silenciosamente o isolamento havia anos, indignação dos que haviam construído suas identidades em torno de serem os primeiros, e uma diversão peculiar e cansada do engenheiro mais velho da nave, que observou que a compulsão da humanidade em declarar as coisas obsoletas assim que algo mais novo surgia era, na verdade, reconfortantemente familiar.", "O que a mensagem não resolvia, e o que ocupava Isolde muito mais do que questões de obsolescência tecnológica, era o que a missão da Meridian de fato havia significado, se seu propósito prático já fora superado em outro lugar. Ela se viu, nos dias seguintes, voltando aos registros acumulados da nave, onze anos de pequenas observações, disputas menores, nascimentos, uma morte, uma comunidade inteira que havia construído algo real, independentemente de alguém na Terra algum dia considerar isso necessário.", "Em sua resposta final, transmitida sabendo que não seria recebida por mais de uma década, Isolde optou por não se deter na obsolescência. Escreveu, em vez disso, sobre a comunidade em que a Meridian se tornara, os sistemas que haviam improvisado, as crianças que nunca conheceram outro mundo além dos corredores da nave e os consideravam inteiramente normais, e encerrou observando que o valor de uma missão nunca era realmente determinado por quem chegava primeiro, mas pelo que seu povo conseguira construir pelo caminho, um sentimento que ela suspeitava que o controle de missão da Terra, onze anos e várias gerações tecnológicas distante, talvez já não estivesse equipado para compreender plenamente."], "hard_words": ["decrypting", "obsolescence", "superseded", "indignation", "compulsion", "maddeningly"], "vocab": [{"word": "decrypting", "meaning": "decodificando, descriptografando", "note": ""}, {"word": "obsolescence", "meaning": "obsolescência", "note": ""}, {"word": "superseded", "meaning": "substituído, superado", "note": ""}, {"word": "indignation", "meaning": "indignação", "note": ""}, {"word": "compulsion", "meaning": "compulsão, impulso incontrolável", "note": ""}, {"word": "maddeningly", "meaning": "de forma enlouquecedora/irritante", "note": ""}, {"word": "dwell on", "meaning": "se deter em, insistir em (um assunto)", "note": ""}, {"word": "weary", "meaning": "cansado, fatigado", "note": ""}], "word_meanings": [{"word": "decrypting", "meaning": "decodificando", "note": ""}, {"word": "obsolescence", "meaning": "obsolescência", "note": ""}, {"word": "superseded", "meaning": "substituído, superado", "note": ""}, {"word": "indignation", "meaning": "indignação", "note": ""}, {"word": "compulsion", "meaning": "compulsão", "note": ""}, {"word": "maddeningly", "meaning": "de forma enlouquecedora", "note": ""}, {"word": "actually", "meaning": "na verdade", "note": "falso amigo"}, {"word": "eventually", "meaning": "finalmente", "note": "falso amigo"}, {"word": "was", "meaning": "era/estava", "note": ""}, {"word": "were", "meaning": "eram/estavam", "note": ""}, {"word": "read", "meaning": "leu", "note": "passado irregular de read (pronúncia muda)"}, {"word": "wrote", "meaning": "escreveu", "note": "passado irregular de write"}, {"word": "chose", "meaning": "escolheu", "note": "passado irregular de choose"}, {"word": "gathered", "meaning": "reuniu", "note": ""}, {"word": "dwell on", "meaning": "se deter em", "note": ""}, {"word": "should it ever occur", "meaning": "caso isso algum dia ocorresse", "note": "inversão condicional formal"}, {"word": "though", "meaning": "embora", "note": ""}, {"word": "regardless of whether", "meaning": "independentemente de", "note": ""}], "grammar_words": {"cognates": ["actually"], "tobe": ["was"], "irregular": ["read", "wrote", "chose", "gathered"], "phrasal": ["dwell on"], "wh": ["whether"], "connectors": ["though", "regardless of whether"], "comparative": []}, "exercises": {"grammar": [{"point": "Inverted conditionals (formal register)", "explanation_pt": "Em registros formais, condicionais podem ser invertidos sem 'if', como em 'should it ever occur' (= if it ever occurred), estrutura típica de textos técnicos ou institucionais em nível C2."}], "multiple_choice": [{"question": "Why had the Meridian lost contact with Earth?", "options": ["A navigational error", "A deliberate decision", "An attack", "Equipment theft"], "correct_index": 0, "explanation": "Foi consequência de um erro de navegação não totalmente explicado."}, {"question": "What did Earth's message reveal about technology?", "options": ["Earth had lost all technology", "Faster ships had already reached and colonized the destination", "The Meridian was the fastest ship ever built", "Earth no longer had space travel"], "correct_index": 1, "explanation": "Naves mais rápidas já haviam alcançado e colonizado o destino."}, {"question": "Where did Isolde choose to share the news with the crew?", "options": ["Over the intercom", "In a written memo", "In the observation deck, face to face", "She didn't tell them"], "correct_index": 2, "explanation": "Ela reuniu a tripulação pessoalmente no convés de observação."}, {"question": "How did the ship's eldest engineer react to the news?", "options": ["With anger", "With panic", "With complete indifference", "With weary amusement"], "correct_index": 3, "explanation": "Ele reagiu com uma diversão peculiar e cansada."}, {"question": "What did Isolde focus on in her final reply to Earth?", "options": ["Complaints about being forgotten", "The community and life the crew had built", "A request for rescue", "Technical specifications"], "correct_index": 1, "explanation": "Ela escreveu sobre a comunidade que a tripulação havia construído."}], "open_questions": [{"question": "Do you agree with Isolde that a mission's worth isn't determined by who arrives first? Why or why not?", "key_points_pt": ["Valor pode estar no processo, não apenas no resultado", "Comunidade e experiência humana como valores em si"]}, {"question": "How do you think the crew members who felt indignation might respond to Isolde's message?", "key_points_pt": ["Podem discordar e sentir que seu sacrifício foi em vão", "Podem eventualmente aceitar a perspectiva dela"]}]}}, {"level": "C2", "genre": "medieval", "title": "The Falconer's Oath", "paragraphs": ["Aldric had served the castle's mews for eleven years before the new steward arrived, a man whose contempt for falconry as a discipline was matched only by his conviction that the birds existed purely to impress visiting dignitaries. When the steward demanded that Sable, Aldric's finest gyrfalcon, be flown at a banquet despite a wing injury the bird had not yet fully recovered from, Aldric refused, quietly but unmistakably, an act of defiance that in lesser households might have earned him a flogging rather than a reprimand.", "The steward, unaccustomed to being contradicted by a man of Aldric's modest station, threatened to have the falconer dismissed and the bird sold to a merchant with less regard for her welfare. Aldric, weighing eleven years of devotion against the very real prospect of losing both his position and the creature he had raised from an eyas, chose instead to appeal directly to the baroness, a woman rumored to possess more sense than her steward and considerably less patience for cruelty conducted in her name.", "The baroness received him in the solar, listening without interruption as Aldric explained, with a bluntness that startled even himself, that a wounded bird forced to fly for spectacle would likely reinjure herself beyond recovery, and that no banquet was worth the loss of a falcon that had, on three separate occasions, brought down game that had fed half the castle through a lean winter. She asked a single question, whether he would stake his position on the truth of his assessment, and Aldric answered without hesitation that he would.", "The baroness overruled her steward that same evening, decreeing that Sable would remain in the mews until fully healed and that any future decisions regarding the hawks would require Aldric's counsel, a ruling the steward received with poorly disguised resentment but did not dare contest openly. Word of the exchange traveled through the household with the particular swiftness reserved for stories in which the powerful are seen to yield to the merely competent, and Aldric found himself regarded, for the first time in over a decade, as someone whose judgment carried genuine weight within those walls.", "Sable recovered fully within the month and, some weeks later, took a heron in a flight so precise that even the steward, watching from the battlements with an expression he clearly wished had gone unnoticed, permitted himself a single, grudging nod of approval. Aldric never learned whether the gesture constituted an apology, and he found, to his own mild surprise, that he no longer particularly needed it to."], "paragraphs_pt": ["Aldric servira na falcoaria do castelo por onze anos antes de o novo mordomo chegar, um homem cujo desprezo pela falcoaria como disciplina só era igualado por sua convicção de que as aves existiam unicamente para impressionar dignitários visitantes. Quando o mordomo exigiu que Sable, o melhor girifalte de Aldric, fosse posto para voar num banquete apesar de um ferimento na asa do qual a ave ainda não havia se recuperado por completo, Aldric se recusou, de forma discreta mas inconfundível, um ato de desafio que em casas menos tolerantes poderia lhe ter rendido açoites em vez de uma simples repreensão.", "O mordomo, pouco acostumado a ser contrariado por um homem da posição modesta de Aldric, ameaçou tê-lo demitido e a ave vendida a um mercador com menos consideração pelo bem-estar dela. Aldric, pesando onze anos de dedicação contra a possibilidade muito real de perder tanto seu posto quanto a criatura que criara desde filhote, optou em vez disso por apelar diretamente à baronesa, uma mulher que se dizia possuir mais bom senso que seu mordomo e consideravelmente menos paciência para crueldade praticada em seu nome.", "A baronesa o recebeu na sala de estar, ouvindo sem interromper enquanto Aldric explicava, com uma franqueza que surpreendeu até a ele mesmo, que uma ave ferida forçada a voar para espetáculo provavelmente se machucaria além de qualquer recuperação, e que nenhum banquete valia a perda de uma falcoa que, em três ocasiões distintas, havia abatido caça que alimentara metade do castelo durante um inverno de escassez. Ela fez uma única pergunta, se ele apostaria seu cargo na veracidade de sua avaliação, e Aldric respondeu sem hesitar que sim.", "A baronesa contrariou seu mordomo naquela mesma noite, decretando que Sable permaneceria na falcoaria até estar completamente curada e que quaisquer decisões futuras a respeito dos falcões exigiriam o parecer de Aldric, uma decisão que o mordomo recebeu com um ressentimento mal disfarçado, mas que não ousou contestar abertamente. A notícia da troca de palavras percorreu a casa com a rapidez particular reservada a histórias em que os poderosos são vistos cedendo aos simplesmente competentes, e Aldric se viu considerado, pela primeira vez em mais de uma década, alguém cujo julgamento tinha peso genuíno dentro daquelas muralhas.", "Sable se recuperou por completo dentro de um mês e, algumas semanas depois, abateu uma garça num voo tão preciso que até o mordomo, observando das ameias com uma expressão que claramente desejava que ninguém notasse, permitiu-se um único e relutante aceno de aprovação. Aldric nunca chegou a saber se aquele gesto constituía um pedido de desculpas, e descobriu, para sua própria surpresa moderada, que já não precisava particularmente dele."], "hard_words": ["gyrfalcon", "flogging", "reprimand", "eyas", "decreeing", "battlements"], "vocab": [{"word": "mews", "meaning": "falcoaria, local onde se mantêm falcões", "note": ""}, {"word": "flogging", "meaning": "açoitamento, castigo físico", "note": ""}, {"word": "reprimand", "meaning": "repreensão", "note": ""}, {"word": "eyas", "meaning": "filhote de ave de rapina ainda não voou", "note": "termo técnico de falcoaria"}, {"word": "decreeing", "meaning": "decretando", "note": ""}, {"word": "battlements", "meaning": "ameias (parte superior do castelo)", "note": ""}, {"word": "stake", "meaning": "apostar, arriscar", "note": ""}, {"word": "grudging", "meaning": "relutante, dado a contragosto", "note": ""}], "word_meanings": [{"word": "gyrfalcon", "meaning": "girifalte (ave de rapina)", "note": ""}, {"word": "flogging", "meaning": "açoitamento", "note": ""}, {"word": "reprimand", "meaning": "repreensão", "note": ""}, {"word": "eyas", "meaning": "filhote de ave de rapina", "note": ""}, {"word": "decreeing", "meaning": "decretando", "note": ""}, {"word": "battlements", "meaning": "ameias", "note": ""}, {"word": "actually", "meaning": "na verdade", "note": "falso amigo"}, {"word": "eventually", "meaning": "finalmente", "note": "não aparece literalmente no texto, mas listado como cognato de referência"}, {"word": "was", "meaning": "era/estava", "note": ""}, {"word": "were", "meaning": "eram/estavam", "note": ""}, {"word": "chose", "meaning": "escolheu", "note": "passado irregular de choose"}, {"word": "received", "meaning": "recebeu", "note": ""}, {"word": "answered", "meaning": "respondeu", "note": ""}, {"word": "took", "meaning": "tomou/abateu", "note": "passado irregular de take"}, {"word": "found himself", "meaning": "se viu/se percebeu", "note": "expressão idiomática"}, {"word": "whether", "meaning": "se (dúvida)", "note": ""}, {"word": "despite", "meaning": "apesar de", "note": ""}], "grammar_words": {"cognates": [], "tobe": ["was"], "irregular": ["chose", "received", "answered", "took"], "phrasal": ["found himself"], "wh": ["whether"], "connectors": ["despite"], "comparative": []}, "exercises": {"grammar": [{"point": "Subjunctive-like formal structures", "explanation_pt": "Estruturas formais como 'demanded that Sable... be flown' usam o subjuntivo (sem -s na terceira pessoa) após verbos como 'demand', típico de registro elevado em inglês C2."}], "multiple_choice": [{"question": "Why did Aldric refuse the steward's order?", "options": ["He disliked the steward personally", "Sable had an unhealed wing injury", "He wanted more pay", "He was too tired"], "correct_index": 1, "explanation": "Sable ainda não havia se recuperado completamente de um ferimento na asa."}, {"question": "What did Aldric risk by appealing to the baroness?", "options": ["His position and possibly the falcon", "Nothing at all", "His life", "His family's land"], "correct_index": 0, "explanation": "Ele arriscava perder o cargo e a ave."}, {"question": "What question did the baroness ask Aldric?", "options": ["Whether he wanted a raise", "Whether he liked the steward", "Whether Sable was for sale", "Whether he would stake his position on his assessment"], "correct_index": 3, "explanation": "Ela perguntou se ele apostaria o cargo na veracidade de sua avaliação."}, {"question": "What did the baroness decide?", "options": ["To dismiss Aldric", "To sell Sable", "That Sable would stay until healed and Aldric's counsel would be required", "To fire the steward immediately"], "correct_index": 2, "explanation": "Ela decretou que Sable ficaria até curar-se e que o parecer de Aldric seria necessário."}, {"question": "How did the steward react when Sable flew perfectly weeks later?", "options": ["With a grudging nod of approval", "With fury", "He left the castle", "He apologized publicly"], "correct_index": 0, "explanation": "Ele permitiu-se um relutante aceno de aprovação."}], "open_questions": [{"question": "Why do you think Aldric was willing to risk his position for Sable?", "key_points_pt": ["Vínculo profundo com a ave criada desde filhote", "Convicção profissional e ética sobre o bem-estar animal"]}, {"question": "What does the baroness's decision reveal about her character as a leader?", "key_points_pt": ["Ela valoriza competência sobre hierarquia", "Está disposta a corrigir decisões injustas de subordinados"]}]}}, {"level": "C2", "genre": "mythology", "title": "The Weaver of Fates", "paragraphs": ["Among the lesser deities who attended the great loom of destiny, none was so resented as Perenna, whose task it was to weave the single thread representing every mortal's final year, a duty the other weavers considered beneath them and that Perenna alone seemed to regard with anything resembling tenderness. She alone insisted on learning something of each mortal before cutting their thread, a practice her fellow weavers dismissed as sentimental inefficiency, arguing that fate required no such intimacy, only precision.", "It was during the weaving of a particularly obstinate thread, belonging to a fisherman who had survived three shipwrecks through what appeared to be nothing but stubborn refusal to drown, that Perenna first hesitated. The pattern the other threads suggested for him was unambiguous, a fourth and final wreck within the month, yet something in the weave itself seemed to resist her shears, as though the thread had absorbed some of the man's own obstinacy and intended to outlast her judgment. She set the shears aside, an act unprecedented among weavers, and resolved to observe him a while longer before proceeding.", "The elder weavers, upon discovering her hesitation, convened to reprimand her, insisting that a single exception would unravel the entire tapestry's coherence, that fate could not be selectively delayed without consequence to threads interwoven with his own. Perenna, unmoved by an argument she had heard rehearsed for centuries, pointed out that the fisherman's thread was tangled inextricably with dozens of others, a wife's, a daughter's, an entire village's fragile economy, and that his premature ending would fray far more than it resolved. She proposed, instead of severance, a reweaving, a longer thread bought at the cost of her own diminished influence among the other deities.", "The elders, more troubled by precedent than by cruelty, ultimately permitted the exception, partly because Perenna's argument was sound and partly because none among them wished to be responsible for the discord her removal from the looms would cause. The fisherman lived another eleven years, long enough to teach his craft to a grandson who would, generations later, become the ancestor of a line of shipbuilders whose vessels would carry entire villages safely through storms that, in the original weave, would have claimed them.", "Perenna never spoke of the incident again, though the other weavers noticed, in the years that followed, a subtle change in how they approached their own shears: a fraction more hesitation, a fraction more curiosity about the lives interrupted by their blades. She had not overturned fate, precisely, only demonstrated, quietly and at considerable personal cost, that even the most rigid pattern occasionally tolerated the intervention of someone willing to look closely enough to notice it mattered."], "paragraphs_pt": ["Entre as divindades menores que atendiam ao grande tear do destino, nenhuma era tão malquista quanto Perenna, cuja tarefa era tecer o fio único que representava o último ano de vida de cada mortal, um dever que as outras tecelãs consideravam indigno delas e que somente Perenna parecia encarar com algo parecido com ternura. Só ela insistia em conhecer algo sobre cada mortal antes de cortar seu fio, prática que suas colegas tecelãs descartavam como ineficiência sentimental, argumentando que o destino não exigia tal intimidade, apenas precisão.", "Foi durante a tecelagem de um fio particularmente obstinado, pertencente a um pescador que sobrevivera a três naufrágios aparentemente por pura recusa teimosa em se afogar, que Perenna hesitou pela primeira vez. O padrão que os outros fios sugeriam para ele era inequívoco, um quarto e último naufrágio dentro daquele mês, mas algo na própria trama parecia resistir à sua tesoura, como se o fio tivesse absorvido um pouco da própria teimosia do homem e pretendesse sobreviver ao seu julgamento. Ela pôs a tesoura de lado, ato sem precedentes entre as tecelãs, e decidiu observá-lo por mais algum tempo antes de prosseguir.", "As tecelãs mais antigas, ao descobrirem sua hesitação, reuniram-se para repreendê-la, insistindo que uma única exceção desfaria a coerência de toda a tapeçaria, que o destino não podia ser seletivamente adiado sem consequências para os fios entrelaçados ao dele. Perenna, impassível diante de um argumento que ouvira repetido havia séculos, apontou que o fio do pescador estava emaranhado de forma inextricável a dezenas de outros, o de uma esposa, o de uma filha, a frágil economia de toda uma vila, e que seu fim prematuro desfiaria muito mais do que resolveria. Ela propôs, em vez do corte, uma retecelagem, um fio mais longo comprado ao custo de sua própria influência diminuída entre as outras divindades.", "As anciãs, mais incomodadas com o precedente do que com a crueldade em si, por fim permitiram a exceção, em parte porque o argumento de Perenna era sólido e em parte porque nenhuma delas queria ser responsável pela discórdia que sua remoção dos teares causaria. O pescador viveu mais onze anos, tempo suficiente para ensinar seu ofício a um neto que, gerações depois, se tornaria o ancestral de uma linhagem de construtores de navios cujos barcos levariam vilas inteiras a salvo por tempestades que, na trama original, as teriam ceifado.", "Perenna nunca mais falou do incidente, embora as outras tecelãs tenham notado, nos anos seguintes, uma sutil mudança na maneira como manejavam suas próprias tesouras: uma fração a mais de hesitação, uma fração a mais de curiosidade sobre as vidas interrompidas por suas lâminas. Ela não havia revertido o destino, precisamente, apenas demonstrado, silenciosamente e a um custo pessoal considerável, que até o padrão mais rígido às vezes tolerava a intervenção de alguém disposto a olhar de perto o suficiente para perceber que aquilo importava."], "hard_words": ["obstinate", "shears", "inextricably", "fray", "severance", "precedent"], "vocab": [{"word": "loom", "meaning": "tear (instrumento de tecelagem)", "note": ""}, {"word": "obstinate", "meaning": "obstinado, teimoso", "note": ""}, {"word": "shears", "meaning": "tesoura grande", "note": ""}, {"word": "inextricably", "meaning": "inextricavelmente, de forma inseparável", "note": ""}, {"word": "fray", "meaning": "desfiar, desgastar", "note": ""}, {"word": "severance", "meaning": "corte, separação", "note": ""}, {"word": "precedent", "meaning": "precedente", "note": ""}, {"word": "unprecedented", "meaning": "sem precedentes, inédito", "note": ""}], "word_meanings": [{"word": "obstinate", "meaning": "obstinado, teimoso", "note": ""}, {"word": "shears", "meaning": "tesoura grande", "note": ""}, {"word": "inextricably", "meaning": "inextricavelmente", "note": ""}, {"word": "fray", "meaning": "desfiar, desgastar", "note": ""}, {"word": "severance", "meaning": "corte, separação", "note": ""}, {"word": "precedent", "meaning": "precedente", "note": ""}, {"word": "actually", "meaning": "na verdade", "note": "falso amigo"}, {"word": "eventually", "meaning": "finalmente", "note": "falso amigo, listado como referência de cognato"}, {"word": "was", "meaning": "era/estava", "note": ""}, {"word": "were", "meaning": "eram/estavam", "note": ""}, {"word": "set aside", "meaning": "pôs de lado", "note": "phrasal verb"}, {"word": "lived", "meaning": "viveu", "note": ""}, {"word": "spoke", "meaning": "falou", "note": "passado irregular de speak"}, {"word": "proposed", "meaning": "propôs", "note": ""}, {"word": "resolved", "meaning": "decidiu, resolveu", "note": ""}, {"word": "though", "meaning": "embora", "note": ""}, {"word": "yet", "meaning": "porém, contudo", "note": ""}], "grammar_words": {"cognates": [], "tobe": ["was"], "irregular": ["lived", "spoke", "proposed", "resolved"], "phrasal": [], "wh": [], "connectors": ["though", "yet"], "comparative": []}, "exercises": {"grammar": [{"point": "Cleft sentences with 'It was... that'", "explanation_pt": "A frase 'It was during the weaving... that Perenna first hesitated' usa a estrutura clivada para enfatizar o momento exato do evento, recurso estilístico comum em narrativas elevadas de nível C2."}], "multiple_choice": [{"question": "What was Perenna's task among the weavers?", "options": ["Weaving the threads of the gods", "Guarding the loom", "Weaving each mortal's final year", "Cutting the elders' threads"], "correct_index": 2, "explanation": "Sua tarefa era tecer o fio do último ano de vida de cada mortal."}, {"question": "Why did Perenna hesitate over the fisherman's thread?", "options": ["She lost the shears", "The elders ordered her to stop", "She was tired", "Something in the weave seemed to resist her shears"], "correct_index": 3, "explanation": "Algo na trama parecia resistir à tesoura dela."}, {"question": "What argument did Perenna use to convince the elders?", "options": ["His thread was tangled with many others whose lives depended on his", "The fisherman was a god in disguise", "She simply refused to explain", "The elders owed her a favor"], "correct_index": 0, "explanation": "Ela argumentou que o fio dele estava emaranhado com muitos outros."}, {"question": "What did the fisherman's extra years lead to?", "options": ["Nothing significant", "A line of shipbuilders who later saved villages from storms", "His own death anyway", "A war"], "correct_index": 1, "explanation": "Ele teve tempo de formar uma linhagem de construtores de navios que salvaram vilas."}, {"question": "What changed among the other weavers after the incident?", "options": ["Nothing at all", "They banned Perenna from the looms", "They stopped weaving completely", "They became slightly more hesitant and curious about mortals' lives"], "correct_index": 3, "explanation": "Elas passaram a hesitar e se interessar um pouco mais pelas vidas dos mortais."}], "open_questions": [{"question": "Do you think Perenna was right to intervene in the fisherman's fate? Why or why not?", "key_points_pt": ["Considerar o impacto em outras vidas conectadas", "Refletir sobre compaixão versus ordem estabelecida"]}, {"question": "What does this myth suggest about the relationship between fate and individual choice?", "key_points_pt": ["Mesmo sistemas rígidos podem ter espaço para exceções", "Pequenos atos de cuidado podem ter grandes consequências"]}]}}, {"level": "C2", "genre": "timetravel", "title": "The Photograph That Wasn't", "paragraphs": ["When Theo inherited his grandmother's belongings, he expected sentimental clutter, not a photograph of himself standing beside her at what was unmistakably her twenty-fifth birthday party, a celebration that had occurred, according to every family record, four decades before he was born. He turned the photograph over repeatedly, half convinced it was some elaborate joke his cousins had engineered, though the sepia tone and the particular brittleness of the paper argued persuasively against forgery, as did his grandmother's unmistakably younger face, unlined in a way he had never once seen in life.", "The attic yielded further evidence, reluctantly: a journal, in handwriting he recognized as his own despite having no memory of writing it, describing a device his grandmother had apparently built in her youth and later dismantled, convinced that the risks of tampering with sequence outweighed any curiosity it might satisfy. The journal's final entry, dated some sixty years earlier, noted only that she intended to use it once more, deliberately, to attend her own birthday accompanied by a grandson not yet conceived, a decision she described as selfish and worth it in equal measure.", "Theo spent a disorienting week reconciling the plain fact of his own existence with a memory that did not exist, a day he had apparently lived that he could not recall living, and arrived eventually at an uneasy peace with the paradox by accepting that some experiences perhaps only became memories the second time they were lived, a theory he had no way of testing and every reason to suspect was simply his mind's attempt to impose order on the impossible.", "He found the device itself in a locked drawer, inert and clearly non-functional, its components corroded well past any hope of repair, exactly as the journal had described. Whether his grandmother had told the truth about dismantling it deliberately, or whether it had simply failed with age the way most instruments eventually do, Theo found he could not determine, and, more surprisingly, found he did not especially want to; some mysteries, he suspected, existed precisely so that families might have something to wonder about together across generations.", "He kept the photograph, framed, on his own mantelpiece, not as proof of anything he could explain to a skeptical relative, but as a private acknowledgment that his grandmother had, in some genuinely inexplicable way, chosen him before he existed, had traveled decades out of sequence specifically to stand beside a grandson she would not otherwise meet for half a century, and had apparently considered that impossible afternoon worth every risk it must have carried."], "paragraphs_pt": ["Quando Theo herdou os pertences da avó, esperava tralha sentimental, não uma fotografia de si mesmo ao lado dela na festa de vinte e cinco anos que, segundo todos os registros da família, acontecera quatro décadas antes de ele nascer. Ele virou a fotografia repetidas vezes, meio convencido de que se tratava de alguma brincadeira elaborada arquitetada pelos primos, embora o tom sépia e a fragilidade particular do papel argumentassem persuasivamente contra a falsificação, assim como o rosto inconfundivelmente mais jovem da avó, sem uma única ruga, de um jeito que ele nunca havia visto em vida.", "O sótão rendeu evidências adicionais, relutantemente: um diário, com uma caligrafia que ele reconheceu como sua própria apesar de não ter memória alguma de tê-lo escrito, descrevendo um dispositivo que sua avó aparentemente construíra na juventude e depois desmontara, convencida de que os riscos de mexer na sequência do tempo superavam qualquer curiosidade que pudessem satisfazer. A última anotação do diário, datada de cerca de sessenta anos antes, registrava apenas que ela pretendia usá-lo mais uma vez, deliberadamente, para comparecer ao próprio aniversário acompanhada de um neto ainda não concebido, decisão que ela descrevia como egoísta e válida em igual medida.", "Theo passou uma semana desorientadora conciliando o simples fato de sua própria existência com uma lembrança que não existia, um dia que ele aparentemente vivera mas não conseguia recordar ter vivido, e chegou, por fim, a uma paz incômoda com o paradoxo ao aceitar que algumas experiências talvez só se tornassem memórias na segunda vez em que eram vividas, uma teoria que ele não tinha como testar e todo motivo para suspeitar que fosse apenas a tentativa da própria mente de impor ordem ao impossível.", "Ele encontrou o próprio dispositivo numa gaveta trancada, inerte e claramente sem funcionar, os componentes corroídos além de qualquer esperança de reparo, exatamente como o diário descrevera. Se a avó dissera a verdade sobre tê-lo desmontado deliberadamente, ou se ele simplesmente falhara com o tempo como a maioria dos instrumentos acaba fazendo, Theo descobriu que não conseguia determinar, e, mais surpreendentemente, descobriu que não fazia questão especial de determinar; algumas coisas misteriosas, ele suspeitava, existiam precisamente para que famílias tivessem algo sobre o que se perguntar juntas ao longo das gerações.", "Ele guardou a fotografia, emoldurada, na própria lareira, não como prova de algo que pudesse explicar a um parente cético, mas como um reconhecimento particular de que sua avó havia, de alguma forma genuinamente inexplicável, escolhido a ele antes mesmo de ele existir, viajara décadas fora de sequência especificamente para ficar ao lado de um neto que, de outro modo, só conheceria meio século depois, e aparentemente considerara aquela tarde impossível válida por qualquer risco que deve ter carregado."], "hard_words": ["sepia", "brittleness", "dismantled", "corroded", "reconciling", "mantelpiece"], "vocab": [{"word": "sepia", "meaning": "sépia (tom marrom-alaranjado de fotos antigas)", "note": ""}, {"word": "brittleness", "meaning": "fragilidade, tendência a quebrar", "note": ""}, {"word": "dismantled", "meaning": "desmontou, desmantelou", "note": ""}, {"word": "corroded", "meaning": "corroído", "note": ""}, {"word": "reconciling", "meaning": "conciliando", "note": ""}, {"word": "mantelpiece", "meaning": "prateleira da lareira", "note": ""}, {"word": "tampering with", "meaning": "mexer indevidamente em, adulterar", "note": ""}, {"word": "uneasy", "meaning": "inquieto, desconfortável", "note": ""}], "word_meanings": [{"word": "sepia", "meaning": "sépia", "note": ""}, {"word": "brittleness", "meaning": "fragilidade", "note": ""}, {"word": "dismantled", "meaning": "desmontou", "note": ""}, {"word": "corroded", "meaning": "corroído", "note": ""}, {"word": "reconciling", "meaning": "conciliando", "note": ""}, {"word": "mantelpiece", "meaning": "prateleira da lareira", "note": ""}, {"word": "actually", "meaning": "na verdade", "note": "falso amigo"}, {"word": "eventually", "meaning": "finalmente", "note": ""}, {"word": "was", "meaning": "era/estava", "note": ""}, {"word": "were", "meaning": "eram/estavam", "note": ""}, {"word": "found", "meaning": "encontrou", "note": "passado irregular de find"}, {"word": "kept", "meaning": "guardou/manteve", "note": "passado irregular de keep"}, {"word": "spent", "meaning": "passou (tempo)", "note": "passado irregular de spend"}, {"word": "turned", "meaning": "virou", "note": ""}, {"word": "tampering with", "meaning": "mexer indevidamente em", "note": "phrasal-like verb"}, {"word": "whether", "meaning": "se (dúvida)", "note": ""}, {"word": "though", "meaning": "embora", "note": ""}], "grammar_words": {"cognates": ["eventually"], "tobe": ["was", "were"], "irregular": ["found", "kept", "spent", "turned"], "phrasal": ["tampering with"], "wh": ["whether"], "connectors": ["though"], "comparative": []}, "exercises": {"grammar": [{"point": "Mixed conditionals and hypothetical past", "explanation_pt": "A narrativa usa estruturas hipotéticas complexas, como 'a grandson not yet conceived', combinando tempos para expressar situações logicamente impossíveis, típico de textos sofisticados em nível C2."}], "multiple_choice": [{"question": "What did Theo find among his grandmother's belongings?", "options": ["A love letter", "Old money", "A map", "A photograph of himself at her 25th birthday, decades before he was born"], "correct_index": 3, "explanation": "Ele encontrou uma foto de si mesmo na festa de 25 anos da avó."}, {"question": "What did the journal in the attic describe?", "options": ["A recipe book", "A family tree", "A time-travel device his grandmother built and later dismantled", "A diary of her childhood"], "correct_index": 2, "explanation": "O diário descrevia um dispositivo de viagem no tempo."}, {"question": "How did Theo come to terms with the impossible memory?", "options": ["He ignored it completely", "He accepted a theory that some experiences become memories only the second time they're lived", "He destroyed the photograph", "He asked his grandmother directly"], "correct_index": 1, "explanation": "Ele aceitou a teoria de que algumas experiências só viram memória na segunda vez."}, {"question": "What condition was the device in when Theo found it?", "options": ["Inert and corroded beyond repair", "Fully functional", "Missing entirely", "Brand new"], "correct_index": 0, "explanation": "O dispositivo estava inerte e corroído."}, {"question": "What did Theo do with the photograph in the end?", "options": ["He threw it away", "He sold it", "He framed it and kept it on his mantelpiece", "He gave it to a museum"], "correct_index": 2, "explanation": "Ele a emoldurou e a manteve na lareira."}], "open_questions": [{"question": "Why do you think Theo's grandmother described her choice as 'selfish and worth it in equal measure'?", "key_points_pt": ["Ela alterou a sequência do tempo por motivos pessoais e emocionais", "Reconhece o risco, mas valoriza a conexão com o neto"]}, {"question": "If you had a device like this, would you use it to meet a future family member? Why or why not?", "key_points_pt": ["Resposta pessoal livre", "Pode considerar riscos, ética e curiosidade"]}]}}, {"level": "C2", "genre": "slice", "title": "Sunday Mending", "paragraphs": ["Every Sunday for as long as her children could remember, Ines set up her sewing basket on the porch and mended whatever had accumulated during the week, a habit that had long since outlived any strict financial necessity but persisted regardless, partly out of thrift and partly, she suspected, because the repetitive motion of needle through fabric emptied her mind in a way meditation apps had repeatedly failed to achieve. Her son, now grown and visiting for the weekend with his own small daughter in tow, found the ritual almost anachronistic, the sort of domestic patience that his own generation had largely outsourced to convenience.", "The granddaughter, four years old and instinctively drawn to anything her grandmother did with such evident absorption, planted herself on the porch steps and demanded, with the imperious confidence unique to small children, to be taught. Ines, secretly delighted though she would never have admitted it outright, produced a spare needle, threaded it with exaggerated patience, and guided small fingers through a stitch clumsy enough to unravel within the hour, though neither of them seemed particularly troubled by its impermanence.", "Her son watched from the doorway with an expression Ines recognized, a mixture of nostalgia and mild guilt, the particular look of someone realizing he had let a skill lapse that his own mother still practiced weekly without complaint. He admitted, somewhat sheepishly, that he generally just replaced torn clothing rather than mending it, a confession Ines received without judgment, having long ago decided that criticizing her children's practical choices accomplished considerably less than simply modeling her own.", "By late afternoon, the granddaughter had produced a wildly uneven line of stitches across a handkerchief destined for no practical purpose whatsoever, and had declared, with the absolute conviction of the very young, that she intended to sew every Sunday for the rest of her life, a promise Ines received with the fond skepticism of someone who had heard equally passionate four-year-old declarations dissolve by the following weekend.", "Still, as she packed the sewing basket away that evening, Ines found herself thinking less about whether the habit would survive her granddaughter's shifting enthusiasms and more about the simple fact of the afternoon itself, three generations arranged loosely around a porch, needle and thread passing quite literally from one pair of hands to another, regardless of what, if anything, would ultimately be made of it."], "paragraphs_pt": ["Todo domingo, desde que seus filhos conseguiam se lembrar, Ines montava a cesta de costura na varanda e consertava o que se acumulara durante a semana, um hábito que havia muito superara qualquer necessidade financeira estrita, mas persistia mesmo assim, em parte por economia e em parte, ela suspeitava, porque o movimento repetitivo da agulha atravessando o tecido esvaziava sua mente de um jeito que aplicativos de meditação repetidamente não conseguiam alcançar. O filho, já adulto e visitando no fim de semana com a própria filha pequena, achava o ritual quase anacrônico, o tipo de paciência doméstica que sua própria geração em grande parte terceirizara em nome da conveniência.", "A neta, de quatro anos e instintivamente atraída por qualquer coisa que a avó fizesse com tamanha absorção evidente, plantou-se nos degraus da varanda e exigiu, com a confiança imperiosa peculiar das crianças pequenas, ser ensinada. Ines, secretamente encantada, embora jamais fosse admitir isso abertamente, tirou uma agulha sobressalente, enfiou a linha com paciência exagerada, e guiou os dedinhos por um ponto desajeitado o suficiente para se desfazer dentro de uma hora, embora nenhuma das duas parecesse particularmente incomodada com sua impermanência.", "O filho observava da porta com uma expressão que Ines reconheceu, uma mistura de nostalgia e leve culpa, o olhar particular de alguém percebendo que deixara uma habilidade se perder que a própria mãe ainda praticava semanalmente sem reclamar. Ele admitiu, um tanto encabulado, que geralmente apenas substituía roupas rasgadas em vez de consertá-las, uma confissão que Ines recebeu sem julgamento, tendo decidido havia muito tempo que criticar as escolhas práticas dos filhos realizava consideravelmente menos do que simplesmente modelar as próprias.", "No fim da tarde, a neta havia produzido uma linha de pontos extremamente irregular num lenço destinado a propósito prático nenhum, e declarara, com a convicção absoluta dos muito jovens, que pretendia costurar todo domingo pelo resto da vida, promessa que Ines recebeu com o ceticismo carinhoso de quem já ouvira declarações igualmente apaixonadas de crianças de quatro anos se dissolverem antes do fim de semana seguinte.", "Ainda assim, ao guardar a cesta de costura naquela noite, Ines se viu pensando menos sobre se o hábito sobreviveria aos entusiasmos mutáveis da neta e mais sobre o simples fato daquela tarde em si, três gerações reunidas frouxamente numa varanda, agulha e linha passando bem literalmente de um par de mãos para outro, independentemente do que, se é que algo, viesse a ser feito com aquilo no fim."], "hard_words": ["anachronistic", "imperious", "sheepishly", "lapse", "impermanence", "skepticism"], "vocab": [{"word": "thrift", "meaning": "economia, poupança", "note": ""}, {"word": "anachronistic", "meaning": "anacrônico, fora de época", "note": ""}, {"word": "imperious", "meaning": "imperioso, autoritário", "note": ""}, {"word": "sheepishly", "meaning": "encabuladamente, timidamente", "note": ""}, {"word": "lapse", "meaning": "deixar cair em desuso, lapso", "note": ""}, {"word": "impermanence", "meaning": "impermanência", "note": ""}, {"word": "skepticism", "meaning": "ceticismo", "note": ""}, {"word": "loosely", "meaning": "frouxamente, de forma solta", "note": ""}], "word_meanings": [{"word": "anachronistic", "meaning": "anacrônico", "note": ""}, {"word": "imperious", "meaning": "imperioso", "note": ""}, {"word": "sheepishly", "meaning": "encabuladamente", "note": ""}, {"word": "lapse", "meaning": "deixar cair em desuso", "note": ""}, {"word": "impermanence", "meaning": "impermanência", "note": ""}, {"word": "skepticism", "meaning": "ceticismo", "note": ""}, {"word": "actually", "meaning": "na verdade", "note": "falso amigo, listado como referência"}, {"word": "eventually", "meaning": "finalmente", "note": "falso amigo, listado como referência"}, {"word": "was", "meaning": "era/estava", "note": ""}, {"word": "were", "meaning": "eram/estavam", "note": ""}, {"word": "set up", "meaning": "montou, organizou", "note": "phrasal verb"}, {"word": "found herself", "meaning": "se viu/se percebeu", "note": "expressão idiomática"}, {"word": "produced", "meaning": "produziu", "note": ""}, {"word": "admitted", "meaning": "admitiu", "note": ""}, {"word": "though", "meaning": "embora", "note": ""}, {"word": "regardless of", "meaning": "independentemente de", "note": ""}], "grammar_words": {"cognates": [], "tobe": [], "irregular": ["set up", "found herself", "produced", "admitted"], "phrasal": ["set up", "found herself"], "wh": [], "connectors": ["though", "regardless of"], "comparative": []}, "exercises": {"grammar": [{"point": "Present participle clauses for background action", "explanation_pt": "Orações reduzidas com gerúndio, como 'having long ago decided', condensam informação de fundo sem criar uma nova oração completa, recurso típico de prosa elegante em nível C2."}], "multiple_choice": [{"question": "What does Ines do every Sunday?", "options": ["Mends clothes on the porch", "Bakes bread", "Goes to church", "Cleans the house"], "correct_index": 0, "explanation": "Ela conserta roupas na varanda todo domingo."}, {"question": "Why does Ines continue this habit even though it isn't financially necessary?", "options": ["She has no other hobbies", "Her family demands it", "The repetitive motion calms her mind", "She sells the mended clothes"], "correct_index": 2, "explanation": "O movimento repetitivo esvazia sua mente de um jeito que meditação não conseguia."}, {"question": "What does the granddaughter ask to be taught?", "options": ["Cooking", "Sewing", "Reading", "Gardening"], "correct_index": 1, "explanation": "Ela pede para ser ensinada a costurar."}, {"question": "What does Ines's son admit about his own habits?", "options": ["He mends everything himself", "He never wears torn clothes", "He hates sewing", "He usually just replaces torn clothing instead of mending it"], "correct_index": 3, "explanation": "Ele admite que geralmente só substitui roupas rasgadas."}, {"question": "What does Ines mainly reflect on at the end of the story?", "options": ["The moment itself, three generations together", "Whether the habit will survive", "Her financial situation", "Her son's career"], "correct_index": 0, "explanation": "Ela pensa principalmente no momento em si, com três gerações reunidas."}], "open_questions": [{"question": "Why do you think Ines doesn't criticize her son for not mending his own clothes?", "key_points_pt": ["Ela prefere modelar comportamentos a criticar escolhas alheias", "Reconhece que gerações diferentes têm hábitos diferentes"]}, {"question": "Do you have a habit or skill passed down from an older family member? Describe it.", "key_points_pt": ["Resposta pessoal livre", "Pode mencionar tradições familiares e seu valor emocional"]}]}}, {"level": "C2", "genre": "interview", "title": "Questions Worth Asking", "paragraphs": ["By the time Farid reached his ninth interview for the same fellowship, he had grown so accustomed to reciting his qualifications that he could recite them, he suspected, in his sleep, a fluency that had somehow curdled into a kind of hollow rehearsedness he worried interviewers could detect immediately. The panel that afternoon consisted of three researchers whose published work he had studied obsessively, and he entered the room bracing himself for the same predictable sequence of questions about strengths, weaknesses, and long-term goals that had, in eight prior attempts, yielded eight polite rejections.", "The interview began conventionally enough, though the youngest panelist, rather than asking about his greatest weakness, asked instead what question he wished interviewers would stop asking, a query so unexpected that Farid's rehearsed composure faltered entirely, and he found himself answering honestly rather than strategically for what felt like the first time in months. He admitted, somewhat to his own surprise, that he was tired of being asked to quantify passion, as though genuine intellectual curiosity could be reduced to a percentage without becoming something else entirely, something hollowed out and unrecognizable.", "The panel exchanged a brief, unreadable glance that Farid initially interpreted as disapproval, bracing himself for the interview's premature and awkward conclusion, but the senior researcher instead leaned forward with what he eventually recognized as genuine interest and asked him to elaborate, an invitation that led, over the following twenty minutes, to the most substantive conversation Farid had had in any interview that year, ranging unpredictably from his actual research interests to a shared frustration with how academic funding incentivized exactly the wrong qualities in early-career researchers.", "He left the building uncertain, as always, whether he had secured the fellowship, but aware of something he hadn't anticipated feeling after any of his previous attempts: a distinct sense of having been genuinely seen rather than merely evaluated, regardless of the outcome. The rehearsed answers he had polished for months suddenly felt, in retrospect, like armor he had been wearing unnecessarily, protecting a version of himself considerably less interesting than the one the interview had eventually allowed to surface.", "The offer arrived nine days later, accompanied by a brief note from the senior researcher remarking that the committee had, for once, been more persuaded by an honest complaint than by any rehearsed enthusiasm, a comment Farid read several times, slowly coming to understand that the questions worth answering honestly were rarely the ones he had spent months preparing for, but the ones that caught him, deliberately or not, off guard."], "paragraphs_pt": ["Quando Farid chegou à sua nona entrevista para a mesma bolsa, já estava tão acostumado a recitar suas qualificações que suspeitava conseguir fazê-lo até dormindo, uma fluência que de alguma forma azedara numa espécie de ensaio oco que ele temia que os entrevistadores detectassem imediatamente. A banca daquela tarde era composta por três pesquisadores cujos trabalhos publicados ele estudara obsessivamente, e ele entrou na sala se preparando para a mesma sequência previsível de perguntas sobre pontos fortes, pontos fracos e objetivos de longo prazo que, em oito tentativas anteriores, haviam rendido oito recusas educadas.", "A entrevista começou de forma bastante convencional, embora a integrante mais jovem da banca, em vez de perguntar sobre seu maior ponto fraco, perguntasse qual pergunta ele gostaria que os entrevistadores parassem de fazer, uma pergunta tão inesperada que a compostura ensaiada de Farid falhou completamente, e ele se viu respondendo com honestidade, em vez de estrategicamente, pela primeira vez em meses, pelo menos era o que sentia. Ele admitiu, para sua própria surpresa, que estava cansado de ser solicitado a quantificar paixão, como se a curiosidade intelectual genuína pudesse ser reduzida a uma porcentagem sem se tornar algo completamente diferente, algo esvaziado e irreconhecível.", "A banca trocou um breve olhar indecifrável que Farid a princípio interpretou como reprovação, preparando-se para o fim prematuro e constrangedor da entrevista, mas o pesquisador sênior, em vez disso, inclinou-se para a frente com o que ele acabou reconhecendo como interesse genuíno e pediu que elaborasse melhor, um convite que levou, ao longo dos vinte minutos seguintes, à conversa mais substancial que Farid tivera em qualquer entrevista naquele ano, passando de forma imprevisível de seus verdadeiros interesses de pesquisa a uma frustração compartilhada sobre como o financiamento acadêmico incentivava exatamente as qualidades erradas em pesquisadores no início de carreira.", "Ele saiu do prédio incerto, como sempre, se conseguira a bolsa, mas consciente de algo que não esperava sentir depois de nenhuma de suas tentativas anteriores: uma nítida sensação de ter sido genuinamente visto, em vez de meramente avaliado, independentemente do resultado. As respostas ensaiadas que polira durante meses de repente pareceram, em retrospecto, uma armadura que ele vinha usando desnecessariamente, protegendo uma versão de si mesmo consideravelmente menos interessante do que aquela que a entrevista finalmente permitira emergir.", "A proposta chegou nove dias depois, acompanhada de um bilhete breve do pesquisador sênior observando que o comitê havia, por uma vez, se deixado convencer mais por uma reclamação honesta do que por qualquer entusiasmo ensaiado, comentário que Farid releu várias vezes, compreendendo aos poucos que as perguntas que valia a pena responder com honestidade raramente eram aquelas para as quais ele passara meses se preparando, mas sim aquelas que o pegavam, deliberadamente ou não, desprevenido."], "hard_words": ["curdled", "faltered", "unreadable", "substantive", "retrospect", "unrecognizable"], "vocab": [{"word": "curdled", "meaning": "azedou, talhou (fig.: degenerou)", "note": ""}, {"word": "faltered", "meaning": "vacilou, falhou", "note": ""}, {"word": "unreadable", "meaning": "indecifrável", "note": ""}, {"word": "substantive", "meaning": "substancial, significativo", "note": ""}, {"word": "retrospect", "meaning": "retrospecto, olhando para trás", "note": ""}, {"word": "off guard", "meaning": "desprevenido, de surpresa", "note": ""}, {"word": "bracing himself", "meaning": "se preparando (para algo difícil)", "note": ""}, {"word": "quantify", "meaning": "quantificar", "note": ""}], "word_meanings": [{"word": "curdled", "meaning": "azedou, degenerou", "note": ""}, {"word": "faltered", "meaning": "vacilou", "note": ""}, {"word": "unreadable", "meaning": "indecifrável", "note": ""}, {"word": "substantive", "meaning": "substancial", "note": ""}, {"word": "retrospect", "meaning": "retrospecto", "note": ""}, {"word": "unrecognizable", "meaning": "irreconhecível", "note": ""}, {"word": "actually", "meaning": "na verdade", "note": "falso amigo"}, {"word": "eventually", "meaning": "finalmente", "note": ""}, {"word": "was", "meaning": "era/estava", "note": ""}, {"word": "were", "meaning": "eram/estavam", "note": ""}, {"word": "began", "meaning": "começou", "note": "passado irregular de begin"}, {"word": "left", "meaning": "saiu/deixou", "note": "passado irregular de leave"}, {"word": "arrived", "meaning": "chegou", "note": ""}, {"word": "found himself", "meaning": "se viu/se percebeu", "note": "expressão idiomática"}, {"word": "though", "meaning": "embora", "note": ""}, {"word": "regardless of", "meaning": "independentemente de", "note": ""}], "grammar_words": {"cognates": ["eventually"], "tobe": ["was", "were"], "irregular": ["began", "left", "arrived", "found himself"], "phrasal": ["found himself"], "wh": [], "connectors": ["though", "regardless of"], "comparative": []}, "exercises": {"grammar": [{"point": "Reduced relative and participle clauses", "explanation_pt": "Frases como 'a query so unexpected that Farid's composure faltered' e 'protecting a version of himself' usam construções reduzidas para adicionar informação de forma compacta, típicas de escrita sofisticada em C2."}], "multiple_choice": [{"question": "How many interviews had Farid attended before this one for the same fellowship?", "options": ["Eight", "Five", "Nine", "Two"], "correct_index": 0, "explanation": "Esta era sua nona entrevista, então havia tido oito anteriores."}, {"question": "What unusual question did the youngest panelist ask?", "options": ["About his weaknesses", "What question he wished interviewers would stop asking", "About his salary expectations", "About his hobbies"], "correct_index": 1, "explanation": "Ela perguntou qual pergunta ele gostaria que parassem de fazer."}, {"question": "What was Farid's honest complaint about?", "options": ["Low pay in academia", "Too many interviews", "Being asked to quantify passion", "Difficult panelists"], "correct_index": 2, "explanation": "Ele reclamou de ser solicitado a quantificar paixão."}, {"question": "How did the senior researcher react to Farid's honest answer?", "options": ["With visible disapproval", "By ending the interview early", "By ignoring it", "With genuine interest, asking him to elaborate"], "correct_index": 3, "explanation": "O pesquisador sênior mostrou interesse genuíno e pediu que ele elaborasse."}, {"question": "What did the committee's note say about their decision?", "options": ["They were unimpressed by him", "They were more persuaded by his honest complaint than by rehearsed enthusiasm", "They chose him randomly", "They needed more interviews"], "correct_index": 1, "explanation": "A nota dizia que se convenceram mais por uma reclamação honesta."}], "open_questions": [{"question": "Why do you think Farid's honest answer worked better than his rehearsed ones?", "key_points_pt": ["Autenticidade pode se destacar mais que respostas decoradas", "Mostra personalidade real ao entrevistador"]}, {"question": "What is a question you wish interviewers would stop asking, and why?", "key_points_pt": ["Resposta pessoal livre", "Pode mencionar perguntas clichês ou pouco reveladoras"]}]}}, {"level": "C2", "genre": "horror", "title": "The Attic Door", "paragraphs": ["The previous owners had mentioned the attic door only in passing, an offhand remark about a warped frame that occasionally stuck, and Marcus had dismissed it as the sort of minor inconvenience every old house accumulated, the kind of detail realtors buried in disclosures precisely because it seemed too trivial to alarm anyone. It was only in his third week in the house that he noticed the door never stuck when he approached it during the day, only ever after dark, and only when he was, as far as he could determine, entirely alone.", "He told himself, with the particular insistence of someone trying to out-argue his own unease, that the discrepancy was almost certainly a matter of temperature, wood contracting and expanding as the house cooled overnight, a perfectly reasonable explanation that nonetheless failed to account for the sound he occasionally heard afterward, a faint, deliberate scraping from above that ceased the instant he paused to listen for it, as though whatever produced it understood the difference between being heard and being caught listening.", "Curiosity, or perhaps simple exhaustion with his own escalating imagination, eventually drove him to force the door open one evening despite its resistance, flashlight in hand, bracing himself for something he couldn't quite name and privately hoping to find nothing more sinister than a family of raccoons that had taken up unauthorized residence. The attic was empty, unremarkable, thick with the ordinary dust of decades, save for a single detail that took him considerably longer to notice than it should have: a narrow, unbroken path swept clean through that dust, leading directly from the door to the far wall, where nothing visible stood to explain its destination.", "He told himself, walking that path with his flashlight trembling more than he cared to admit, that dust settled unevenly all the time, that drafts and old insulation could produce a hundred mundane explanations he simply hadn't considered yet, a litany of reassurance that dissolved entirely the moment his light caught a section of the far wall subtly discolored in the precise outline of a doorway that, according to every plan of the house he had reviewed before purchase, did not exist.", "Marcus did not investigate the discolored wall that night, nor, he told himself firmly, would he investigate it the following morning, a resolution he maintained with reasonable success until roughly four in the afternoon, when he found himself standing before it anyway, hammer in hand, unable to fully articulate why leaving a swept path and an outlined door unexamined felt, on reflection, considerably more frightening than whatever he might actually find behind it."], "paragraphs_pt": ["Os antigos donos haviam mencionado a porta do sótão apenas de passagem, um comentário casual sobre um caixilho empenado que às vezes emperrava, e Marcus descartara aquilo como o tipo de inconveniente menor que toda casa velha acumula, o tipo de detalhe que corretores enterram em divulgações justamente por parecer trivial demais para alarmar alguém. Foi só na terceira semana na casa que ele notou que a porta nunca emperrava quando ele se aproximava durante o dia, só depois de escurecer, e só quando ele estava, até onde conseguia determinar, completamente sozinho.", "Ele dizia a si mesmo, com a insistência particular de quem tenta argumentar contra o próprio desconforto, que a discrepância era quase certamente uma questão de temperatura, a madeira se contraindo e se expandindo enquanto a casa esfriava durante a noite, uma explicação perfeitamente razoável que, no entanto, não dava conta do som que ele às vezes ouvia depois, um raspado fraco e deliberado vindo de cima, que cessava no instante em que ele parava para prestar atenção, como se o que quer que o produzisse compreendesse a diferença entre ser ouvido e ser flagrado escutando.", "Curiosidade, ou talvez simples exaustão com a própria imaginação em escalada, por fim o levou a forçar a porta certa noite, apesar da resistência dela, lanterna em mãos, preparando-se para algo que não conseguia nomear direito e torcendo em segredo para não encontrar nada mais sinistro que uma família de guaxinins morando ali sem autorização. O sótão estava vazio, nada notável, coberto pela poeira comum de décadas, exceto por um único detalhe que ele demorou bem mais do que deveria para notar: um caminho estreito e ininterrupto varrido através daquela poeira, indo direto da porta até a parede do fundo, onde nada visível explicava seu destino.", "Ele dizia a si mesmo, caminhando por aquele trajeto com a lanterna tremendo mais do que gostaria de admitir, que a poeira se acumulava de forma irregular o tempo todo, que correntes de ar e isolamento velho podiam produzir uma centena de explicações banais que ele simplesmente ainda não havia considerado, uma litania de consolo que se dissolveu por completo no instante em que sua luz revelou uma seção da parede do fundo sutilmente descolorida no contorno preciso de uma porta que, segundo toda planta da casa que ele revisara antes da compra, não existia.", "Marcus não investigou a parede descolorida naquela noite, nem, disse a si mesmo com firmeza, a investigaria na manhã seguinte, resolução que manteve com razoável sucesso até por volta das quatro da tarde, quando se viu parado diante dela mesmo assim, martelo em mãos, incapaz de articular plenamente por que deixar um caminho varrido e uma porta contornada sem investigação parecia, pensando bem, consideravelmente mais assustador do que qualquer coisa que pudesse realmente encontrar atrás dela."], "hard_words": ["warped", "discrepancy", "scraping", "litany", "discolored", "unremarkable"], "vocab": [{"word": "warped", "meaning": "empenado, deformado", "note": ""}, {"word": "discrepancy", "meaning": "discrepância", "note": ""}, {"word": "scraping", "meaning": "raspado, som de arranhão", "note": ""}, {"word": "litany", "meaning": "litania (fig.: lista repetitiva)", "note": ""}, {"word": "discolored", "meaning": "descolorido, manchado", "note": ""}, {"word": "unremarkable", "meaning": "nada notável, comum", "note": ""}, {"word": "bracing himself", "meaning": "se preparando (para algo difícil)", "note": ""}, {"word": "take up residence", "meaning": "fixar residência, se instalar", "note": ""}], "word_meanings": [{"word": "warped", "meaning": "empenado", "note": ""}, {"word": "discrepancy", "meaning": "discrepância", "note": ""}, {"word": "scraping", "meaning": "raspado", "note": ""}, {"word": "litany", "meaning": "litania, lista repetitiva", "note": ""}, {"word": "discolored", "meaning": "descolorido", "note": ""}, {"word": "unremarkable", "meaning": "nada notável", "note": ""}, {"word": "actually", "meaning": "na verdade", "note": "falso amigo"}, {"word": "eventually", "meaning": "finalmente", "note": ""}, {"word": "was", "meaning": "era/estava", "note": ""}, {"word": "were", "meaning": "eram/estavam", "note": ""}, {"word": "told", "meaning": "disse/contou", "note": "passado irregular de tell"}, {"word": "heard", "meaning": "ouviu", "note": "passado irregular de hear"}, {"word": "found himself", "meaning": "se viu/se percebeu", "note": "expressão idiomática"}, {"word": "drove", "meaning": "levou/dirigiu (fig.: impeliu)", "note": "passado irregular de drive"}, {"word": "though", "meaning": "embora", "note": ""}, {"word": "as though", "meaning": "como se", "note": ""}, {"word": "take up residence", "meaning": "fixar residência, se instalar", "note": ""}], "grammar_words": {"cognates": ["actually", "eventually"], "tobe": ["was"], "irregular": ["told", "heard", "found himself", "drove"], "phrasal": ["found himself"], "wh": [], "connectors": ["though", "as though"], "comparative": []}, "exercises": {"grammar": [{"point": "'As though' + past simple for hypothetical comparison", "explanation_pt": "A estrutura 'as though whatever produced it understood' usa o passado simples após 'as though' para expressar uma comparação hipotética não real, recurso comum em narrativas de suspense/horror em nível C2."}], "multiple_choice": [{"question": "When did the attic door only stick, according to Marcus's observation?", "options": ["Only during the day", "Only after dark, when he was alone", "Only on weekends", "Only in winter"], "correct_index": 1, "explanation": "A porta só emperrava depois de escurecer e quando ele estava sozinho."}, {"question": "What sound did Marcus sometimes hear?", "options": ["A faint, deliberate scraping that stopped when he listened", "Music", "Voices", "Footsteps outside"], "correct_index": 0, "explanation": "Ele ouvia um raspado fraco que cessava quando ele parava para escutar."}, {"question": "What did Marcus find in the attic dust?", "options": ["Animal tracks", "Old furniture", "Nothing unusual", "A narrow swept path leading to the far wall"], "correct_index": 3, "explanation": "Ele encontrou um caminho estreito varrido na poeira."}, {"question": "What did Marcus notice on the far wall?", "options": ["A window", "A painting", "A discolored outline of a doorway that shouldn't exist", "Nothing at all"], "correct_index": 2, "explanation": "Ele notou o contorno de uma porta descolorida que não constava nas plantas da casa."}, {"question": "What did Marcus do at the end of the story?", "options": ["He found himself standing before the wall with a hammer", "He called the police", "He moved out immediately", "He ignored it forever"], "correct_index": 0, "explanation": "Ele se viu diante da parede com um martelo na mão."}], "open_questions": [{"question": "Why do you think Marcus felt more afraid of ignoring the mystery than of investigating it?", "key_points_pt": ["O desconhecido não resolvido pode ser mais perturbador que o confronto direto", "A curiosidade humana muitas vezes supera o medo"]}, {"question": "What do you think Marcus will find behind the discolored wall? Why?", "key_points_pt": ["Resposta pessoal livre e especulativa", "Pode basear-se nas pistas de suspense do texto"]}]}}];
